C                                                                       P-N00630
CCC   RELATIVISTIC ENERGY AND MASS FUNCTIONS                            P-N00640
C                                                                       P-N00650
      W(A,B,C,D)=SQRT(A*A+B*B+C*C+D*D)                                  P-N00660
      AM(A,B,C,D)=SQRT(D*D-A*A-B*B-C*C)                                 P-N00670
C                                                                       P-N00680
CCC   FORMATS                                                           P-N00690
C                                                                       P-N00700
C                                                                       P-N01700
CCC   READING OF THE DATA                                               P-N01710
C                                                                       P-N01720
C-------EXPLANATION OF SOME PHYSICAL QUANTITIES------------------------ P-N01730
C           (BASICALLY INPUT DATA, WHEN RUN AS A PROGRAM)
C                                                                       P-N01740
C     IA1=MASS NUMBER OF THE INCIDENT ION                               P-N01750
C                                                                       P-N01760
C     IA2=MASS NUMBER OF THE TARGET                                     P-N01770
C     IZ1=ATOMIC NUMBER OF THE PROJECTILE                               P-N01780
C                                                                       P-N01790
C     IZ2=ATOMIC NUMBER OF THE TARGET                                   P-N01800
C     R01=RADIUS PARAMETER OF THE PROJECTILE                            P-N01810
C           R01 SHOULD BE PUT TO 1.000                                  P-N01820
C     R02=RADIUS PARAMETER OF THE TARGET                                P-N01830
C     ADIF1=DIFFUSENESS OF THE PROJECTILE                               P-N01840
C           ADIF1 SHOULD BE PUT TO 1.0000                               P-N01850
C     ADIF2=DIFFUSENESS OF THE TARGET                                   P-N01860
C                                                                       P-N01870
C     TLAB = INCIDENT ENERGY  (IN MEV)                                  P-N01880
C                                                                       P-N01890
C     K1=1 REFERENCE FRAME=C.M. OF THE COVERING MATTER                  P-N01900
C     K1=2 REFERENCE FRAME=C.M. FRAME OF THE INCIDENT ION AND ITS       P-N01910
C          INTERCEPT                                                    P-N01920
C     K1=3 REFERENCE FRAME=C.M. FRAME OF A N-N SYSTEM WITH THE SAME     P-N01930
C          KINEMATICS AS THE TWO IONS                                   P-N01940
C     K1=4 REFERENCE FRAME=C.M. FRAME FOR THE TOTAL  SYSTEM             P-N01950
C     K1=5 REFERENCE FRAME=LAB SYSTEM                                   P-N01960
C              K1 SHOULD BE PUT TO 5 IN THIS VERSION                    P-N01970
C     K2=0 RELATIVISTIC KINEMATICS                                      P-N01980
C     K2=1 NON-RELATIVISTIC KINEMATICS(ABANDONNED IN THIS VERSION)      P-N01990
C     K3=0  DELTAS ARE PRODUCED                                         P-N02000
C     K3=1  NO DELTA PRODUCTION                                         P-N02010
C     K4=0 THE DELTA IS GIVEN A VANISHING LIFETIME                      P-N02020
C     K4=1 THE DELTA HAS A VERY LARGE LIFETIME                          P-N02030
C     K4=2 THE DELTA HAS A EXPONENTIALLY RANDOM LIFETIME                P-N02040
C     K5=0 NO DELTA-NUCLEON,DELTA-DELTA INTERACTIONS                    P-N02050
C     K5=1 DELTA-NUCLEON=DELTA-DELTA=NUCLEON-NUCLEON ELASTIC X-SECTION  P-N02060
C     K6=0 NO ANGULAR MOMENTUM CONSERVATION                             P-N02070
C     K6=1 ANGULAR MOMENTUM CONSERVATION                                P-N02080
C     Kclst=F(11) Light clusters computed if =1
C                                                                       P-N02090
C     B=IMPACT PARAMETER                                                P-N02100
C                                                                       P-N02110
C     RBL(PBL) IS THE RADIUS IN REAL(MOMENTUM) SPACE OF THE VOLUME      P-N02120
C         ON WHICH THE NUCLEONS ARE COUNTED TO EVALUATE THE PAULI       P-N02130
C         BLOCKING FACTORS                                              P-N02140
C     RECOMMENDED VALUES ARE 2 FM AND 200 MEV/C RESPECTIVELY            P-N02150
C                                                                       P-N02160
C     NRUN= NUMBER OF  RUNS (IRRELEVANT HERE)                           P-N02170
C                                                                       P-N02180
C     NTM=NUMBER OF INTERMEDIATE TIMES AT WHICH THE SPATIAL AND MOMENTUMP-N02190
C         DISTRIBUTIONS ARE STORED (NOT RELEVANT HERE)                  P-N02200
C                                                                       P-N02210
C     TEM(IT)=VALUES OF THE INTERMEDIATE TIMES  -> PLUS UTILISE         P-N02220
C                                                                       P-N02230
C     V0N=DEPTH OF THE NEUTRON AND DELTA0 POTENTIAL IN FERMI LEVEL      P-N02240
C     V0P=DEPTH OF THE PROTON AND DELTA+ POTENTIAL IN FERMI LEVEL
C     V0PP=DEPTH OF THE DELTA++ POTENTIAL IN FERMI LEVEL
C     V0M=DEPTH OF THE DELTA- POTENTIAL IN FERMI LEVEL
C     V0PIM=DEPTH OF PI-
C     V0PIN=DEPTH OF PI0
C     V0PIP=DEPTH OF PI+
C
C         (ATTENTION! A  V0 > 0 CORRESPONDS TO AN ATTRACTIVE POTENTIAL) P-N02270
C                                                                       P-N02280
C     NCASE=NUMBER OF CELLS NECESSARY TO DEPICT THE SPATIAL DISTRIBUTIONP-N02290
C         IN THE X AND Z DIRECTIONS -> PLUS UTILISE                     P-N02300
C                                                                       P-N02310
C     XP,XG,ZP,ZG=LIMITS OF THE BOX IN THE X AND Z DIRECTIONS           P-N02320
C     IN ORDER TO HAVE THE SAME SCALE IN THE TWO DIRECTIONS ,PUT XG-XP= P-N02330
C         0.9*(ZG-ZP)                                                   P-N02340
C     DY=DIMENSION OF THE BOX IN THE Y DIRECTION                        P-N02350
C     -> PLUS UTILISE
C                                                                       P-N02360
C     RAP1,RAP2,PP1,PP2=LIMITS OF THE BOX IN THE RAPIDITY-P(PERPENDICU- P-N02370
C          -LAR) SPACE                                                  P-N02380
C     -> PLUS UTILISE
C     THE BOX IS DIVIDED INTO 15 CELLS ALONG P(PERP) AND 40 CELLS ALONG P-N02390
C         THE RAPIDITY                                                  P-N02400
C                                                                       P-N02410
C     EN,SN=AVERAGE ENERGY CARRIED AWAY BY A NUCLEON,SEPARATION ENERGY  P-N02420
C                                                                       P-N02430
C       (NTM,NCASE,XP,...,SN are not used here)
C-----------------------------------------------------------------------P-N02440

      ibw=-1 !IBERT value for detailed print

C  Test of local energy correction for NN (1/2007)
C O No correction, 1 Full correction, 2 NN cross sections only
      LOCE = INT(F(18)+0.1)
      LOCED =  INT(F(10)+0.1)
      VLOC1 = 0.
      VLOC2 = 0.
      VLOCP1 = 0.
      VLOCP2 = 0.
C Test blocage NN
      LBLNN = INT(F(15)+0.1)
C NCOL_2C for effective NN after the first accepted collision:
      NCOL_2C = 0
      incol_2c = 0
C NN effectif used (2 parameters S1NN, S2NN)
      LNNEF = INT(F(20)+0.1)
C Coulomb distortion of incoming trajectories
      LCOUL = INT(F(21)+0.1)
      LCOUL_OUT=LCOUL !For outgoing charged particles
      kindf7=int(f(7)+0.1)
      IF(kindf7.EQ.2.OR.kindf7.EQ.4) LCOUL = 0 ! Neutral beam
C S.H. added IF statement for icrhi=3 and low incident energy below
C Coulomb barrier in deuteron-induced reactions. (2014.8.20)
      if ( kindf7 .eq. 6 .and. LCOUL_iadeu .eq. 1 ) then
         LCOUL = 0
      end if
C BackToSpectator (after avatar if T is below EF+PARAM_LOC) 1/0=Yes/No
C    Value of IAEA intercomparison:      PARAM_LOC=18.
      IBACKTOSPECT=INT(F(19)+0.1)
      PARAM_LOC=0.


      tim=0.

        irtst=0
c deutons
      beproj=0.
      ia2=amat(imat)
      iz2=zmat(imat)
      IN2=IA2-IZ2    ! ***** ThA
      r02=1.12
      Kclst=INT(f(11)+0.1)

      ia1=ia1t(kindf7)
      iz1=iz1t(kindf7)
      fmpinc=fmpinct(kindf7)
      rms1=rms1t(kindf7)
      pf1=pf1t(kindf7)

C TEST 25/11/2010 (No binding energy of projectiles for threshold tests) (AB-SL):
C Exact projectile mass from table for composite projectiles:
      IF(kindf7.GE.6) fmpinc=FMNUC(IA1,IZ1)


      coulf=1.44*IZ1*IZ2/f(3)

c deutons
      TLAB=F(3)
      K1=5                                                              P-N02530
      K2=0                                                              P-N02540
      k3=0
      k4=2
      k5=1
      k6=0

c espace de phases test (R et P) pour PAULI:
C Valeur recommandee par J.C. V-test=0.589 h**3:

C Valeur pour avoir V-test=h**3 avec 200 MeV/c:

C Valeur pour avoir V-test=h**3 avec 2fm:

C Valeur pour avoir V-test=2.38 h**3 (avec pbl=200)
      rbl=3.1848
      pbl=200.

C Cette valeur donne vol =0.5 dans pauli: f=0 ou 1, pas de seconde chance.

      XRR=RBL
      XRR2=XRR*XRR
      PR=PBL
      PR2=PR*PR

      ntm=1
c   temfin (time at which the INC is stopped), tmax5 defined after chosing b

       RATHR=0.
       RAMASS=0.0
C                                                                       P-N02780
CCC   CONSTANTS AND DERIVED DATA                                        P-N02790
C                                                                       P-N02800
c  separation energy of neutrons and protons
c  here in hard but later via the use of a mass formule.
c  ALPH is the dependence of energy of Vnucleon
c  STVINIT and STVREM will be used to check E conservation
c
       if(f(12).ge.0.0) then
          sn=f(12)
       else
          sn=0d0
       endif
       sp=sn

       IVFCTE=1   ! linear variation of V(E) default
       ALPH=0.223   ! Coeff. of linear variation
       if(f(13).lt.1.5) alph=0.0
       STVINIT=0.
       STVREM=0.
       IREJET=0
       SEJNVT=0.0
       SEJPVT=0.0
       NB_CLST=0
       SUM_Q=0.
       CORSEPA=0.
       NB_VU_MATTER=0

       nb_jpart=0

       IFL_BOUND_PROJ=0 ! Flag global projectile OFF(HI)

C Counter for the current value of A,Z inside the nuclear pot.
       IACOUR=IA2
       IZCOUR=IZ2
C Modif AB 27/10/2010
      ITCH=IZ2
c
c  definition of the Fermi spheres
c
c

      PF=1.37*HC                                                        P-N02820


      G0=115.                                                           P-N02830
      SQ0=4000.                                                         P-N02840
      TH=0.                                                             P-N02850
      PM2=FMP*FMP                                                       P-N02860
      TF=SQRT(PF*PF+PM2)-FMP
c proton
      FZA=real(IZ2,8)/real(IA2,8)
      PFP=PF*(2.0*FZA)**0.3333333
      if(f(13).lt.0.5) pfp=pf
      TFP=SQRT(PFP**2+PM2)-FMP
      V0P=TFP+SP
      IF(IVFCTE.EQ.1) V2P=(1.0-ALPH)*V0P+ALPH*(TFP)
      IF(IVFCTE.EQ.2) V2P=V0P/(EXP(-0.006681*(TFP-V0P)))
c neutron
      FNA=real(IN2,8)/real(IA2,8)
      PFN=PF*(2.0*FNA)**0.3333333
      if(f(13).lt.0.5) pfn=pf
      TFN=SQRT(PFN**2+PM2)-FMP
      V0N=TFN+SN
      IF(IVFCTE.EQ.1) V2N=(1.0-ALPH)*V0N+ALPH*(TFN)
      IF(IVFCTE.EQ.2) V2N=V0N/(EXP(-0.006681*(TFN-V0N)))
c other : linear interpolation
      DELTAV0=V0P-V0N

      V0M=V0N-DELTAV0
      V0PP=V0P+DELTAV0
      TFM=V0M-SN
      if ( TFM .lt. 0d0 ) TFM=0.001d0 !S.H. added on 2014.6.12
      PFM=SQRT(TFM**2+2*FMP*TFM)
      TFPP=V0PP-SP
      if ( TFPP .lt. 0d0 ) TFPP=0.001d0 !S.H. added on 2014.6.12
      PFPP=SQRT(TFPP**2+2*FMP*TFPP)
c
      IA=IA1+IA2                                                        P-N02870
      ITM=NTM+1                                                         P-N02880
      A1=dble(IA1)                                                            P-N02890
      A2=dble(IA2)                                                            P-N02900
      R2=R02*A2**0.33333333                                             P-N02910

c Safely settings for all nucleons (AB 07/2007):
      do kik=1,350
      nesc(kik)=0
      npproj(kik)=0
      enddo

C Radius for p coulomb barrier (R0+0.88) 11/2006
      r_zero_prot=r2+0.88

      if(idnint(f(17)).eq.1)then
         r_zero_prot=r2
       endif
c
c  calcul of the pions potential ThA
c
      if(f(16).gt.0.5) then
        XSI=(real(IA2,8)-2*real(IZ2,8))/real(IA2,8)
        VC=1.25*real(IZ2,8)*1.44/R2

C For test (Vpi*5) 16/3.2008
C Valeur canonique Th A.: 30.6 MeV
      VBPI=30.6

        V0PIP=VBPI+XSI*71.0-VC
        V0PIN=VBPI
        V0PIM=VBPI-XSI*71.0+VC
      else
        V0PIP=0.0
        V0PIN=0.0
        V0PIM=0.0
      endif
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'Pion Pot VP,VN,VM:',V0PIP,V0PIN,V0PIM
      ENDIF
c
C parametres moyens de densite de la cible (fermi 2 parametres)
C parametres moyens de densite de la cible (fermi 2 parametres)
      IF (IA2.GE.28) THEN
            R0 = (2.745E-4*IA2+1.063)*IA2**0.33333333
            ADIF = 1.63E-4*IA2+0.510
        RMAXWS = R0 + XFOISA*ADIF
      ELSE IF(IA2.GE.19) THEN
            R0 = R_light_nuc(IA2)
            ADIF = a_light_nuc(IA2)
        RMAXWS = R0 + XFOISA*ADIF
      ELSE IF(IA2.GE.6) THEN
            R0 = 1.581*a_light_nuc(IA2)
     s            *(2.+5.*R_light_nuc(IA2))/(2.+3.*R_light_nuc(IA2))
            ADIF = a_light_nuc(IA2)
      RMAXWS = 5.5 + 0.3*(IA2-6.)/12.
      ELSE IF(IA2.GE.2) THEN
        IF(IA2.EQ.2) THEN
                R0=rms1t(6)
                PFP=pfln(6,1)   ! we have two sea's ***** ThA
                TFP=tfln(6,1)
                V0P=vnuc(6,1)
                PFN=pfln(6,2)
                TFN=tfln(6,2)
                V0N=vnuc(6,2)
        ENDIF
        IF(IA2.EQ.3.AND.IZ2.EQ.1) THEN
                R0=rms1t(7)
                PFP=pfln(7,1)
                TFP=tfln(7,1)
                V0P=vnuc(7,1)
                PFN=pfln(7,2)
                TFN=tfln(7,2)
                V0N=vnuc(7,2)
        ENDIF
        IF(IA2.EQ.3.AND.IZ2.EQ.2) THEN
                R0=rms1t(8)
                PFP=pfln(8,1)
                TFP=tfln(8,1)
                V0P=vnuc(8,1)
                PFN=pfln(8,2)
                TFN=tfln(8,2)
                V0N=vnuc(8,2)
        ENDIF
        IF(IA2.EQ.4) THEN
                R0=rms1t(9)
                PFP=pfln(9,1)
                TFP=tfln(9,1)
                V0P=vnuc(9,1)
                PFN=pfln(9,2)
                TFN=tfln(9,2)
                V0N=vnuc(9,2)
        ENDIF
C For light targets, SP-SN are defined in init_incl and common/light_gaus_nuc/
c (modif AB 9/4/2010)
            SP=V0P-TFP
            SN=V0N-TFN
c
c ***** ThA b : other derived data
c
      V2P=(1.0-ALPH)*V0P+ALPH*(TFP)
      V2N=(1.0-ALPH)*V0N+ALPH*(TFN)
        DELTAV0=V0P-V0N

      if(f(13).lt.1.5)DELTAV0=0

        V0M=V0N-DELTAV0
        V0PP=V0P+DELTAV0
      TFM=V0M-SN
      PFM=SQRT(TFM**2+2*FMP*TFM)
        TFPP=V0PP-SP
      PFPP=SQRT(TFPP**2+2*FMP*TFPP)
      ADIF=0.57735*R0
      RMAXWS=R0+2.5
      END IF

C Enlarge RMAXWS to take into account the distance of interaction
      IF(kindf7.LE.2) THEN
C Nucleon beam:
          SQS=SQRT(2.*FMP**2 +2.*FMP*(TLAB+FMP))
          DINTER=SQRT(STOT(SQS,0,0)/31.416)
          SQS1=SQRT(2.*FMP**2 +2.*FMP*(1000.+FMP))
          DINTER1=SQRT(STOT(SQS1,0,0)/31.416)
          RMAX1=RMAXWS-DINTER1+DINTER
          IF(RMAX1.GT.RMAXWS) RMAXWS=RMAX1
        ELSE
        IF(kindf7.LE.5) THEN
C Pion beam
          SQS=SQRT(FMP**2+FMPI**2+2.*FMP*(TLAB+FMPI))
          DINTER=SPN(SQS,1,2,idnint(f(17)))
          DINTER1=SPN(SQS,-1,2,idnint(f(17)))
          IF(DINTER1.GT.DINTER) DINTER=DINTER1
          DINTER=SQRT(DINTER/31.416)
          RMAX1=RMAXWS-1.0+DINTER
          IF(RMAX1.GT.RMAXWS) RMAXWS=RMAX1
        ELSE
C Light ion beam (Nothing at the moment...threshold results
C already adjusted.. Bimpact spectra to study at low energy later)
        ENDIF
      ENDIF

      IF(NOSURF.GT.0) THEN
            ADIF=0.
      RMAXWS=R0
      END IF


C on impose le rayon du noyau:********************
C   ....voir coherence FUNCTION WSAX(R) et DERIVWSAX(R)

            R2=R0
                RPION=RMAXWS
                RPION2=RPION*RPION
C*************************************************

      TNR=TLAB                                                          P-N02930
      BINC=SQRT(TNR*TNR+2.*TLAB*FMPINC)/(TNR+FMPINC)                    P-N02940
      GINC=1./SQRT(1.-BINC*BINC)                                        P-N02950
      PINC=FMPINC*BINC*GINC                                             P-N02970


      DO I=1,IA
            JPARTICIP(I)=0
      END DO
c
C                                                                       P-N03860
CCC   GENERATION OF THE INITIAL DISTRIBUTION IN THE REST FRAME OF THE IOP-N03870
C                                                                       P-N03880

C **********  bmax definition **************************************
        IFIX=0
        if (kindf7.lt.6)  then
         rmc=rmaxws   ! maximum extension of the nucleus ( W.S.)
        else
         beproj=fmpinc-ia1*fmp
         rmc=rmaxws+2.*rms1   ! maximum extension of the nucleus + HI density
         IF(kindf7.eq.6) THEN
         BAR_COUL=0.2565*ia2**0.6667-0.78
         rmc=1.44*iz1*iz2/BAR_COUL
         rmc=rmc-2.5
         ENDIF
         IF(kindf7.eq.7) THEN
         BAR_COUL=(0.5009*ia2**0.6667-1.16)/2.
         rmc=1.44*iz1*iz2/BAR_COUL
         rmc=rmc-0.5
         ENDIF
         IF(kindf7.eq.8) THEN
         BAR_COUL=0.5009*ia2**0.6667-1.16
         rmc=1.44*iz1*iz2/BAR_COUL
         rmc=rmc-0.5
         ENDIF
         IF(kindf7.eq.9) THEN
         BAR_COUL=0.5939*ia2**0.6667-1.64
         rmc=1.44*iz1*iz2/BAR_COUL
         rmc=rmc-0.5
         ENDIF
         IF(IA2.LT.10) THEN
         RMC=RMAXWS
         BAR_COUL=1.44*iz1*iz2/rmc
         IFIX=2
         ENDIF
        endif

        IF(rmc.LE.R0) THEN
           rmc=R0
           BAR_COUL=1.44*iz1*iz2/rmc
           IFIX=1
        ENDIF
      IF(LCOUL.EQ.1) THEN
C With coulomb deviation, the projectile hyperbola should intercept
C the sphere of radius rmc=RMAXWS for single projectiles and rmaxws+2.*rms1
C for incident clusters.
          IF((rmc-COULF).LE.0.) THEN
             IF(kindf7.lt.6) THEN
C S.H. revised below (2012.5.2). In this low energy case, nopart=-1.
        nopart=-1
        return
             ELSE
             bmax0=0.
             ENDIF
          ELSE
          bmax0=SQRT(rmc*(rmc-COULF))
          ENDIF
        IF(kindf7.lt.6) THEN
          bmax=bmax0           !For structurless projectiles
        ELSE
          bmax=bmax0+2.*rms1   !For composite IN
        ENDIF
      ELSE    !No coulomb deviation
        IF(kindf7.lt.6) THEN
          bmax=RMAXWS          !For structurless projectiles
        ELSE
          bmax=RMAXWS+2.*rms1  !For composite IN
        ENDIF
      ENDIF


      IF(IBERT.EQ.ibw) WRITE(6,*) 'IBERT,BMAX:',IBERT,BMAX
C*********************************************************************

       IRUN=0
      al=rn(0)
      B=sqrt(al)*bmax
      bred=b/r2

      BIMPACT=B


      IF(NOSURF.NE.-2) THEN    ! La suite, c'est la version temps AVANT 2001

           IF(NOSURF.LE.0) THEN
C**********************************
      tnor=70./30.6349
C**********************************
           ELSE
      tnor=1.
           ENDIF
      IF(NOSURF.EQ.0) bred = 0.

       if (kindf7.le.2) then
        if (tlab.lt.400.) then
          cb0=6.86-0.0035*tlab
          eb0=0.32-0.00005*tlab
        else
          if (tlab.lt.1000.) then
            cb0=5.23+0.000575*tlab
            eb0=0.32-0.00005*tlab
          else
            cb0=5.73+0.00007*tlab
            eb0=0.283-0.000013*tlab
          endif
        endif
C S.H. revised 2012/5/1
        temfin=1.25*cb0/dmax1(1.,0.854+.438*bred)
     -     *ia2**(eb0/dmax1(1.,.941+.177*bred))
C S.H. revised 2012/5/1
        temfin = temfin*tnor
C**********************************
      else
       if (kindf7.lt.6)  then
c here for pions:
       temfin=30.*(real(IA2,8)/208.)**0.25*(1.-0.2*bred)*(1.-tlab/1250.)
C correction for pions in the case NOSURF=0 or -1 (A.B., C.V. 2/2002)
       temfin=temfin*tnor
       else
c deutons
         tlabu=tlab/ia1
         if (tlabu.le.400) then
          coeffb0=-0.0035*tlabu+6.86
          expob0=-0.00005*tlabu+0.32
         else
          if (tlabu.le.1000) then
             coeffb0=0.000575*tlabu+5.23
             expob0=-0.00005*tlabu+0.32
          else
              coeffb0=0.00007*tlabu+5.73
              expob0=-0.000013*tlabu+0.283
          endif
         endif
         if (bred.le.0.33333) then
          xc=1.
          xe=1.
         else
          xc=0.438*bred+0.854
          xe=0.177*bred+0.941
         endif
         temfin=1.25*(coeffb0/xc)*ia2**(expob0/xe)
C**********************************
C Same renormalisation of time for p,n and composit particles.
         temfin = temfin*tnor
       endif
      endif

      ELSE        ! Ici,NOSURF=-2 c'est la fonction temps 2001 (avec surface).
         IF(kindf7.GE.3.AND.kindf7.LE.5) THEN
c here for pions (arbitrary multiplied by 2 for surface) (A.B., C.V.) 2/2002:
C modified in april 2003 (more reasonable but not yet checked!)
c modified in June 2005 (function of A and TLAB)
         temfin = 30.18*ia2**0.17*(1-5.7E-5*tlab)
         if(idnint(f(17)).eq.1) temfin=25.5*ia2**0.16  ! Pb208->60fm/c
         ELSE
c here for other hadrons
         temfin = 29.8*ia2**0.16  ! Pb208->70fm/c
C For low energies:
         Dmax=2.*RMAXWS+2.725*rms1
         BETAPROJO=SQRT(TLAB*(TLAB+2.*FMPINC))/(TLAB+FMPINC)
         temfin2=Dmax/BETAPROJO
         temfin=DMAX1(temfin,temfin2)
         ENDIF
      ENDIF

C**********************************
C ATTENTION !!! 30/04/2001 scaling time is now a multiplication factor
      factemp=F(6)
      temfin=temfin*factemp
C init of the actual stopping time value for histograming 12/2011 AB
      t_fin=0.
c
      exi=0.
      nbquit=0
      iqe=0
      idecf=0
      TMAX5=temfin+0.1
      NPION=0
      EFER=0.                                                           P-N03920
C This will count the number of nucleons geometrically
c spectators for H.I. in (missing the rmaxws sphere):
      nb_geom_spect=0
c deutons
      IF (IA1.GT.1) GO TO 7
c deutons
      IF (IA1.EQ.1) THEN
        NESC(1)=0                                                       P-N03940
        IND2(1)=2*IZ1-1                                                 P-N03950
        IND1(1)=0                                                       P-N03960
        X1(1)=0.                                                        P-N03970
        X2(1)=0.                                                        P-N03980
        X3(1)=0.                                                        P-N03990
        P1(1)=0.                                                        P-N04000
        P2(1)=0.                                                        P-N04010
        P3(1)=0.                                                        P-N04020
        hel(1)=0.
        JPARTICIP(1)=1
      nb_jpart=nb_jpart+1
       ELSE
        NPION=1
        IPI(1)=8-2*KINDF7
        Y1(1)=0.
        Y2(1)=0.
        Y3(1)=0.
        Q1(1)=0.
        Q2(1)=0.
        Q3(1)=0.
        Q4(1)=FMPI
      ENDIF
c deutons
      go to 9

    7 s1t1=0.
      s2t1=0.
      s3t1=0.
      sp1t1=0.
      sp2t1=0.
      sp3t1=0.
      do 8 i=1,ia1-1
      hel(i)=0
      nesc(i)=0
      ind2(i)=1
      if (i.gt.iz1) ind2(i)=-1
      ind1(i)=0
c deutons
        JPARTICIP(i)=1
      nb_jpart=nb_jpart+1

      IF(kindf7.EQ.6) THEN
C Deuteron density from Paris potential in q space:
      xq=rn(0)
      qdeut=SPLINEAB(xq)*197.3289
      u=rn(0)
      cstet=u*2 -1
      IF(ABS(cstet).GT.1.) cstet=SIGN(real(1.,8),cstet)
      sitet=SQRT(1.-cstet**2)
      vr=rn(0)
      phi=2.*3.141592654*vr    ! ThA

      p1(i)=qdeut*sitet*COS(phi)
      p2(i)=qdeut*sitet*SIN(phi)
      p3(i)=qdeut*cstet

      IFL_Deuteron_Rspace=1 ! 0 for gaussian, 1 for PARIS-Pot.

      IF(IFL_Deuteron_Rspace.EQ.0) THEN
C...r-space gaussian:
      call rgauss(xga)
      x1(i)=xga*rms1*0.57735
      call rgauss(xga)
      x2(i)=xga*rms1*0.57735
      call rgauss(xga)
      x3(i)=xga*rms1*0.57735
      ELSE
C....or from Paris potential (r is the relative p-n distance):
      xq=rn(0)
      rdeut=SPLINECD(xq)/2.
      u=rn(0)
      cstet=u*2 -1
      IF(ABS(cstet).GT.1.) cstet=SIGN(real(1.,8),cstet)
      sitet=SQRT(1.-cstet**2)
      vr=rn(0)
      phi=2.*3.141592654*vr    ! ThA

      x1(i)=rdeut*sitet*COS(phi)
      x2(i)=rdeut*sitet*SIN(phi)
      x3(i)=rdeut*cstet
      ENDIF

      ELSE ! (Not a deuteron)
C Density of composite as a gaussien in q space and r-space:
      call rgauss(xga)
      p1(i)=xga*pf1*0.57735
      call rgauss(xga)
      p2(i)=xga*pf1*0.57735
      call rgauss(xga)
      p3(i)=xga*pf1*0.57735

      call rgauss(xga)
      x1(i)=xga*rms1*0.57735
      call rgauss(xga)
      x2(i)=xga*rms1*0.57735
      call rgauss(xga)
      x3(i)=xga*rms1*0.57735
      ENDIF

      eps(i)=w(p1(i),p2(i),p3(i),fmp)

      sp1t1=sp1t1+p1(i)
      sp2t1=sp2t1+p2(i)
      sp3t1=sp3t1+p3(i)
      s1t1=s1t1+x1(i)
      s2t1=s2t1+x2(i)
      s3t1=s3t1+x3(i)

    8 continue

      IF(IA1.EQ.2) THEN !Deuteron case; pure correlation
      hel(ia1)=0
      nesc(ia1)=0
      ind2(ia1)=-1
      ind1(ia1)=0
      x1(ia1)=-s1t1
      x2(ia1)=-s2t1
      x3(ia1)=-s3t1
      p1(ia1)=-sp1t1
      p2(ia1)=-sp2t1
      p3(ia1)=-sp3t1
      eps(ia1)=w(p1(ia1),p2(ia1),p3(ia1),fmp)
        JPARTICIP(ia1)=1
      nb_jpart=nb_jpart+1
      s1t1=0.
      s2t1=0.
      s3t1=0.
      sp1t1=0.
      sp2t1=0.
      sp3t1=0.
      ELSE !Not a deuteron
      hel(ia1)=0
      nesc(ia1)=0
      ind2(ia1)=-1
      ind1(ia1)=0
      call rgauss(xga)
      x1(ia1)=xga*rms1*0.57735
      s1t1=s1t1+x1(ia1)
      call rgauss(xga)
      x2(ia1)=xga*rms1*0.57735
      s2t1=s2t1+x2(ia1)
      call rgauss(xga)
      x3(ia1)=xga*rms1*0.57735
      s3t1=s3t1+x3(ia1)

      call rgauss(xga)
      p1(ia1)=xga*pf1*0.57735
      call rgauss(xga)
      p2(ia1)=xga*pf1*0.57735
      call rgauss(xga)
      p3(ia1)=xga*pf1*0.57735

      eps(ia1)=w(p1(ia1),p2(ia1),p3(ia1),fmp)

      sp1t1=sp1t1+p1(ia1)
      sp2t1=sp2t1+p2(ia1)
      sp3t1=sp3t1+p3(ia1)
      DO i=1,ia1
      x1(i)=x1(i)-s1t1/ia1
      x2(i)=x2(i)-s2t1/ia1
      x3(i)=x3(i)-s3t1/ia1
      p1(i)=p1(i)-sp1t1/ia1
      p2(i)=p2(i)-sp2t1/ia1
      p3(i)=p3(i)-sp3t1/ia1
      ENDDO
        JPARTICIP(ia1)=1
      nb_jpart=nb_jpart+1

      ENDIF
C coordinates for projectile density checking:

    9 continue
c deutons
C**********************************************************
C Target preparation for 1<A<5 (with sum of momentum and r =0)
      IF(IA2.GE.2.AND.IA2.LE.4) THEN
1633  s1t1=0.
      s2t1=0.
      s3t1=0.
      sp1t1=0.
      sp2t1=0.
      sp3t1=0.
        X1_target=0.
        X2_target=0.
        X3_target=0.
C Corrected 04/2010 A.B.
      STVINIT=0.

      EFER=0.
      DO 1330 I=IA1+1,IA-1
      NESC(I)=0
      IND2(I)=1                  ! ***** ThA for protons
      PF=PFP
      VKF=V2P
      IF (I.GT.IZ2+IA1) THEN     ! ***** ThA for neutrons
         IND2(I)=-1
         PF=PFN
         VKF=V2N
      ENDIF
      DO 633 J=1,7
      t(j)=rn(0)
  633 CONTINUE
      T(2)=-1.+2.*T(2)
      T(3)=6.283185*T(3)
      T(5)=-1.+2.*T(5)
      T(6)=6.283185*T(6)
      T1=T(2)
      IF(ABS(T1).GT.1.) T1=SIGN(real(1.,8),T1)
      T2=SQRT(1.-T1*T1)
      T3=COS(T(3))
      T4=SIN(T(3))
      T5=T(5)
      IF(ABS(T5).GT.1.) T5=SIGN(real(1.,8),T5)
      T6=SQRT(1.-T5*T5)
      T7=COS(T(6))
      T8=SIN(T(6))
           IF (NOSURF.EQ.1) THEN
      X=R2*T(1)**0.33333333
      Y=PF*T(4)**0.33333333
           ELSE
c surface..W.S.: impulsion (sphere dure), puis R(q)
       t33=t(7)**0.33333333
       Y=PF*t33
       RR=FLIN(t33)
       X=RR*T(4)**0.33333333
c fin surface on a redefini x et y
           END IF
      X1(I)=X*T2*T3
      X2(I)=X*T2*T4
      X3(I)=X*T1
      s1t1=s1t1+x1(i)
      s2t1=s2t1+x2(i)
      s3t1=s3t1+x3(i)
      P1(I)=Y*T6*T7
      P2(I)=Y*T6*T8
      P3(I)=Y*T5
      sp1t1=sp1t1+p1(i)
      sp2t1=sp2t1+p2(i)
      sp3t1=sp3t1+p3(i)
      IND1(I)=0
      EPS(I)=W(P1(I),P2(I),P3(I),FMP)
      PKM=SQRT(P1(I)**2+P2(I)**2+P3(I)**2)
      TKM=SQRT(PKM**2+PM2)-FMP
      V(I)=POTENT(TKM,FMP,VKF,IVFCTE,f(13))
      STVINIT=STVINIT+(EPS(I)-FMP-V(I))
      hel(i)=0.
      EFER=EFER+EPS(I)-FMP

1330  CONTINUE
            hel(ia)=0
            nesc(ia)=0
            ind2(ia)=-1
            ind1(ia)=0
            x1(ia)=-s1t1
            x2(ia)=-s2t1
            x3(ia)=-s3t1
            p1(ia)=-sp1t1
            p2(ia)=-sp2t1
            p3(ia)=-sp3t1
      p_mod = SQRT(P1(IA)**2+P2(IA)**2+P3(IA)**2)
      IF(p_mod.GT.(PFN+0.05)) GO TO 1633           ! ThA: the last part is a neutron => PFN???
        eps(ia)=w(p1(ia),p2(ia),p3(ia),fmp)
      TKM=SQRT(p_mod**2+PM2)-FMP
      V(IA)=POTENT(TKM,FMP,V2N,IVFCTE,f(13))
      STVINIT=STVINIT+(EPS(IA)-FMP-V(IA))
        EFER=EFER+EPS(ia)-FMP

      END IF       !(IA2.GE.2.AND.IA2.LE.4)
C******************************************************
C Target preparation for A>4
      IF(IA2.GT.4) THEN
        X1_target=0.
        X2_target=0.
        X3_target=0.
      DO 1 I=IA1+1,IA                                                   P-N04030
      NESC(I)=0                                                         P-N04040
      IND2(I)=1                  ! ***** ThA for protons
      PF=PFP
      VKF=V2P
      IF (I.GT.IZ2+IA1) THEN     ! ***** ThA for neutrons
         IND2(I)=-1
         PF=PFN
         VKF=V2N
      ENDIF                                                             P-N04060
c surface ajout de t(7) surface.f avait do 6 j=2,7 ici 1,6 ?
    5 DO 6 J=1,7                                                        P-N04070
      t(j)=rn(0)
    6 continue                                                          P-N04120
      T(2)=-1.+2.*T(2)                                                  P-N04130
      T(3)=6.283185*T(3)                                                P-N04140
      T(5)=-1.+2.*T(5)                                                  P-N04150
      T(6)=6.283185*T(6)                                                P-N04160
      T1=T(2)                                                           P-N04170
      IF(ABS(T1).GT.1.) T1=SIGN(real(1.,8),T1)
      T2=SQRT(1.-T1*T1)                                                 P-N04180
      T3=COS(T(3))                                                      P-N04190
      T4=SIN(T(3))                                                      P-N04200
      T5=T(5)                                                           P-N04210
      IF(ABS(T5).GT.1.) T5=SIGN(real(1.,8),T5)
      T6=SQRT(1.-T5*T5)                                                 P-N04220
      T7=COS(T(6))                                                      P-N04230
      T8=SIN(T(6))                                                      P-N04240
           IF (NOSURF.EQ.1) THEN
      X=R2*T(1)**0.33333333                                             P-N04250
      Y=PF*T(4)**0.33333333                                             P-N04260
           ELSE
c surface..W.S.: impulsion (sphere dure), puis R(q)
       t33=t(7)**0.33333333
       Y=PF*t33
       RR=FLIN(t33)
       X=RR*T(4)**0.33333333
c fin surface on a redefini x et y
           END IF
      X1(I)=X*T2*T3                                                     P-N04270
      X2(I)=X*T2*T4                                                     P-N04280
      X3(I)=X*T1                                                        P-N04290
      P1(I)=Y*T6*T7                                                     P-N04300
      P2(I)=Y*T6*T8                                                     P-N04310
      P3(I)=Y*T5                                                        P-N04320
      X1_target=X1_target + X1(I)
      X2_target=X2_target + X2(I)
      X3_target=X3_target + X3(I)
    4 IND1(I)=0                                                         P-N04330
      EPS(I)=W(P1(I),P2(I),P3(I),FMP)                                   P-N04340
      hel(i)=0.
      EFER=EFER+EPS(I)-FMP                                              P-N04350
      PKM=SQRT(P1(I)**2+P2(I)**2+P3(I)**2)
      TKM=SQRT(PKM**2+PM2)-FMP
      V(I)=POTENT(TKM,FMP,VKF,IVFCTE,f(13))
      STVINIT=STVINIT+(EPS(I)-FMP-V(I))
    1 CONTINUE                                                          P-N04360
      X1_target=X1_target/IA2
      X2_target=X2_target/IA2
      X3_target=X3_target/IA2

      END IF                !(IA2.GT.4)

C                                                                       P-N04380
CCC   LOCATION OF incident particle AT POINT (B,Z)                      P-N04390
C                                                                       P-N04400
      R22=R2*R2                                                         P-N04410
C correction 24 janv 99 A.B.
C Kept for angular momentum IN
       BINF=B
C For Ntuple impact parameter (possible choice, see below):
       BIMPACT = BINF
C No coulomb distorsion for zero charges or composite beams (9/06/2010)
C ....accepting now also composite beams (8/03/2011)
      IF(LCOUL.EQ.0.OR.COULF.LE.1.e-6) THEN
       Z=rmc*rmc - B*B       ! Oz value of the entering particle
       ALPM=0.
      ELSE
C Here Coulomb distorsion IN
       rmc0=rmc
       IF(B.GT.bmax0) rmc0=(COULF+SQRT(COULF**2+4.*B*B))/2.

       THRS2 = ATAN(COULF/(2.*B))
       EXC = -1./SIN(THRS2)
       BMIN = (COULF+SQRT(COULF**2 +4*B*B))/2.
       PHYP = (1.+EXC)*BMIN
          argtest=(PHYP/rmc0 -1.)/EXC
          IF(argtest.GE.1..AND.argtest.LE.1.00001) argtest=1.0
       THMAX = ACOS(argtest)
       if(dabs(THMAX).lt.1d-9) THMAX=1d-9 !S.H. added (2013.8.7)
       BNEW = rmc0*COS(THRS2+THMAX)
       PSI = ATAN((1.+EXC*COS(THMAX))/(EXC*SIN(THMAX)))
       ALPM = PSI - 1.5708 +THRS2 +THMAX
       Z=rmc0*rmc0 - BNEW*BNEW
       IF(IBERT.EQ.ibw) THEN
       WRITE(6,*) 'rmc0,argtest',rmc0,argtest
       WRITE(6,*) 'THRS2,EXC,BMIN,PHYP,THMAX,PSI',
     s             THRS2,EXC,BMIN,PHYP,THMAX,PSI
       WRITE(6,*) 'B,bmax0,BNEW,ALPM,Z',B,bmax0,BNEW,ALPM,Z
       ENDIF
C Correction; 9/03/2011. BIMPACT was BNEW before, so the B on the nucleus.
c (in the NTUPLE, only visualization, but also
c for momentum IN which is wrong with PINC along Oz).
       B=BNEW
      ENDIF

      IF (Z.LT.0.) Z=0.
   20 Z=SQRT(Z)                                                         P-N04460


C***********************************************************************
CCC   TRANSCRIPTION IN THE GENERAL FRAME OF REFERENCE                   P-N04500
CCC        (HERE,=LAB FRAME)                                            P-N04510
C                                                                       P-N04520
      BE=0.                                                             P-N04530
      B1=(BINC-BE)/(1.-BE*BINC)                                         P-N04550
      B2=-BE                                                            P-N04560
      G1=1./SQRT(1.-B1*B1)                                              P-N04570
C Random phi angle:
      TBID=rn(0)
      TBID=TBID*6.283185

      IF (kindf7.le.2) THEN
C Here for nucleons
          VKM=V2P
          if (kindf7.eq.2) VKM=V2N
        IF(IVFCTE.EQ.1) THEN
          EPSo=G1*FMP
          P3o=SQRT(EPSo**2-PM2)
          T3P1o=SQRT(P3o**2+PM2)-FMP
          T3P1i=T3P1o*(1.-ALPH)+VKM
C Correction for realistic Q value:
          QV=QVAL(IA2+IA1,IZ2+IZ1,IA1,IZ1)


          IF(kindf7.eq.1) THEN
            T3P1i=T3P1i-(SP+QV)*(1.-ALPH)
            EPSo=EPSo-(SP+QV)
          ELSE
            T3P1i=T3P1i-(SN+QV)*(1.-ALPH)
            EPSo=EPSo-(SN+QV)
          ENDIF

          V(1)=POTENT(T3P1i,FMP,VKM,IVFCTE,f(13))
            EPS(1)=EPSo+V(1)
          P3(1)=SQRT(EPS(1)**2-PM2)
          IF(IBERT.EQ.ibw)
     s           WRITE(6,*) 'Particle 1 enter, EPS(1),V(1),T3P1i',
     s  ' SP,SN, Q value:',EPS(1),V(1),T3P1i,SP,SN,QV
        ENDIF
        IF(IVFCTE.EQ.2) THEN
          V(1)=0.0
   33       EPS(1)=G1*FMP+V(1)
            P3(1)=SQRT(EPS(1)**2-FMP**2)
          T3P1=SQRT(P3(1)**2+FMP**2)-FMP
          VP=POTENT(T3P1,FMP,VKM,IVFCTE,f(13))
            IF(ABS(VP-V(1)).GT.0.0001) THEN
              V(1)=VP
              GOTO 33
            ENDIF
        ENDIF
C Coulomb deviation of incoming nucleon
          IF(LCOUL.EQ.1) THEN
          P3SAVE=P3(1)
          P1(1)=P3SAVE*SIN(ALPM)*COS(TBID)
          P2(1)=P3SAVE*SIN(ALPM)*SIN(TBID)
          P3(1)=P3SAVE*COS(ALPM)
          PINC1=PINC*SIN(ALPM)*COS(TBID)
          PINC2=PINC*SIN(ALPM)*SIN(TBID)
          PINC3=PINC*COS(ALPM)
          ENDIF
      ENDIF

      IF (kindf7.lt.6.AND.kindf7.GT.2) THEN
C Here for pions
C ... with correction for realistic Q value:
        if (kindf7.eq.3) THEN
        V0PI=V0PIP
        QV=FMNUC(IA2,IZ2+1)-FMNUC(IA2,IZ2)+FMPI-FMNUC(0,IZ1)


        ENDIF
        if (kindf7.eq.4) THEN
        V0PI=V0PIN
        QV=FMPI-FMNUC(0,IZ1)
        ENDIF
        if (kindf7.eq.5) THEN
        V0PI=V0PIM
        QV=FMNUC(IA2,IZ2-1)-FMNUC(IA2,IZ2)+FMPI-FMNUC(0,IZ1)


        ENDIF
        q4(1)=g1*fmpi+V0PI-QV
        q3(1)=sqrt(q4(1)**2-fmpi**2)
C Coulomb deviation of incoming pion
          IF(LCOUL.EQ.1) THEN
          P3SAVE=Q3(1)
          Q1(1)=P3SAVE*SIN(ALPM)*COS(TBID)
          Q2(1)=P3SAVE*SIN(ALPM)*SIN(TBID)
          Q3(1)=P3SAVE*COS(ALPM)
          ENDIF
          IF(IBERT.EQ.ibw)
     s           WRITE(6,*) 'Pion 1 enter, Q4(1),V0PI,Q3',
     s  ' Q value:',Q4(1),V0PI,P3SAVE,QV
      ENDIF

      IF (kindf7.GE.6) THEN
C Here for composite projectiles:
C New procedure with potential in the projectile rest frame (12/2010):
C Coulomb deviation of incoming projectile
          IF(LCOUL.EQ.0) THEN
      PINC1=0.
      PINC2=0.
      PINC3=PINC
          ELSE
      PINC1=PINC*SIN(ALPM)*COS(TBID)
      PINC2=PINC*SIN(ALPM)*SIN(TBID)
      PINC3=PINC*COS(ALPM)
	  ENDIF
      ENERGIE_IN=tlab+fmpinc
      Vproj=0.
      DO i=1,ia1
      Vproj=Vproj+eps(i)
      ENDDO
      Vproj=(Vproj-fmpinc)/ia1
C Boost in the lab:
        sueps=0.
	sigp3=0.
        do i=1,ia1
        tte=eps(i)-Vproj
        eps(i)=g1*(tte+b1*p3(i))
        p3(i)=g1*(b1*tte+p3(i))
        sueps=sueps+eps(i)
	sigp3=sigp3+p3(i)
        IF(IBERT.EQ.ibw) THEN
        WRITE(6,*) 'In lab:',i,'E,P123:',
     s                    eps(i),p1(i),p2(i),p3(i)
        WRITE(6,*) 'In Proj rest frame X123:',X1(i),X2(i),X3(i)
        ENDIF
        enddo
        IF(IBERT.EQ.ibw)
     s  WRITE(6,*) 'Vproj,SommeE,SommeP3,fmpinc:',
     s     Vproj,sueps,sigp3,fmpinc
      GO TO 1871 ! End of the new procedure.

C    The kinetic energy is below the threshold. Put all
C    Fermi momentum to 0... projectile nucleons not on shell!
      energie_in=tlab+fmpinc
      IF((energie_in).LE.(ia1*FMP)) THEN
            DO i=1,ia1
            eps(i)=energie_in/ia1
            P1(i)=0.
            P2(i)=0.
            P3(i)=PINC/ia1
            ENDDO
            GO TO 1871
      ENDIF

C    Here the composit is above threshold
      DO i=1,ia1  !save E,P in the composite rest frame
      eps_c(i)=eps(i)
      p3_c(i)=p3(i)
      IF(IBERT.EQ.ibw) WRITE(6,*) i,'E,P123:',eps(i),p1(i),p2(i),p3(i)
      ENDDO

       nbtest=ia1-1
       if(kindf7.EQ.6) nbtest=2
       IFLAG=0
1870        sueps=0.

       IFLAG=IFLAG+1

        do i=1,ia1
        tte=eps_c(i)
        eps(i)=g1*(eps_c(i)+b1*p3_c(i))
        p3(i)=g1*(b1*tte+p3_c(i))
        sueps=sueps+eps(i)
      IF(IBERT.EQ.ibw) WRITE(6,*) 'IFLAG:',IFLAG,i,'LAB E,P123:',
     s                    eps(i),p1(i),p2(i),p3(i)
        enddo

        cobe=(tlab+fmpinc)/sueps
      IF(IBERT.EQ.ibw) WRITE(6,*) 'tlab,fmpinc,sueps,cobe',
     s                       tlab,fmpinc,sueps,cobe
C OFF shell problem for incident clusters (A.B. 2/2002)
                  IF(IFLAG.EQ.nbtest) THEN !Too much..all momentum to 0
                        DO klm=1,ia1
                        eps_c(klm)=FMP
                        P1(klm)=0.
                        P2(klm)=0.
                        P3_c(klm)=0
                        ENDDO
                        GO TO 1870
                  ENDIF
        do i=1,ia1
      ARG = (cobe*eps(i))**2-pm2
            IF (ARG.LE.0.) THEN     ! put maximum momentum to 0.
                  i_emax=1    !find maximum
                  ener_max=eps(1)
                  DO klm=2,ia1
                        IF(eps(klm).GT.ener_max) THEN
                        ener_max=eps(klm)
                        i_emax=klm
                        ENDIF
                  ENDDO
                  eps_c(i_emax)=FMP
                  P1(i_emax)=0.
                  P2(i_emax)=0.
                  P3_c(i_emax)=0.

                  IF(i_emax.EQ.ia1) THEN  !circular permut if the last one
                  epsv=eps_c(ia1)         !permutation circulaire
                  p1v=p1(ia1)
                  p2v=p2(ia1)
                  p3v=p3_c(ia1)
                    DO k=ia1-1,1,-1
                      eps_c(k+1)=eps_c(k)
                      p1(k+1)=p1(k)
                      p2(k+1)=p2(k)
                      p3_c(k+1)=p3_c(k)
                    ENDDO
                    eps_c(1)=epsv
                    p1(1)=p1v
                    p2(1)=p2v
                    p3_c(1)=p3v           !fin permut.

                  ENDIF
                        sp1t1=0.          !re-compute the last one
                        sp2t1=0.
                        sp3t1=0.
                  DO j=1,ia1-1
                          sp1t1=sp1t1+p1(j)
                          sp2t1=sp2t1+p2(j)
                          sp3t1=sp3t1+p3_c(j)
                  ENDDO
                        p1(ia1)=-sp1t1
                        p2(ia1)=-sp2t1
                        p3_c(ia1)=-sp3t1
                        eps_c(ia1)=w(p1(ia1),p2(ia1),p3_c(ia1),fmp)

                  GO TO 1870      !..and boost all of them.
            ENDIF
        enddo

        do i=1,ia1
      ARG = (cobe*eps(i))**2-pm2
        comom=sqrt(ARG/(eps(i)**2-pm2))
        p1(i)=comom*p1(i)
        p2(i)=comom*p2(i)
        p3(i)=comom*p3(i)
        eps(i)=eps(i)*cobe
        enddo

      ENDIF ! end of composite projectiles

1871  CONTINUE
C****************************************************************

C Random azimuthal direction of the impact parameter (sept 99)********
C ...and x1,x2,x3(i)for projectiles in the target (lab) system.
C The random value is done earlier (TBID)

C Initial momentum for all type of incident particles:
C Correction for coulomb distorsion (finally we set the value
C BEFORE coulomb. distorsion for global conservation balanced
C by the remnant).:
C 9/03/2011 Should be in that case B before distorsion (BINF):
      CFCL=1.
      XLP1=BINF*PINC*SIN(TBID)*CFCL
      XLP2=-BINF*PINC*COS(TBID)*CFCL
      XLP3=0.

      IF (kindf7.le.2) THEN
C Here for nucleons
        X1(1)=X1(1)+B*COS(TBID)
        X2(1)=X2(1)+B*SIN(TBID)
        X3(1)=X3(1)-Z
C Counter of p(n) entering the potential 4/2008 AB
        IF(ind2(1).EQ.1) THEN
        npenter=1
        nnenter=0
        IACOUR=IACOUR+1
        IZCOUR=IZCOUR+1
C Modif AB 27/10/2010
        ITCH=ITCH+1
        ELSE
        npenter=0
        nnenter=1
        IACOUR=IACOUR+1
        ENDIF
      ENDIF

      IF (kindf7.lt.6.AND.kindf7.GT.2) THEN
C Here for pions
        y1(1)=y1(1)+b*COS(TBID)
        y2(1)=y2(1)+b*SIN(TBID)
        y3(1)=y3(1)-z
        IZCOUR=IZCOUR - (kindf7-4)
C Modif AB 27/10/2010
        ITCH=ITCH - (kindf7-4)
      ENDIF

      IF (kindf7.GE.6) THEN
C Here for composite projectiles: Found the first entering nucleon
C Note: No angular deviation is considered for counting nmiss. This
C counter is only to search for ilm based on impact parameter
C compared to Rmaxws.
         IFL_BOUND_PROJ=1       ! Flag global projectile ON
         nspecg = 0             ! Number of proj spectators
         enerspg = 0.           ! Additional energy needed for PS on shell
         nmiss=0.
         xlengm=1000.

         IF(LCOUL.EQ.0.OR.COULF.LE.1.e-6) THEN
           BC=B
         ELSE
            eta=ASIN(BNEW/rmc0)
           BC=rmc0*SIN(eta+ALPM)
           IF((eta+ALPM).GT.1.5708) BC=rmc0*SIN(1.5708)
         ENDIF
C For the NTUPLE:

         do 21 i=1,ia1
C Histos for density evolution

         x3(i)=x3(i)/ginc
         zai2=RMAXWS*RMAXWS-(BC+x1(i))**2-x2(i)**2
         if (zai2.lt.0.) go to 22
         kpart(i)=1             ! participants of the proj (if =1)
         ztu=-sqrt(zai2)
         za_i=2.*RMAXWS+ztu
         xleng=za_i-x3(i)
         if (xleng.gt.xlengm) go to 21
         ilm=i
         xlengm=xleng
         ztouch=ztu
         go to 21
   22    nmiss=nmiss+1
         kpart(i)= 0 ! participants of the proj (if =1)
         nspecg = nspecg +1
         T2=P1(i)*P1(i)+P2(i)*P2(i)+P3(i)*P3(i)
         EPSOLD=EPS(i)

      IF(kindf7.EQ.6.AND.IZ2.GE.50) THEN
C Polarization of the deuteron: n always first entering:
         prob=(IZ2-50)/30.
         IF(prob.GT.1.) prob=1.
         rndm=rn(0)
        IF(rndm.LT.prob) THEN
         ind2(i)=1
         IF(i.EQ.1) THEN
         ind2(2)=-1
         ELSE
         ind2(1)=-1
         ENDIF
        ENDIF
      ENDIF

C Spectator of proj on shell:
C Correction: Real mass 14/06/2011 AB
         IF(ind2(i).EQ.1) THEN
         FMLOC=FMNUC(1,1)
         ELSE
         FMLOC=FMNUC(1,0)
         ENDIF
         EPS(i)= SQRT(T2+FMLOC**2)

         enerspg = enerspg + EPS(i)-EPSOLD
   21    continue
      n_flag_nb_spect=nspecg
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'BC, Number of transparents (b(i)>Rmaxws) nmiss:',
     s           BC,nmiss
      WRITE(6,*) 'RMAXWS:',RMAXWS
      ENDIF

         if (nmiss.eq.ia1) then
             nopart=-10
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'No nucleon can enter (return) TRANSPARENT'
      ENDIF
           t_fin=tim
           RETURN
         endif

      IF(kindf7.EQ.6.AND.IZ2.GE.50) THEN
C Polarization of the deuteron: n always first entering:
         prob=(IZ2-50)/30.
         IF(prob.GT.1.) prob=1.
         rndm=rn(0)
        IF(rndm.LT.prob) THEN
         ind2(ilm)=-1
         IF(ilm.EQ.1) THEN
         ind2(2)=1
         ELSE
         ind2(1)=1
         ENDIF
        ENDIF
      ENDIF

C Geometrical position in the lab:
          zshif=x3(ilm)-ztouch
          do i=1,ia1
          xxx=x1(i)+BC
          zzz=x3(i)-zshif
          r_trans2(i)=xxx**2+X2(i)**2 !Transv coord to Oz paral to HI axis
C Rotation in the lab (Coulomb deviation)
          xlab=xxx*cos(ALPM)+zzz*sin(ALPM)
          zlab=-xxx*sin(ALPM)+zzz*cos(ALPM)
          pxlab=P1(i)*cos(ALPM)+P3(i)*sin(ALPM)
          pzlab=-P1(i)*sin(ALPM)+P3(i)*cos(ALPM)
C Random PHI:
          X1(i)=xlab*cos(TBID)-x2(i)*sin(TBID)
          X2(i)=xlab*sin(TBID)+x2(i)*cos(TBID)
          X3(i)=zlab
          P1(i)=pxlab*cos(TBID)-P2(i)*sin(TBID)
          P2(i)=pxlab*sin(TBID)+P2(i)*cos(TBID)
          P3(i)=pzlab
          enddo

C ****************** Unused part ******************************
      GO TO 7760
C Search for geometrical spectators:
      nspecg=0
      enerspg=0.
      DO i=1,ia1
      kpart(i)=1
      IF(i.EQ.ilm) GO TO 1038
      T1=X1(i)*P1(i)+X2(i)*P2(i)+X3(i)*P3(i)
      T2=P1(i)*P1(i)+P2(i)*P2(i)+P3(i)*P3(i)
      T3=T1/T2
      T4=X1(i)*X1(i)+X2(i)*X2(i)+X3(i)*X3(i)
c incoming nucleons enter potential at maximum radius (modif. 13/06/01)
      T5=T3*T3+(RMAXWS*RMAXWS-T4)/T2
        IF (T5.LT.0.) GO TO 1037
      TREF=(-T3-SQRT(T5))
C Correction DM,AB for composit IN at low energy (backward propagation) 19/02/2010
        IF(TREF.LE.0.) GO TO 1037
        IF (TREF*EPS(I).GT.TMAX5) GO TO 1037
      TREF_HI(i) = TREF         !Store time/eps to build the time to reach RMAXWS
C This nucleon of the proj will enter later (participant):
      GO TO 1038
C This nucleon will never enter: spectator
1037  CONTINUE
      nspecg=nspecg+1
      enerspg=enerspg+SQRT(T2+FMP**2)-EPS(i)
      kpart(i)=0
      TREF_HI(i) = 50000.
      IF(IBERT.EQ.ibw)
     s WRITE(6,*) 'Spectateur projo (off shell), i, E, P:',
     s i,EPS(i),SQRT(T2)
      eps(i)=SQRT(T2+FMP**2)
1038  CONTINUE
      ENDDO
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'ilm,b,nb spect,enerspg:',ilm,b,nspecg,enerspg
      WRITE(6,*) 'kpart:',(kpart(iloc),iloc=1,4)
      ENDIF

7760   CONTINUE
C******************************************************
C Modification of participant energies for spectators on shell:
C...Now preparing the threshold test for a possible compound nuc.
      delener=enerspg/(ia1-nspecg)
      sume_check=0.
      sump1_check=0.
      sump2_check=0.
      sump3_check=0.
      iap=0
      izp=0
      sumep=0.
      sump1p=0.
      sump2p=0.
      sump3p=0.
      DO i=1,ia1
        IF(kpart(i).EQ.1) THEN
C Change participant energies for geom spect. on shell:
           eps(i)=eps(i)-delener
           sume_check=sume_check+eps(i)
           sumep=sumep+eps(i)
           sump1p=sump1p+P1(i)
           sump2p=sump2p+P2(i)
           sump3p=sump3p+P3(i)
           IF(IND2(i).EQ.1) THEN
              iap=iap+1
              izp=izp+1
           ELSE
              iap=iap+1
           ENDIF
        ELSE
           sume_check=sume_check+eps(i)
        ENDIF
      sump1_check=sump1_check+P1(i)
      sump2_check=sump2_check+P2(i)
      sump3_check=sump3_check+P3(i)
      IF(IBERT.EQ.ibw)
     s WRITE(6,*) 'spect on shell,E,P123:',eps(i),p1(i),p2(i),p3(i)
      ENDDO

      IF(IBERT.EQ.ibw)
     s WRITE(6,*) 'E,P123:',
     s   sume_check,sump1_check,sump2_check,sump3_check

C Flag for NOT a compound nuclei.
      ifl_compound_nuc=0

C Check threshold for the composite nuclei with participant nucleons:
      IANC=IA2+iap
      IZNC=IZ2+izp
      FM_CMPNUC=FMNUC(IANC,IZNC)
      FM_TG=FMNUC(IA2,IZ2)
      ECM_invar=(FM_TG+sumep)**2 -sump1p**2 -sump2p**2 -sump3p**2
      IF(IBERT.EQ.ibw)
     s WRITE(6,*) 'iap,izp,FM_CMPNUC,FM_TG,Malpha,sqrt_S,sumep:',
     s  iap,izp,FM_CMPNUC,FM_TG,FMNUC(4,2),SQRT(ECM_invar),sumep
      IF(ECM_invar.LE.FM_CMPNUC**2) THEN
         t_fin=tim
         NOPART=-11
         RETURN
      ENDIF

C Save the state of projectile nucleon for future compound nucleus (if
C energy is smaller than Tf during the cascade) and go to normal cascade.
      DO i=1,ia1
        IND2C(i)=IND2(i)
        EPSC(i)=EPS(i)
        X1C(i)=X1(i)
        X2C(i)=X2(i)
        X3C(i)=X3(i)
        P1C(i)=P1(i)
        P2C(i)=P2(i)
        P3C(i)=P3(i)
      ENDDO

C Below it will be a normal cascade with all nucleons above Tf entering at RmaxWS.
c The first nucleon ilm in the potential:
      IF (ind2(ilm).eq.1) THEN
      VKM=V2P
      VK0=V0P
      TFK=TFP
      PFK=PFP
      SK=SP
          QV=FMNUC(IA2+1,IZ2+1)-FMNUC(IA2,IZ2)-FMP
      ELSE
      VKM=V2N
      VK0=V0N
      TFK=TFN
      PFK=PFN
      SK=SN
          QV=FMNUC(IA2+1,IZ2)-FMNUC(IA2,IZ2)-FMP
      ENDIF
C Correction for realistic Q value:
            EPSilm0=EPS(ilm)-(SK+QV)

      Tilmo=EPSilm0-FMP
      Tilmi=Tilmo*(1.-ALPH)+VKM
C Go to compound nucleus:
        IF(Tilmi.LE.TFK) THEN
        nb_belowtf=nb_belowtf+1
        GO TO 1492
        ENDIF

      IF(IBERT.EQ.ibw) WRITE(6,*) 'EPS_out,T(ilm)_in (Q val corrected)'
     s ,',TF,VKM:',
     s EPSilm0,Tilmi,TFK,VKM,IND2(ilm)

        V(ilm)=POTENT(Tilmi,FMP,VKM,IVFCTE,f(13))
        EPSilm=EPSilm0+V(ilm)
        Pilmi=SQRT(EPSilm**2-PM2)
C ilm inside the pot at RMAXWS:
        EPS(ilm)=EPSilm
        Pilmo=SQRT(p1(ilm)**2+p2(ilm)**2+p3(ilm)**2)
        CORRI=0.0
        IF (Pilmo.GT.0.) CORRI=Pilmi/Pilmo
          p1(ilm)=CORRI*p1(ilm)
          p2(ilm)=CORRI*p2(ilm)
          p3(ilm)=CORRI*p3(ilm)
C Counter of p(n) entering the potential 4/2008 AB
          IF(ind2(ilm).EQ.1) THEN
          npenter=1
          nnenter=0
        IACOUR=IACOUR+1
        IZCOUR=IZCOUR+1
C Modif AB 27/10/2010
        ITCH=ITCH+1
          ELSE
          npenter=0
          nnenter=1
        IACOUR=IACOUR+1
          ENDIF
        IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'ilm first entering, npenter,nnenter,bimpact:',
     s    ilm,npenter,nnenter,bimpact
        ENDIF


      IF(IBERT.EQ.ibw) THEN
c check:
      WRITE(6,*) 'ilm at rmax: E,P123,V,Tin,Q value,ind2:',
     s  EPS(ilm),p1(ilm),p2(ilm),p3(ilm),V(ilm),Tilmi,QV,ind2(ilm)
      WRITE(6,*) '   Composite beam particles IBERT:',IBERT
      WRITE(6,*) 'i,eps(i),p1(i),p2(i),p3(i),V(i),ind2(i):'
      DO iloc=1,ia1
      WRITE(6,*) iloc,eps(iloc),p1(iloc),p2(iloc),p3(iloc),
     s V(iloc),ind2(iloc)
      ENDDO
      ENDIF


      ENDIF
      goto 1494

C *******************************************************************
C At least one nucleon entering below Tf. Force compound nucleus?
C *******************************************************************
C Back from cascade if one nucleon enters below Tf:
1492  CONTINUE
      DO i=1,ia1
        IND2(i)=IND2C(i)
        EPS(i)=EPSC(i)
        X1(i)=X1C(i)
        X2(i)=X2C(i)
        X3(i)=X3C(i)
        P1(i)=P1C(i)
        P2(i)=P2C(i)
        P3(i)=P3C(i)
      ENDDO

C Q value to go to the compound nucleus:
      QV_NC = FM_CMPNUC - FM_TG
      DO i=1,ia1
        IF(kpart(i).EQ.1) THEN
          IF(IND2(i).EQ.1) THEN
            QV_NC = QV_NC - FMNUC(1,1)
          ELSE
            QV_NC = QV_NC - FMNUC(1,0)
          ENDIF
        ENDIF
      ENDDO
      QV_NC = QV_NC/iap

C Comparison of participant energies (in) with Tf:
      IFLGOOD_LE_TF=0
      IFL_LE_TF=0
      DO i=1,ia1
      IF(kpart(i).EQ.1) THEN
        IF (ind2(i).eq.1) THEN
          VKM=V2P
          VK0=V0P
          TFK=TFP
          PFK=PFP
          SK=SP
        ELSE
          VKM=V2N
          VK0=V0N
          TFK=TFN
          PFK=PFN
          SK=SN
        ENDIF
C Correction for realistic Q value (compound nucleus):
      EPSilm0=EPS(i)-(SK+QV_NC)
      Tilmo=EPSilm0-FMP
      Tilmi=Tilmo*(1.-ALPH)+VKM

C Compare to TF value and option 3 of V(T) and Correction for realistic Q value:
        IF(Tilmi.LE.TFK) THEN
         IF(f(13).GT.2.5) Tilmi=Tilmo+VK0
         IF(Tilmi.LE.0.) THEN
            t_fin=tim
            NOPART=-2
            RETURN
         ENDIF

C Keep the version 4.6.ab.21 ....fully empirical choice! 22/02/2012

      IFL_LE_TF = IFL_LE_TF + 1
      V(i)=POTENT(Tilmi,FMP,VKM,IVFCTE,f(13))
      EPSilm=EPSilm0+V(i)
      Pilmi=SQRT(EPSilm**2-PM2)
C i can enter in the pot at radius R(p)?
C....with the global motion of the projectile:
C i is at a NN interaction-distance from the target?

C Keep the version 4.6.ab.21 ....fully empirical choice! 22/02/2012
      SQS=2.*FMP+TLAB/ia1

      DINTER=(STOT(SQS,0,0)+ STOT(SQS,0,2))/2.
      DINTER=SQRT(DINTER/31.416)
      DINTER=DINTER+R0
C....with the global motion of the projectile:
      IF(r_trans2(i).GT.DINTER*DINTER) GO TO 379

C YES, this nucleon of the proj can enter in the nucleus.
      IFLGOOD_LE_TF = IFLGOOD_LE_TF + 1
379   CONTINUE
        ENDIF   !IF line 2422

      ENDIF
      ENDDO

c Restore the value of ncol_2c for the ntuple
      ncol_2c=incol_2c

      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'KPART:',(KPART(iloc),iloc=1,4)
      WRITE(6,*) 'EPS:',(EPS(iloc),iloc=1,4)
      WRITE(6,*) IFL_LE_TF,IFLGOOD_LE_TF
      ENDIF

C Test to continue the cascade or produce a compound nucleus:
C....All nucleons below Tf can reach their potential R(p)?:
C....At least one of them can enter its potential R(p)? (other possibility):
       IF(IFLGOOD_LE_TF.EQ.0) THEN
         t_fin=tim
         NOPART=-3
         RETURN
       ENDIF
C  Produce a compound nucleus:
        NOPART = 0
C With coulomb trajectories the compound nucleus is the
C   difference between the asymptotic projectile and the
C   deviated spectators (21/03/2011)
      PINC1=0.
      PINC2=0.
      PINC3=PINC
        DO i=1,ia1
          IF(KPART(i).EQ.0) THEN
            NOPART = NOPART + 1
            ic33=(IND2(i)+3)/2
            KIND(NOPART)=3-ic33
         IF(ind2(i).EQ.1) THEN
         FMLOC=FMNUC(1,1)
         ELSE
         FMLOC=FMNUC(1,0)
         ENDIF
            EP(NOPART)=EPS(i)-FMLOC
            ptotl=sqrt(p1(i)**2+p2(i)**2+p3(i)**2)
            alpha(NOPART)=p1(i)/ptotl
            beta(NOPART)=p2(i)/ptotl
            gam(NOPART)=p3(i)/ptotl
            TVT(NOPART) = 0.
            PINC1=PINC1-P1(i)
            PINC2=PINC2-P2(i)
            PINC3=PINC3-P3(i)
            XLP1=XLP1-X2(i)*P3(i)+X3(i)*P2(i)
            XLP2=XLP2-X3(i)*P1(i)+X1(i)*P3(i)
            XLP3=XLP3-X1(i)*P2(i)+X2(i)*P1(i)
          ELSE
C Projectile density leading to compound nucleus:
          ENDIF
        ENDDO
            sump1p=PINC1
            sump2p=PINC2
            sump3p=PINC3
            XL1=XLP1
            XL2=XLP2
            XL3=XLP3
            L=int(SQRT(XL1**2+XL2**2+XL3**2)/HC + 0.5)

          IAREM = IANC
          IZREM = IZNC
          PREM = SQRT(sump1p**2 + sump2p**2 + sump3p**2)
          ALREM = sump1p/PREM
          BEREM = sump2p/PREM
          GAREM = sump3p/PREM
          EREM = sumep + FM_TG
          ESREMD = SQRT(EREM**2 - PREM**2) - FM_CMPNUC
C The following test can arrive since the previous test on comp. nuc.
C threshold was done with the FMP masses of the participant nucleons.
          IF(ESREMD.LT.0.) THEN
             t_fin=tim
             NOPART=-11
             RETURN
        IF(IBERT.EQ.ibw)
     s  WRITE(6,*) IBERT,'IBERT Negative excit of comp nucl:',ESREMD
          ENDIF
          ERECREMD = EREM - FM_CMPNUC - ESREMD
C Real*4 for outgoing argument:
          ESREM=ESREMD
          ERECREM=ERECREMD

          BIMPACT = BINF
          T_FIN = 0.
C Flag, This is a compound nucleus:
          ifl_compound_nuc=1
      IF(IBERT.EQ.ibw) THEN
      PTEST=SQRT(ERECREM*(ERECREM+2.*(FM_CMPNUC+ESREM)))
      PTESTD=SQRT(ERECREMD*(ERECREMD+2.*(FM_CMPNUC+ESREMD)))
      WRITE(6,*) 'IAREM,IZREM,PREM,ALREM,BEREM,GAREM,ESREM,ERECREM:'
      WRITE(6,*) IAREM,IZREM,PREM,ALREM,BEREM,GAREM,ESREM,ERECREM
      WRITE(6,*) 'PINC,PTEST,PTESTD,FM_CMPNUC,EREM:',
     s PINC,PTEST,PTESTD,FM_CMPNUC,EREM
      DO iloc=1,NOPART
      WRITE(6,*) 'I,EP,ALPHA,BETA,GAM:',
     s     iloc,EP(iloc),ALPHA(iloc),BETA(iloc),GAM(iloc)
      ENDDO
      ENDIF
        t_fin=tim
        BIMPACT=-BIMPACT   !Identif of Compound nucleus before cascade
        RETURN          !Remnant is a Compound nucleus

1494   continue
C***********************************************************************

      IF (ibert.EQ.ibw) THEN
      WRITE(6,*) '*******************************'
      Write(6,*) 'IBERT,ilm,STVINIT:',IBERT,ilm,STVINIT
      DO iloc=1,IA
      Write(6,*) 'i,EPS(i),V(i),P,IND2(i):',
     s iloc,EPS(iloc),V(iloc),P1(iloc),P2(iloc),P3(iloc),IND2(iloc)
      ENDDO
      ENDIF

C                                                                       P-N04680
CCC   EVALUATION OF THE TIMES T(A,B)                                    P-N04690
C                                                                       P-N04700
      K=0                                                               P-N04710

C modif 12/2011 AB: Discussed with DM to perform the reflections before
C deciding that it is a transparent. This suppressed also negative values of TFIN
C for clusters on transparent projectiles.
      KCOL=1

      if (kindf7.le.2) then
      DO 40 I=1,IA
      IF(IND2(I).EQ.1) PF=PFP
      IF(IND2(I).EQ.-1) PF=PFN
      TREF=REF(X1(I),X2(I),X3(I),P1(I),P2(I),P3(I),EPS(I),R22,PF)       P-N04740
      IF (TREF.GT.TMAX5) GO TO 45                                       P-N04750
      K=K+1                                                             P-N04760
      CROIS(K)=TREF                                                     P-N04770
      IND(K)=I                                                          P-N04780
      JND(K)=-1                                                         P-N04790
   45 I1=I-1                                                            P-N04800
      if (i.eq.1) go to 40
C ICI on ne calcule que les interactions NN impliquant le projectile !!! (2/02)
                          IF (I1.GT.IA1) I1=IA1
C**********************************************************************
      DO 41 J=1,I1                                                      P-N04810
c    no collisions before the first collision of the incident particle
      CALL TIME_b (I,J)                                                   P-N04820
      IF (TA.LT.0.) GO TO 41                                            P-N04830
      IF(TA.GT.TMAX5) GO TO 41                                          P-N04840
      IF(LOCE.NE.0) THEN
          CALL EIJLOC(I,J,EIJ)
c
      ELSE
      EIJ=AM(P1(I)+P1(J),P2(I)+P2(J),P3(I)+P3(J),EPS(I)+EPS(J))         P-N04850
      ENDIF
      IF (EIJ.LT.CUTNN) GO TO 41                                        P-N04860
      ISOS=IND2(I)+IND2(J)                                              P-N04870
      R_N1=SQRT(X1(I)**2+X2(I)**2+X3(I)**2)
      R_N2=SQRT(X1(J)**2+X2(J)**2+X3(J)**2)
      IF (31.4159265358979*RAB2.GT.STOT(EIJ,0,ISOS)) GO TO 41           P-N04880
      K=K+1                                                             P-N04890
      IF (J.EQ.1) KCOL=KCOL+1                                           P-N04900
      CROIS(K)=TA                                                       P-N04910
      IND(K)=I                                                          P-N04920
      JND(K)=J                                                          P-N04930
   41 CONTINUE                                                          P-N04940
   40 CONTINUE                                                          P-N04950
      else
c deutons
      if (kindf7.lt.6) then
C Here for incoming pions:
c on teste si le pion incident peut sortir
      if(idnint(f(17)).ne.1)then
       ij=1
       TREF=REFPI(ij,RPION2)
       if(f(16).lt.0.5) tref=10.0*TMAX5
       IF (TREF.LT.TMAX5) then
         K=K+1
         CROIS(K)=TREF
         IND(K)=IA+1
         JND(K)=-2
       ENDIF
       endif
      do i=ia1+1,ia
      IF(IND2(I).EQ.1) PF=PFP
      IF(IND2(I).EQ.-1) PF=PFN
      TREF=REF(X1(I),X2(I),X3(I),P1(I),P2(I),P3(I),EPS(I),R22,PF)
       IF (TREF.LT.TMAX5) then
         K=K+1
         CROIS(K)=TREF
         IND(K)=I
         JND(K)=-1
       ENDIF
      enddo
      call new2(1,0,idnint(f(17))) ! ***** ThA
C Modif A.B. 21/06/2002: Should check at least one valid collision
C    with incoming pion.
       IF(K.NE.0) KCOL=1
c deutons
      else

c incoming nucleons enter potential at maximum radius (modif. 13/06/01)
C Correction DM,AB for composit IN at low energy 19/02/2010
C This nucleon of the proj can enter later in the nucleus:

C**************************************************
C counter for the number of spectators (composite projectiles)
      NB_SPECT = IA1
c Logic reorganised (more clear?) AB 25/02/2010
      nb_geom_spect=ia1
      DO 38 i=1,ia1
C Participant nucleons are setted to BOUND nucleons:
      IBOUND_NUC(i)=KPART(i)
      nesc(i)=1
      tevt(i)=tim
      IF(IFL_BOUND_PROJ.EQ.1) THEN
      EPSSP=ENERGIE_IN
      P1SP=PINC1
      P2SP=PINC2
      P3SP=PINC3
      ELSE
      EPSSP=EPS(i)
      P1SP=P1(i)
      P2SP=P2(i)
      P3SP=P3(i)
      ENDIF
      IF (i.EQ.ilm) THEN
C Explicit TREF for ilm (should be above Tf to exit at RMAXWS)
      T1=X1(i)*P1SP+X2(i)*P2SP+X3(i)*P3SP
      T2=P1SP*P1SP+P2SP*P2SP+P3SP*P3SP
      T3=T1/T2
      T4=X1(i)*X1(i)+X2(i)*X2(i)+X3(i)*X3(i)
c incoming nucleons enter potential at maximum radius (modif. 13/06/01)
      T5=T3*T3+(RMAXWS*RMAXWS-T4)/T2
        IF (T5.LT.0.) GO TO 38
      TREF=(-T3+SQRT(T5))*EPSSP
        IF (TREF.GT.TMAX5) GO TO 38
C Correction DM,AB for composit IN at low energy 19/02/2010
        IF(TREF.LE.0.) GO TO 38

      nesc(i)=0
      npproj(i)=0
      nb_geom_spect=nb_geom_spect-1
      NB_SPECT = NB_SPECT-1
      ELSE
      T1=X1(i)*P1SP+X2(i)*P2SP+X3(i)*P3SP
      T2=P1SP*P1SP+P2SP*P2SP+P3SP*P3SP
      T3=T1/T2
      T4=X1(i)*X1(i)+X2(i)*X2(i)+X3(i)*X3(i)
c incoming nucleons enter potential at maximum radius (modif. 13/06/01)
      T5=T3*T3+(RMAXWS*RMAXWS-T4)/T2
        IF (T5.LT.0.) GO TO 38
      TREF=(-T3-SQRT(T5))*EPSSP
        IF (TREF.GT.TMAX5) GO TO 38
C Correction DM,AB for composit IN at low energy 19/02/2010
        IF(TREF.LE.0.) GO TO 38
C This nucleon of the proj can enter later in the nucleus:
      npproj(i)=1
      nb_geom_spect=nb_geom_spect-1
      ENDIF
      K=K+1
      CROIS(K)=TREF
      IND(K)=I
      JND(K)=-1
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'L1 at surface TIM (Avatar stored):',I,TREF
      WRITE(6,*) '  P123,EPS:',P1(I),P2(I),P3(I),EPS(I)
      WRITE(6,*) '  R123:',X1(I),X2(I),X3(I)
      ENDIF
   38 continue
C**************************************************

      kcol=1

      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'i,npproj(i),jparticip(i),nb_jpart:',
     s(iloc,npproj(iloc),jparticip(iloc),iloc=1,ia1),
     s nb_jpart
      ENDIF

      DO  39 I=IA1+1,IA
      npproj(i)=0
      IF(IND2(I).EQ.1) PF=PFP
      IF(IND2(I).EQ.-1) PF=PFN
      TREF=REF(X1(I),X2(I),X3(I),P1(I),P2(I),P3(I),EPS(I),R22,PF)
      IF (TREF.LT.TMAX5) then
       K=K+1
       CROIS(K)=TREF
       IND(K)=I
       JND(K)=-1
       endif
      CALL TIME_b (I,ILM)
      IF (TA.LT.0.) GO TO 39
      IF (TA.GT.TMAX5) GO TO 39
      IF(LOCE.NE.0) THEN
          CALL EIJLOC(I,ILM,EIJ)
      ELSE
      EIJ=AM(P1(I)+P1(ILM),P2(I)+P2(ILM),P3(I)+P3(ILM),EPS(I)+EPS(ILM))
      ENDIF
      IF (EIJ.LT.CUTNN) GO TO 39
      ISOS=IND2(I)+IND2(ILM)
      R_N1=SQRT(X1(I)**2+X2(I)**2+X3(I)**2)
      R_N2=SQRT(X1(ILM)**2+X2(ILM)**2+X3(ILM)**2)
      IF (31.4159265358979*RAB2.GT.STOT(EIJ,0,ISOS)) GO TO 39
      K=K+1
      KCOL=KCOL+1
      CROIS(K)=TA
      IND(K)=I
      JND(K)=ILM
   39 CONTINUE
      endif
      endif
c deutons
      IF (KCOL.eq.0) then
!     No collisions are possible; we try to make a cluster with the
!     escaping projectile nucleon
!     NOT here for transparent of a cluster projectile!

!     Move the nucleon to its final position
         vdvd1 = p1(1) / eps(1)
         vdvd2 = p2(1) / eps(1)
         vdvd3 = p3(1) / eps(1)
         xsquare = x1(1)**2 + x2(1)**2 + x3(1)**2
         vsquare = vdvd1**2 + vdvd2**2 + vdvd3**2
         tau = x1(1)*vdvd1 + x2(1)*vdvd2 + x3(1)*vdvd3
         tau = sqrt( tau**2 - (xsquare-rmaxws**2)*vsquare ) - tau
         tau = tau / vsquare
         TA=TAU/EPS(1)
         X1(1)=X1(1)+P1(1)*TA
         X2(1)=X2(1)+P2(1)*TA
         X3(1)=X3(1)+P3(1)*TA
         tim=tau
         L1=1
C Modif AB 27/10/2010
         itch=iz2+iz1
         ncol=0
! Jump to cluster code
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'No collisions possible ilm:',ilm
      ENDIF
         goto 608
      end if
C                                                                       P-N05000
CCC   INITIALIZATION  AT THE BEGINNING OF THE RUN                       P-N05010
C                                                                       P-N05020
   48 TIMI=0.                                                           P-N05030
      TIM=0.                                                            P-N05040
      NCOL=0                                                            P-N05050
C compteur des collisions a deux corps (call collis acceptes par pauli)
      NCOL_2C=0
C Energie maximale d'un nucleon IN au dessus de TF (critere d'arret):
C Differentiaton p/n: 15/11/2011 AB  (DELTA sans BCP barriere Coulombiennne)
      EIN_MAX = 10.

      BCP=1.44*IZ2/r_zero_prot
C test (correction) 19/01/2012 AB,DM
      BCP=2.*BCP/3.

C correction 19/0/2012 AB
      EIN_MAXP = EIN_MAX
      EIN_MAXN = EIN_MAX
      NB_SUPE = 0
      IF(kindf7.LT.6) THEN
c Note: for pion IN, EPS(1) is a target nucleon, so < TF
C correction 19/0/2012 AB: EPS Should be compared to Tf + EIN_MAXp(n)
C but this choice makes a conservative init of NB_SUPE=1 which is then
C actualized or not (f(14) choice) and TESTED <= 0 to stop the cascade.
          IF(IND2(1).EQ.1.AND.EPS(1).GE.EIN_MAXP) NB_SUPE = 1
          IF(IND2(1).EQ.-1.AND.EPS(1).GE.EIN_MAXN) NB_SUPE = 1
      ELSE
C For an in HI, the nucleon ilm is below TF if entering at 600CONTINUE
          IF(IND2(ilm).EQ.1.AND.EPS(ilm).GE.EIN_MAXP) NB_SUPE = 1
          IF(IND2(ilm).EQ.-1.AND.EPS(ilm).GE.EIN_MAXN) NB_SUPE = 1
      ENDIF
C Init for Global statistical Pauli:
      IF(NPAULSTR.EQ.2) THEN
C  Number of slices in the Fermi sea:
      nblevels=1
      CALL GLBP_INIT(nblevels)
C Init of particles below fermi sea
      ENDIF

C Correction for exact nucleon mass in Delta decays OUTSIDE:
      EOUTDM=0.

C Test counters:
      nbiok0 = 0
      nbiok1 = 0
      nbiok2 = 0

C---  NPION=0                                                           P-N05060
      MRNN=0                                                            P-N05070
      MRND=0                                                            P-N05080
      MRDD=0                                                            P-N05090
      MRDN=0                                                            P-N05100
      MRDP=0                                                            P-N05110
      MRPD=0                                                            P-N05120
      MCDD=0                                                            P-N05130
      MPAUL2=0                                                          P-N05140
      MPAUL1=0                                                          P-N05150

C Approx. (not considering escaping protons of incident clusters) 11/03 A.B.
C number of participants (substract geometrical spectators for HI in):
      nb_jpart=nb_jpart-nb_geom_spect
      IF(IBERT.EQ.ibw)
     s WRITE(6,*) 'nb_jpart (take account of geom spectators):',nb_jpart

      DO 47 I=1,IA                                                      P-N05170
      TLG(I)=0.                                                         P-N05180
   47 NC(I)=0                                                           P-N05190
      ITT=1                                                             P-N05200

C                                                                       P-N05210
CCC   SEARCH FOR THE SMALLEST POSITIVE T(A,B)                           P-N05220
C                                                                       P-N05230
C Pour tests, =0 interdit les  reflexions avant un avatar du projectile,
C             =1 comme avant (reflexions autorisees). (A.B. 3/2002)
                irst_avatar=1

  449 NEXT=1                                                            P-N05240
      INDIC(NEXT)=1                                                     P-N05250
   44 IF(NEXT.EQ.0) GO TO 449                                           P-N05260
      IDEP=INDIC(NEXT)+1                                                P-N05270
      TAU=CROIS(IDEP-1)                                                 P-N05280
      IF(IDEP.GT.K) GO TO 448                                           P-N05290
      DO 42 I=IDEP,K                                                    P-N05300
      IF (CROIS(I).GT.TAU) GO TO 42                                     P-N05310
      TAU=CROIS(I)                                                      P-N05320
      NEXT=NEXT+1                                                       P-N05330
      INDIC(NEXT)=I                                                     P-N05340
   42 CONTINUE                                                          P-N05350
  448 IMIN=INDIC(NEXT)                                                  P-N05360
      L1=IND(IMIN)                                                      P-N05370
      L2=JND(IMIN)                                                      P-N05380

C TEST le 20/3/2003: tue sinon le dernier avatar?
      IF (K.EQ.0) GO TO 230                                             P-N05400
      K=K-1                                                             P-N05390

      NEXT=NEXT-1                                                       P-N05410
c correction S.Vuillier 25/1/96 decalage temps correct
      IF (IMIN.GT.K) GO TO 46
      DO 43 I=IMIN,K                                                    P-N05430
      CROIS(I)=CROIS(I+1)                                               P-N05440
      IND(I)=IND(I+1)                                                   P-N05450
   43 JND(I)=JND(I+1)                                                   P-N05460
   46 TIM=TIMI+TAU                                                      P-N05470
C                                                                       P-N05480
CCC   COUNTING THE POSITIONS AND THE MOMENTA AT INTERMEDIATE TIMES      P-N05490
C                                                                       P-N05500

C Modif: Pas de reflexions avant au moins un avatar du (des) nucleon incident
C   Celui-ci ne peut etre qu'une collision NN (ou piN)

               IF((irst_avatar.EQ.0).AND.(L2.EQ.-1)) GO TO 44

            irst_avatar=irst_avatar+1

C Interaction between nucleons of the projectile only if one of them
C  has been involved in an accepted collision 10/2/2011 AB
      IF(L2.GT.0) THEN
        IF(L1.LE.IA1.AND.L2.LE.IA1
     s      .AND.NC(L1).EQ.0.AND.NC(L2).EQ.0) GO TO 44
      ENDIF

C Critere d'arret sur energie:
         t_fin=tim

C Supprime pour NO StopE et BackToSpect 22/11/2011 AB

c counting pions inside:
         nb_pi_in=0
       IF(npion.NE.0) THEN
       DO i_pi=1,npion
          IF(nesc(ia+i_pi).EQ.0) nb_pi_in = nb_pi_in+1
       ENDDO
       ENDIF


C Added 10/03/2009, stop if 0 participant (related to JPARTICIP=0 after collis)
C Previous stopping criteria based on stopE or temfin:
c Previous stopping criteria with BackTpSpect only (more constraining)
C Stopping condition with both: nb_jpart=0  OR  nb_supe=0  11/2011 AB
         IF((tim.lt.temfin).AND.((nb_pi_in.NE.0).OR.
     s           ((NB_JPART.GT.0).AND.(NB_SUPE.GT.0))))
     s                     GO TO 49


      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) ''
      WRITE(6,*) 'STOP the cascade,tim,temfin,NB_JPART,nb_pi_in:',
     s tim,temfin,NB_JPART,nb_pi_in
      ENDIF

      go to 255

   49 CONTINUE


C*****************************************************
C    POUR TEST LE 20/3/2003... Tue le dernier avatar?

C New positions (nucleon or delta) are computed here for L1,L2 taking
C into account bound composite projectiles (02/2011 AB).
      IF(IFL_BOUND_PROJ.EQ.0) THEN
        IF(L1.LE.IA) THEN
          TA = TAU/EPS(L1)
          X1L1 =X1(L1)+P1(L1)*TA
          X2L1 =X2(L1)+P2(L1)*TA
          X3L1 =X3(L1)+P3(L1)*TA
        ENDIF
        IF(L2.LE.IA.AND.L2.GT.0) THEN
          TA = TAU/EPS(L2)
          X1L2 =X1(L2)+P1(L2)*TA
          X2L2 =X2(L2)+P2(L2)*TA
          X3L2 =X3(L2)+P3(L2)*TA
        ENDIF
      ELSE
        IF(L1.GT.IA) GO TO 731
        IF(L1.GT.IA1) THEN
          P1L1=P1(L1)
          P2L1=P2(L1)
          P3L1=P3(L1)
          EPSL1=EPS(L1)
        ELSE
          IF(IBOUND_NUC(L1).EQ.0) THEN
            P1L1=P1(L1)
            P2L1=P2(L1)
            P3L1=P3(L1)
            EPSL1=EPS(L1)
          ELSE
            P1L1=PINC1
            P2L1=PINC2
            P3L1=PINC3
            EPSL1=ENERGIE_IN
          ENDIF
        ENDIF
        TA = TAU/EPSL1
        X1L1 =X1(L1)+P1L1*TA
        X2L1 =X2(L1)+P2L1*TA
        X3L1 =X3(L1)+P3L1*TA
731     CONTINUE
        IF(L2.LE.0.OR.L2.GT.IA) GO TO 733
        IF(L2.GT.IA1) THEN
          P1L2=P1(L2)
          P2L2=P2(L2)
          P3L2=P3(L2)
          EPSL2=EPS(L2)
        ELSE
          IF(IBOUND_NUC(L2).EQ.0) THEN
            P1L2=P1(L2)
            P2L2=P2(L2)
            P3L2=P3(L2)
            EPSL2=EPS(L2)
          ELSE
            P1L2=PINC1
            P2L2=PINC2
            P3L2=PINC3
            EPSL2=ENERGIE_IN
          ENDIF
        ENDIF
        TA = TAU/EPSL2
        X1L2 =X1(L2)+P1L2*TA
        X2L2 =X2(L2)+P2L2*TA
        X3L2 =X3(L2)+P3L2*TA
733     CONTINUE
      ENDIF


C L1 va a la surface du noyau:
      IF (L2.EQ.-1) GO TO 220                                           P-N06350

C L1 is a pion at the surface (L1>IA)
      if(idnint(f(17)).ne.1)then
         IF (L2.EQ.-2) GO TO 220 ! ***** ThA
      endif

      IF(K4-1) 803,803,830                                              P-N06360
C L1 est un delta:
  830 IF(L2.EQ.0) then
      GO TO 220
      endif                                                             P-N06370
C Interaction pi(L1-IA)-nucleon(L2)
      IF(L1.GT.IA) GO TO 801                                            P-N06380
  803 CONTINUE                                                          P-N06390

C Pas de collision entre 2 non participants:
      IF(JPARTICIP(L1).EQ.0.AND.JPARTICIP(L2).EQ.0) GO TO 44

C                                                                       P-N06400
CCC   PARAMETERS FOR THE NEXT COLLIDING PAIR                            P-N06410
C                                                                       P-N06420

      IF(LOCE.NE.0) THEN
c LocE:
      R_1 =X1L1**2 +X2L1**2 +X3L1**2
      R_1 = SQRT(R_1)
      R_2 =X1L2**2 +X2L2**2 +X3L2**2
      R_2 = SQRT(R_2)

      PI2 = P1(L1)**2 + P2(L1)**2 + P3(L1)**2
      FMI2=FMP**2
      IF(IND1(L1).EQ.1) THEN
      FMI2=EPS(L1)**2 - PI2
      ENDIF
      fmi=sqrt(fmi2)
      vloc1 = VLOC(l1,r_1,fmi,eps(l1)-fmi,v(l1),ind1(l1),ind2(l1))
      E_1=EPS(L1)-VLOC1

      PJ2 = P1(L2)**2 + P2(L2)**2 + P3(L2)**2
      FMJ2=FMP**2
      IF(IND1(L2).EQ.1) THEN
      FMJ2=EPS(L2)**2 - PJ2
      ENDIF
      fmj=sqrt(fmj2)
      vloc2 = VLOC(l2,r_2,fmj,eps(l2)-fmj,v(l2),ind1(l2),ind2(l2))
      E_2=EPS(L2)-VLOC2

      AA=E_1**2 - FMI2
      IF (AA.LT.0) THEN
            COR1 = 0
      E_1=SQRT(FMI2)
      ELSE
      COR1=SQRT(AA/PI2)
      ENDIF
      AA=E_2**2 - FMJ2
      IF (AA.LT.0) THEN
            COR2 = 0
      E_2 = SQRT(FMJ2)
      ELSE
      COR2=SQRT(AA/PJ2)
      ENDIF


      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) ''
      WRITE(6,*) 'Next colliding pair TA,TIM,LOCE:',TA,TIM,LOCE
      WRITE(6,*) 'L1,R_1,VLOC1,E_1,L2,R_2,VLOC2,E_2'
     s ,L1,R_1,VLOC1,E_1,L2,R_2,VLOC2,E_2
      WRITE(6,*) 'EPS(L1),P(L1),EPS(L2),P(L2):'
      WRITE(6,*) EPS(L1),P1(L1),P2(L1),P3(L1)
      WRITE(6,*) EPS(L2),P1(L2),P2(L2),P3(L2)
      ENDIF

      T(10)=E_1+E_2
      T0=1./T(10)
      P1L1=P1(L1)*COR1
      P2L1=P2(L1)*COR1
      P3L1=P3(L1)*COR1
      P1L2=P1(L2)*COR2
      P2L2=P2(L2)*COR2
      P3L2=P3(L2)*COR2
      B1=(P1L1+P1L2)*T0
      B2=(P2L1+P2L2)*T0
      B3=(P3L1+P3L2)*T0

      ELSE
c No LocE:
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) ''
      WRITE(6,*) 'Next colliding pair TA,TIM,LOCE:',TA,TIM,LOCE
      WRITE(6,*) 'L1,R_1,VLOC1,E_1,L2,R_2,VLOC2,E_2'
     s ,L1,R_1,VLOC1,E_1,L2,R_2,VLOC2,E_2
      WRITE(6,*) 'EPS(L1),P(L1),EPS(L2),P(L2):'
      WRITE(6,*) EPS(L1),P1(L1),P2(L1),P3(L1)
      WRITE(6,*) EPS(L2),P1(L2),P2(L2),P3(L2)
      ENDIF
      T(10)=EPS(L1)+EPS(L2)                                             P-N06430
      T0=1./T(10)                                                       P-N06440
      B1=(P1(L1)+P1(L2))*T0                                             P-N06450
      B2=(P2(L1)+P2(L2))*T0                                             P-N06460
      B3=(P3(L1)+P3(L2))*T0                                             P-N06470
      ENDIF
      S=(1.-B1*B1-B2*B2-B3*B3)*T(10)*T(10)                              P-N06480
      SQ=SQRT(S)                                                        P-N06490

C verif loce:
      SQNORMAL=SQRT((EPS(L1)+EPS(L2))**2 - (P1(L1)+P1(L2))**2
     s - (P2(L1)+P2(L2))**2 - (P3(L1)+P3(L2))**2)

      IF(LBLNN.NE.0) THEN
        IF(IND2(L1).EQ.-1) THEN
            ELIM1=V(L1)-SN+FMP
        ELSE
            ELIM1=V(L1)-SP+FMP
        ENDIF
        IF(IND2(L2).EQ.-1) THEN
            ELIM2=V(L2)-SN+FMP
        ELSE
            ELIM2=V(L2)-SP+FMP
        ENDIF
        IF((EPS(L1).LT.ELIM1).AND.(EPS(L2).LT.ELIM2)) THEN
          IF(IBERT.EQ.ibw) WRITE(6,*) 'Rejected by 2N<TF'
          GO TO 44
        ENDIF
      ENDIF
      IF(SQ.LT.CUTNN) THEN
        IF(IBERT.EQ.ibw)
     s       WRITE(6,*)'Rejected by CUTNN, SQ,CUTNN:',SQ,CUTNN
      GO TO 44
      ENDIF
C                                                                       P-N06590
CCC   TEST ON THE MINIMUM DISTANCE OF APPROACH                          P-N06600
C                                                                       P-N06610
      TAVAIL=SQ-2.*FMP
      T(11)=X1L1-X1L2                                                   P-N06620
      T(12)=X2L1-X2L2                                                   P-N06630
      T(13)=X3L1-X3L2                                                   P-N06640
      T(14)=T(11)*T(11)+T(12)*T(12)+T(13)*T(13)                         P-N06650
      T(15)=B1*T(11)+B2*T(12)+B3*T(13)                                  P-N06660
      T(16)=B1*B1+B2*B2+B3*B3                                           P-N06670
      BB2=T(14)+T(15)*T(15)/(1.-T(16))                                  P-N06680
      IF (K3.EQ.1) GO TO 260                                            P-N06690
      IF (K4.EQ.0) GO TO 260                                            P-N06700
      MG=IND1(L1)+IND1(L2)                                              P-N06710
      ISOS=IND2(L1)+IND2(L2)                                            P-N06720
      IF (MG.NE.1) GO TO 260                                            P-N06730
      LDEL=L2                                                           P-N06740
      IF(MG-IND1(L1).EQ.0) LDEL=L1                                      P-N06750
      XX10=SQRT(EPS(LDEL)**2-P1(LDEL)**2-P2(LDEL)**2-P3(LDEL)**2)       P-N06760
      ISA=IND2(LDEL)                                                    P-N06770
      R_N1=SQRT(X1(L1)**2+X2(L1)**2+X3(L1)**2)
      R_N2=SQRT(X1(L2)**2+X2(L2)**2+X3(L2)**2)
      BMAX2=STOT(SQ,MG,ISOS)/31.4159265358979                           P-N06780
      IF (K5.EQ.0.AND.MG.NE.0)
     &  BMAX2=BMAX2-SEL(SQ,MG,ISOS)/31.4159265358979                    P-N06790
      GO TO 261                                                         P-N06800
  260 BMAX2=STOT(SQ,MG,ISOS)/31.4159265358979                           P-N06810
  261 IF (BB2.LT.BMAX2) GO TO 219                                       P-N06820
      IF (K.EQ.0) GO TO 230                                             P-N06830
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'Rejected by dist approach BB2,BMAX2:',BB2,BMAX2
      WRITE(6,*) '   SQ,MG,ISOS,LOCE:',SQ,MG,ISOS,LOCE
      ENDIF
      GO TO 44                                                          P-N06840
C                                                                       P-N06850
CCC   EVALUATION OF THE POSITIONS AT TIME=TIM                           P-N06860
C
  219 CONTINUE
C Matter is seen by a negative energy nucleon of the HI projectile:
      NB_VU_OLD=NB_VU_MATTER
      IF(L1.LE.IA1.AND.(EPS(L1)-FMP).LT.V(L1).AND.L2.GT.IA1)THEN
      NB_VU_MATTER=NB_VU_MATTER+1
      ENDIF
      IF(L2.LE.IA1.AND.(EPS(L2)-FMP).LT.V(L2).AND.L1.GT.IA1)THEN
      NB_VU_MATTER=NB_VU_MATTER+1
      ENDIF
      IF(NB_VU_OLD.NE.NB_VU_MATTER.AND.IBERT.EQ.ibw) THEN
      WRITE(6,*) 'IBERT:',IBERT
      WRITE(6,*) 'L1,R1,T1,V1,L2,R2,T2,V2,BB2:',
     s L1,R_N1,EPS(L1)-FMP,V(L1),
     s L2,R_N2,EPS(L2)-FMP,V(L2),BB2
      ENDIF


  220 CONTINUE                                                          P-N06880

      TIMI=TIM                                                          P-N06890
C Gel des nucleons non participants sur le premier avatar (NN)=(L1,1)
      IF (irst_avatar.EQ.1) THEN
                  TA=TAU/EPS(1)
                  X1(1)=X1(1)+P1(1)*TA
                  X2(1)=X2(1)+P2(1)*TA
                  X3(1)=X3(1)+P3(1)*TA
                  X1(L1)=X1L1
                  X2(L1)=X2L1
                  X3(L1)=X3L1
         DO i=1,K
            CROIS(i)=CROIS(i)+TAU
         ENDDO
      ELSE

      DO 51 I=1,IA                                                      P-N06900
      IF(IFL_BOUND_PROJ.EQ.0) THEN
        P1SP=P1(i)
        P2SP=P2(i)
        P3SP=P3(i)
        EPSP=EPS(i)
      ELSE
        IF(i.LE.IA1) then
         if(IBOUND_NUC(i).EQ.1) THEN
          P1SP=PINC1
          P2SP=PINC2
          P3SP=PINC3
          EPSP=ENERGIE_IN
         else
          P1SP=P1(i)
          P2SP=P2(i)
          P3SP=P3(i)
          EPSP=EPS(i)
         end if
        ELSE
          P1SP=P1(i)
          P2SP=P2(i)
          P3SP=P3(i)
          EPSP=EPS(i)
        ENDIF
      ENDIF
      TA=TAU/EPSP
      X1(I)=X1(I)+P1SP*TA                                               P-N06920
      X2(I)=X2(I)+P2SP*TA                                               P-N06930
   51 X3(I)=X3(I)+P3SP*TA                                               P-N06940
               IF(L1.LE.IA) THEN
                  X1(L1)=X1L1
                  X2(L1)=X2L1
                  X3(L1)=X3L1
               ENDIF
               IF(L2.GT.0.AND.L2.LE.IA) THEN
                  X1(L2)=X1L2
                  X2(L2)=X2L2
                  X3(L2)=X3L2
               ENDIF
      ENDIF

      IF(NPION.EQ.0) GO TO 840                                          P-N06950
      DO 804 I=1,NPION                                                  P-N06960
      TA=TAU/Q4(I)                                                      P-N06970
      Y1(I)=Y1(I)+Q1(I)*TA                                              P-N06980
      Y2(I)=Y2(I)+Q2(I)*TA                                              P-N06990
  804 Y3(I)=Y3(I)+Q3(I)*TA                                              P-N07000
  840 IF(L2.EQ.0) then
      GO TO 805
      endif                                                             P-N07010

C coupure sur l'energie cinetique maximale **********************************
C****************************************************************************

C Reflexions sur le potentiel, sortie eventuelle de la particule:
      IF (L2.EQ.-1) GO TO 600                                           P-N07020
      if(idnint(f(17)).ne.1)then
         IF (L2.EQ.-2) GO TO 620 ! ***** ThA Transmission of the pion
      endif
      IF(L1.GT.IA) GO TO 831                                            P-N07030
C                                                                       P-N07040
CCC   COLLISION OF PARTICLES L1 AND L2                                  P-N07050
C                                                                       P-N07060
      TAVAIL=SQ-2.*FMP
      ICH1=IND1(L1)                                                     P-N07070
      ICH2=IND1(L2)                                                     P-N07080
      ICH3=IND2(L1)                                                     P-N07090
      ICH4=IND2(L2)                                                     P-N07100
      TV1=V(L1)
      TV2=V(L2)

c
      IF(ICH1.EQ.0.AND.ICH3.EQ.1) VKFO1=V2P
      IF(ICH1.EQ.0.AND.ICH3.EQ.-1) VKFO1=V2N
      IF(ICH1.EQ.1.AND.ICH3.EQ.3) VKFO1=V0PP
      IF(ICH1.EQ.1.AND.ICH3.EQ.1) VKFO1=V0P
      IF(ICH1.EQ.1.AND.ICH3.EQ.-1) VKFO1=V0N
      IF(ICH1.EQ.1.AND.ICH3.EQ.-3) VKFO1=V0M
c
      IF(ICH2.EQ.0.AND.ICH4.EQ.1) VKFO2=V2P
      IF(ICH2.EQ.0.AND.ICH4.EQ.-1) VKFO2=V2N
      IF(ICH2.EQ.1.AND.ICH4.EQ.3) VKFO2=V0PP
      IF(ICH2.EQ.1.AND.ICH4.EQ.1) VKFO2=V0P
      IF(ICH2.EQ.1.AND.ICH4.EQ.-1) VKFO2=V0N
      IF(ICH2.EQ.1.AND.ICH4.EQ.-3) VKFO2=V0M
      AML1=SQRT(EPS(L1)**2-P1(L1)**2-P2(L1)**2-P3(L1)**2)               P-N07120
      AML2=SQRT(EPS(L2)**2-P1(L2)**2-P2(L2)**2-P3(L2)**2)               P-N07130
      GL1=EPS(L1)/AML1                                                  P-N07140
      GL2=EPS(L2)/AML2                                                  P-N07150
C++++++++++++++ L-CONSERVATION +++++++++++++++++++++++++++++++++++++++
      IF (K6.EQ.1) THEN                                                 P-N07160
      T(31)=(AML1*X1(L1)+AML2*X1(L2))/(AML1+AML2)                       P-N07170
      T(32)=(AML1*X2(L1)+AML2*X2(L2))/(AML1+AML2)                       P-N07180
      T(33)=(AML1*X3(L1)+AML2*X3(L2))/(AML1+AML2)                       P-N07190
      TT31 =X1(L1)-X1(L2)                                               P-N07200
      TT32 =X2(L1)-X2(L2)                                               P-N07210
      TT33 =X3(L1)-X3(L2)                                               P-N07220
      T(34)=(AML2*P1(L1)-AML1*P1(L2))/(AML1+AML2)                       P-N07230
      T(35)=(AML2*P2(L1)-AML1*P2(L2))/(AML1+AML2)                       P-N07240
      T(36)=(AML2*P3(L1)-AML1*P3(L2))/(AML1+AML2)                       P-N07250
      TT34=P1(L1)+P1(L2)                                                P-N07260
      TT35=P2(L1)+P2(L2)                                                P-N07270
      TT36=P3(L1)+P3(L2)                                                P-N07280
      ENDIF                                                             P-N07290
C++++++++++++++++ L-CONSERVATION ++++++++++++++                         P-N07300
      T(21)=P1(L1)                                                      P-N07310
      T(22)=P2(L1)                                                      P-N07320
      T(23)=P3(L1)                                                      P-N07330
      T(24)=EPS(L1)                                                     P-N07340
      T(25)=P1(L2)                                                      P-N07350
      T(26)=P2(L2)                                                      P-N07360
      T(27)=P3(L2)                                                      P-N07370
      T(28)=EPS(L2)                                                     P-N07380
      t(29)=hel(l1)
      t(30)=hel(l2)
C Info delta ou nucleon:
      Eavant=EPS(L1)-V(L1)+EPS(L2)-V(L2)  ! ThA to test E cons.

C For global statistical Pauli, counts particles in fermi sea.
      IF(NPAULSTR.EQ.2) THEN
C Number of neutrons (p) below TF BEFORE collision
C NOT a DELTA!
      CALL GLBP_COUNT(L1,L2,-1)
      ENDIF
c Verifs loc E
      XLL1=SQRT(X1(L1)**2+X2(L1)**2+X3(L1)**2)
      XLL1V=XLL1
      LV1=L1
      IS1AB=IND2(L1)
      IDEL1AB=IND1(L1)
      TV_AB1=EPS(L1)-FMP
      tminab1 = VLOC(l1,xll1,fmp,tv_ab1,v(l1),ind1(l1),ind2(l1))

      XLL2=SQRT(X1(L2)**2+X2(L2)**2+X3(L2)**2)
      XLL2V=XLL2
      LV2=L2
      IS2AB=IND2(L2)
      IDEL2AB=IND1(L2)
      TV_AB2=EPS(L2)-FMP
      tminab2 = VLOC(l2,xll2,fmp,tv_ab2,v(l2),ind1(l2),ind2(l2))

      IF (ibert.EQ.ibw) THEN
      WRITE(6,*)''
      WRITE(6,*)'Collision:L1,IND2(L1),IND1(L1),L2,IND2(L2),IND1(L2):'
     s ,L1,IND2(L1),IND1(L1),L2,IND2(L2),IND1(L2)
      WRITE(6,*) 'NN before locE; EPS(L1),EPS(L2),V(L1),V(L2):',
     s EPS(L1),EPS(L2),V(L1),V(L2)
      ENDIF

      IF(LOCE.EQ.1.OR.LOCE.EQ.3) THEN
       EPS(L1) = E_1
       P1(L1) = P1L1
       P2(L1) = P2L1
       P3(L1) = P3L1
       EPS(L2) = E_2
       P1(L2) = P1L2
       P2(L2) = P2L2
       P3(L2) = P3L2
       vold1 = v(l1)
       vold2 = v(l2)
C Pour test conservation de E avec E-Vloc(r)
      ENDIF
      Eavant = EPS(L1)-V(L1)+EPS(L2)-V(L2)
      IF (ibert.EQ.ibw) THEN
      WRITE(6,*) 'NN AFTER locE; EPS(L1),EPS(L2),Eavant:',
     s EPS(L1),EPS(L2),Eavant
      WRITE(6,*) '   P(L1),P(L2):'
      WRITE(6,*) P1(L1),P2(L1),P3(L1)
      WRITE(6,*) P1(L2),P2(L2),P3(L2)
      ENDIF
C Pour faire remarcher loce=2 (20/10/06 AB)
      IF(LOCE.EQ.2) THEN
      T(10)=EPS(L1)+EPS(L2)                                             P-N06430
      T0=1./T(10)                                                       P-N06440
      B1=(P1(L1)+P1(L2))*T0                                             P-N06450
      B2=(P2(L1)+P2(L2))*T0                                             P-N06460
      B3=(P3(L1)+P3(L2))*T0                                             P-N06470
      ENDIF

C Critere d'arret sur energie:
      IF(idnint(F(14)).EQ.1.) THEN
          IF(IND2(L1).EQ.-3) TF=TFM
          IF(IND2(L1).EQ.-1) TF=TFN
          IF(IND2(L1).EQ.1)  TF=TFP
          IF(IND2(L1).EQ.3)  TF=TFPP
      locsupe=0
      IF(IND1(L1).EQ.0) THEN
          IF(IND2(L1).EQ.1.AND.(EPS(L1)-FMP-V(L1)+SP).GE.EIN_MAXP)
     s            locsupe=locsupe-1
          IF(IND2(L1).EQ.-1.AND.(EPS(L1)-FMP-V(L1)+SN).GE.EIN_MAXN)
     s            locsupe=locsupe-1
      ELSE
         IF((EPS(L1)-FMP-FMPI-V(L1)+SP).GT.EIN_MAX) locsupe=locsupe-1
      ENDIF
          IF(IND2(L2).EQ.-3) TF=TFM
          IF(IND2(L2).EQ.-1) TF=TFN
          IF(IND2(L2).EQ.1)  TF=TFP
          IF(IND2(L2).EQ.3)  TF=TFPP
      IF(IND1(L2).EQ.0) THEN
          IF(IND2(L2).EQ.1.AND.(EPS(L2)-FMP-V(L2)+SP).GE.EIN_MAXP)
     s            locsupe=locsupe-1
          IF(IND2(L2).EQ.-1.AND.(EPS(L2)-FMP-V(L2)+SN).GE.EIN_MAXN)
     s            locsupe=locsupe-1
      ELSE
         IF((EPS(L2)-FMP-FMPI-V(L2)+SP).GT.EIN_MAX) locsupe=locsupe-1
      ENDIF
      ENDIF

      IF(IBERT.EQ.IBW) THEN
      WRITE(6,*) ''
      WRITE(6,*) 'Interaction of L1,L2 tried,TIM,nb_jpart:',
     s  L1,L2,TIM,nb_jpart
      R_N1=SQRT(X1(L1)**2+X2(L1)**2+X3(L1)**2)
      R_N2=SQRT(X1(L2)**2+X2(L2)**2+X3(L2)**2)
      WRITE(6,*) '   R(L1),R(L2):',R_N1,R_N2
      ENDIF

C For density dependence of NN interaction:
      R_N1=SQRT(X1(L1)**2+X2(L1)**2+X3(L1)**2)
      R_N2=SQRT(X1(L2)**2+X2(L2)**2+X3(L2)**2)

      CALL LOREN(P1(L1),P2(L1),P3(L1),-B1,-B2,-B3,EPS(L1))              P-N07390
      CALL LOREN(P1(L2),P2(L2),P3(L2),-B1,-B2,-B3,EPS(L2))              P-N07400


      CALL COLLIS(P1(L1),P2(L1),P3(L1),EPS(L1),P1(L2),P2(L2),P3(L2),EPS(P-N07410
     -L2),T(12),T(13),T(14),T(15),NP,IP,K2,K3,K4,K5,IND1(L1),IND1(L2),INP-N07420
     -D2(L1),IND2(L2))                                                  P-N07430


      CALL LOREN(P1(L1),P2(L1),P3(L1),B1,B2,B3,EPS(L1))                 P-N07440
      CALL LOREN(P1(L2),P2(L2),P3(L2),B1,B2,B3,EPS(L2))                 P-N07450

      IF(IND1(L1).EQ.0.AND.IND2(L1).EQ.1) VKF1=V2P
      IF(IND1(L1).EQ.0.AND.IND2(L1).EQ.-1) VKF1=V2N
      IF(IND1(L1).EQ.1.AND.IND2(L1).EQ.3) VKF1=V0PP
      IF(IND1(L1).EQ.1.AND.IND2(L1).EQ.1) VKF1=V0P
      IF(IND1(L1).EQ.1.AND.IND2(L1).EQ.-1) VKF1=V0N
      IF(IND1(L1).EQ.1.AND.IND2(L1).EQ.-3) VKF1=V0M
c
      IF(IND1(L2).EQ.0.AND.IND2(L2).EQ.1) VKF2=V2P
      IF(IND1(L2).EQ.0.AND.IND2(L2).EQ.-1) VKF2=V2N
      IF(IND1(L2).EQ.1.AND.IND2(L2).EQ.3) VKF2=V0PP
      IF(IND1(L2).EQ.1.AND.IND2(L2).EQ.1) VKF2=V0P
      IF(IND1(L2).EQ.1.AND.IND2(L2).EQ.-1) VKF2=V0N
      IF(IND1(L2).EQ.1.AND.IND2(L2).EQ.-3) VKF2=V0M
c %%%%%
      IF(LOCE.EQ.1.OR.LOCE.EQ.3) THEN
      fmdvd = sqrt(eps(l1)**2-p1(l1)**2-p2(l1)**2-p3(l1)**2)
      vlocp1 = VLOC(l1,xll1,fmdvd,eps(l1)-fmdvd,v(l1),ind1(l1),ind2(l1))
      fmdvd = sqrt(eps(l2)**2-p1(l2)**2-p2(l2)**2-p3(l2)**2)
      vlocp2 = VLOC(l2,xll2,fmdvd,eps(l2)-fmdvd,v(l2),ind1(l2),ind2(l2))
      Q=VLOCP1+VLOCP2-VLOC1-VLOC2
      IFLAB=0
      IF(ABS(Q).GT.0.0001) THEN
      IFLAB=1
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'Q=',Q,LV1,LV2,L1,L2
      WRITE(6,*) 'r=',XLL1V,XLL2V,XLL1,XLL2
      WRITE(6,*) 'Pot:',VLOC1,VLOC2,VLOCP1,VLOCP2
      WRITE(6,*) 'iso in/out:',IS1AB,IS2AB,IND2(L1),IND2(L2)
      ENDIF
      ENDIF
      CALL AECSVT(eavant+vloc1+vloc2,
     &B1,B2,B3,P1(L1),P2(L1),P3(L1),EPS(L1),VKF1,P1(L2),P2(L2),
     &P3(L2),EPS(L2),VKF2,V(L1),V(L2),IEJCT,DELTAE,IVFCTE,f(13),
     sVLOCP1,VLOCP2,l1,r_1,l2,r_2,loce,ind1(l1),ind1(l2),ind2(l1),
     sind2(l2))
      ELSE
      Q=0
      CALL AECSVT(eavant,
     &B1,B2,B3,P1(L1),P2(L1),P3(L1),EPS(L1),VKF1,P1(L2),P2(L2),
     &P3(L2),EPS(L2),VKF2,V(L1),V(L2),IEJCT,DELTAE,IVFCTE,f(13),
     sreal(0.,8),real(0.,8),
     sl1,r_1,l2,r_2,loce,ind1(l1),ind1(l2),ind2(l1),
     sind2(l2))
      ENDIF
      IF(IEJCT.EQ.1) then
        irejet=irejet+1
      GOTO 249
      ENDIF
      Eapres=EPS(L1)-V(L1)+EPS(L2)-V(L2)
      if(loce.eq.1.or.loce.eq.3) then
        fmdvd=sqrt(eps(l1)**2-p1(l1)**2-p2(l1)**2-p3(l1)**2)
        vlocp1=VLOC(l1,r_1,fmdvd,eps(l1)-fmdvd+vlocp1,v(l1),
     s   ind1(l1),ind2(l1))
        fmdvd=sqrt(eps(l2)**2-p1(l2)**2-p2(l2)**2-p3(l2)**2)
        vlocp2=VLOC(l2,r_2,fmdvd,eps(l2)-fmdvd+vlocp2,v(l2),
     s   ind1(l2),ind2(l2))
         Q = VLOCP1+VLOCP2-VLOC1-VLOC2
      endif

      IF(ABS(Eavant-Eapres-Q).gt.0.005) then
      goto 249
      ENDIF

      IF(LOCE.EQ.1.OR.LOCE.EQ.3) THEN
C test of local energy, restitution of pot energy:
       FML1=FMP
       IF(IND1(L1).EQ.1) FML1 = AM(P1(L1),P2(L1),P3(L1),EPS(L1))
       EPS(L1)=EPS(L1)+ VLOCP1
       COR=P1(L1)**2 + P2(L1)**2 + P3(L1)**2
       COR = SQRT((EPS(L1)**2 - FML1**2)/COR)
       P1(L1) = P1(L1)*COR
       P2(L1) = P2(L1)*COR
       P3(L1) = P3(L1)*COR
       COR1=COR
       FML2=FMP
       IF(IND1(L2).EQ.1) FML2 = AM(P1(L2),P2(L2),P3(L2),EPS(L2))
       EPS(L2)=EPS(L2)+ VLOCP2
       COR=P1(L2)**2 + P2(L2)**2 + P3(L2)**2
       COR = SQRT((EPS(L2)**2 - FML2**2)/COR)
       P1(L2) = P1(L2)*COR
       P2(L2) = P2(L2)*COR
       P3(L2) = P3(L2)*COR
       COR2=COR
      ENDIF


c Verifs loc E


C Test LocE:


C Pauli strict sur premiere collision (Pauli PH)
      if(idnint(f(17)).ne.1)then
         if (ncol_2c.eq.0) then
            NPAULOLD=NPAULSTR
            NPAULSTR=1
         endif
      endif

      IF (IND1(L1).EQ.1) GO TO 243                                      P-N07460
      IF(IND2(L1).EQ.-3) PF=PFM   ! ThA
      IF(IND2(L1).EQ.-1) PF=PFN   ! ThA
      IF(IND2(L1).EQ.1) PF=PFP    ! ThA
      IF(IND2(L1).EQ.3) PF=PFPP   ! ThA
      CALL PAULIL(L1,RBL,PBL,XBL1,PF,LOCE)                               P-N07470
      rndm=rn(0)
      IF (RNDM.GT.1.-XBL1) GO TO 248                                    P-N07530
  243 IF (IND1(L2).EQ.1) GO TO 241                                      P-N07540
      IF(IND2(L2).EQ.-3) PF=PFM   ! ThA
      IF(IND2(L2).EQ.-1) PF=PFN   ! ThA
      IF(IND2(L2).EQ.1) PF=PFP    ! ThA
      IF(IND2(L2).EQ.3) PF=PFPP   ! ThA
      CALL PAULIL(L2,RBL,PBL,XBL2,PF,LOCE)                               P-N07550
      rndm=rn(0)

      IF (RNDM.GT.1.-XBL2) GO TO 248                                    P-N07610
      GO TO 241                                                         P-N07620
  248 MPAUL1=MPAUL1+1                                                   P-N07630
      if(irtst.eq.1) WRITE(*,*) 'PAULI BLOC'
C Restitution Pauli
      if(idnint(f(17)).ne.1)then
         if (ncol_2c.eq.0) then
            NPAULSTR=NPAULOLD
         endif
      endif

C Restitution de L1 et L2 si rejet de la col. par Pauli:
  249 CONTINUE
      P1(L1)=T(21)                                                      P-N07640
      P2(L1)=T(22)                                                      P-N07650
      P3(L1)=T(23)                                                      P-N07660
      EPS(L1)=T(24)                                                     P-N07670
      V(L1)=TV1     ! ThA restitution of V
      P1(L2)=T(25)                                                      P-N07680
      P2(L2)=T(26)                                                      P-N07690
      P3(L2)=T(27)                                                      P-N07700
      EPS(L2)=T(28)                                                     P-N07710
      V(L2)=TV2     ! ThA restitution of V
      IND1(L1)=ICH1                                                     P-N07720
      IND1(L2)=ICH2                                                     P-N07730
      IND2(L1)=ICH3                                                     P-N07740
      IND2(L2)=ICH4                                                     P-N07750
      hel(l1)=t(29)
      hel(l2)=t(30)
      IF (K.EQ.0) GO TO 230                                             P-N07760
      DO 284 I=1,K                                                      P-N07770
  284 CROIS(I)=CROIS(I)-TAU                                             P-N07780
C Pour le temps de calcul (A.B. 02/2002)
      IF (ibert.EQ.ibw) THEN
      WRITE(6,*) 'Pauli rejected EPS(L1),EPS(L2),V(L1),V(L2):',
     s EPS(L1),EPS(L2),V(L1),V(L2)
      ENDIF

      GO TO 44

241   CONTINUE
C Restitution Pauli
      if(idnint(f(17)).ne.1)then
         if (ncol_2c.eq.0) then
            NPAULSTR=NPAULOLD
         endif
      endif

C La premiere collision a deux corps ne peut pas baisser l'energie
C    du nucleon de recul (bloque par pauli dans un noyau cible froid).
C    (Ici, toujours L2 < L1)
C Added that one of the nucleon must be of the target (for HI) AB 7/2/2011
      IF(L1.GT.IA1.OR.L2.GT.IA1)
     s           NCOL_2C=NCOL_2C+1

c Pour retrouver INCL4.2:
       IF(NCOL_2C.EQ.1.and.idnint(f(17)).eq.1) THEN
       do icomp=1,ia1
C Test on the first collision modified 4/07/2001 for direct AND exchange.
C Test suppressed 5/2005( wrong for incoming pions)(AB)
         IF(icomp.EQ.L1.OR.icomp.EQ.L2) THEN
           Xavant=MIN(T(24),T(28))
           Xapres=MIN(EPS(L1),EPS(L2))
           IF(Xapres.LE.Xavant) THEN
              GO TO 248
           ENDIF
         ENDIF
       enddo
       ELSE

C Les collisions suivantes ne penvent conduire a un noyau de A nucleons
C  sous l'energie de Fermi et dans une config. d'energie inferieure a
C  EFER-(IA2-NBALTTF)*TF).
       EGS=0.
       NBALTTFZ=0
       NBALTTFN=0
       NoALTTFZ=0
       NoALTTFN=0
       ICPI=0
       IF(NPION.GT.0) THEN
         DO KLN=1,NPION
          ICPI=ICPI+IPI(KLN)/2
         ENDDO
       ENDIF
       DO I=1,IA
         IF(NESC(I).EQ.0) THEN
          IF(IND2(I).EQ.-3) TF=TFM
          IF(IND2(I).EQ.-1) TF=TFN
          IF(IND2(I).EQ.1)  TF=TFP
          IF(IND2(I).EQ.3)  TF=TFPP
          PTEST2=P1(I)**2+P2(I)**2+P3(I)**2
          AMTEST=SQRT(EPS(I)**2-PTEST2)
          TTEST=EPS(I)-AMTEST
          IF(TTEST.LE.TF) THEN
             IF(IND2(I).LT.0) NBALTTFN=NBALTTFN+1
             IF(IND2(I).GT.0) NBALTTFZ=NBALTTFZ+1
             IF(IND2(I).EQ.-3) THEN
                 NBALTTFN=NBALTTFN+1
                 NBALTTFZ=NBALTTFZ-1
             ENDIF
             IF(IND2(I).EQ.3) THEN
                 NBALTTFN=NBALTTFN-1
                 NBALTTFZ=NBALTTFZ+1
             ENDIF
             EGS=EGS+EPS(I)-FMP-V(I)
          ELSE
             IF(IND2(I).LT.0) NoALTTFN=NoALTTFN+1
             IF(IND2(I).GT.0) NoALTTFZ=NoALTTFZ+1
             IF(IND2(I).EQ.-3) THEN
                 NoALTTFN=NoALTTFN+1
                 NoALTTFZ=NoALTTFZ-1
                 NBALTTFN=NBALTTFN+1
                 NBALTTFZ=NBALTTFZ-1
             ENDIF
             IF(IND2(I).EQ.3) THEN
                 NoALTTFN=NoALTTFN-1
                 NoALTTFZ=NoALTTFZ+1
                 NBALTTFN=NBALTTFN-1
                 NBALTTFZ=NBALTTFZ+1
             ENDIF
          ENDIF
         ELSE
            IF(IND2(I).EQ.-3) THEN
               NBALTTFN=NBALTTFN+1
               NBALTTFZ=NBALTTFZ-1
            ENDIF
            IF(IND2(I).EQ.3) THEN
               NBALTTFN=NBALTTFN-1
               NBALTTFZ=NBALTTFZ+1
            ENDIF
         ENDIF
       END DO
       VARIA=EGS-(STVINIT+(IN2-NBALTTFN+ICPI)*SN+(IZ2-NBALTTFZ-ICPI)*SP)
       IF(VARIA.LT.0.0) THEN
C Unaccepted collision
      IF(L1.GT.IA1.OR.L2.GT.IA1)
     s   NCOL_2C = NCOL_2C-1
        IF(IBERT.EQ.ibw) WRITE(6,*) 'Rejected by CDPP:EGS,STVINIT,',
     s 'NBALTTFN,NBALTTFZ,ICPI:',EGS,STVINIT,NBALTTFN,NBALTTFZ,ICPI
        GO TO 248
       ENDIF
      ENDIF

C Accepted collision; sum of Q values (charge exchange)
      IF (ibert.EQ.ibw) THEN
      WRITE(6,*) 'Accept collis EPS(L1),EPS(L2),V(L1),V(L2),Eapres,Q:',
     s EPS(L1),EPS(L2),V(L1),V(L2),Eapres,Q
      ENDIF
      SUM_Q = SUM_Q + Q
C One collision at least is accepted: No more local energy if option LOCE=3
C...and this collision is not between nucleons of the projectile (AB 7/2/2011)
      IF (LOCE.EQ.3.AND.(L1.GT.IA1.OR.L2.GT.IA1)) LOCE=0

C For composite projectiles, nucleons are free after an accepted interaction:
      IF(L1.LE.IA1) IBOUND_NUC(L1) = 0
      IF(L2.LE.IA1) IBOUND_NUC(L2) = 0

C Critere d'arret sur energie:
      IF(idnint(F(14)).EQ.1.) THEN
          IF(IND2(L1).EQ.-3) TF=TFM
          IF(IND2(L1).EQ.-1) TF=TFN
          IF(IND2(L1).EQ.1)  TF=TFP
          IF(IND2(L1).EQ.3)  TF=TFPP
      IF(IND1(L1).EQ.0) THEN
          IF(IND2(L1).EQ.1.AND.(EPS(L1)-FMP-V(L1)+SP).GE.EIN_MAXP)
     s            locsupe=locsupe+1
          IF(IND2(L1).EQ.-1.AND.(EPS(L1)-FMP-V(L1)+SN).GE.EIN_MAXN)
     s            locsupe=locsupe+1
      ELSE
         IF((EPS(L1)-FMP-FMPI-V(L1)+SP).GT.EIN_MAX) locsupe=locsupe+1
      ENDIF
          IF(IND2(L2).EQ.-3) TF=TFM
          IF(IND2(L2).EQ.-1) TF=TFN
          IF(IND2(L2).EQ.1)  TF=TFP
          IF(IND2(L2).EQ.3)  TF=TFPP
      IF(IND1(L2).EQ.0) THEN
          IF(IND2(L2).EQ.1.AND.(EPS(L2)-FMP-V(L2)+SP).GE.EIN_MAXP)
     s            locsupe=locsupe+1
          IF(IND2(L2).EQ.-1.AND.(EPS(L2)-FMP-V(L2)+SN).GE.EIN_MAXN)
     s            locsupe=locsupe+1
      ELSE
         IF((EPS(L2)-FMP-FMPI-V(L2)+SP).GT.EIN_MAX) locsupe=locsupe+1
      ENDIF
      NB_SUPE = NB_SUPE + locsupe
      ENDIF

      IF(IBERT.EQ.IBW) THEN
      WRITE(6,*) 'Before BACKTOSPECT,L1,L2,nb_jpart:',L1,L2,nb_jpart
      ENDIF
C TEST: Participant becomes a spectateur if below some energy
c (this is to compare with ISABEL) 3/3/2009 AB,SL
c Coulomb Barrier (BCP) introduced for p. 11/2011 AB
      IF(IBACKTOSPECT.EQ.1) THEN

        IF(IND2(L1).EQ.1) THEN
      CTE_LOC=FMP+V(L1)-SP+SP+PARAM_LOC+BCP
      ELSE
      CTE_LOC=FMP+V(L1)-SN+SN+PARAM_LOC
      ENDIF
      IF (IND1(L1).EQ.0.AND.EPS(L1).LE.CTE_LOC) THEN
              JKILL_L1=1
              JVIEUX=JPARTICIP(L1)
              JPARTICIP(L1)=0
      IF (ibert.EQ.ibw) THEN
           WRITE(6,*) 'L1 back as spectateur:',L1
      ENDIF
            IF(JVIEUX.NE.0) nb_jpart=nb_jpart-1
                  nb_bloc=nb_bloc +1
      ELSE
              JKILL_L1=0
              JVIEUX=JPARTICIP(L1)
              JPARTICIP(L1)=1
            IF(JVIEUX.NE.1) nb_jpart=nb_jpart+1
      ENDIF

        IF(IND2(L2).EQ.1) THEN
      CTE_LOC=FMP+V(L2)-SP+SP+PARAM_LOC+BCP

      ELSE
      CTE_LOC=FMP+V(L2)-SN+SN+PARAM_LOC

      ENDIF

            IF (IND1(L2).EQ.0.AND.EPS(L2).LE.CTE_LOC) THEN
              JKILL_L2=1
              JVIEUX=JPARTICIP(L2)
              JPARTICIP(L2)=0
      IF (ibert.EQ.ibw) THEN
           WRITE(6,*) 'L2 back as spectateur:',L2
      ENDIF
              IF(JVIEUX.NE.0) nb_jpart=nb_jpart-1
                  nb_bloc=nb_bloc +1
            ELSE
              JKILL_L2=0
              JVIEUX=JPARTICIP(L2)
              JPARTICIP(L2)=1
              IF(JVIEUX.NE.1) nb_jpart=nb_jpart+1
            ENDIF

C If both back to spectateur, only the less energetic one!

      ELSE
C Here NOBackToSpectator
      JVIEUX=JPARTICIP(L1)
      JPARTICIP(L1)=1
            IF(JVIEUX.EQ.0) nb_jpart=nb_jpart+1
      JVIEUX=JPARTICIP(L2)
      JPARTICIP(L2)=1
            IF(JVIEUX.EQ.0) nb_jpart=nb_jpart+1

      ENDIF

      IF(IBERT.EQ.IBW) THEN
      WRITE(6,*) 'AFTER BACKTOSPECT, nb_jpart:',nb_jpart
      ENDIF

      TAVAIL=SQ-2.*FMP

C HERE RIGHT PLACE FOR GLOBAL STATISTICAL PAULI:
C For global statistical Pauli, counts particles in fermi sea.
      IF(NPAULSTR.EQ.2) THEN
C Number of neutrons (p) below EF AFTER collision

C NOT a DELTA!
C Actualisation of global counters after this collision:
      CALL GLBP_COUNT(L1,L2,+1)
      ENDIF

            IF (NOSURF.LE.0) THEN
c surface
      pppp=sqrt(p1(l1)**2+p2(l1)**2+p3(l1)**2)
      rrrr=sqrt(x1(l1)**2+x2(l1)**2+x3(l1)**2)
      IF(IND1(L1).EQ.0) THEN
      IF(IND2(L1).EQ.3) PF=PFPP
      IF(IND2(L1).EQ.1) PF=PFP
      IF(IND2(L1).EQ.-1) PF=PFN
      IF(IND2(L1).EQ.-3) PF=PFM
      ELSE
      IS = (IND2(L1)+5)/2
            FMDEL = SQRT(EPS(L1)**2 -P1(L1)**2 -P2(L1)**2 - P3(L1)**2)
            if(IS.eq.1)then                   !FURUTA20121003
              PF = SQRT(TFM*(TFM+2.*FMDEL))   !FURUTA20121003
            elseif(IS.eq.2)then               !FURUTA20121003
              PF = SQRT(TFN*(TFN+2.*FMDEL))   !FURUTA20121003
            elseif(IS.eq.3)then               !FURUTA20121003
              PF = SQRT(TFP*(TFP+2.*FMDEL))   !FURUTA20121003
            elseif(IS.eq.4)then               !FURUTA20121003
              PF = SQRT(TFPP*(TFPP+2.*FMDEL)) !FURUTA20121003
            endif                             !FURUTA20121003
      ENDIF
      if (pppp.le.pf) then
      XV=pppp/pf
      rcorr=FLIN(XV)
      if (rrrr.gt.rcorr) then
      rcab=rcorr/rrrr
      x1(l1)=x1(l1)*0.99*rcorr/rrrr
      x2(l1)=x2(l1)*0.99*rcorr/rrrr
      x3(l1)=x3(l1)*0.99*rcorr/rrrr
      endif
      endif
      pppp=sqrt(p1(l2)**2+p2(l2)**2+p3(l2)**2)
      rrrr=sqrt(x1(l2)**2+x2(l2)**2+x3(l2)**2)
      IF(IND1(L2).EQ.0) THEN
      IF(IND2(L2).EQ.3) PF=PFPP
      IF(IND2(L2).EQ.1) PF=PFP
      IF(IND2(L2).EQ.-1) PF=PFN
      IF(IND2(L2).EQ.-3) PF=PFM
      ELSE
      IS = (IND2(L2)+5)/2
            FMDEL = SQRT(EPS(L2)**2 -P1(L2)**2 -P2(L2)**2 - P3(L2)**2)
            if(IS.eq.1)then                   !FURUTA20121003
              PF = SQRT(TFM*(TFM+2.*FMDEL))   !FURUTA20121003
            elseif(IS.eq.2)then               !FURUTA20121003
              PF = SQRT(TFN*(TFN+2.*FMDEL))   !FURUTA20121003
            elseif(IS.eq.3)then               !FURUTA20121003
              PF = SQRT(TFP*(TFP+2.*FMDEL))   !FURUTA20121003
            elseif(IS.eq.4)then               !FURUTA20121003
              PF = SQRT(TFPP*(TFPP+2.*FMDEL)) !FURUTA20121003
            endif                             !FURUTA20121003
      ENDIF
      if (pppp.le.pf) then
      XV=pppp/pf
      rcorr=FLIN(XV)
      if (rrrr.gt.rcorr) then
      rcab=rcorr/rrrr
      x1(l2)=x1(l2)*0.99*rcorr/rrrr
      x2(l2)=x2(l2)*0.99*rcorr/rrrr
      x3(l2)=x3(l2)*0.99*rcorr/rrrr
      endif
      endif
            END IF
      IF (NP.EQ.0) GO TO 240                                            P-N07800
      NPION=NPION+1                                                     P-N07810
      CALL LOREN(T(12),T(13),T(14),B1,B2,B3,T(15))                      P-N07820
      Q1(NPION)=T(12)                                                   P-N07830
      Q2(NPION)=T(13)                                                   P-N07840
      Q3(NPION)=T(14)                                                   P-N07850
      Q4(NPION)=T(15)                                                   P-N07860
  240 CONTINUE
C Exclude here interactions between nucleons of composit projectiles
C for identification of transparent events. 24/06/2010 A.B.
      IF(L1.GT.IA1.OR.L2.GT.IA1) NCOL=NCOL+1
      IF (L2.NE.1) GO TO 870                                            P-N07880
C critere pour la leading particle: AVANT impulsion longitudinale max L=1
C Change en fevrier 2002: leading part. = energie totale max (L=1)

      IF (P3(L2).GT.P3(L1)) GO TO 870                                   P-N07890
C***************************************************************
C ATTENTION, Il faut mieux faire et selectionner la plus grande energie
C   des particules participantes (JPARTICIP()=1) et dans le noyau (NESC()=0)!
C***************************************************************
      XR1=P1(L1)                                                        P-N07900
      XR2=P2(L1)                                                        P-N07910
      XR3=P3(L1)                                                        P-N07920
      XR4=EPS(L1)                                                       P-N07930
      XR5=X1(L1)                                                        P-N07940
      XR6=X2(L1)                                                        P-N07950
      XR7=X3(L1)                                                        P-N07960
      XR8=GL1                                                           P-N07970
      XR9=V(L1)         ! ThA  Stock V
      xr11=hel(l1)
      IXR1=IND1(L1)                                                     P-N07980
      IXR2=IND2(L1)                                                     P-N07990
      IXR3=ICH1                                                         P-N08000
      IXR4=JPARTICIP(L1)
      P1(L1)=P1(L2)                                                     P-N08010
      P2(L1)=P2(L2)                                                     P-N08020
      P3(L1)=P3(L2)                                                     P-N08030
      EPS(L1)=EPS(L2)                                                   P-N08040
      V(L1)=V(L2)       ! ThA copy V
      X1(L1)=X1(L2)                                                     P-N08050
      X2(L1)=X2(L2)                                                     P-N08060
      X3(L1)=X3(L2)                                                     P-N08070
      GL1=GL2                                                           P-N08080
      IND1(L1)=IND1(L2)                                                 P-N08090
      IND2(L1)=IND2(L2)                                                 P-N08100
      ICH1=ICH2                                                         P-N08110
      JPARTICIP(L1)=JPARTICIP(L2)
      hel(l1)=hel(l2)
      P1(L2)=XR1                                                        P-N08120
      P2(L2)=XR2                                                        P-N08130
      P3(L2)=XR3                                                        P-N08140
      EPS(L2)=XR4                                                       P-N08150
      V(L2)=XR9         ! ThA copy V
      X1(L2)=XR5                                                        P-N08160
      X2(L2)=XR6                                                        P-N08170
      X3(L2)=XR7                                                        P-N08180
      GL2=XR8                                                           P-N08190
      IND1(L2)=IXR1                                                     P-N08200
      IND2(L2)=IXR2                                                     P-N08210
      ICH2=IXR3                                                         P-N08220
      JPARTICIP(L2)=IXR4
      hel(l2)=xr11
      IF(ICH1+ICH2-IND1(L1)-IND1(L2).NE.0.OR.ICH1+ICH2.NE.1) GO TO 870  P-N08230
      IF (K.EQ.0) GO TO 870                                             P-N08240
      DO 871 I=1,K                                                      P-N08250
      IF (IND(I).NE.1) GO TO 872                                        P-N08260
      IF (JND(I).NE.0) GO TO 872                                        P-N08270
      IND(I)=L1                                                         P-N08280
      GO TO 870                                                         P-N08290
  872 IF (IND(I).NE.L1) GO TO 871                                       P-N08300
      IF (JND(I).NE.0) GO TO 871                                        P-N08310
      IND(I)=1                                                          P-N08320
      GO TO 870                                                         P-N08330
  871 CONTINUE                                                          P-N08340
  870 TLG(L1)=TH*EPS(L1)/SQRT(EPS(L1)**2-P1(L1)**2-P2(L1)**2-P3(L1)**2) P-N08350
      TLG(L2)=TH*EPS(L2)/SQRT(EPS(L2)**2-P1(L2)**2-P2(L2)**2-P3(L2)**2) P-N08360
      NC(L1)=NC(L1)+1                                                   P-N08370
      NC(L2)=NC(L2)+1                                                   P-N08380
      LED=0                                                             P-N08390
      IF(ICH1+ICH2-IND1(L1)-IND1(L2)) 500,501,502                       P-N08400
  500 MRND=MRND+1                                                       P-N08410
      GO TO 503                                                         P-N08420
  501 IF(ICH1+ICH2-1) 504,505,506                                       P-N08430
  504 MRNN=MRNN+1                                                       P-N08440
      GO TO 503                                                         P-N08450
  505 MRDD=MRDD+1                                                       P-N08460
      LED=1                                                             P-N08470
      GO TO 503                                                         P-N08480
  506 MCDD=MCDD+1                                                       P-N08490
      LED=1                                                             P-N08500
      GO TO 503                                                         P-N08510
  502 MRDN=MRDN+1                                                       P-N08520
  503 CONTINUE                                                          P-N08530
  242 CONTINUE                                                          P-N08540

      IF(IBERT.EQ.IBW) THEN
      WRITE(6,*) ' ACCEPTED interaction, L1,IND2(L1),IND1(L1),',
     s'L2,IND2(L2),IND1(L2),',L1,IND2(L1),IND1(L1),L2,IND2(L2),IND1(L2)
      WRITE(6,*) 'EPS(L1),JPARTICIP(L1),...(L2),NB_JPART:',
     s EPS(L1),JPARTICIP(L1),EPS(L2),JPARTICIP(L2),NB_JPART
      ENDIF

c Fill the histogram of the time to the first accepted collision

C*******************************************************************
C Test d'arret sur max des energies des particules dans le noyau
C +10Mev=parametre d'energie au dessus du potentiel f(5)
C*******************************************************************

C                                                                       P-N08550
CCC   REEVALUATION OF THE TIMES T(A,B) FOR (A OR B)=(L1 OR L2)          P-N08560
C                                                                       P-N08570
C+++++++++++ L-CONSERVATION ++++++++++++++++++++++++++++++++++          P-N08580
      IF (K6.EQ.1) THEN                                                 P-N08590
      AML1=AM(P1(L1),P2(L1),P3(L1),EPS(L1))                             P-N08600
      AML2=AM(P1(L2),P2(L2),P3(L2),EPS(L2))                             P-N08610
      T(37)=(AML2*P1(L1)-AML1*P1(L2))/(AML1+AML2)                       P-N08620
      T(38)=(AML2*P2(L1)-AML1*P2(L2))/(AML1+AML2)                       P-N08630
      T(39)=(AML2*P3(L1)-AML1*P3(L2))/(AML1+AML2)                       P-N08640
      T(40)=SQRT(T(34)*T(34)+T(35)*T(35)+T(36)*T(36))                   P-N08650
      T(41)=SQRT(T(37)*T(37)+T(38)*T(38)+T(39)*T(39))                   P-N08660
      RHOPI=TT31*T(34)+TT32*T(35)+TT33*T(36)                            P-N08670
      T(43)=TT31-RHOPI*T(34)/T(40)**2                                   P-N08680
      T(44)=TT32-RHOPI*T(35)/T(40)**2                                   P-N08690
      T(45)=TT33-RHOPI*T(36)/T(40)**2                                   P-N08700
      T(46)=SQRT(T(43)*T(43)+T(44)*T(44)+T(45)*T(45))                   P-N08710
      T(43)=T(43)/T(46)                                                 P-N08720
      T(44)=T(44)/T(46)                                                 P-N08730
      T(45)=T(45)/T(46)                                                 P-N08740
      CIF=(T(34)*T(37)+T(35)*T(38)+T(36)*T(39))/T(40)/T(41)             P-N08750
c trouble with forward scattering 22/3/95
      if(abs(cif).gt.1.)cif=sign(real(1.,8),cif)
      SIF=SQRT(1.-CIF*CIF)                                              P-N08760
      T(37)=(T(34)*CIF/T(40)+T(43)*SIF)*T(41)                           P-N08770
      T(38)=(T(35)*CIF/T(40)+T(44)*SIF)*T(41)                           P-N08780
      T(39)=(T(36)*CIF/T(40)+T(45)*SIF)*T(41)                           P-N08790
      TRI=SQRT(TT31*TT31+TT32*TT32+TT33*TT33)                           P-N08800
      CCHI=RHOPI/TRI/T(40)                                              P-N08810
      SCHI=SQRT(1.-CCHI*CCHI)                                           P-N08820
      C1=CIF*CCHI-SIF*SCHI                                              P-N08830
      C2=SIF*CCHI+CIF*SCHI                                              P-N08840
      TT31=(C1*T(34)/T(40)+C2*T(43))*TRI*T(40)/T(41)                    P-N08850
      TT32=(C1*T(35)/T(40)+C2*T(44))*TRI*T(40)/T(41)                    P-N08860
      TT33=(C1*T(36)/T(40)+C2*T(45))*TRI*T(40)/T(41)                    P-N08870
      X1(L1)=T(31)+AML2*TT31/(AML1+AML2)                                P-N08880
      X2(L1)=T(32)+AML2*TT32/(AML1+AML2)                                P-N08890
      X3(L1)=T(33)+AML2*TT33/(AML1+AML2)                                P-N08900
      X1(L2)=T(31)-AML1*TT31/(AML1+AML2)                                P-N08910
      X2(L2)=T(32)-AML1*TT32/(AML1+AML2)                                P-N08920
      X3(L2)=T(33)-AML1*TT33/(AML1+AML2)                                P-N08930
      P1(L1)=AML1*TT34/(AML1+AML2)+T(37)                                P-N08940
      P2(L1)=AML1*TT35/(AML1+AML2)+T(38)                                P-N08950
      P3(L1)=AML1*TT36/(AML1+AML2)+T(39)                                P-N08960
      EPS(L1)=W(P1(L1),P2(L1),P3(L1),AML1)                              P-N08970
      P1(L2)=AML2*TT34/(AML1+AML2)-T(37)                                P-N08980
      P2(L2)=AML2*TT35/(AML1+AML2)-T(38)                                P-N08990
      P3(L2)=AML2*TT36/(AML1+AML2)-T(39)                                P-N09000
      EPS(L2)=W(P1(L2),P2(L2),P3(L2),AML2)                              P-N09010
      ENDIF                                                             P-N09020
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'Ready for next avatar: EPS(L1),EPS(L2),V(L1),V(L2)',
     s EPS(L1),EPS(L2),V(L1),V(L2)
      WRITE(6,*) '   P(L1),P(L2):'
      WRITE(6,*) P1(L1),P2(L1),P3(L1)
      WRITE(6,*) P1(L2),P2(L2),P3(L2)
      ENDIF
C+++++++++++++++ L-CONSERVATION ++++++++++++++++++++++++++++++++++++    P-N09030
c     -ind1(l2),ind2(l1),ind2(l2), eps(l1)+eps(l2)
      IF (K.EQ.0) GO TO 514                                             P-N09040
      KD=0                                                              P-N09050
      CCR=TAU                                                           P-N09060
      DO 50 I=1,K                                                       P-N09070
      I20=I-KD                                                          P-N09080
      IF (K4.NE.2.OR.LED.NE.1) GO TO 512                                P-N09090
      IF (JND(I).EQ.0) GO TO 511                                        P-N09100
  512 CONTINUE                                                          P-N09110
      IF (IND(I).EQ.L1) GO TO 52                                        P-N09120
      IF (IND(I).EQ.L2) GO TO 52                                        P-N09130
      IF (JND(I).EQ.L2) GO TO 52                                        P-N09140
      IF (JND(I).EQ.L1) GO TO 52                                        P-N09150
      GO TO 513                                                         P-N09160
  511 IF (IND(I).EQ.L1.AND.IND1(L1).EQ.1) CROIS(I)=(CROIS(I)-CCR)*EPS(L1P-N09170
     -)/SQRT(EPS(L1)**2-P1(L1)**2-P2(L1)**2-P3(L1)**2)/GL1+CCR          P-N09180
      IF (IND(I).EQ.L2.AND.IND1(L2).EQ.1) CROIS(I)=(CROIS(I)-CCR)*EPS(L2P-N09190
     -)/SQRT(EPS(L2)**2-P1(L2)**2-P2(L2)**2-P3(L2)**2)/GL2+CCR          P-N09200
  513 CONTINUE                                                          P-N09210
      CROIS(I20)=CROIS(I)-CCR                                           P-N09220
      IND(I20)=IND(I)                                                   P-N09230
      JND(I20)=JND(I)                                                   P-N09240
      GO TO 50                                                          P-N09250
   52 KD=KD+1                                                           P-N09260
   50 CONTINUE                                                          P-N09270
      K=K-KD                                                            P-N09280
  514 CALL NEWT(L1,L2,LOCE,IBERT,ibw)                                   P-N09290
      IF(IBERT.EQ.ibw) WRITE(6,*) 'IFL_BOUND_PROJ:',IFL_BOUND_PROJ
      IF(IND2(L1).EQ.3) TFC=TFPP
      IF(IND2(L1).EQ.1) TFC=TFP
      IF(IND2(L1).EQ.-1) TFC=TFN
      IF(IND2(L1).EQ.-3) TFC=TFM
      FMDEL = SQRT(EPS(L1)**2 -P1(L1)**2 - P2(L1)**2 - P3(L1)**2)
      PF = SQRT(TFC*(TFC + 2.*FMDEL))
C For bound composite projectiles:
      IF(IFL_BOUND_PROJ.EQ.0) THEN
        P1SP=P1(L1)
        P2SP=P2(L1)
        P3SP=P3(L1)
        EPSP=EPS(L1)
      ELSE
        IF(L1.LE.IA1) then
         if (IBOUND_NUC(L1).EQ.1) THEN
          P1SP=PINC1
          P2SP=PINC2
          P3SP=PINC3
          EPSP=ENERGIE_IN
         else
          P1SP=P1(L1)
          P2SP=P2(L1)
          P3SP=P3(L1)
          EPSP=EPS(L1)
         end if
        ELSE
          P1SP=P1(L1)
          P2SP=P2(L1)
          P3SP=P3(L1)
          EPSP=EPS(L1)
        ENDIF
      ENDIF
      TREF=REF(X1(L1),X2(L1),X3(L1),P1SP,P2SP,P3SP,EPSP,R22,PF)
      IF (TREF.GT.TMAX5) GO TO 515                                      P-N09310
      K=K+1                                                             P-N09320
      CROIS(K)=TREF                                                     P-N09330
      IND(K)=L1                                                         P-N09340
      JND(K)=-1                                                         P-N09350
  515 IF(IND2(L2).EQ.3) TFC=TFPP
      IF(IND2(L2).EQ.1) TFC=TFP
      IF(IND2(L2).EQ.-1) TFC=TFN
      IF(IND2(L2).EQ.-3) TFC=TFM
      FMDEL = SQRT(EPS(L2)**2 -P1(L2)**2 - P2(L2)**2 - P3(L2)**2)
      PF = SQRT(TFC*(TFC + 2.*FMDEL))
      IF(IFL_BOUND_PROJ.EQ.0) THEN
        P1SP=P1(L2)
        P2SP=P2(L2)
        P3SP=P3(L2)
        EPSP=EPS(L2)
      ELSE
        IF(L2.LE.IA1) then
         if (IBOUND_NUC(L2).EQ.1) THEN
          P1SP=PINC1
          P2SP=PINC2
          P3SP=PINC3
          EPSP=ENERGIE_IN
         else
          P1SP=P1(L2)
          P2SP=P2(L2)
          P3SP=P3(L2)
          EPSP=EPS(L2)
         end if
        ELSE
          P1SP=P1(L2)
          P2SP=P2(L2)
          P3SP=P3(L2)
          EPSP=EPS(L2)
        ENDIF
      ENDIF
      TREF=REF(X1(L2),X2(L2),X3(L2),P1SP,P2SP,P3SP,EPSP,R22,PF)
      IF (TREF.GT.TMAX5) GO TO 516                                      P-N09370
      K=K+1                                                             P-N09380
      CROIS(K)=TREF                                                     P-N09390
      IND(K)=L2                                                         P-N09400
      JND(K)=-1                                                         P-N09410
  516 IF (K4.EQ.2) GO TO 848                                            P-N09420
      IF (K) 230,230,449                                                P-N09430
C                                                                       P-N09440
  848 IF (NPION.EQ.0) GO TO 844                                         P-N09450
      IF (IND1(L1).EQ.1) GO TO 843                                      P-N09460
      DO 842 K20=1,NPION                                                P-N09470
  842 CALL NEW3(K20,L1,IND2(L1),idnint(f(17))) ! ***** ThA                 P-N09490
  843 IF (IND1(L2).EQ.1) GO TO 844                                      P-N09500
      DO 847 K20=1,NPION                                                P-N09510
  847 CALL NEW3(K20,L2,IND2(L2),idnint(f(17))) ! ***** ThA                 P-N09530
  844 CONTINUE                                                          P-N09540
C                                                                       P-N09550
      IF(IND1(L1)+IND1(L2).LE.ICH1+ICH2) GO TO 849                      P-N09560
      IF(IND1(L1)-ICH1.NE.1) GO TO 820                                  P-N09570
      LNEW=L1                                                           P-N09580
      GO TO 821                                                         P-N09590
  820 IF(IND1(L2)-ICH2.NE.1) GO TO 849                                  P-N09600
      LNEW=L2                                                           P-N09610
  821 rndm=rn(0)
C largeur variable du delta (Phase Space Factor introduced 4/2001)
C (180.**3 = 5832000.)
      AMLNEW=SQRT(EPS(LNEW)**2-P1(LNEW)**2-P2(LNEW)**2-P3(LNEW)**2)
      GG=G0
      IF(AMLNEW.GT.1500.) GG=200.
      if(idnint(f(17)).eq.1)then
         GG=G0
      endif

      GEFF=EPS(LNEW)/AMLNEW
      QQQ=SQRT((AMLNEW**2-(FMP+FMPI)**2)*(AMLNEW**2-(FMP-FMPI)**2))
     s     /(2.*AMLNEW)
      PSF=QQQ**3/(QQQ**3+5832000.)
      TDEL=-HC/(GG*PSF)*LOG(RNDM)*GEFF
      if(idnint(f(17)).eq.1)TDEL=-HC/(G0*PSF)*LOG(RNDM)*GEFF

      IF (TDEL.GT.TMAX5) GO TO 849                                      P-N09700
      K=K+1                                                             P-N09710
      CROIS(K)=TDEL                                                     P-N09720
      IND(K)=LNEW                                                       P-N09730
      JND(K)=0                                                          P-N09740
  849 IF (K.EQ.0) GO TO 230                                             P-N09750

      GO TO 449                                                         P-N09760
C                                                                       P-N09770
CCC   DECAY OF THE DELTA PARTICLE                                       P-N09780
C                                                                       P-N09790
  805 NPION=NPION+1                                                     P-N09800
      ICHD=IND2(L1)                                                     P-N09810
      T(31)=P1(L1)                                                      P-N09820
      T(32)=P2(L1)                                                      P-N09830
      T(33)=P3(L1)                                                      P-N09840
      T(34)=EPS(L1)                                                     P-N09850
      savehel=hel(l1)
      TV=V(L1)
      IF(IND2(L1).EQ.3) VKFO1=V0PP
      IF(IND2(L1).EQ.1) VKFO1=V0P
      IF(IND2(L1).EQ.-1) VKFO1=V0N
      IF(IND2(L1).EQ.-3) VKFO1=V0M
      Eavant=EPS(L1)-V(L1)
      var_ab=EPS(L1)**2-P1(L1)**2-P2(L1)**2-P3(L1)**2
      YM(NPION)=0.
      IF(var_ab.GT.0.)
     s                 YM(NPION)=SQRT(var_ab)                           P-N09860
        ASSD=YM(NPION)

C Critere d'arret sur energie:
      IF(idnint(F(14)).EQ.1.) THEN
      locsupe=0
          IF(IND2(L1).EQ.-3) TF=TFM
          IF(IND2(L1).EQ.-1) TF=TFN
          IF(IND2(L1).EQ.1)  TF=TFP
          IF(IND2(L1).EQ.3)  TF=TFPP
      IF(IND1(L1).EQ.0) THEN
          IF(IND2(L1).EQ.1.AND.(EPS(L1)-FMP-V(L1)+SP).GE.EIN_MAXP)
     s            locsupe=locsupe-1
          IF(IND2(L1).EQ.-1.AND.(EPS(L1)-FMP-V(L1)+SN).GE.EIN_MAXN)
     s            locsupe=locsupe-1
      ELSE
         IF((EPS(L1)-FMP-FMPI-V(L1)+SP).GT.EIN_MAX) locsupe=locsupe-1
      ENDIF
      ENDIF
C Global Statistical Pauli
      IF(NPAULSTR.EQ.2)
     s          CALL GLBP_COUNT(L1,0,-1)

  800 continue
      if(IBERT.EQ.ibw) then
      WRITE(6,*) 'DELTA decay, L1,IND2:',L1,ind2(L1)
      WRITE(6,*) '   IND1,P,EPS,YM(invariant mass):'
      write(6,*) ind1(l1),P1(L1),P2(L1),P3(L1),EPS(L1),YM(NPION)
      endif
      if(idnint(f(17)).ne.1)then
         IF(YM(NPION).LT.(FMP+FMPI)) GOTO 853
      endif

      IF(LOCED.NE.0) THEN
      R_1 =X1(L1)**2 +X2(L1)**2 +X3(L1)**2
      R_1 = SQRT(R_1)
      PI2 = P1(L1)**2 + P2(L1)**2 + P3(L1)**2
      FMI2=EPS(L1)**2 - PI2
      fmi=sqrt(fmi2)
      vloc1=VLOC(l1,r_1,fmi,eps(l1)-fmi,v(l1),ind1(l1),ind2(l1))
      E_1=EPS(L1)-VLOC1
      AA=E_1**2 - FMI2
      IF (AA.LT.0) THEN
            COR1 = 0
      E_1=SQRT(FMI2)
      ELSE
      COR1=SQRT(AA/PI2)
      ENDIF
      P1L1=P1(L1)*COR1
      P2L1=P2(L1)*COR1
      P3L1=P3(L1)*COR1

      ENDIF

      IF(LOCED.EQ.1) THEN
       EPS(L1) = E_1
       P1(L1) = P1L1
       P2(L1) = P2L1
       P3(L1) = P3L1
C Pour test conservation de E avec E-Vloc(r)
      ENDIF
      Eavant = EPS(L1)-V(L1)


      CALL DECAY2(P1(L1),P2(L1),P3(L1),EPS(L1),NPION,
     s  FMP,FMPI,hel(l1),B1d,B2d,B3d)

C DECAY
      IF (IND2(L1)*IND2(L1).EQ.9) GO TO 806                             P-N10210
      rndm=rn(0)

      IF (RNDM.LT.0.333333333) GO TO 837                                P-N10260
      IPI(NPION)=0                                                      P-N10270
      GO TO 809                                                         P-N10280
  837 IPI(NPION)=IND2(L1)*2                                             P-N10290
      IND2(L1)=-IND2(L1)                                                P-N10300
      GO TO 809                                                         P-N10310
  806 IND2(L1)=IND2(L1)/3                                               P-N10320
      IPI(NPION)=2*IND2(L1)                                             P-N10330
  809 CONTINUE                                                          P-N10340
      IND1(L1)=0                                                        P-N10350
      TLG(L1)=0.                                                        P-N10360
      if(idnint(f(17)).ne.1)then
      if(IBERT.EQ.ibw) then
       write(6,*) 'P1 :','1',ICHD,T(34),TV,ASSD
       write(6,*) 'P3 :',IND1(L1),IND2(L1),EPS(L1)
       write(6,*) 'P4 :',IPI(NPION),Q4(NPION)
      endif

C (For decays out of the nucleus):
      VLOCP1=0.
C Correction for realistic Q value (Right nucleon mass for EOUT):
      IF(NESC(L1).EQ.1) THEN
      JZ=(1+IND2(L1))/2
      EOUTDM=EOUTDM+FMP-FMNUC(1,JZ)
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'Nucleon mass correction for Delta decay outside:',L1
      WRITE(6,*) '   EOUTDM,JZ:',EOUTDM,JZ
      ENDIF
      ENDIF

      IF (NESC(L1).LT.1) THEN
      bnul=0.0
      IF(IND1(L1).EQ.0.AND.IND2(L1).EQ.1) VKF1=V2P
      IF(IND1(L1).EQ.0.AND.IND2(L1).EQ.-1) VKF1=V2N
      IF(IPI(NPION).EQ.-2) V0PI=V0PIM
      IF(IPI(NPION).EQ.0) V0PI=V0PIN
      IF(IPI(NPION).EQ.2) V0PI=V0PIP
        POSDELTA=SQRT(X1(L1)**2+X2(L1)**2+X3(L1)**2)
        IF(POSDELTA.GT.RPION) V0PI=0.0

      QQ1=Q1(NPION)
      QQ2=Q2(NPION)
      QQ3=Q3(NPION)
      QQ4=Q4(NPION)
      IF(LOCED.EQ.1) THEN
      fmi=sqrt(fmi2)
      vlocp1=VLOC(l1,r_1,fmi,eps(l1)-fmi,v(l1),ind1(l1),ind2(l1))
      Q=VLOCP1-VLOC1
      IFLAB=0
      IF(ABS(Q).GT.0.0001) THEN
      IFLAB=1
      ENDIF
        CALL AECSVT(eavant+vloc1,
     &  B1d,B2d,B3d,
     &  P1(L1),P2(L1),P3(L1),EPS(L1),VKF1,QQ1,QQ2,QQ3,QQ4,
     &  V0PI,V(L1),bnul,IEJCT,DELTAE,IVFCTE,f(13),
     s  VLOCP1,real(0.,8),l1,r_1,0,real(0.,8),
     s  loced,ind1(l1),0,ind2(l1),0)
      ELSE
      Q=0.
        CALL AECSVT(eavant,
     &  B1d,B2d,B3d,
     &  P1(L1),P2(L1),P3(L1),EPS(L1),VKF1,QQ1,QQ2,QQ3,QQ4,
     &  V0PI,V(L1),bnul,IEJCT,DELTAE,IVFCTE,f(13),
     s  real(0.,8),real(0.,8),
     s  l1,r_1,0,real(0.,8),loced,ind1(l1),0,ind2(l1),0)
      ENDIF
      Q1(NPION)=QQ1
      Q2(NPION)=QQ2
      Q3(NPION)=QQ3
      Q4(NPION)=QQ4

      IF(IEJCT.EQ.1) THEN
          irejet=irejet+1
        GOTO 853
        ENDIF
        Eapres=EPS(L1)-V(L1)+Q4(NPION)-V0PI
      if(loced.eq.1) then
         vlocp1=VLOC(l1,r_1,fmi,eps(l1)-fmi,v(l1),ind1(l1),ind2(l1))
         Q = VLOCP1-VLOC1
      endif
      if(IBERT.EQ.ibw) then
       write(*,*) ' bilan DEL',ibert,ABS(Eavant-Eapres)
       write(*,*) 'P1 :','1',ICHD,T(34),TV,ASSD
       write(*,*) 'P3 :',IND1(L1),IND2(L1),EPS(L1),V(L1)
       write(*,*) 'P4 :',IPI(NPION),' -- ',Q4(NPION),V0PI
      endif
        IF(ABS(Eavant-Eapres-Q).gt.0.001) then
        goto 853
        ENDIF
      END IF

      IF(LOCED.EQ.1) THEN
C test of local energy, restitution of pot energy:
      IF(IFLAB.EQ.1) THEN
      ENDIF
       FML1=FMP
       EPS(L1)=EPS(L1)+ VLOCP1
       COR=P1(L1)**2 + P2(L1)**2 + P3(L1)**2
       COR = SQRT((EPS(L1)**2 - FML1**2)/COR)
       P1(L1) = P1(L1)*COR
       P2(L1) = P2(L1)*COR
       P3(L1) = P3(L1)*COR
      ENDIF

      endif

C escape ?
      IF (NESC(L1).GT.0) GO TO 850                                      P-N09890
      IF(IND2(L1).EQ.-3) PF=PFM   ! ThA
      IF(IND2(L1).EQ.-1) PF=PFN   ! ThA
      IF(IND2(L1).EQ.1) PF=PFP    ! ThA
      IF(IND2(L1).EQ.3) PF=PFPP   ! ThA
      CALL PAULIL(L1,RBL,PBL,XPB,PF,LOCE)       ! ThA                    P-N09900
      rndm=rn(0)
C Pauli blocking?
      IF (RNDM.LE.XPB) GO TO 1848                                       P-N09960

      IZLOC= IPI(npion)/2
      QV=FMNUC(IACOUR,IZCOUR)-FMNUC(IACOUR,IZCOUR-IZLOC)-FMNUC(0,IZLOC)
      QVV=QV+FMPI
      if(posdelta.gt.rpion.and.q4(npion)+qvv.lt.fmpi) then
c     Forbid the delta decay if the pion cannot be emitted with a
c     positive kinetic energy (using realistic masses)!
        goto 1848
      endif

C Le decay ne peut conduire a un noyau de A nucleons
C  sous l'energie de Fermi et dans une config. d'energie inferieure a
C  EFER-(IA2-NBALTTF)*TF).
       EGS=0.
       NBALTTFN=0
       NBALTTFZ=0
       NoALTTFN=0
       NoALTTFZ=0
       ICPI=0
       IF(NPION.GT.0) THEN
        DO KJ=1,NPION
         ICPI=ICPI+IPI(KJ)/2
        ENDDO
       ENDIF
       DO I=1,IA
         IF(NESC(I).EQ.0) THEN
          IF(IND2(I).EQ.-3) TF=TFM
          IF(IND2(I).EQ.-1) TF=TFN
          IF(IND2(I).EQ.1)  TF=TFP
          IF(IND2(I).EQ.3)  TF=TFPP
          PTEST2=P1(I)**2+P2(I)**2+P3(I)**2
          AMTEST=SQRT(EPS(I)**2-PTEST2)
          TTEST=EPS(I)-AMTEST
          IF(TTEST.LE.TF) THEN
             IF(IND2(I).LT.0) NBALTTFN=NBALTTFN+1
             IF(IND2(I).GT.0) NBALTTFZ=NBALTTFZ+1
             EGS=EGS+EPS(I)-FMP-V(I)
             IF(IND2(I).EQ.-3) THEN
                 NBALTTFN=NBALTTFN+1
                 NBALTTFZ=NBALTTFZ-1
             ENDIF
               IF(IND2(I).EQ.3) THEN
                     NBALTTFN=NBALTTFN-1
                     NBALTTFZ=NBALTTFZ+1
               ENDIF
          ELSE
               IF(IND2(I).LT.0) NoALTTFN=NoALTTFN+1
             IF(IND2(I).GT.0) NoALTTFZ=NoALTTFZ+1
             IF(IND2(I).EQ.-3) THEN
                 NoALTTFN=NoALTTFN+1
                 NoALTTFZ=NoALTTFZ-1
                 NBALTTFN=NBALTTFN+1
                 NBALTTFZ=NBALTTFZ-1
             ENDIF
               IF(IND2(I).EQ.3) THEN
                     NoALTTFN=NoALTTFN-1
                     NoALTTFZ=NoALTTFZ+1
                     NBALTTFN=NBALTTFN-1
                     NBALTTFZ=NBALTTFZ+1
                  ENDIF
          ENDIF
       ELSE
            IF(IND2(I).EQ.-3) THEN
               NBALTTFN=NBALTTFN+1
               NBALTTFZ=NBALTTFZ-1
            ENDIF
            IF(IND2(I).EQ.3) THEN
               NBALTTFN=NBALTTFN-1
               NBALTTFZ=NBALTTFZ+1
            ENDIF
       ENDIF
       ENDDO
       VARIA=EGS-(STVINIT+(IN2-NBALTTFN+ICPI)*SN+(IZ2-NBALTTFZ-ICPI)*SP)
       IF(IBERT.EQ.ibw) WRITE(6,*) 'VARIA',VARIA,NBALTTFN,NBALTTFZ
       IF(IBERT.EQ.ibw) WRITE(6,*) 'VARIA',VARIA,NoALTTFN,NoALTTFZ
       IF(VARIA.GE.0.0) GO TO 850
