            IF(AMTEST.LT.(FMP+FMPI)) GOTO 832


            COR = SQRT(((E_TEST)**2 - AMTEST**2)/PTEST2)
            PTS1=PTS1*COR
            PTS2=PTS2*COR
            PTS3=PTS3*COR
           ELSE
            PTEST2=PTS1**2+PTS2**2+PTS3**2
