      QQQ=SQRT((rdmss**2-(FMP+FMPI)**2)*(rdmss**2-(FMP-FMPI)**2))
     & /(2.*rdmss)
      PSF=QQQ**3/(QQQ**3+5832000.)
      TDEL=-HC/(GG*PSF)*LOG(RNDM)*GEFF

C For global statistical Pauli, counts particles in fermi sea.
      IF(NPAULSTR.EQ.2) THEN
      CALL GLBP_COUNT(L2,0,+1)
      ENDIF

C Ce nucleon (ici delta obtenu par pi-N) devient un participant:
      JVIEUX=JPARTICIP(L2)
            JPARTICIP(L2)=1
            IF(JVIEUX.NE.1) nb_jpart=nb_jpart+1


      IF(IBERT.EQ.IBW) THEN
      WRITE(6,*) 'nb_jpart after pi-N->Delta:',NB_JPART
      ENDIF

C For composite projectiles, nucleons are free after an accepted interaction:
      IF(L2.LE.IA1) IBOUND_NUC(L2) = 0

      IF(IND2(L2).EQ.-3) V(L2)=V0M
      IF(IND2(L2).EQ.-1) V(L2)=V0N
      IF(IND2(L2).EQ.1)  V(L2)=V0P
      IF(IND2(L2).EQ.3)  V(L2)=V0PP
      if(IBERT.EQ.ibw) then
      write(*,*) 'Delta: L2,IND1(L2),IND2(L2),EPS(L2),V(L2),NESC(L2):'
     s ,L2,IND1(L2),IND2(L2),EPS(L2),V(L2),NESC(L2)
      endif

c Critere d'arret sur energie:
      IF(idnint(F(14)).EQ.1.) THEN
          IF(IND2(L2).EQ.-3) TF=TFM
          IF(IND2(L2).EQ.-1) TF=TFN
          IF(IND2(L2).EQ.1)  TF=TFP
          IF(IND2(L2).EQ.3)  TF=TFPP
      IF(IND1(L2).EQ.0) THEN
          IF(IND2(L2).EQ.1.AND.(EPS(L2)-FMP-V(L2)+SP).GE.EIN_MAXP)
     s            locsupe=locsupe+1
          IF(IND2(L2).EQ.-1.AND.(EPS(L2)-FMP-V(L2)+SN).GE.EIN_MAXN)
     s            locsupe=locsupe+1
      ELSE
         IF((EPS(L2)-FMP-FMPI-V(L2)+SP).GT.EIN_MAX) locsupe=locsupe+1
      ENDIF
      NB_SUPE = NB_SUPE + locsupe
      ENDIF
            IF (NOSURF.LE.0) THEN
c surface
      pppp=sqrt(p1(l2)**2+p2(l2)**2+p3(l2)**2)
      rrrr=sqrt(x1(l2)**2+x2(l2)**2+x3(l2)**2)
      IF(IND2(L2).EQ.3) TFC=TFPP
      IF(IND2(L2).EQ.1) TFC=TFP
      IF(IND2(L2).EQ.-1) TFC=TFN
      IF(IND2(L2).EQ.-3) TFC=TFM
      FMDEL = SQRT(EPS(L2)**2 -P1(L2)**2 - P2(L2)**2 - P3(L2)**2)
      PF = SQRT(TFC*(TFC + 2.*FMDEL))
      if (pppp.le.pf) then
      XV=pppp/pf
      rcorr=FLIN(XV)
      if (rrrr.gt.rcorr) then
      x1(l2)=x1(l2)*0.99*rcorr/rrrr
      x2(l2)=x2(l2)*0.99*rcorr/rrrr
      x3(l2)=x3(l2)*0.99*rcorr/rrrr
      endif
      endif
c fin surface
            END IF
C                                                                       P-N11050
COMM  COMMENT :DIFFERENCE WITH STANDARD CASCADE :                       P-N11060
COMM     THE DELTA IS LOCATED AT THE NUCLEON SITE TO AVOID PROBLEMS     P-N11070
COMM     WITH THE REFLEXION ON THE WALL                                 P-N11080
C                                                                       P-N11090
      IF(LP.EQ.NPION) GO TO 701                                         P-N11100
      LP1=LP+1                                                          P-N11110
      DO 702 I10=LP1,NPION                                              P-N11120
       if(idnint(f(17)).ne.1) THEN
        NESC(IA+I10-1)=NESC(IA+I10)  ! ***** ThA ici aussi
        TEVT(IA+I10-1)=TEVT(IA+I10)
       ENDIF
      IPI(I10-1)=IPI(I10)                                               P-N11130
      YM(I10-1)=YM(I10)                                                 P-N11140
      Q1(I10-1)=Q1(I10)                                                 P-N11150
      Q2(I10-1)=Q2(I10)                                                 P-N11160
      Q3(I10-1)=Q3(I10)                                                 P-N11170
      Q4(I10-1)=Q4(I10)                                                 P-N11180
      Y1(I10-1)=Y1(I10)                                                 P-N11190
      Y2(I10-1)=Y2(I10)                                                 P-N11200
  702 Y3(I10-1)=Y3(I10)                                                 P-N11210
  701 NPION=NPION-1                                                     P-N11220
      NCOL=NCOL+1                                                       P-N11230
      ncol_2c=ncol_2c+1
      MRPD=MRPD+1                                                       P-N11240
      IF (K.EQ.0) GO TO 704                                             P-N11250
      KD=0                                                              P-N11260
      CCR=TAU                                                           P-N11270
      DO 810 I=1,K                                                      P-N11280
      I20=I-KD                                                          P-N11290
      IF (IND(I).EQ.L1) GO TO 59                                        P-N11300
      IF (IND(I).EQ.L2) GO TO 59                                        P-N11310
      IF (JND(I).EQ.L2) GO TO 59                                        P-N11320
      IF (JND(I).EQ.L1) GO TO 59                                        P-N11330
      CROIS(I20)=CROIS(I)-CCR                                           P-N11340
      IND(I20)=IND(I)                                                   P-N11350
      JND(I20)=JND(I)                                                   P-N11360
      GO TO 810                                                         P-N11370
   59 KD=KD+1                                                           P-N11380
  810 CONTINUE                                                          P-N11390
      K=K-KD                                                            P-N11400
      DO 703 I10=1,K                                                    P-N11410
      IF(IND(I10).LE.L1) GO TO 703                                      P-N11420
      IND(I10)=IND(I10)-1                                               P-N11430
  703 CONTINUE                                                          P-N11440
  704 CALL NEW1(L2,LOCE)                                                P-N11450
      IF(TDEL.GT.TMAX5) GO TO 447                                       P-N11460
      K=K+1                                                             P-N11470
      CROIS(K)=TDEL                                                     P-N11480
      IND(K)=L2                                                         P-N11490
      JND(K)=0                                                          P-N11500
  447 K=K+1                                                             P-N11510
      IF(IND2(L2).EQ.3) TFC=TFPP
      IF(IND2(L2).EQ.1) TFC=TFP
      IF(IND2(L2).EQ.-1) TFC=TFN
      IF(IND2(L2).EQ.-3) TFC=TFM
      FMDEL = SQRT(EPS(L2)**2 -P1(L2)**2 - P2(L2)**2 - P3(L2)**2)
      PF = SQRT(TFC*(TFC + 2.*FMDEL))
      CROIS(K)=REF(X1(L2),X2(L2),X3(L2),P1(L2),P2(L2),P3(L2),EPS(L2),R22P-N11520
     -,PF)                                                              P-N11530
      IND(K)=L2                                                         P-N11540
      JND(K)=-1                                                         P-N11550
      GO TO 449                                                         P-N11560
C                                                                       P-N11570
CCC   REFLECTION ON OR TRANSMISSION THROUGH THE POTENTIAL WALL          P-N11580
C                                                                       P-N11590

  600 CONTINUE

c for test; forced reflexion of the delta:

      if (npproj(l1).eq.0) go to 608

      IF (IND2(L1).EQ.1) THEN
      VKM=V2P
      VK0=V0P
      TFK=TFP
      SK=SP
      IF(kindf7.LE.5)THEN
          QV=QVAL(IACOUR+1,IZCOUR+1,1,1)
      ELSE
          QV=FMNUC(IACOUR+1,IZCOUR+1)-FMNUC(IACOUR,IZCOUR)-FMP
      ENDIF
      npenter=npenter+1
            IACOUR=IACOUR+1
            IZCOUR=IZCOUR+1
C Modif AB 27/10/2010
      ITCH=ITCH+1
      ELSE
      VKM=V2N
      VK0=V0N
      TFK=TFN
      SK=SN
      IF(kindf7.LE.5)THEN
          QV=QVAL(IACOUR+1,IZCOUR,1,0)
      ELSE
          QV=FMNUC(IACOUR+1,IZCOUR)-FMNUC(IACOUR,IZCOUR)-FMP
      ENDIF
      nnenter=nnenter+1
            IACOUR=IACOUR+1
      ENDIF
C Correction for realistic Q value:
            EPS(L1)=EPS(L1)-(SK+QV)

      TL1o=eps(L1)-FMP
      TL1i=TL1o*(1.-ALPH)+VKM
C Compare to TF value and option 3 of V(T) and Correction for realistic Q value:
      IF(TL1i.LE.TFK) THEN
        nb_belowtf=nb_belowtf+1
C pour test:

c Set ncol_2c to zero before jumping to the compound-nucleus code!
c Otherwise STOT (used to compute DINTER in the CN part) will return an
c incorrect value, depending on S1NN and S2NN! DM 26/01/2012

      incol_2c=ncol_2c
      ncol_2c=0

C Go to compound nucleus:
        GO TO 1492

        IF(f(13).GT.2.5) THEN
           TL1i=TL1o+VK0
        ENDIF
      ENDIF

      IF(IBERT.EQ.ibw)
     s WRITE(6,*) 'L1 enter,EPS_out,T(L1)_in,TF,VKM:',
     s L1,EPS(L1),TL1i,TFK,VKM,IND2(L1)
C No way to propagate if the kinetic energy is negative!
      IF(TL1i.LE.0.) THEN
      t_fin=tim
      NOPART=-2
      RETURN
      ENDIF

C L1 inside the pot:
      V(L1)=POTENT(TL1i,FMP,VKM,IVFCTE,f(13))
      EPS(L1)=EPS(L1)+V(L1)
      GPSG=0.
      PL1o=SQRT(p1(L1)**2+p2(L1)**2+p3(L1)**2)
      IF (PL1o.GT.0.)
     s      GPSG=(SQRT(EPS(L1)**2-PM2)/PL1o)   ! ThA
      P1(L1)=GPSG*P1(L1)
      P2(L1)=GPSG*P2(L1)
      P3(L1)=GPSG*P3(L1)
      npproj(l1)=0
      nesc(l1)=0
      nb_spect = nb_spect - 1
C...and add this nucleon energy to STVINIT if below TF (AB 6/1/2011):
C Correction supprimee 15/06/2011 AB

      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'L1 enter,SP,SN,Q value,ind2:',L1,SP,SN,QV,ind2(L1)
      WRITE(6,*) '    T_inside,EPS_inside,V(L1):',TL1i,EPS(L1),V(L1)
      WRITE(6,*) '    P123:',P1(L1),P2(L1),P3(L1)
      WRITE(6,*) 'IACOUR,IZCOUR,ITCH:',IACOUR,IZCOUR,ITCH
      WRITE(6,*) 'TA,TIM:',TA,TIM
      WRITE(6,*) 'npenter,nnenter,nb_spect,nb_supe:',
     s npenter,nnenter,nb_spect,nb_supe
      RTEST=SQRT(X1(L1)**2+X2(L1)**2+X3(L1)**2)
      WRITE(6,*) '       nb_jpart,R:',nb_jpart,RTEST
      ENDIF

c for test 10/04/2008
c reevaluation of the times tab after entrance of 2nd,..nucleon
c of the projectile (goto 602 instead of 607 modif. 13/06/01)

      go to 602

c deutons
C Pour un non participant la transmission est impossible:
 608  CONTINUE
      IF(JPARTICIP(L1).EQ.0) GO TO 601
      IF (IND1(L1).EQ.0) GO TO 605                                      P-N11600
      FM=AM(P1(L1),P2(L1),P3(L1),EPS(L1))                               P-N11610
      POT=V(L1)       ! ThA                                             P-N11620

c Forbid delta emission if the particle is below Tf. Emission of a delta
c below Tf can lead to negative excitation energies, since CDPP assumes
c that all particles below Tf stay in the nucleus.
c DM 10/7/2012
      IF(IND2(L1).EQ.-3) TF=TFM
      IF(IND2(L1).EQ.-1) TF=TFN
      IF(IND2(L1).EQ.1)  TF=TFP
      IF(IND2(L1).EQ.3)  TF=TFPP
      if(eps(l1)-fm.lt.tf) then
        if(ibert.eq.ibw) then
          write(6,*) "Delta reflects below Tf", eps(l1), fm, tf
        endif
        goto 601
      endif

C Correction for realistic Q value:
      IZLOC=(1+IND2(L1))/2
      SLOC = -FMP +(1-IZLOC)*SN +IZLOC*SP
      QV=FMNUC(IACOUR,IZCOUR)-FMNUC(IACOUR-1,IZCOUR-IZLOC)


      QVV=SLOC+QV

c     The delta can be emitted only if its kinetic energy outside the
c     nucleus exceeds the correction to its total energy due to
c     realistic decay Q-values. The most constraining limit is assumed,
c     i.e. neutron + pi+.
      if(eps(l1)-pot+qvv-fm.lt.fmnuc(0,1)+fmnuc(1,0)-fmp-fmpi) goto 601

      GO TO 606                                                         P-N11630
  605 FM=FMP                                                            P-N11640
      POT=V(L1)       ! ThA                                             P-N11650
C Correction for realistic Q value:
      IZLOC=(1+IND2(L1))/2
      QV=QVAL(IACOUR,IZCOUR,1,IZLOC)


      IF(IZLOC.EQ.1) THEN
      QVV=QV+SP
      ELSE
      QVV=QV+SN
      ENDIF
  606 CONTINUE
      ELOC=EPS(L1)-FM+QVV
      TP=BARR(ELOC,IND2(L1),1,ITCH,r_zero_prot,POT,fm,idnint(f(17)))    ! ThA
      rndm=rn(0)


C Modif logique clusters (3/2006)
      IF (TP.LE.1.E-4) GO TO 601
C ANCIENNE LOGIQUE (test barriere AVANT recherche cluster)


       IF(IBERT.EQ.IBW) THEN
      WRITE(6,*) ''
      WRITE(6,*) 'L1 particule can exit',L1,ind2(l1),ind1(l1),eps(l1)
      WRITE(6,*) '   (before call clust) tim,npproj:',TIM,npproj(l1)
      WRITE(6,*) '   KCLST:',KCLST
      WRITE(6,*) 'QV,QVV,IACOUR,IZCOUR,ITCH:',QV,QVV,IACOUR,IZCOUR,ITCH
      WRITE(6,*) ''
      ENDIF

C Commande clusters ou non (1/0)!
      IF(Kclst.EQ.0) GO TO 1610
C-------------------------------------------------------------------
C Ici la particule L1 s'echappe du noyau:
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'L1 can escape: L1,EPS(L1),V(L1),IND2(L1):',
     s L1,EPS(L1),V(L1),IND2(L1)
      WRITE(6,*) '   P(L1):'
      WRITE(6,*) P1(L1),P2(L1),P3(L1)
      ENDIF

      IF (IND1(L1).EQ.1) GO TO 1610

      IF(IBERT.EQ.IBW) THEN
      WRITE(6,*) ''
      WRITE(6,*) 'L1 particule exits',L1,ind2(l1),ind1(l1),eps(l1)
      WRITE(6,*) '   CALL CLUSTER for it, tim:',TIM
      ENDIF

C Condition pour test 15/10/2007:
c     Reflexion forcee 1/2 pour les protons
      IF(idnint(f(17)).EQ.1.) THEN
      ELSE

C For time spent in CLUSTER_NEW
      CALL CLUSTER_new(L1,ITCH,IACOUR,IZCOUR,NCOL,tim,IOK,KINDCLST,
     s             ID_NUC_CLST,
     s             ROUT,EOUT,TOUT,POUT,LOUT,idnint(f(17)),KCLST,
     s             ASELECT,ZSELECT)

      ENDIF

      IF(IBERT.EQ.IBW) THEN
      WRITE(6,*) 'Cluster result: IOK,KINDCLST',IOK,KINDCLST
      WRITE(6,*) '  NCOL,NC(1),NC(2):',NCOL,NC(1),NC(2)
      ENDIF


C Test:

c Test for a transparent and no possible cluster:
C No print above (p 50MeV and 1 GeV on Pb): Change of the test:

C test for light targets: the remnant should be at least ONE nucleon!
      IF((IA-nbquit-ASELECT).LT.1) IOK=0

C (Test for a H.I. transparent will arrive after testing the transmission)
C The comment on the folllowing test open the possibility of a reflexion
C    for a nucleon without NN accepted interaction. 8/02/2012 DM AB
      IF((NCOL.EQ.0).AND.iok.ne.1.AND.IA1.EQ.1)
     s                        goto 9100

C No clusters with only projectile nucleons having no interaction:
C 8/02/212 AB DM SL JC
      IF(IFL_BOUND_PROJ.EQ.1.AND.IOK.EQ.1) THEN
         NB_PROJONUC_IN_CLST=0
         DO iloc=1,ASELECT
             NO_NUC = ID_NUC_CLST(iloc)
             IF(NO_NUC.LE.IA1) then
              if (IBOUND_NUC(NO_NUC).EQ.1)
     s         NB_PROJONUC_IN_CLST= NB_PROJONUC_IN_CLST + 1
             end if
         ENDDO
         IF(NB_PROJONUC_IN_CLST.EQ.ASELECT) IOK = 0
      ENDIF

      IF(IOK.EQ.0) nbiok0=nbiok0+1
      IF(IOK.EQ.1) nbiok1=nbiok1+1
      IF(IOK.EQ.2) nbiok2=nbiok2+1

C HERE we decide to force (OR NOT) a reflexion of the leading nucleon
C if a cluster is formed without escaping the coulomb barrier.


      IF (IOK.EQ.1) THEN      !cluster OK
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'L1 in a cluster: L1,EPS(L1),V(L1),KINDCLST:',
     s L1,EPS(L1),V(L1),KINDCLST
      WRITE(6,*) 'EOUT,TOUT,POUT():',EOUT,TOUT,POUT(1),POUT(2),POUT(3)
      ENDIF
C density of selected clusters:
               translat=1.5
               CALL CLUST_DENS_new(translat,
     s                       ID_NUC_CLST,ASELECT,ZSELECT,ROUT)
                   NB_CLST = NB_CLST + 1
             IF(NB_CLST.GT.20) THEN
             WRITE(6,*) 'More clusters than allowed by dimensions'
             STOP
             ENDIF

             K_CLST(NB_CLST)=KINDCLST
             E_CLST(NB_CLST)=EOUT
             T_CLST(NB_CLST)=TOUT


c Counting the probability of taking a participant in the cluster
c (there is always one participant in a cluster!).
C Histos 30-33 for comparison with NPART_CLST.
               na=0
               jpar=0
               do ii=1,IA
                  if(nesc(ii).EQ.0)then
                     na=na+1
                     if(jparticip(ii).EQ.1)jpar=jpar+1
                  endif
               enddo

               ratio_clst(NB_CLST)=real(jpar-1,8)/real(na-1,8)

         DO iloc=1,3
             POUT_CLST(iloc,NB_CLST)=POUT(iloc)
             LOUT_CLST(iloc,NB_CLST)=LOUT(iloc)
             ROUT_CLST(iloc,NB_CLST)=ROUT(iloc)
         END DO

         nb_nuc_clst = 0
           N_PARTICIP(NB_CLST)= 0
         DO iloc=1,ASELECT
             NO_NUC = ID_NUC_CLST(iloc)
             ID_CLST(iloc,NB_CLST) = NO_NUC
             IF (NO_NUC.NE.0) THEN
                        NESC(NO_NUC) = 2
                  TEVT(NO_NUC) = tim
                  nb_nuc_clst = nb_nuc_clst + 1
                  IF(jparticip(NO_NUC).EQ.1)
     s      N_PARTICIP(NB_CLST)= N_PARTICIP(NB_CLST) + 1

C Check participant content only up to Alpha
          IF (KINDCLST.LE.9) THEN
            rat=ratio_clst(NB_CLST)
          np_1=nb_nuc_clst-1
          na_clst=ia1t(KINDCLST)
          np_2=na_clst-nb_nuc_clst
          co_ef=C_O(na_clst,nb_nuc_clst)
            weight=co_ef*rat**np_1*(1-rat)**np_2

            ENDIF

C Critere d'arret sur energie (Ce sont des nucleons!):
                        IF(idnint(F(14)).EQ.1.) THEN
           IF(IND2(NO_NUC).EQ.-1) TF=TFN
           IF(IND2(NO_NUC).EQ.1)  TF=TFP
          IF(IND2(NO_NUC).EQ.1.AND.(EPS(NO_NUC)-FMP-V(NO_NUC)+SP)
     s       .GE.EIN_MAXP)     NB_SUPE = NB_SUPE - 1
          IF(IND2(NO_NUC).EQ.-1.AND.(EPS(NO_NUC)-FMP-V(NO_NUC)+SN)
     s       .GE.EIN_MAXN)     NB_SUPE = NB_SUPE - 1
                        ENDIF
           IF(JPARTICIP(NO_NUC).EQ.1)nb_jpart = nb_jpart - 1

         if(irtst.eq.1) then
          write(*,*) 'cluster part',ind1(no_nuc),ind2(no_nuc)
         endif
                  IF (NO_NUC.NE.L1) THEN
C On retire les nucleons autre que L1 des tableaux des avatars.
C    (Le decalage en temps (TAU) se fera en traitant L1)
                 IF (K.EQ.0) GO TO 1607
                      KD=0
               DO kloc=1,K
                 I20=kloc-KD
                 IF(JND(kloc).EQ.NO_NUC) GO TO 1604
                 IF(IND(kloc).EQ.NO_NUC.AND.
     &            (JND(kloc).NE.0.or.nesc(no_nuc).ne.0)) GO TO 1604
                 CROIS(I20)=CROIS(kloc)
                 IND(I20)=IND(kloc)
                 JND(I20)=JND(kloc)
                 GO TO 1603
 1604            KD=KD+1
 1603            CONTINUE
               END DO
               K=K-KD
 1607          CONTINUE
               ENDIF
             ENDIF
         END DO

       nbquit = nbquit + nb_nuc_clst
       IACOUR=IACOUR-ASELECT
       IZCOUR=IZCOUR-ZSELECT
      IF(KINDCLST.LE.9) THEN
       ITCH = ITCH - ((KINDCLST-6)/2 + 1)
         IF(KINDCLST.EQ.6) THEN
            SEJNVT=SEJNVT+SN
            SEJPVT=SEJPVT+SP
         ENDIF
         IF(KINDCLST.EQ.7) THEN
            SEJNVT=SEJNVT+2*SN
            SEJPVT=SEJPVT+SP
         ENDIF
         IF(KINDCLST.EQ.8) THEN
            SEJNVT=SEJNVT+SN
            SEJPVT=SEJPVT+2*SP
         ENDIF
         IF(KINDCLST.EQ.9) THEN
            SEJNVT=SEJNVT+2*SN
            SEJPVT=SEJPVT+2*SP
         ENDIF
      ELSE
      ITCH=ITCH-ZSELECT
          SEJNVT=SEJNVT+(ASELECT-ZSELECT)*SN
          SEJPVT=SEJPVT+ZSELECT*SP
      ENDIF

       GO TO  610

      ENDIF             !sortie de la particule (nucleon ou delta)

C Modif logique clusters (3/2006)
1610  CONTINUE
C No cluster out: nucleon or delta will escape?
      rndm=rn(0)
C ANCIENNE LOGIQUE (2ieme endroit)
C Modif AB 27/10/2010
      IF (RNDM.GE.TP) GO TO 601
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'L1 escapes (in): L1,EPS(L1),V(L1),IND2(L1):',
     s L1,EPS(L1),V(L1),IND2(L1)
      WRITE(6,*) '   P(L1):'
      WRITE(6,*) P1(L1),P2(L1),P3(L1)
      ENDIF

      NESC(L1)=1                                                        P-N11730
      nbquit=nbquit+1
       IACOUR=IACOUR-1
       IZCOUR=IZCOUR-(1+IND2(L1))/2
      TEVT(L1)=tim
      ITCH=ITCH-(1+IND2(L1))/2                                          P-N11740

C Critere d'arret sur energie:
      IF(idnint(F(14)).EQ.1.) THEN
          IF(IND2(L1).EQ.-3) TF=TFM
          IF(IND2(L1).EQ.-1) TF=TFN
          IF(IND2(L1).EQ.1)  TF=TFP
          IF(IND2(L1).EQ.3)  TF=TFPP
      IF(IND1(L1).EQ.0) THEN
          IF(IND2(L1).EQ.1.AND.(EPS(L1)-FMP-V(L1)+SP).GE.EIN_MAXP)
     s            NB_SUPE = NB_SUPE - 1
          IF(IND2(L1).EQ.-1.AND.(EPS(L1)-FMP-V(L1)+SN).GE.EIN_MAXN)
     s            NB_SUPE = NB_SUPE - 1
      ELSE
         IF((EPS(L1)-FMP-FMPI-V(L1)+SP).GT.EIN_MAX)
     s                                         NB_SUPE = NB_SUPE - 1
      ENDIF
      ENDIF
             IF(JPARTICIP(L1).EQ.1)nb_jpart = nb_jpart - 1

C Correction for realistic Q value:
      EPS(L1)=EPS(L1)-POT+QVV
      var_ab=p1(l1)**2+p2(l1)**2+p3(l1)**2
             GPSG=0.
      IF(var_ab.GT.0.)
     s       GPSG=SQRT((EPS(L1)**2-FM*FM)/var_ab)
      P1(L1)=GPSG*P1(L1)                                                P-N11760
      P2(L1)=GPSG*P2(L1)                                                P-N11770
      P3(L1)=GPSG*P3(L1)                                                P-N11780

      IF(IBERT.EQ.IBW) THEN
      WRITE(6,*) ''
      RTEST=SQRT(X1(L1)**2+X2(L1)**2+X3(L1)**2)
      WRITE(6,*) 'L1, escapes,tim,R:',L1,tim,RTEST
      WRITE(6,*) '  nb_supe (after possibly cluster search):',NB_SUPE
      WRITE(6,*) '  nb_jpart(after possibly cluster search):',NB_JPART
      ENDIF

C Test of transparent for H.I. beam:
      IF(NCOL.EQ.0.AND.nb_jpart.EQ.0.AND.nb_clst.EQ.0) THEN
                            GO TO 9100
      ENDIF

      IF(IND2(L1).LE.-1) SEJNVT=SEJNVT+SN
      IF(IND2(L1).GE.1) SEJPVT=SEJPVT+SP
610   CONTINUE
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'L1 outside: L1,EPS(L1),POT,IND2(L1):',
     s L1,EPS(L1),POT,IND2(L1)
      WRITE(6,*) '   P(L1):'
      WRITE(6,*) P1(L1),P2(L1),P3(L1)
      WRITE(6,*) '   IACOUR,IZCOUR,ITCH,QVV:',IACOUR,IZCOUR,ITCH,QVV
      ENDIF
C Comptage des particules hors du noyau (7/6/2002):
C (remnant minimum=1 nucleon)
      IF(nbquit.GE.(IA-1)) GO TO 255
C Following block not in INCL4.3, Not understood, Problems with H.I. beams
C ....commented AB 2/2010
      GO TO 602                                                         P-N11800

C Here no transmission possible
  601 PSPR=X1(L1)*P1(L1)+X2(L1)*P2(L1)+X3(L1)*P3(L1)                    P-N11810
C Surface: Modif A.B. pour tenir compte du rayon variable du noyau.
C        (X2COUR remplace R22 le rayon**2 fixe du noyau)

      X2COUR=X1(L1)**2+X2(L1)**2+X3(L1)**2
      P1(L1)=P1(L1)-2.*X1(L1)*PSPR/X2COUR
      P2(L1)=P2(L1)-2.*X2(L1)*PSPR/X2COUR
      P3(L1)=P3(L1)-2.*X3(L1)*PSPR/X2COUR
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'reflection of L,EPS,P:',
     s   L1,EPS(L1),P1(L1),P2(L1),P3(L1)
      ENDIF
C For composite projectiles, nucleons are free after a reflexion:
      IF(L1.LE.IA1) IBOUND_NUC(L1) = 0

C Fin modif surface A.B.
  602 IF (K.EQ.0) GO TO 607                                             P-N11850
      KD=0                                                              P-N11860
      CCR=TAU                                                           P-N11870
      DO 603 I=1,K                                                      P-N11880
      I20=I-KD                                                          P-N11890
      IF(JND(I).EQ.L1) GO TO 604                                        P-N11900
C...up to 19/04/2011 an emitted DELTA was decayed during the cascade!
      IF(IND(I).EQ.L1.AND.(JND(I).NE.0.or.nesc(l1).eq.1)) GO TO 604     P-N11910
      CROIS(I20)=CROIS(I)-CCR                                           P-N11920
      IND(I20)=IND(I)                                                   P-N11930
      JND(I20)=JND(I)                                                   P-N11940
      GO TO 603                                                         P-N11950
  604 KD=KD+1                                                           P-N11960
  603 CONTINUE                                                          P-N11970
      K=K-KD                                                            P-N11980
C modif 10/02 pour logique des clusters (nesc()=2!)
  607 IF (NESC(L1).NE.0) GO TO 613
      CALL NEW1(L1,LOCE)
      IF(IND2(L1).EQ.3) TFC=TFPP
      IF(IND2(L1).EQ.1) TFC=TFP
      IF(IND2(L1).EQ.-1) TFC=TFN
      IF(IND2(L1).EQ.-3) TFC=TFM
      FMDEL = SQRT(EPS(L1)**2 -P1(L1)**2 - P2(L1)**2 - P3(L1)**2)
      PF = SQRT(TFC*(TFC + 2.*FMDEL))
C For bound composite projectiles:
      IF(IFL_BOUND_PROJ.EQ.0) THEN
        P1SP=P1(L1)
        P2SP=P2(L1)
        P3SP=P3(L1)
        EPSP=EPS(L1)
      ELSE
        IF(L1.LE.IA1) then
         if (IBOUND_NUC(L1).EQ.1) THEN
          P1SP=PINC1
          P2SP=PINC2
          P3SP=PINC3
          EPSP=ENERGIE_IN
         else
          P1SP=P1(L1)
          P2SP=P2(L1)
          P3SP=P3(L1)
          EPSP=EPS(L1)
         endif
        ELSE
          P1SP=P1(L1)
          P2SP=P2(L1)
          P3SP=P3(L1)
          EPSP=EPS(L1)
        ENDIF
      ENDIF
      TREF=REF(X1(L1),X2(L1),X3(L1),P1SP,P2SP,P3SP,EPSP,R22,PF)
      IF (TREF.GT.TMAX5) GO TO 615                                      P-N12020
      K=K+1                                                             P-N12030
      CROIS(K)=TREF                                                     P-N12040
      IND(K)=L1                                                         P-N12050
      JND(K)=-1                                                         P-N12060
  615 IF (NPION.EQ.0) GO TO 613                                         P-N12070
      IF (IND1(L1).EQ.1) GO TO 613                                      P-N12080
      DO 614 K20=1,NPION                                                P-N12090
  614 CALL NEW3(K20,L1,IND2(L1),idnint(f(17))) ! ***** ThA
  613 IF (K.EQ.0) GO TO 230                                             P-N12120
      GO TO 449                                                         P-N12130
c     CASE OF PION
  620 CONTINUE
      if(idnint(f(17)).ne.1)then
      LP=L1-IA
      IF(IPI(LP).EQ.-2) V0PI=V0PIM
      IF(IPI(LP).EQ.0) V0PI=V0PIN
      IF(IPI(LP).EQ.2) V0PI=V0PIP
C Correction for realistic Q value:
      IZLOC= IPI(LP)/2
      QV=FMNUC(IACOUR,IZCOUR)-FMNUC(IACOUR,IZCOUR-IZLOC)-FMNUC(0,IZLOC)


      QVV=FMPI+QV
      ELOC=Q4(LP)-FMPI+QVV

      TP=BARR(ELOC,IPI(LP)/2,-1,ITCH,R2,V0PI,fmpi,idnint(f(17)))
      rndm=rn(0)
      IF (RNDM.GE.TP) GO TO 621
C Pi goes OUT
      NESC(L1)=1
      IZCOUR=IZCOUR-IPI(LP)/2
      ITCH=ITCH-IPI(LP)/2
      if(IBERT.EQ.ibw) then
       write(6,*) 'pion out',ipi(lp),q4(lp),v0pi,FMPI,L1
       WRITE(6,*) '  QV,QVV,IACOUR,IZCOUR,ITCH:',
     s               QV,QVV,IACOUR,IZCOUR,ITCH
      endif

C For test; flag for escaping pion
      TEVT(L1)=tim

      Q4(LP)=Q4(LP)-V0PI+QVV
      var_ab=q1(lp)**2+q2(lp)**2+q3(lp)**2
             GPSG=0.
      IF(var_ab.GT.0.)
     s       GPSG=SQRT((Q4(LP)**2-FMPI*FMPI)/var_ab)
      Q1(LP)=GPSG*Q1(LP)
      Q2(LP)=GPSG*Q2(LP)
      Q3(LP)=GPSG*Q3(LP)
      GO TO 622
C Pi stays IN
  621 NESC(L1)=0
      PSPR=Y1(LP)*Q1(LP)+Y2(LP)*Q2(LP)+Y3(LP)*Q3(LP)
      Y2COUR=Y1(LP)**2+Y2(LP)**2+Y3(LP)**2
      Q1(LP)=Q1(LP)-2.*Y1(LP)*PSPR/Y2COUR
      Q2(LP)=Q2(LP)-2.*Y2(LP)*PSPR/Y2COUR
      Q3(LP)=Q3(LP)-2.*Y3(LP)*PSPR/Y2COUR
C For pion in or out
  622 IF (K.EQ.0) GO TO 627
      KD=0
      CCR=TAU
      DO 625 I=1,K
      I20=I-KD
      IF(JND(I).EQ.L1) GO TO 624
      IF(IND(I).EQ.L1) GO TO 624
      CROIS(I20)=CROIS(I)-CCR
      IND(I20)=IND(I)
      JND(I20)=JND(I)
      GO TO 625
  624 KD=KD+1
  625 CONTINUE
      K=K-KD
c ici il s'agit du pion L1
  627 IF (NESC(L1).EQ.1) GO TO 634
      CALL NEW2(LP,0,idnint(f(17)))             ! ***** ThA
      TREF=REFPI(LP,RPION2)
      IF (TREF.GT.TMAX5) GO TO 634
      K=K+1
      CROIS(K)=TREF
      IND(K)=L1
      JND(K)=-2
  634 IF (K.EQ.0) GO TO 230
       GO TO 449
      endif

C                                                                       P-N12140
CCC   DECAY OF THE SURVIVING DELTAS                                     P-N12150
C                                                                       P-N12160
  230 CONTINUE                                                          P-N12170
  255 CONTINUE                                                          P-N12200

C Checking sequence:
      IZIN=0
      IZOUT=0
      IAIN=0
      IAOUT=0
      DO i=1,IA
      IF(NESC(i).EQ.0) THEN
      IZIN=IZIN+(1+IND2(i))/2
      IAIN=IAIN+1
      ELSE
      IZOUT=IZOUT+(1+IND2(i))/2
      IAOUT=IAOUT+1
      ENDIF
      ENDDO
      IF(NPION.EQ.0) GO TO 732
      ICPIIN=0
      ICPIOUT=0
      DO I=1,NPION
      IF(NESC(IA+i).EQ.0) THEN
      IZIN=IZIN+IPI(i)/2
      ICPIIN=ICPIIN+1
      ELSE
      IZOUT=IZOUT+IPI(i)/2
      ICPIOUT=ICPIOUT+1
      ENDIF
      ENDDO
732   CONTINUE

      IF (K3.EQ.1) GO TO 256                                            P-N12210
      IF (K4.EQ.0) GO TO 256                                            P-N12220
      IFL_forcedecay=0
      DO 257 I=1,IA                                                     P-N12240
      IF (IND1(I).EQ.0) GO TO 257                                       P-N12250
      IFL_forcedecay=1
      if(IBERT.eq.ibw) write(6,*) 'DECAY OF THE SURVIVING DELTAS'

C Moved statements
      NPION=NPION+1                                                     P-N12260
         ICHD=IND2(I)

C Choice of the decay channel:
      IF (IND2(I)*IND2(I).EQ.9) GO TO 280                               P-N12300

      rndm=rn(0)
      IF (RNDM*3..LT.1.) GO TO 283                                      P-N12350
      IPI(NPION)=0                                                      P-N12360
      GO TO 285                                                         P-N12370
  283 IPI(NPION)=IND2( I)*2                                             P-N12380
      IND2( I)=-IND2(I)                                                 P-N12390
      GO TO 285                                                         P-N12400
  280 IND2(I)=IND2(I)/3                                                 P-N12410
      IPI(NPION)=2*IND2(I)                                              P-N12420
  285 IND1(I)=0

      IF(IBERT.EQ.ibw) WRITE(6,*) 'decay channel:',IND2(I),IPI(NPION)

C Correction for right masses:
      IF(NESC(I).EQ.1) THEN
        POLD2=P1(I)**2+P2(I)**2+P3(I)**2
        FMOLD2=EPS(I)**2-POLD2
        IZLOC = IPI(NPION)/2
         JZ=(1+IND2(I))/2
       EPS(I)= EPS(I)+FMPI-FMNUC(0,IZLOC)+FMP-FMNUC(1,JZ)
        IF(IBERT.EQ.ibw)
     s WRITE(6,*) 'Mass correction izloc,MPI,MNuc:',
     s         IZLOC,FMNUC(0,IZLOC),FMNUC(1,JZ)
        FACT=SQRT((EPS(I)**2-FMOLD2)/POLD2)
        P1(I)=P1(I)*FACT
        P2(I)=P2(I)*FACT
        P3(I)=P3(I)*FACT
      ENDIF

      var_ab=EPS(I)**2-P1(I)**2-P2(I)**2-P3(I)**2
            YM(NPION)=0.
      IF(var_ab.GT.0.)
     s      YM(NPION)=SQRT(var_ab)                                      P-N12270

      IF(IBERT.EQ.ibw) WRITE(6,*) 'Inv_mass:',YM(NPION)

c ***** ThA b    (Switch as 4.2 if f(17)=1)
      if(idnint(f(17)).ne.1)then

C TEST POSSIBLE! Delta forces en energie d'excitation!
         IF(YM(NPION).LT.(FMP+FMPI)) THEN
            NPION=NPION-1
            GOTO 262
         ENDIF

         ASSD=YM(NPION)
         xy1=p1(i)
         xy2=p2(i)
         xy3=p3(i)
         xye=eps(i)
         TV=V(I)
         IF(ICHD.EQ.3) VKFO1=V0PP
         IF(ICHD.EQ.1) VKFO1=V0P
         IF(ICHD.EQ.-1) VKFO1=V0N
         IF(ICHD.EQ.-3) VKFO1=V0M
         Eavant=EPS(I)-V(I)

      IF(LOCED.NE.0.AND.NESC(I).EQ.0) THEN
C Where are the surviving Deltas?
      R_1 =X1(I)**2 +X2(I)**2 +X3(I)**2
      R_1 = SQRT(R_1)
      PI2 = P1(I)**2 + P2(I)**2 + P3(I)**2
      FMI2=EPS(I)**2 - PI2
      fmi=sqrt(fmi2)
      vloc1 = VLOC(i,r_1,fmi,eps(i)-fmi,v(i),ind1(i),ind2(i))
      E_1=EPS(I)-VLOC1
      AA=E_1**2 - FMI2
      IF (AA.LT.0) THEN
            COR1 = 0
      E_1=SQRT(FMI2)
      ELSE
      COR1=SQRT(AA/PI2)
      ENDIF
      P1L1=P1(I)*COR1
      P2L1=P2(I)*COR1
      P3L1=P3(I)*COR1
      ENDIF

      IF(LOCED.EQ.1.AND.NESC(I).EQ.0) THEN
       EPS(I) = E_1
       P1(I) = P1L1
       P2(I) = P2L1
       P3(I) = P3L1
C Pour test conservation de E avec E-Vloc(r)
      ENDIF
       Eavant = EPS(I)-V(I)

      IF(IBERT.EQ.ibw)
     s WRITE(6,*) 'Before decay,E,P:',EPS(I),P1(I),P2(I),P3(I)

      CALL DECAY2(P1(I),P2(I),P3(I),EPS(I),NPION,
     s  FMP,FMPI,hel(i),B1d,B2d,B3d)

      IF(IBERT.EQ.ibw) THEN
       WRITE(6,*) 'After decay, E,P:',EPS(I),P1(I),P2(I),P3(I)
       WRITE(6,*) '  PION       E,P:',
     s         Q4(NPION),Q1(NPION),Q2(NPION),Q3(NPION)
      ENDIF

C ATTENTION ICI version AB traitait decroissance forcee du Delta different de TA
      if(nesc(i).eq.0) idecf=1
      Y1(NPION)=X1(I)                                                   P-N12430
      Y2(NPION)=X2(I)                                                   P-N12440
      Y3(NPION)=X3(I)                                                   P-N12450
      POSDELTA=SQRT(X1(I)**2+X2(I)**2+X3(I)**2)
      if(IBERT.EQ.ibw) then
       write(6,*) ' bilan DEL LAST',ibert,ABS(Eavant-Eapres)
       write(6,*) 'P1 :','1',ICHD,xye,TV,ASSD
       write(6,*) 'P3 :',IND1(I),IND2(I),EPS(I),V(I)
       write(6,*) 'P4 :',IPI(NPION),' -- ',Q4(NPION),'0'
      endif

      IF(NESC(I).EQ.1) THEN
         NESC(NPION+IA)=1    ! ***** ThA le pion est egalement out
         TEVT(NPION+IA)=tim
         nb_delta_decay_out = nb_delta_decay_out + 1
C Correction for realistic Q value (Right nucleon mass for EOUT):
         JZ=(1+IND2(I))/2
       IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'Nucleon mass correction for Delta decay outside:',I
      WRITE(6,*) '   EOUTDM,JZ:',EOUTDM,JZ
       ENDIF
      ENDIF

      IF(NESC(I).EQ.0) THEN
        NESC(NPION+IA)=0    ! le pion est egalement in
C TEST Un delta IN au-dela de RPION ne peut pas sortir un pi
C 28/01/2009 AB, SL; (Under nesc=0 3/03/2011 AB)
      ENDIF

C If no pion potential, all pions OUT  3/03/2011 AB
      if(f(16).lt.0.5) nesc(npion+ia)=1

      if (nesc(i).eq.0) then
      bnul=0.0
      IF(IND2(I).EQ.1)  VKF1=V2P
      IF(IND2(I).EQ.-1) VKF1=V2N
      IF(IPI(NPION).EQ.-2) V0PI=V0PIM
      IF(IPI(NPION).EQ.0)  V0PI=V0PIN
      IF(IPI(NPION).EQ.2)  V0PI=V0PIP

      QQ1=Q1(NPION)
      QQ2=Q2(NPION)
      QQ3=Q3(NPION)
      QQ4=Q4(NPION)
      IF(LOCED.EQ.1) THEN
      fmdvd=sqrt(eps(i)**2-p1(i)**2-p2(i)**2-p3(i)**2)
      vlocp1 = VLOC(i,r_1,fmdvd,eps(i)-fmdvd,v(i),ind1(i),ind2(i))
      Q=VLOCP1-VLOC1
      IFLAB=0
      IF(ABS(Q).GT.0.0001) THEN
      IFLAB=1
      ENDIF
        CALL AECSVT(eavant+vloc1,
     &  B1d,B2d,B3d,P1(I),P2(I),P3(I),EPS(I),VKF1,QQ1,QQ2,QQ3,QQ4,
     &  V0PI,V(I),bnul,IEJCT,DELTAE,
     &  IVFCTE,f(13),
     s  VLOCP1,real(0.,8),l1,r_1,0,real(0.,8),loced,ind1(i),0,ind2(i),0)
      ELSE
      Q=0.
        CALL AECSVT(eavant,
     &  B1d,B2d,B3d,P1(I),P2(I),P3(I),EPS(I),VKF1,QQ1,QQ2,QQ3,QQ4,
     &  V0PI,V(I),bnul,IEJCT,DELTAE,
     &  IVFCTE,f(13),
     s  real(0.,8),real(0.,8),
     s  l1,r_1,0,real(0.,8),loced,ind1(i),0,ind2(i),0)
      ENDIF
      Q1(NPION)=QQ1
      Q2(NPION)=QQ2
      Q3(NPION)=QQ3
      Q4(NPION)=QQ4

      Eapres=EPS(I)-V(I)+Q4(NPION)-V0PI
      if(loced.eq.1) then
       fmdvd=sqrt(eps(l1)**2-p1(l1)**2-p2(l1)**2-p3(l1)**2)
       vlocp1 = VLOC(l1,r_1,fmdvd,eps(l1)-fmdvd,v(l1),ind1(l1),ind2(l1))
         Q = VLOCP1-VLOC1
      endif
      if(IBERT.EQ.ibw) then
       write(6,*) ' bilan DEL LAST',ibert,ABS(Eavant-Eapres)
       write(6,*) 'P1 :','1',ICHD,xye,TV,ASSD
       write(6,*) 'P3 :',IND1(I),IND2(I),EPS(I),V(I)
       write(6,*) 'P4 :',IPI(NPION),' -- ',Q4(NPION),V0PI
      endif

      IF(LOCED.EQ.1) THEN
C test of local energy, restitution of pot energy:
       IF(IFLAB.EQ.1) THEN
       ENDIF
       FML1=FMP
       EPS(I)=EPS(I)+ VLOCP1
       COR=P1(I)**2 + P2(I)**2 + P3(I)**2
       COR = SQRT((EPS(I)**2 - FML1**2)/COR)
       P1(I) = P1(I)*COR
       P2(I) = P2(I)*COR
       P3(I) = P3(I)*COR
       SUM_Q=SUM_Q + Q
      ENDIF


c       IF NO SOLUTION: DELTA DECAYS ACCEPTED AND THE REST BECOMES
c       EXCITATION ENERGY
c
        IF(IEJCT.EQ.1.OR.ABS(Eavant-Eapres-Q).gt.0.0005) THEN
          MPAUL2=MPAUL2+1
          if(IBERT.EQ.ibw) write(6,*) 'DECAY BLOQUE PAR NON E CSVT'
          P1(I)=XY1
          P2(I)=XY2
          P3(I)=XY3
          EPS(I)=XYE
          V(I)=TV
          IND1(I)=1
          IND2(I)=ICHD
          NPION=NPION-1
        GOTO 262
        ENDIF
c **************************
       EGS=0.
       NBALTTFN=0
       NBALTTFZ=0
       NoALTTFN=0
       NoALTTFZ=0
       ICPI=0
       IF(NPION.GT.0) THEN
        DO KIJ=1,NPION
          ICPI=ICPI+IPI(KIJ)/2
        ENDDO
       ENDIF
       DO J=1,IA
         IF(NESC(J).EQ.0) THEN
            IF(IND2(J).EQ.-3) TF=TFM
          IF(IND2(J).EQ.-1) TF=TFN
          IF(IND2(J).EQ.1)  TF=TFP
          IF(IND2(J).EQ.3)  TF=TFPP
          PTEST2=P1(J)**2+P2(J)**2+P3(J)**2
          AMTEST=SQRT(EPS(J)**2-PTEST2)
          TTEST=EPS(J)-AMTEST
          IF(TTEST.LE.TF) THEN
               IF(IND2(J).LT.0) NBALTTFN=NBALTTFN+1
             IF(IND2(J).GT.0) NBALTTFZ=NBALTTFZ+1
             IF(IND2(J).EQ.-3) THEN
              NBALTTFN=NBALTTFN+1
              NBALTTFZ=NBALTTFZ-1
             ENDIF
               IF(IND2(J).EQ.3) THEN
                  NBALTTFN=NBALTTFN-1
                  NBALTTFZ=NBALTTFZ+1
               ENDIF
             EGS=EGS+EPS(J)-FMP-V(J)
          ELSE
               IF(IND2(J).LT.0) NoALTTFN=NoALTTFN+1
             IF(IND2(J).GT.0) NoALTTFZ=NoALTTFZ+1
             IF(IND2(J).EQ.-3) THEN
              NoALTTFN=NoALTTFN+1
              NoALTTFZ=NoALTTFZ-1
              NBALTTFN=NBALTTFN+1
              NBALTTFZ=NBALTTFZ-1
             ENDIF
               IF(IND2(J).EQ.3) THEN
                  NoALTTFN=NoALTTFN-1
                  NoALTTFZ=NoALTTFZ+1
                  NBALTTFN=NBALTTFN-1
                  NBALTTFZ=NBALTTFZ+1
               ENDIF
          ENDIF
       ELSE
            IF(IND2(J).EQ.-3) THEN
               NBALTTFN=NBALTTFN+1
               NBALTTFZ=NBALTTFZ-1
            ENDIF
            IF(IND2(J).EQ.3) THEN
               NBALTTFN=NBALTTFN-1
               NBALTTFZ=NBALTTFZ+1
            ENDIF
       ENDIF
       ENDDO
       VARIA=EGS-(STVINIT+(IN2-NBALTTFN+ICPI)*SN+(IZ2-NBALTTFZ-ICPI)*SP)
       IF(VARIA.LT.0) THEN
          MPAUL2=MPAUL2+1
          if(irtst.eq.1) write(*,*) 'PAULI BLOC CE DECAY'
          P1(I)=XY1
          P2(I)=XY2
          P3(I)=XY3
          EPS(I)=XYE
          V(I)=TV
          IND1(I)=1
          IND2(I)=ICHD
          NPION=NPION-1
        GOTO 262
       ENDIF
      endif
            IF (NOSURF.LE.0) THEN
c surface
      if (nesc(i).eq.0.) then
       pppp=sqrt(p1(i)**2+p2(i)**2+p3(i)**2)
       rrrr=sqrt(x1(i)**2+x2(i)**2+x3(i)**2)
      IF(IND2(I).EQ.3) PF=PFPP
      IF(IND2(I).EQ.1) PF=PFP
      IF(IND2(I).EQ.-1) PF=PFN
      IF(IND2(I).EQ.-3) PF=PFM
       if (pppp.le.pf) then
       XV=pppp/pf
       rcorr=FLIN(XV)
         if (rrrr.gt.rcorr) then
          x1(i)=x1(i)*0.99*rcorr/rrrr
          x2(i)=x2(i)*0.99*rcorr/rrrr
          x3(i)=x3(i)*0.99*rcorr/rrrr
         endif
       endif
      endif
c fin surface
            END IF
C compteur des decay forces et reussis des deltas
      nb_force_delta_decay = nb_force_delta_decay + 1
  262 CONTINUE

c-------option incl4.2 for delta decay
      else  ! if(f(17).ne.1)
         xy1=p1(i)
         xy2=p2(i)
         xy3=p3(i)
         xye=eps(i)

      CALL DECAY2(P1(I),P2(I),P3(I),EPS(I),NPION,
     s   FMP,FMPI,hel(i),B1d,B2d,B3d)
      if(nesc(i).eq.0) idecf=1
            IF (NOSURF.LE.0) THEN
c surface
      if (nesc(i).eq.0.) then
      pppp=sqrt(p1(i)**2+p2(i)**2+p3(i)**2)
      rrrr=sqrt(x1(i)**2+x2(i)**2+x3(i)**2)
      if (pppp.le.pf) then
      XV=pppp/pf
      rcorr=FLIN(XV)
      if (rrrr.gt.rcorr) then
      x1(i)=x1(i)*0.99*rcorr/rrrr
      x2(i)=x2(i)*0.99*rcorr/rrrr
      x3(i)=x3(i)*0.99*rcorr/rrrr
      endif
      endif
      endif
c fin surface
            END IF
      IF (IND2( I)*IND2( I).EQ.9) GO TO 380                             P-N12300
      rndm=rn(0)

      IF (RNDM*3..LT.1.) GO TO 383                                      P-N12350
      IPI(NPION)=0                                                      P-N12360
      GO TO 385                                                         P-N12370
  383 IPI(NPION)=IND2( I)*2                                             P-N12380
      IND2( I)=-IND2(I)                                                 P-N12390
      GO TO 385                                                         P-N12400
  380 IND2( I)=IND2( I)/3                                               P-N12410
      IPI(NPION)=2*IND2( I)                                             P-N12420
  385 Y1(NPION)=X1(I)                                                   P-N12430
      Y2(NPION)=X2(I)                                                   P-N12440
      Y3(NPION)=X3(I)                                                   P-N12450

      endif       ! if(f(17).ne.1)

  257 CONTINUE
C pour test:
      nb_pions=nb_pions+NPION
                                                                        P-N12460
C                                                                       P-N12470
CCC   FINAL PROPERTIES OF THE INCOMING NUCLEON AND OF THE REMNANT       P-N12480
C     BEFORE EVAPORATION                                                P-N12490
C                                                                       P-N12500

  256 ELEAD=0.                                                          P-N12510
      LEAD=0                                                            P-N12520
      NPX=0                                                             P-N12530
      EREM=0.                                                           P-N12540
      IZREM=0                                                           P-N12550
      INREM=0                                                           P-N12560
      iarem=0
      STVREM=0.0
      RCM1=0.                                                           P-N12570
      RCM2=0.                                                           P-N12580
      RCM3=0.                                                           P-N12590
      PREM1=0.                                                          P-N12600
      PREM2=0.                                                          P-N12610
      PREM3=0.                                                          P-N12620
      POUT1=0.                                                          HE-13640
      POUT2=0.                                                          HE-13650
      POUT3=0.                                                          HE-13660
C Correction for realistic Q value (Right nucleon mass for EOUT):
      EOUT =EOUTDM

      XL1=0.
      XL2=0.
      XL3=0.
      cmultn=0.
      if (kindf7.le.2) then
          if ( (ncol.eq.0.or.nc(1).eq.0) .and. nb_clst.eq.0 ) then
           go to 9100
          endif
      else
        if (kindf7.le.5) then
           if (ncol.eq.0.AND.nb_clst.eq.0) then
            go to 9100
           endif
        else
C Ici faisceau composite: modif A.B. 2/2002 pour tous les composites:
	nsum_col=0
	DO i=1,ia1
		nsum_col = nsum_col + NC(i)
	ENDDO
C....also count the number of participants in the pot.
C   (composite nuclei for low enrgy HI in) AB 6/1/2011
       nb_part_bl_v0=0
       DO i=1,ia1
         IF(JPARTICIP(i).EQ.1.AND.nesc(i).EQ.0)THEN
             IF((EPS(i)-FMP).LT.V(i))nb_part_bl_v0=nb_part_bl_v0+1
         ENDIF
       ENDDO	
C Added nb_clst=0 (A.B. 16/06/2010) NO cluster on transparent nuc.
C Add no participant in V0 for a transp. (for low energy HI_in)AB 6/1/2011
      IF (((ncol.eq.0.or.nsum_col.eq.0)
     s   .AND.nb_clst.eq.0
     s   .AND.nb_part_bl_v0.EQ.0)) THEN

            go to 9100
          endif
        endif
      endif
      go to 9101
c pour eviter renvoi des resultats du run precedent CV 20/11/98
 9100  iarem=ia2
       izrem=iz2
       esrem=0.
       erecrem=0.
       nopart=-1
c fin ajout CV
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'Transparent, IBERT,ncol,nsum_col,nb_jpart:',
     s   IBERT,ncol,nsum_col,nb_jpart
      WRITE(6,*) '       nb_clst,nb_part_bl_v0,NB_VU_MATTER:',
     s   nb_clst,nb_part_bl_v0,NB_VU_MATTER
      ENDIF
      t_fin=tim
        return

 9101 CONTINUE

      nopart=0
      ekout=0.
C Angular deviation of charged exiting particles in the remnant coulomb field
      IF(LCOUL_OUT.EQ.1) CALL DIST_COUL_OUT(IA,IBERT,NPION,NB_CLST,F)

C************************
C Here force the emission of pions IN if the remnant is not physical
C (This can induce infinit loops or problems in the deexcitation)
C No coulomb deviation, so after call dist_coul_out.

          EPIEMIT = 0. !total energy carried by pi forced OUT

C Test: There is a potential for pions and there is pions:
      IF(idnint(f(17)).NE.1.AND.f(16).GE.0.5.AND.NPION.NE.0) THEN

C Count the remnant:
        IAREM=0
        IZREM=0
        DO i=1,IA
          IF(NESC(i).EQ.0) THEN
            IAREM=IAREM+1
            IZREM=IZREM+(1+IND2(i))/2
          ENDIF
        ENDDO
        DO ipion=1,NPION
          IF(NESC(IA+ipion).EQ.0)
     s             IZREM=IZREM+IPI(ipion)/2
        ENDDO

C Test of possible problem:
        IF(IZREM.LT.0.OR.IZREM.GT.IAREM) THEN
C.... emits the pions IN with 0.1 MeV (and NO coulomb deviation for them):
              EPIEXT = 0.1
          DO ipion=1,NPION
            L1=IA+ipion
            IF(NESC(L1).EQ.0) THEN
              NESC(L1)=1
              TEVT(L1)=TIM
              ITCH=ITCH-IPI(ipion)/2
          fact=SQRT((EPIEXT*(EPIEXT+2.*FMPI))/(Q4(ipion)**2-FMPI**2))
              Q4(ipion)=EPIEXT+FMPI
              Q1(ipion)=Q1(ipion)*fact
              Q2(ipion)=Q2(ipion)*fact
              Q3(ipion)=Q3(ipion)*fact
              EPIEMIT=EPIEMIT+Q4(ipion)
            ENDIF
          ENDDO
        ENDIF

C Init again of the counters:
        IAREM=0
        IZREM=0
      ENDIF
C************************
C Counter of mass from tables and for emitted baryons:
      BARMTABLE= 0.
      Qvalue=0.

      IF (Kclst.NE.0) THEN
C On traite les clusters si il y en a:
      IF (NB_CLST.NE.0) THEN

C flag Without_decay (=1) for tests (a.b. 27/10/08):
        iflag_withoutdecay=0

      NBG_CLST=0
          DO iloc=1,NB_CLST
          izclst=k2z(k_clst(iloc))
          iaclst=k2a(k_clst(iloc))

        IF(iflag_withoutdecay.EQ.1) THEN
        idec=1
        ndectot=1
        pdec(1,idec)= POUT_CLST(1,iloc)
        pdec(2,idec)= POUT_CLST(2,iloc)
        pdec(3,idec)= POUT_CLST(3,iloc)
        tdec(idec)= T_CLST(iloc)
        edec(idec)= E_CLST(iloc)
        kdec(idec)= K_CLST(iloc)

        NBG_CLST=NBG_CLST+1               !Copy info in /BL13/
        EG_CLST(NBG_CLST)=edec(idec)
        DO kloc=1,3
        PG_CLST(kloc,NBG_CLST)=pdec(kloc,idec)
        RGOUT_CLST(kloc,NBG_CLST)=ROUT_CLST(kloc,iloc)
        ENDDO
        ELSE
c Check if the clusters we produced are nuclear-stable
c If not, make them decay
             zclst=k2z(k_clst(iloc))
             aclst=k2a(k_clst(iloc))
             ndectot=0
             call unstclst(aclst,zclst,
     &            pout_clst(1,iloc),pout_clst(2,iloc),pout_clst(3,iloc),
     &            t_clst(iloc),e_clst(iloc),ndectot,unstclst)
c     Check energy and momentum conservation for cluster decay
             tclbil=0.0
             eclbil=0.0
             pclbil(1)=0.0
             pclbil(2)=0.0
             pclbil(3)=0.0
      Qvalue=-bind_clst_new(aclst,zclst)
             do idec=1,ndectot
                tclbil    = tclbil    + tdec(idec)
                eclbil    = eclbil    + edec(idec)
                pclbil(1) = pclbil(1) + pdec(1,idec)
                pclbil(2) = pclbil(2) + pdec(2,idec)
                pclbil(3) = pclbil(3) + pdec(3,idec)
      Qvalue=Qvalue+bind_clst_new(adec(idec),zdec(idec))
C ..will contain exact cluster masses after decay.
          BARMTABLE= BARMTABLE+ FMNUC(adec(idec),zdec(idec))
             end do


          ENDIF
c     Put the decay particles (if any) in the ntuple variables
             XL1=XL1-LOUT_CLST(1,iloc)
             XL2=XL2-LOUT_CLST(2,iloc)
             XL3=XL3-LOUT_CLST(3,iloc)

             do idec=1,ndectot

                POUT1=POUT1+pdec(1,idec) ! Bilans
                POUT2=POUT2+pdec(2,idec)
                POUT3=POUT3+pdec(3,idec)

                EOUT=EOUT+tdec(idec)

C Suppressed for balance with exact Q- values:

                nopart=nopart+1 ! copie pour sortie
                kind(nopart)=kdec(idec)
                ep(nopart)=tdec(idec)

                if( ndectot.eq.1 ) then
                   num_particip(nopart)=n_particip(iloc)
                else
                   num_particip(nopart)=-1
                end if

                TVT(nopart)=TEVT(ID_CLST(1,iloc))
                ratio(nopart)=ratio_clst(iloc)

                bmass(nopart)=edec(idec) - tdec(idec)
                ekout=ekout+ep(nopart)
                ptotl=SQRT(pdec(1,idec)**2
     s               + pdec(2,idec)**2
     s               + pdec(3,idec)**2)
                alpha(nopart)=pdec(1,idec)/ptotl
                beta(nopart)=pdec(2,idec)/ptotl
                gam(nopart)=pdec(3,idec)/ptotl

        NBG_CLST=NBG_CLST+1               !Copy info in /BL13/
        EG_CLST(NBG_CLST)=edec(idec)
        DO kloc=1,3
        PG_CLST(kloc,NBG_CLST)=pdec(kloc,idec)
        RGOUT_CLST(kloc,NBG_CLST)=ROUT_CLST(kloc,iloc)
        ENDDO
             end do

        END DO
      else
      ndectot=0

      END IF
      ELSE  ! (KCLST=0, No search for cluster production)
          ndectot=0
      END IF

C Remnant size (same as IAREM):
      IREMSIZE=0
      DO i=1,IA
         IF(NESC(i).EQ.0) THEN
         IREMSIZE=IREMSIZE+1
         LREM=i
         ENDIF
      ENDDO

      IF(IREMSIZE.EQ.1) THEN
C The remnant is only one nucleon:
            CALL KINE_ADJUST(IBERT,ibw,PINC,TLAB,IA,NPION,NB_CLST,
     s      LREM,EREM,PFREM1,PFREM2,PFREM3,
     &      ierrincl)
      ESREM=0.
      PFREMl2=PFREM1**2+PFREM2**2+PFREM3**2
      ERECREM=PFREMl2/(SQRT(PFREMl2+FMP**2) + FMP)
         if (PFREMl2.gt.1.0e-12) then
           PFREML=SQRT(PFREMl2)
           ALREM=PFREM1/PFREML
           BEREM=PFREM2/PFREML
           GAREM=PFREM3/PFREML
         else
           ALREM=0.
           BEREM=0.
           GAREM=1.0
         endif

      IF(NB_CLST.NE.0) THEN
C For all clusters (momentum modified by KIN_ADJUST)
      POUT1=0.
      POUT2=0.
      POUT3=0.
      EOUT =0.
         XL1=0.
         XL2=0.
         XL3=0.
      nopart=0
         DO iloc=1,NBG_CLST
C Recompute angular momentum of clusters (and decays)
             ANGMOM1=RGOUT_CLST(2,iloc)*PG_CLST(3,iloc)
     s                       -RGOUT_CLST(3,iloc)*PG_CLST(2,iloc)
             ANGMOM2=RGOUT_CLST(3,iloc)*PG_CLST(1,iloc)
     s                       -RGOUT_CLST(1,iloc)*PG_CLST(3,iloc)
             ANGMOM3=RGOUT_CLST(1,iloc)*PG_CLST(2,iloc)
     s                       -RGOUT_CLST(2,iloc)*PG_CLST(1,iloc)
             XL1=XL1-ANGMOM1
             XL2=XL2-ANGMOM2
             XL3=XL3-ANGMOM3
C Put clusters (and decays) in output arguments
             nopart=nopart+1 ! copie pour sortie
             ptotl2=PG_CLST(1,iloc)**2
     s               + PG_CLST(2,iloc)**2
     s               + PG_CLST(3,iloc)**2
             ptotl=SQRT(ptotl2)
                alpha(nopart)=PG_CLST(1,iloc)/ptotl
                beta(nopart)=PG_CLST(2,iloc)/ptotl
                gam(nopart)=PG_CLST(3,iloc)/ptotl
             ep(nopart)=EG_CLST(iloc)-SQRT(EG_CLST(iloc)**2-ptotl2)
C Recompute POUT and EOUT...but not used if remnant= One nucleon):
             POUT1=POUT1+PG_CLST(1,iloc)
             POUT2=POUT2+PG_CLST(2,iloc)
             POUT3=POUT3+PG_CLST(3,iloc)
             EOUT=EOUT+ep(nopart)
         ENDDO
      ENDIF
      ENDIF

      DO 258 I=1,IA                                                     P-N12660
  259 IF (NESC(I).EQ.0) GO TO 254                                       P-N12700
      IF (NESC(I).GT.1) GO TO 258   ! on evite les nucleons des clusters

      JZ=(1+IND2(I))/2
      RightMass = FMNUC(1,JZ)
      BARMTABLE = BARMTABLE + RightMass

      XL1_I=X2(I)*P3(I)-X3(I)*P2(I) ! moment angulaire emporte
      XL2_I=X3(I)*P1(I)-X1(I)*P3(I)
      XL3_I=X1(I)*P2(I)-X2(I)*P1(I)


      XL1=XL1-XL1_I
      XL2=XL2-XL2_I
      XL3=XL3-XL3_I


c   ici ajout de pout CV le 5/7/95
        POUT1=POUT1+P1(I)                                               HE-13740
        POUT2=POUT2+P2(I)                                               HE-13750
        POUT3=POUT3+P3(I)                                               HE-13760
       IF(IBERT.EQ.ibw) THEN
       WRITE(6,*) 'I,NESC(I),P1,P2,P3,POUT123:',
     s     I,NESC(I),P1(I),P2(I),P3(I),POUT1,POUT2,POUT3
       ENDIF

      IC33=(IND2(I)+3)/2

      nopart=nopart+1
      kind(nopart)=3-ic33
      num_particip(nopart)=1
      TVT(nopart)=TEVT(I)

      ratio(nopart)=-1

C Right mass to be used for the remnant recoil
      bmass(nopart)=RightMass

C Correction: right mass for spectators 14/6/2011 AB
       IF(i.LE.ia1.AND.kindf7.GE.6)THEN
         IF(kpart(i).EQ.0) THEN
	   ep(nopart)=eps(i)-RightMass
	 ELSE
	   ep(nopart)=eps(i)-fmp
           if ( ep(nopart).lt.0d0 ) then ! S.H. 2020.2.5
              nopart = -1
              return
           end if
	 ENDIF
       ELSE
         ep(nopart)=eps(i)-fmp
       ENDIF
       EOUT =EOUT+ep(nopart)
      ekout=ekout+ep(nopart)
      ptotl=sqrt(p1(i)**2+p2(i)**2+p3(i)**2)
      alpha(nopart)=p1(i)/ptotl
      beta(nopart)=p2(i)/ptotl
      gam(nopart)=p3(i)/ptotl

      go to 258
  254 T(4)=X1(I)*X1(I)+X2(I)*X2(I)+X3(I)*X3(I)                          P-N12780
      EREM=EREM+EPS(I)-FMP                                              P-N12800
      STVREM=STVREM+(EPS(I)-FMP-V(I))
      RCM1=RCM1+X1(I)                                                   P-N12840
      RCM2=RCM2+X2(I)                                                   P-N12850
      RCM3=RCM3+X3(I)                                                   P-N12860
      PREM1=PREM1+P1(I)                                                 P-N12870
      PREM2=PREM2+P2(I)                                                 P-N12880
      PREM3=PREM3+P3(I)                                                 P-N12890
      izrem=izrem+(1+ind2(i))/2
      iarem=iarem+1

  258 CONTINUE                                                          P-N12990
c    correction pions 21/3/95 JC
      ichpion=0
C Takes into account low energy pi IN forced OUT (for unphysical remnant)
      epiin = -EPIEMIT
      dmpiout=0.
      ipiin=0
      ipiou=0
      if(npion.ne.0)then
      do ipion=1,npion
         if(idnint(f(17)).ne.1)then
            if(f(16).lt.0.5) then
             nesc(ia+ipion)=1
             tevt(ia+ipion)=tim
          endif
            if(nesc(ia+ipion).eq.0) goto 263
            ipiou=ipiou+1
         endif
         pout1=pout1+q1(ipion)
         pout2=pout2+q2(ipion)
         pout3=pout3+q3(ipion)
         eout=eout+q4(ipion)
         xl1=xl1-y2(ipion)*q3(ipion)+y3(ipion)*q2(ipion)
         xl2=xl2-y3(ipion)*q1(ipion)+y1(ipion)*q3(ipion)
         xl3=xl3-y1(ipion)*q2(ipion)+y2(ipion)*q1(ipion)
	 izloc=ipi(ipion)/2
	 RightMass=FMNUC(0,izloc)
	 dmpiout=dmpiout+FMPI-RightMass
         ichpion=ichpion+ipi(ipion)/2
         nopart=nopart+1
         kind(nopart)=4-ipi(ipion)/2
         ptotl=sqrt(q1(ipion)**2+q2(ipion)**2+q3(ipion)**2)
         ep(nopart)=q4(ipion)-fmpi
         num_particip(nopart)=0
       TVT(nopart)=TEVT(ia+ipion)

         ratio(nopart)=-1

C Right mass to be used for the remnant recoil
         bmass(nopart)=RightMass
	
         ekout=ekout+ep(nopart)
         alpha(nopart)=q1(ipion)/ptotl
         beta(nopart)=q2(ipion)/ptotl
         gam(nopart)=q3(ipion)/ptotl

         GOTO 264

  263 CONTINUE
      if(IPI(IPION).EQ.2) ipiin=ipiin+1
      IF(IPI(IPION).EQ.-2) V0PI=V0PIM
      IF(IPI(IPION).EQ.0) V0PI=V0PIN
      IF(IPI(IPION).EQ.2) V0PI=V0PIP
      RCM1=RCM1+Y1(IPION)
      RCM2=RCM2+Y2(IPION)
      RCM3=RCM3+Y3(IPION)
      PREM1=PREM1+Q1(IPION)
      PREM2=PREM2+Q2(IPION)
      PREM3=PREM3+Q3(IPION)
      epiin=epiin+Q4(ipion)-V0PI
      izrem=izrem+ipi(ipion)/2
  264 CONTINUE
      enddo
      endif
c Fin correction pions sur impulsion et moment angulaire et charge


c ici ajout de PFREM CV le 5/7/95
C For coulomb distorsion, we finally keep the beam value (balance will be
C done by the remant value).

C Exact mass for a nucleon beam (conservations with remnant recoil) 8/11/2011 AB
      IF(IA1.EQ.1) PINC = SQRT(TLAB*(TLAB+2.*FMNUC(IA1,IZ1)))

      IF(LCOUL.EQ.0) THEN
      PFREM1=-POUT1                                                     HE-14070
      PFREM2=-POUT2                                                     HE-14080
      PFREM3=PINC-POUT3                                                 HE-14090
      ELSE
      PFREM1=-POUT1                                                     HE-14070
      PFREM2=-POUT2                                                     HE-14080
      PFREM3=PINC-POUT3                                                 HE-14090
      ENDIF
      INREM=IAREM-IZREM
      IREM=IAREM  ! ***** ThA
C Intrinsic momentum of the remnant (A.B. 05/2001):
C    momentum of projectile minus momentum of all outgoing particles
C                           minus angular momentum of the remnant computed
C                                  from the sum of all inside nucleons.
C                           Here the remnant momentum is Pin - SIG(pout),
C   and the distance with respect to the barycenter of the actual target 10/2003
      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) ''
      WRITE(6,*) 'IBERT,IREM,XLP:',IBERT,IREM,XLP1,XLP2,XLP3
      WRITE(6,*) 'XL:',XL1,XL2,XL3
      WRITE(6,*) 'RCM:',RCM1,RCM2,RCM3
      WRITE(6,*) 'X_target:',X1_target,X2_target,X3_target
      WRITE(6,*) 'PFREM,BilanPZ:',PFREM1,PFREM2,PFREM3,PINC-PFREM3-POUT3
      ENDIF

      XL1=XLP1+XL1-(RCM2/IREM - X2_target)*PFREM3
     s       +(RCM3/IREM - X3_target)*PFREM2
      XL2=XLP2+XL2-(RCM3/IREM - X3_target)*PFREM1
     s       +(RCM1/IREM - X1_target)*PFREM3
      XL3=XLP3+XL3-(RCM1/IREM - X1_target)*PFREM2
     s       +(RCM2/IREM - X2_target)*PFREM1
      if(mod(irem,2).eq.0) then
      L=nint(SQRT(XL1*XL1+XL2*XL2+XL3*XL3)/HC)
      else
      L=nint(SQRT(XL1*XL1+XL2*XL2+XL3*XL3)/HC-0.5) + 0.5
      endif

      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'L,XL:',L,XL1,XL2,XL3
      ENDIF

C The end if the remnant is one nucleon:
      t_fin=tim
      IF(IREMSIZE.EQ.1) RETURN

  623 CONTINUE
c     -IHREM(IEJN+9,IEJP+9)=IHREM(IEJN+9,IEJP+9)+1
c deutons ajout beproj ?????? On retire beproj (18/06/2002 AB CV)
 5555  format (i6,3(i4,f8.1),i4,3(i4,f7.1),i4,i4,i4,i4)

       nninc=ia1-iz1
       IF(kindf7.le.5) THEN
       sepa=SEJNVT+SEJPVT-real(nninc,8)*SN-real(iz1,8)*SP
       ELSE
       sepa=SEJNVT+SEJPVT-nnenter*SN-npenter*SP
       ENDIF
C test 19/04/08 (sepa de INCL4.3)

       EH5=STVREM-STVINIT-SEPA+EPIIN

       IF(IBERT.EQ.ibw) THEN
       WRITE(6,*) 'EH5,STVREM,STVINIT,SEPA,EPIIN',
     s  EH5,STVREM,STVINIT,SEPA,EPIIN
       WRITE(6,*) 'SEJNVT,SEJPVT,SN,SP,IAREM,IZREM',
     s  SEJNVT,SEJPVT,SN,SP,IAREM,IZREM
       ENDIF


       if(idnint(f(17)).eq.1)then
          sepa=(ia2-irem)*(V0P-tf)
          eh5=erem-efer+(ia2-irem)*tf
          IF (EH5.LT.0.) EH5=0.00000001
       endif


C Test (and correction) for d 10 MeV 10/04/2008 (SL AB):
      xlab=tlab-eout-eh5-sepa+beproj
      xlab2=tlab+STVINIT-eout-epiin-STVREM+beproj

      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) '1 at the end: EPS(1),V(1),nesc(1):',
     s EPS(1),V(1),nesc(1)
      WRITE(6,*) '2 at the end: EPS(2),V(2),nesc(2):',
     s EPS(2),V(2),nesc(2)
      WRITE(6,*) 'i,E,PX,PY,PZ,NESC,V(i):'
      DO iloc=1,ia1+ia2
      WRITE(6,*) iloc,eps(iloc),p1(iloc),p2(iloc),p3(iloc),
     s NESC(iloc),V(iloc)
      ENDDO
      WRITE(6,*) 'PFREM1,2,3:',pfrem1,pfrem2,pfrem3
      ENDIF

C ???? (Cidessous commente mais mis anciennement ad oc  pour pi IN)

c ***** ThA: calcul du Tini-Tfin / Tini
      errel=xlab/(tlab+STVINIT)
      if(idnint(f(17)).ne.1)then

C Realistic Q value AB 8/11/2010
       SEPAP=FMNUC(IAREM,IZREM)+BARMTABLE-FMNUC(IA2,IZ2)-FMNUC(IA1,IZ1)
C Correction for HI and projectile nucleons entering below TF:
       SEPAP=SEPAP+CORSEPA
       beprojp=0
       IF(kindf7.GE.6)
     s   beprojp=FMNUC(IA1,IZ1)-IZ1*FMNUC(1,1)-(IA1-IZ1)*FMNUC(1,0)
       xlabp=xlab+SEPA-SEPAP+dmpiout-beprojp

C TEST for composits IN (ad oc quantity substracted from xlabp!) 10/06/2011 AB
       corloc=0.
       IF(kindf7.ge.6) THEN
       corloc=IZ1*FMNUC(1,1)+(IA1-IZ1)*FMNUC(1,0)-IA1*FMP
       ENDIF
C This line is ad oc to obtain xlabp=0 :
       xlabp=xlabp-corloc

      endif
      if(IBERT.eq.ibw) then
       write(6,*) IBERT,' xlab,xlab2,xlabp',
     s           xlab,xlab2,xlabp,EH5,VARIA
       write(6,*)'sepa,SEPAP,BARMTABLE,xlabP',
     s            sepa,SEPAP,BARMTABLE,xlabp
       WRITE(6,*) 'beprojp,CORSEPA,SP,SN,dmpiout:',
     s             beprojp,CORSEPA,SP,SN,dmpiout
       write(6,*)'NOPART,NB_CLST,NBG_CLST,npion,EPIIN'
       write(6,*) NOPART,NB_CLST,NBG_CLST,npion,EPIIN
       write(6,*)'eout ',eout,' epiin ',epiin
       write(6,*)'st',STVINIT,STVREM
       write(6,*)'num pi',npion
       write(6,*)'num ej',nopart
      endif
       ecoreh5=0.
      IF (iqe.eq.1) THEN
        eh5=0.00000001
      ELSE
C Modif du test pour composites et right Q-val (souvent -1.77e-15) 15/06/2011 AB
        IF (eh5.lt.-0.00001) THEN
         if (npion.eq.0) then
           nopart=-1
	   t_fin=tim
           return
         else
           ecoreh5=-eh5
           eh5=0.000000001
         endif
	ELSE
	 if (eh5.LT.0) then
	 eh5=0.000000001
	 endif
        ENDIF
      ENDIF

      if (idecf.ne.0.and.eh5.lt.0.) then
       ecoreh5=-eh5
       eh5=0.000001
      endif

C***********************************************************

      pfreml2=pfrem1**2+pfrem2**2+pfrem3**2

C test 30/4/2008 Remnant mass more consistent:
C Right mass to be used for the remnant recoil
      FMREM=FMNUC(IAREM,IZREM)+eh5

      erecrem=pfreml2/(SQRT(pfreml2+FMREM**2) + FMREM)
C****************************************************************
C Test of Right Q-Values:
      ifl_print=0
776   CONTINUE	!First olympiade
      BIL_INCL=0.
      BIL_RIGHT=0.
      BIL_P1=0.
      BIL_P2=0.
      BIL_P3=0.
      DO iloc=1,NOPART
      IF(KIND(iloc).GE.10) THEN
      IZCLS=MOD(KIND(iloc),10)
      IACLS=(KIND(iloc)-IZCLS)/10
      FNCLMass=IACLS*FMP-BIND_CLST_NEW(IACLS,IZCLS)
      RightMass=FMNUC(IACLS,IZCLS)
      ELSE
      IF(KIND(iloc).EQ.1) THEN
      FNCLMass=FMP
      RightMass=FMNUC(1,1)
      ENDIF
      IF(KIND(iloc).EQ.2) THEN
      FNCLMass=FMP
      RightMass=FMNUC(1,0)
      ENDIF
      IF(KIND(iloc).EQ.3) THEN
      FNCLMass=FMPI
      RightMass=FMNUC(0,1)
      ENDIF
      IF(KIND(iloc).EQ.4) THEN
      FNCLMass=FMPI
      RightMass=FMNUC(0,0)
      ENDIF
      IF(KIND(iloc).EQ.5) THEN
      FNCLMass=FMPI
      RightMass=FMNUC(0,-1)
      ENDIF
      IF(KIND(iloc).EQ.6) THEN
      FNCLMass=2.*FMP-BIND_CLST_NEW(2,1)
      RightMass=FMNUC(2,1)
      ENDIF
      IF(KIND(iloc).EQ.7) THEN
      FNCLMass=3.*FMP-BIND_CLST_NEW(3,1)
      RightMass=FMNUC(3,1)
      ENDIF
      IF(KIND(iloc).EQ.8) THEN
      FNCLMass=3.*FMP-BIND_CLST_NEW(3,2)
      RightMass=FMNUC(3,2)
      ENDIF
      IF(KIND(iloc).EQ.9) THEN
      FNCLMass=4.*FMP-BIND_CLST_NEW(4,2)
      RightMass=FMNUC(4,2)
      ENDIF
      ENDIF
      P_test=SQRT(EP(iloc)*(EP(iloc)+2.*RightMass))
      BIL_P1=BIL_P1+P_test*alpha(iloc)
      BIL_P2=BIL_P2+P_test*beta(iloc)
      BIL_P3=BIL_P3+P_test*gam(iloc)
      BIL_INCL=BIL_INCL+EP(iloc)+FNCLMass
      BIL_RIGHT=BIL_RIGHT+EP(iloc)+RightMass
      ENDDO
      BIL_P3=SQRT(TLAB*(TLAB+2.*FMNUC(IA1,IZ1)))-BIL_P3
      BIL_INCL=BIL_INCL+FMNUC(IAREM,IZREM)+EH5-FMNUC(IA2,IZ2)
      BIL_RIGHT=BIL_RIGHT+FMNUC(IAREM,IZREM)+EH5-FMNUC(IA2,IZ2)
      IF(ifl_print.EQ.1) THEN
      ELSE
C test of E conservation (before remnant recoil) for a print:
        IF(ABS(TLAB+FMNUC(IA1,IZ1)-BIL_RIGHT).GE.0.05)THEN
          ifl_print=1
          GO TO 776
        ENDIF
C test of P conservation (before remnant recoil) is violated!

C Print for a given cascade (ibw):
        IF(IBERT.EQ.ibw) THEN
          ifl_print=1
          GO TO 776
        ENDIF
      ENDIF

C****************************************************************
      if (pfreml2.gt.1.0e-12) then
      pfreml=sqrt(pfreml2)
      alrem=pfrem1/pfreml
      berem=pfrem2/pfreml
      garem=pfrem3/pfreml
      else
      alrem=0.
      berem=0.
      garem=1.0
      endif
      IF(iarem.EQ.1) erecrem = erecrem + eh5
c correction recul
      erecg=erecrem+ecoreh5
C Correction energie d'excitation pour une absorption (A.B., C.V. 2/2002)
      ESREM=eh5

C Special calculation of the remnant for absorption 01/2012 A.B., D.M.
      IF(NOPART.EQ.0) THEN
      alrem=0.
      berem=0.
      garem=1.0
      pfrem=PINC
      FMREM=FMNUC(IAREM,IZREM)
      FMTARGET=FMNUC(IA2,IZ2)
      FMPROJ=FMNUC(IA1,IZ1)
      EH5=SQRT(FMPROJ**2+FMTARGET**2+2.*(TLAB+FMPROJ)*FMTARGET)
     s               -FMREM
        IF(EH5.LT.0.) THEN
	  EH5=0.
        ENDIF
      ESREM=EH5
      FMSTREM=FMREM+ESREM
      ERECREM=SQRT(pfrem**2+FMSTREM**2)-FMSTREM
      IF(IBERT.EQ.ibw)
     s WRITE(6,*) 'Absorption IBERT,ESREM,ERECREM,FMREM:',
     s                         IBERT,ESREM,ERECREM,FMREM
      RETURN
      ENDIF

      if (ekout.lt.0.001) then
      t_fin=tim
      return
      endif
c on ote l'instruction precedente car esrem toujours nulle 14/9/99

C For iteration on FFFC: 1/2012 AB
      ITER_FFFC=0
      SAVE_EKOUT=ekout
      TEST_E_val=0.5

C Prepare the function FFFC_FUNC for the FFFC adjustment (remant recoil) ****
      DO ipart=1,NOPART
        EPF(ipart) = EP(ipart)
	ALPHAF(ipart) = ALPHA(ipart)
	BETAF(ipart) = BETA(ipart)
	GAMF(ipart) = GAM(ipart)
	BMASSF(ipart) = BMASS(ipart)
      ENDDO
        FMREMF = FMREM
	PINC1F = 0.
	PINC2F = 0.
      PINC3F = SQRT(TLAB*(TLAB+2.*FMNUC(IA1,IZ1)))
	NOPARTF = NOPART
C First guess:
       IF (erecg.gt.0.05.AND.SAVE_EKOUT.GT.erecg) THEN
         fffc=(SAVE_EKOUT-erecg)/ekout
       ELSE
         fffc=0.2
       ENDIF
C Call the adjustment (i_ok=0 if no sol after 20 iterations):
      FFFC_adjust = SOLV_FP(FFFC_FUNC,
     s real(0.,8),real(1.,8),real(0.,8),real(0.001,8),i_ok)
      IF(i_ok.EQ.1) THEN
C ...and keep the result:
      BID=FFFC_FUNC(FFFC_adjust)
      EKOUTN=0.
      DO ipart=1,NOPART
        EP(ipart) = EPR(ipart)
	EKOUTN=EKOUTN+EP(ipart)
      ENDDO
      PFREM1=PFREM1R
      PFREM2=PFREM2R
      PFREM3=PFREM3R
      PFREMl2 = PFREMl2R
      ERECREM = ERECREMR
      GO TO 783
      ENDIF
c*****************************************************************************
782   CONTINUE

c modif 2008: rescaling of energies for smaller values (0.05 instead of 0.25)
       if (erecg.gt.0.05) then
         fffc=(SAVE_EKOUT-erecg)/ekout
	
C Modif pour eviter les spectateurs (provisoire deuton seulement) 13/04/08
           if (fffc.lt.0.0) fffc=0.
C S.H. removed 'c' in the three lines below (2013.8.8).
           nopart=-100
           return
           else
           do ipart=1,nopart
C Modif pour eviter les spectateurs (provisoire deuton seulement) 13/04/08
           ep(ipart)=ep(ipart)*fffc
           enddo
       endif

c Modif BOUDARD juillet 99 (il faut tenir compte de la renormalisation
C   des energies pour les impulsions.)
           EKOUTN=0.
           pfrem1=0.
           pfrem2=0.
           pfrem3=pinc
         do ipart=1,nopart
	   EKOUTN = EKOUTN + ep(ipart)
           xmodp=sqrt(ep(ipart)*(2.*bmass(ipart)+ep(ipart)))
           pfrem1=pfrem1-alpha(ipart)*xmodp
           pfrem2=pfrem2-beta(ipart)*xmodp
           pfrem3=pfrem3-gam(ipart)*xmodp
         enddo
c Fin modif A.B.
      pfreml2=pfrem1**2+pfrem2**2+pfrem3**2
C Historical value (this is the same as SQRT(pfreml2+(fmp*iarem)**2) - fmp*iarem)
C test 30/4/2008 Remnant mass more consistent:
      erecrem=pfreml2/(SQRT(pfreml2+(fmrem)**2) + fmrem)
783   CONTINUE

      if (pfreml2.gt.1.0e-12) then
      pfreml=sqrt(pfreml2)
      alrem=pfrem1/pfreml
      berem=pfrem2/pfreml
      garem=pfrem3/pfreml
      else
      alrem=0.
      berem=0.
      garem=1.0
      endif
C Fin  modif A.B. pour incl3
      esrem=eh5
C If the remnant is a nucleon, NO excitation energy
      IF(IAREM.EQ.1) THEN
      esrem=0.
      ENDIF

      IF(IBERT.EQ.ibw) THEN
      WRITE(6,*) 'EREM,PFREM:',fmrem+ERECREM,pfrem1,pfrem2,pfrem3
      WRITE(6,*) 'FMREM,ERECREM,ESREM:',FMREM,ERECREM,ESREM
      ENDIF

C Test for iteration on fffc (remnant recoil adjusted):
      ERECGN = ERECREM + ECOREH5
      ARG=EKOUTN+ERECGN-SAVE_EKOUT
      IF(ABS(EKOUTN+ERECGN-SAVE_EKOUT).GE.TEST_E_val)THEN
      IF(IBERT.EQ.ibw) WRITE(6,*) ERECGN,EKOUTN,ARG,SAVE_EKOUT
        IF(ITER_FFFC.EQ.0) THEN
      IF(IBERT.EQ.ibw) WRITE(6,*) 'Remnant recoil iteration:',
     s ITER_FFFC,' *** IBERT = ',IBERT
      IF(IBERT.EQ.ibw) WRITE(6,*) 'fffc, ERECG, EKOUT, Bilan:',
     s                 fffc,erecg,ekout,ARG
	ENDIF
        ITER_FFFC = ITER_FFFC + 1
        IF(ITER_FFFC.LE.5) THEN
      IF(IBERT.EQ.ibw) WRITE(6,*) 'Remnant recoil iteration:',
     s                 ITER_FFFC
	   fffcN=(SAVE_EKOUT-ERECGN)/EKOUTN
      IF(IBERT.EQ.ibw) WRITE(6,*) 'fffcN, ERECGN, EKOUTN, Bilan:',
     s                      fffcN,ERECGN,EKOUTN,ARG
	   erecg = ERECGN
	   ekout = EKOUTN
	   GO TO 782
	ENDIF
      IF(IBERT.EQ.ibw)
     s  WRITE(6,*) 'No recoil by iteration of historical methode',
     s  IBERT,fffc
      ENDIF

C Test of Right Q-Values at the end:
      ifl_print=0
780   CONTINUE	!Second olympiade
      BIL_INCL=0.
      BIL_RIGHT=0.
      BIL_P1=0.
      BIL_P2=0.
      BIL_P3=0.
      DO iloc=1,NOPART
      IF(KIND(iloc).GE.10) THEN
      IZCLS=MOD(KIND(iloc),10)
      IACLS=(KIND(iloc)-IZCLS)/10
      FNCLMass=IACLS*FMP-BIND_CLST_NEW(IACLS,IZCLS)
      RightMass=FMNUC(IACLS,IZCLS)
      ELSE
      IF(KIND(iloc).EQ.1) THEN
      FNCLMass=FMP
      RightMass=FMNUC(1,1)
      ENDIF
      IF(KIND(iloc).EQ.2) THEN
      FNCLMass=FMP
      RightMass=FMNUC(1,0)
      ENDIF
      IF(KIND(iloc).EQ.3) THEN
      FNCLMass=FMPI
      RightMass=FMNUC(0,1)
      ENDIF
      IF(KIND(iloc).EQ.4) THEN
      FNCLMass=FMPI
      RightMass=FMNUC(0,0)
      ENDIF
      IF(KIND(iloc).EQ.5) THEN
      FNCLMass=FMPI
      RightMass=FMNUC(0,-1)
      ENDIF
      IF(KIND(iloc).EQ.6) THEN
      FNCLMass=2.*FMP-BIND_CLST_NEW(2,1)
      RightMass=FMNUC(2,1)
      ENDIF
      IF(KIND(iloc).EQ.7) THEN
      FNCLMass=3.*FMP-BIND_CLST_NEW(3,1)
      RightMass=FMNUC(3,1)
      ENDIF
      IF(KIND(iloc).EQ.8) THEN
      FNCLMass=3.*FMP-BIND_CLST_NEW(3,2)
      RightMass=FMNUC(3,2)
      ENDIF
      IF(KIND(iloc).EQ.9) THEN
      FNCLMass=4.*FMP-BIND_CLST_NEW(4,2)
      RightMass=FMNUC(4,2)
      ENDIF
      ENDIF
      P_test=SQRT(EP(iloc)*(EP(iloc)+2.*RightMass))
      BIL_P1=BIL_P1+P_test*alpha(iloc)
      BIL_P2=BIL_P2+P_test*beta(iloc)
      BIL_P3=BIL_P3+P_test*gam(iloc)
      BIL_INCL=BIL_INCL+EP(iloc)+FNCLMass
      BIL_RIGHT=BIL_RIGHT+EP(iloc)+RightMass
      ENDDO
      BIL_P1=BIL_P1+PFREM1
      BIL_P2=BIL_P2+PFREM2
      BIL_P3=BIL_P3+PFREM3
      BIL_P3=SQRT(TLAB*(TLAB+2.*FMNUC(IA1,IZ1)))-BIL_P3
      BIL_INCL=BIL_INCL+FMNUC(IAREM,IZREM)+EH5-FMNUC(IA2,IZ2)
      BIL_INCL=BIL_INCL+ERECREM
      BIL_RIGHT=BIL_RIGHT+FMNUC(IAREM,IZREM)+EH5-FMNUC(IA2,IZ2)
      BIL_RIGHT=BIL_RIGHT+ERECREM
      IF(ifl_print.EQ.2.OR.ifl_print.EQ.3) GO TO 781

C test of E conservation (with remnant recoil) for a print:
        IF(ABS(TLAB+FMNUC(IA1,IZ1)-BIL_RIGHT).GE.TEST_E_val)THEN
	  IF(ifl_print.EQ.0) THEN
C print avant correction (1 for full print, 3 for small print):
       IF(IBERT.EQ.ibw)
     s     WRITE(6,*) 'No energy conservation (FINAL) ',
     s  'without change of ESREM; IBERT',IBERT
      BIL_RIGHT=0.
      BIL_P1=0.
      BIL_P2=0.
      BIL_P3=0.
      EKOUTN=0.
      DO ipart=1,NOPARTF
        EP(ipart) = EPF(ipart)
	ALPHA(ipart) = ALPHAF(ipart)
	BETA(ipart) = BETAF(ipart)
	GAM(ipart) = GAMF(ipart)
	BMASS(ipart) = BMASSF(ipart)
	EKOUTN=EKOUTN+EP(ipart)+BMASS(ipart)
      P_test=SQRT(EP(ipart)*(EP(ipart)+2.*BMASS(ipart)))
      BIL_P1=BIL_P1+P_test*alpha(ipart)
      BIL_P2=BIL_P2+P_test*beta(ipart)
      BIL_P3=BIL_P3+P_test*gam(ipart)
      BIL_RIGHT=BIL_RIGHT+EP(ipart)+BMASS(ipart)
      ENDDO
        FMREM = FMREMF
	PFREM1 = PINC1F-POUT1
	PFREM2 = PINC2F-POUT2
	PFREM3 = PINC3F-POUT3
	NOPART = NOPARTF
	PFREML2 = PFREM1**2 + PFREM2**2 + PFREM3**2
      if (pfreml2.gt.1.0e-12) then
      pfreml=sqrt(pfremL2)
      alrem=pfrem1/pfreml
      berem=pfrem2/pfreml
      garem=pfrem3/pfreml
      else
      alrem=0.
      berem=0.
      garem=1.0
      endif
        CTPRIM=TLAB+FMNUC(IA1,IZ1)+FMNUC(IA2,IZ2)-EKOUTN
	ESTNEW=SQRT(CTPRIM**2-PFREML2)-FMNUC(IAREM,IZREM)
	IF(ESTNEW.GE.0.) THEN
       IF(IBERT.EQ.ibw)
     s  WRITE(6,*) '  ',ESREM,' ESREM adjusted'
	  ESREM=ESTNEW
	ELSE
	  ESREM=0.
	ENDIF
	  FMREM = FMNUC(IAREM,IZREM)+ ESREM
	  ERECREM = SQRT(PFREML2+FMREM**2) - FMREM
	  EH5=ESREM
       IF(IBERT.EQ.ibw)
     s  WRITE(6,*) 'New values: ESREM,ERECREM,FMREM:',
     s              ESREM,ERECREM,FMREM
      BIL_P1=BIL_P1+PFREM1
      BIL_P2=BIL_P2+PFREM2
      BIL_P3=BIL_P3+PFREM3
      BIL_P3=SQRT(TLAB*(TLAB+2.*FMNUC(IA1,IZ1)))-BIL_P3
      BIL_RIGHT=BIL_RIGHT+FMNUC(IAREM,IZREM)+EH5-FMNUC(IA2,IZ2)
      BIL_RIGHT=BIL_RIGHT+ERECREM
C test of E conservation (with remnant recoil) for a print:
        IF(ABS(TLAB+FMNUC(IA1,IZ1)-BIL_RIGHT).GE.TEST_E_val)THEN
            ifl_print=2
            GO TO 780
	ENDIF
C test of P conservation (with remnant recoil) for a print:
        IF(ABS(BIL_P1).GE.0.07.OR.ABS(BIL_P2).GE.0.07
     s                           .OR.ABS(BIL_P3).GE.0.07)THEN
            ifl_print=2
            GO TO 780
	ENDIF
	GO TO 781
	
	
	  ENDIF
        ENDIF
C test of P conservation (with remnant recoil) for a print:
        IF(ABS(BIL_P1).GE.0.07.OR.ABS(BIL_P2).GE.0.07
     s                           .OR.ABS(BIL_P3).GE.0.07)THEN
C print (2 for full print, 3 for small print):
       IF(IBERT.EQ.ibw)
     s  WRITE(6,*) 'No momentum conservation (FINAL) IBERT',IBERT
          ifl_print=3
          GO TO 780
        ENDIF
C Print for a given cascade (ibw):
        IF(IBERT.EQ.ibw) THEN
          ifl_print=2
          GO TO 780
        ENDIF

781   CONTINUE
C****************************************************************
        t_fin=tim
        RETURN

   77 continue                                                          P-N17750
        print *,' Ia1 > 1 ! '
        t_fin=tim
        RETURN
      END SUBROUTINE PNU                                                P-N17760

c
C COLLIS                                                                P-N17770
      SUBROUTINE COLLIS(P1,P2,P3,E1,POUT11,POUT12,POUT13,EOUT1,Q1,Q2,Q3,P-N17780
     -Q4,NP,IP,K2,K3,K4,K5,M1,M2,IS1,IS2)                               P-N17790
      implicit real*8(A-H,O-Z)
      COMMON/BL6/XX10,ISA                                               P-N17800
!$OMP THREADPRIVATE(/BL6/)
      COMMON/BL8/RATHR,RAMASS                                           P-N17810
!$OMP THREADPRIVATE(/BL8/)
      COMMON/bl12/QQ1(200),QQ2(200),QQ3(200),QQ4(200),
     s            YY1(200),YY2(200),YY3(200),YM(200),IPI(200)
!$OMP THREADPRIVATE(/bl12/)
      common/bl9/hel(350),l1,l2
!$OMP THREADPRIVATE(/bl9/)
      COMMON/OPTI/CUTNN,ALPH,TFM,TFN,TFP,TFPP,
     s  PFM,PFN,PFP,PFPP,V0M,V0N,V0P,V0PP,S1NN,S2NN,V2P,V2N,LBLNN,LNNEF
!$OMP THREADPRIVATE(/OPTI/)
      DIMENSION EX(3),EY(3),EZ(3),QQ(3)                                 P-N17820
      DATA XM,XM2,XMDEL,EZERO,XPI/938.2796,8.8037E5,1232.,1876.6,138./  P-N17830
      PCM(E,A,C)=0.5*SQRT((E**2-(A+C)**2)*(E**2-(A-C)**2))/E            P-N17870
      ISO=IS1+IS2                                                       P-N17880
      NP=0                                                              P-N17890
      PSQ=P1*P1+P2*P2+P3*P3                                             P-N17900
      PNORM=SQRT(PSQ)                                                   P-N17910
      ECM=E1+EOUT1                                                      P-N17920
      IF (ECM.LT.CUTNN) GO TO 160                                        P-N17930
      IF (K3.EQ.1) GO TO 17                                             P-N17940
      IF (ECM.LT.2065.+RATHR) GO TO 17                                   P-N17950
      IF (K4-1) 18,10,20                                                 P-N17960
   10 IF (M1+M2-1) 19,14,13                                             P-N17970
   19 IF (ECM-2170.4-RAMASS) 17,17,18                                   P-N17980
   20 IF (M1+M2-1) 18,14,13                                              P-N17990
C                                                                       P-N18000
CCC   TEST ON THE RECOMBINATION POSSIBILITY FOR THE N-DELTA SYSTEM      P-N18010
C                                                                       P-N18020
   14 IF (K5.EQ.0) GO TO 170                                            P-N18030
      rndm=rn(0)
      S1=SEL(ECM,1,ISO)                                                 P-N18090
  206 IF (M1.EQ.0) GO TO 200                                            P-N18100
      XX10=SQRT(E1*E1-PSQ)                                              P-N18110
      ISA=IS1                                                           P-N18120
      GO TO 201                                                         P-N18130
  200 XX10=SQRT(EOUT1**2-PSQ)                                           P-N18140
      ISA=IS2                                                           P-N18150
  201 CONTINUE                                                          P-N18160
      S=S1+SREC(ECM,XX10,ISO,ISA)                                       P-N18170
      A=(S-S1)/S                                                        P-N18180
      IF (RNDM-A) 170,170,17                                            P-N18190
C                                                                       P-N18200
CCC   TEST FOR THE BEHAVIOUR OF THE DELTA-DELTA SYSTEM                  P-N18210
C                                                                       P-N18220
   13 IF (K5.EQ.0) GO TO 160                                            P-N18230
      GO TO 17                                                          P-N18240
C                                                                       P-N18250
CCC   TEST ON THE INELASTICITY                                          P-N18260
C                                                                       P-N18270
   18 rndm=rn(0)
      S=SEL(ECM,0,ISO)                                                  P-N18330
      A=SPRO(ECM,ISO)                                                   P-N18340
      A=S/(S+A)                                                         P-N18350
      IF(RNDM.GT.A) GO TO 100                                           P-N18360
C                                                                       P-N18370
CCC   ELASTIC SCATTERING                                                P-N18380
CCC      FIT OF THE B PARAMETER IN THE DIFFERENTIAL X-SECTION:          P-N18390
CCC       TAKEN FROM :J.C.,D.L'HOTE, J.VANDERMEULEN,NIMB111(1996)215    P-N18400
CCC       FOR PN :IMPROVEMENT OF THE BACKWARD SCATTERING ACCORDING
CCC          J.C ET AL, PRC56(1997)2431
C                                                                       P-N18430
   17 CONTINUE
      PL=0.5*ECM*SQRT(ECM**2-4.*XM2)/XM                                 P-N18440
      X=0.001*PL                                                        P-N18450
      IF (ISO.EQ.0) GO TO 80                                            P-N18460
   83 IF (PL.GT.2000.) GO TO 81                                         P-N18470
      X=X*X                                                             P-N18480
      X=X**4                                                            P-N18490
      B=5.5E-6*X/(7.7+X)                                                P-N18500

      GO TO 82                                                          P-N18510
   81 B=(5.34+0.67*(X-2.))*1.E-6                                        P-N18520

      GO TO 82                                                          P-N18530
   80 IF (PL.LT.800.) THEN
         B=(7.16-1.63*X)*1.E-6                                            P-N18550
         B=B/(1.+EXP(-(X-0.45)/0.05))                                      P-N18560
      ELSE
         IF (PL.LT.1100.) THEN
            B=(9.87-4.88*X)*1.E-6
         ELSE
            B=(3.68+0.76*X)*1.E-6
         ENDIF
      ENDIF
   82 BTMAX=4.*PSQ*B                                                    P-N18570
      Z=EXP(-BTMAX)                                                     P-N18580
      rndm=rn(0)
      ranres=rndm
      Y=1.-RNDM*(1.-Z)                                                  P-N18640
      T=LOG(Y)/B                                                        P-N18650
      IEXPI=0

      IF (M1+M2.EQ.0.AND.ISO.EQ.0) THEN

         APT=1.
         IF (PL.GT.800.)THEN
            APT=(800./PL)**2
            CPT=DMAX1(6.23*EXP(-1.79*X),0.3)
            ALPHAC=100.*1.E-6
            AAA=(1+APT)*(1-EXP(-BTMAX))/B
            ARGU=PSQ*ALPHAC
            IF (ARGU.GE.8) THEN
               ARGU=0.
            ELSE ARGU=EXP(-4.*ARGU)
            ENDIF
            AAC=CPT*(1.-ARGU)/ALPHAC
            FRACPN=AAA/(AAC+AAA)
            rndm=rn(0)

            IF (RNDM.GT.FRACPN) THEN
               Z=EXP(-4.*PSQ*ALPHAC)
               IEXPI=1
               Y=1.-RANRES*(1.-Z)
               T=LOG(Y)/ALPHAC
            ENDIF
         ENDIF
      ENDIF

      CTET=1.+0.5*T/PSQ                                                 P-N18660
      if (abs(ctet).gt.1.) ctet=sign(real(1.,8),ctet)
      STET=SQRT(1.-CTET**2)                                             P-N18670
      rndm=rn(0)

      FI=6.2832*RNDM                                                    P-N18730
      CFI=COS(FI)                                                       P-N18740
      SFI=SIN(FI)                                                       P-N18750
      XX=P1*P1+P2*P2                                                    P-N18760
      ZZ=P3*P3                                                          P-N18770
      IF (XX.LT.ZZ*1.E-8) GO TO 30                                      P-N18780
      YN=SQRT(XX)                                                       P-N18790
      ZN=YN*PNORM                                                       P-N18800
      EZ(1)=P1/PNORM                                                    P-N18810
      EZ(2)=P2/PNORM                                                    P-N18820
      EZ(3)=P3/PNORM                                                    P-N18830
      EX(1)=P2/YN                                                       P-N18840
      EX(2)=-P1/YN                                                      P-N18850
      EX(3)=0.                                                          P-N18860
      EY(1)=P1*P3/ZN                                                    P-N18870
      EY(2)=P2*P3/ZN                                                    P-N18880
      EY(3)=-XX/ZN                                                      P-N18890
      P1=(EX(1)*CFI*STET+EY(1)*SFI*STET+EZ(1)*CTET)*PNORM               P-N18900
      P2=(EX(2)*CFI*STET+EY(2)*SFI*STET+EZ(2)*CTET)*PNORM               P-N18910
      P3=(EX(3)*CFI*STET+EY(3)*SFI*STET+EZ(3)*CTET)*PNORM               P-N18920
      GO TO 31                                                          P-N18930
   30 P1=P3*CFI*STET                                                    P-N18940
      P2=P3*SFI*STET                                                    P-N18950
      P3=P3*CTET                                                        P-N18960
   31 POUT11=-P1                                                        P-N18970
      POUT12=-P2                                                        P-N18980
      POUT13=-P3                                                        P-N18990
C
C%%%  BACKWARD SCATTERING ACCORDING THE PARAMETRIZATION OF REF
C%%%     PRC56(1997)1
C
      IF (M1+M2.EQ.1) GO TO 133                                         P-N19000
      IF (ISO.NE.0) GO TO 133
      rndm=rn(0)

      APT=1.                                                            P-N19050
      IF (PL.GT.800.)THEN
         APT=(800./PL)**2                                               P-N19060
      ENDIF
      IF (IEXPI.EQ.1.OR.RNDM.GT.1./(1.+APT)) THEN
      II=IS1                                                            P-N19080
      IS1=IS2                                                           P-N19090
      IS2=II                                                            P-N19100
      ENDIF
  133 CONTINUE                                                          P-N19110
      RETURN                                                            P-N19120
C                                                                       P-N19130
CCC   DELTA PRODUCTION                                                  P-N19140
C                                                                       P-N19150
C        THE PRODUCTION IS NOT ISOTROPIC IN THIS VERSION                P-N19160
C        IT HAS THE SAME EXP(B*T) STRUCTURE AS THE NN ELASTIC SCATTERINGP-N19170
C          (FORMULA 2.3 OF J.CUGNON ET AL, NUCL PHYS A352(1981)505)     P-N19180
C        PARAMETRIZATION OF B TAKEN FROM REF. PRC56(1997)2431
C                                                                       P-N19190
  100 IF (K4.NE.1) GO TO 101    ! ThA K4 = 2 by default                 P-N19200
      XMDEL=1232.+RAMASS                                                P-N19210
      GO TO 103                                                         P-N19220
  101 rndm=rn(0)

      Y=TAN(3.1415926*(RNDM-0.5))                                       P-N19280
      X=1232.+0.5*130.*Y+RAMASS                                         P-N19290
      IF (X.LT.XM+XPI+2.) GO TO 101                                     P-N19300
      IF (ECM.LT.X+XM+1.) GO TO 101                                     P-N19310
C
C%%%   GENERATION OF THE DELTA MASS WITH THE PENETRATION FACTOR
C          (SEE PRC56(1997)2431)
      Y=ECM**2
      Q2=(Y-1076.**2)*(Y-800.**2)/Y/4.
      Q3=(SQRT(Q2))**3
      F3MAX=Q3/(Q3+180.0**3)
      Y=X**2
      Q2=(Y-1076.**2)*(Y-800.**2)/Y/4.
      Q3=(SQRT(Q2))**3
      F3=Q3/(Q3+180.0**3)
      rndm=rn(0)
      if (rndm.gt.f3/f3max) go to 101
      XMDEL=X                                                           P-N19320
  103 PIN=PNORM                                                         P-N19330
      PNORM=PCM(ECM,XM,XMDEL)                                           P-N19340
      if (pnorm.le.0) pnorm=0.000001
      INDEX=0                                                           P-N19350
      INDEX2=0                                                          P-N19360
      rndm=rn(0)

      IF (RNDM.LT.0.5) INDEX=1                                          P-N19420
      IF (ISO.EQ.0) THEN
         rndm=rn(0)

         IF (RNDM.LT.0.5) INDEX2=1
      ENDIF
      rndm=rn(0)

      x=0.001*0.5*ECM*SQRT(ECM**2-4.*XM2)/XM
      if (x.lt.1.4) then
         b=(5.287/(1.+exp((1.3-x)/0.05)))*1.e-6
      else
         b=(4.65+0.706*(x-1.4))*1.e-6
      endif
      XKH=2.*B*PIN*PNORM                                                P-N19510
      CTET=1.+LOG(1.-RNDM*(1.-EXP(-2.*XKH)))/XKH                        P-N19520
      if (abs(ctet).gt.1.) ctet=sign(real(1.,8),ctet)
      STET=SQRT(1.-CTET**2)                                             P-N19530
      rndm=rn(0)

      FI=6.2832*RNDM                                                    P-N19590
      CFI=COS(FI)                                                       P-N19600
      SFI=SIN(FI)                                                       P-N19610
c   delta production: correction of the angular distribution 02/09/02

      XX=P1*P1+P2*P2                                                    P-N18760
      ZZ=P3*P3                                                          P-N18770
      IF (XX.LT.ZZ*1.E-8) GO TO 230                                     P-N18780
      YN=SQRT(XX)                                                       P-N18790
      ZN=YN*PIN                                                         P-N18800
      EZ(1)=P1/PIN                                                      P-N18810
      EZ(2)=P2/PIN                                                      P-N18820
      EZ(3)=P3/PIN                                                      P-N18830
      EX(1)=P2/YN                                                       P-N18840
      EX(2)=-P1/YN                                                      P-N18850
      EX(3)=0.                                                          P-N18860
      EY(1)=P1*P3/ZN                                                    P-N18870
      EY(2)=P2*P3/ZN                                                    P-N18880
      EY(3)=-XX/ZN                                                      P-N18890
      XP1=(EX(1)*CFI*STET+EY(1)*SFI*STET+EZ(1)*CTET)*PNORM              P-N18900
      XP2=(EX(2)*CFI*STET+EY(2)*SFI*STET+EZ(2)*CTET)*PNORM              P-N18910
      XP3=(EX(3)*CFI*STET+EY(3)*SFI*STET+EZ(3)*CTET)*PNORM              P-N18920
      GO TO 231
  230 CONTINUE
      XP1=PNORM*STET*CFI                                                P-N19620
      XP2=PNORM*STET*SFI                                                P-N19630
      XP3=PNORM*CTET                                                    P-N19640
  231 CONTINUE
c     end of correction angular distribution of delta production
      E3=SQRT(XP1*XP1+XP2*XP2+XP3*XP3+XM*XM)                            P-N19650
      IF(K4.NE.0) GO TO 161                                             P-N19660
C                                                                       P-N19670
CCC   DECAY OF THE DELTA PARTICLE (K4=0)                                P-N19680
C                                                                       P-N19690
      NP=1                                                              P-N19700
      IP=0                                                              P-N19710
      QQ(1)=XP1                                                         P-N19720
      QQ(2)=XP2                                                         P-N19730
      QQ(3)=XP3                                                         P-N19740
      QQ4P=SQRT(XP1*XP1+XP2*XP2+XP3*XP3+XMDEL*XMDEL)                    P-N19750
      heli=ctet**2

      YM(200)=XMDEL
      CALL DECAY2(QQ(1),QQ(2),QQ(3),QQ4P,200,
     s         XM,XPI,heli,B1x,B2x,B3x)
      Q1=QQ1(200)
      Q2=QQ2(200)
      Q3=QQ3(200)
      Q4=QQ4(200)

      IF (INDEX.EQ.0) GO TO 149                                         P-N19770
      P1=QQ(1)                                                          P-N19780
      P2=QQ(2)                                                          P-N19790
      P3=QQ(3)                                                          P-N19800
      POUT11=-XP1                                                       P-N19810
      POUT12=-XP2                                                       P-N19820
      POUT13=-XP3                                                       P-N19830
      EOUT1=E3                                                          P-N19840
      GO TO 153                                                         P-N19850
  149 POUT11=QQ(1)                                                      P-N19860
      POUT12=QQ(2)                                                      P-N19870
      POUT13=QQ(3)                                                      P-N19880
      EOUT1=E1                                                          P-N19890
      P1=-XP1                                                           P-N19900
      P2=-XP2                                                           P-N19910
      P3=-XP3                                                           P-N19920
      E1=E3                                                             P-N19930
  153 IF (ISO.EQ.0) GO TO 150                                           P-N19940
      IF (RNDM.GT.0.333333) GO TO 151                                   P-N19950
      IS1=-IS1                                                          P-N19960
      IP=-2*IS1                                                         P-N19970
  151 RETURN                                                            P-N19980
  150 IF (INDEX.EQ.1) RETURN                                            P-N19990
      IF (RNDM.LT.0.5) GO TO 152                                        P-N20000
      IS1=1                                                             P-N20010
      IS2=1                                                             P-N20020
      IP=-2                                                             P-N20030
      RETURN                                                            P-N20040
  152 IS1=-1                                                            P-N20050
      IS2=-1                                                            P-N20060
      IP=2                                                              P-N20070
      RETURN                                                            P-N20080
  160 POUT11=-P1                                                        P-N20090
      POUT12=-P2                                                        P-N20100
      POUT13=-P3                                                        P-N20110
      RETURN                                                            P-N20120

C                                                                       P-N20130
CCC   LONG-LIVED DELTA                                                  P-N20140
C                                                                       P-N20150
  161 IF (INDEX.EQ.1) GO TO 162                                         P-N20160
      P1=XP1                                                            P-N20170
      P2=XP2                                                            P-N20180
      P3=XP3                                                            P-N20190
      eout1=e3
      e1=ecm-eout1
      m1=1

      GO TO 163                                                         P-N20230
  162 P1=-XP1                                                           P-N20240
      P2=-XP2                                                           P-N20250
      P3=-XP3                                                           P-N20260
      EOUT1=E3                                                          P-N20270
      E1=ECM-EOUT1                                                      P-N20280
      M1=1                                                              P-N20290
C%%%  SYMMETRIZATION OF CHARGES IN pn -> N DELTA
C%%%     THE TEST ON "INDEX" ABOVE SYMETRIZES THE EXCITATION OF ONE
C%%%     OF THE NUCLEONS WITH RESPECT TO THE DELTA EXCITATION
C%%%     (SEE NOTE 16/10/97)
C
 163  IF (ISO.EQ.0) THEN
         IF (INDEX2.EQ.1) THEN
            ISI=IS1
            IS1=IS2
            IS2=ISI
         ENDIF
         GO TO 160
      ENDIF
      hel(l1)=ctet**2
      rndm=rn(0)

      IF (RNDM.LT.0.25) GO TO 160                                       P-N20350
      IS1=3*IS1*M1-(1-M1)*IS1                                           P-N20360
      IS2=3*IS2*M2-(1-M2)*IS2                                           P-N20370
      GO TO 160                                                         P-N20380
C                                                                       P-N20390
CCC  RECOMBINATION PROCESS                                              P-N20400
C                                                                       P-N20410
  170 PNORM=PCM(ECM,XM,XM)                                              P-N20420
      rndm=rn(0)

      CTET=-1.+2.*RNDM                                                  P-N20480
      if (abs(ctet).gt.1.) ctet=sign(real(1.,8),ctet)
      STET=SQRT(1.-CTET*CTET)                                           P-N20490
      rndm=rn(0)

      FI=6.2832*RNDM                                                    P-N20550
      CFI=COS(FI)                                                       P-N20560
      SFI=SIN(FI)                                                       P-N20570
      P1=PNORM*STET*CFI                                                 P-N20580
      P2=PNORM*STET*SFI                                                 P-N20590
      P3=PNORM*CTET                                                     P-N20600
      M1=0                                                              P-N20610
      M2=0                                                              P-N20620
      E1=SQRT(P1*P1+P2*P2+P3*P3+XM*XM)                                  P-N20630
      EOUT1=ECM-E1                                                      P-N20640
      IF (ISO.EQ.0) GO TO 160                                           P-N20650
      IS1=ISO/2                                                         P-N20660
      IS2=ISO/2                                                         P-N20670
      GO TO 160                                                         P-N20680
      END SUBROUTINE COLLIS                                             P-N20690

C DECAY2
      SUBROUTINE DECAY2(P1,P2,P3,WP,ij,
     s       X1,X2,hel,B1,B2,B3)
      implicit real*8(A-H,O-Z)
C
CCC   THIS ROUTINE DESCRIBES THE ANISOTROPIC DECAY OF A PARTICLE OF MASS
CCC     XI INTO 2 PARTICLES OF MASSES X1,X2
CCC   THE ANISOTROPY IS SUPPOSED TO FOLLOW A 1+3*hel*(cos(theta))**2
CCC   LAW WITH RESPECT TO THE DIRECTION OF THE INCOMING PARTICLE
CCC   IN THE INPUT, P1,P2,P3 IS THE MOMENTUM OF PARTICLE XI             P-N20750
CCC   IN THE OUTPUT, P1,P2,P3 IS THE MOMENTUM OF PARTICLE X1 , WHILE    P-N20760
CCC     Q1,Q2,Q3 IS THE MOMENTUM OF PARTICLE X2                         P-N20770
C                                                                       P-N20780
      COMMON/bl12/QQ1(200),QQ2(200),QQ3(200),QQ4(200),
     s            YY1(200),YY2(200),YY3(200),YM(200),IPI(200)
!$OMP THREADPRIVATE(/bl12/)

      PCM(E,A,C)=0.5*SQRT((E**2-(A+C)**2)*(E**2-(A-C)**2))/E            P-N20800
      XI=YM(ij)

      XE=WP                                                             P-N20810
      B1=P1/XE                                                          P-N20820
      B2=P2/XE                                                          P-N20830
      B3=P3/XE
      XQ=PCM(XI,X1,X2)
  100 rndm=rn(0)
      CTET=-1.+2.*RNDM                                                  P-N20910
      if(abs(ctet).gt.1.)ctet=sign(real(1.,8),ctet)
      STET=SQRT(1.-CTET**2)                                             P-N20920
      rndm=rn(0)
      if (rndm.gt.((1.+3.*hel*ctet**2)/(1.+3.*hel))) go to 100
      rndm=rn(0)
      FI=6.2832*RNDM                                                    P-N20980
      CFI=COS(FI)                                                       P-N20990
      SFI=SIN(FI)
      beta=sqrt(b1*b1+b2*b2+b3*b3)
      if (beta.lt.1.0e-10) go to 101
      sal=sqrt(b1**2+b2**2)/beta
      cal=b3/beta
      if (sal.lt.1.0e-6) go to 101
      t1=ctet+cal*stet*sfi/sal
      t2=stet/sal
      q1=xq*(b1*t1+b2*t2*cfi)/beta
      q2=xq*(b2*t1-b1*t2*cfi)/beta
      q3=xq*(b3*t1/beta-t2*sfi)
      go to 102
  101 Q1=XQ*STET*CFI
      Q2=XQ*STET*SFI
      Q3=XQ*CTET
  102 hel=0.
      W1=Q1*Q1+Q2*Q2+Q3*Q3                                              P-N21040
      WQ=SQRT(W1+X2*X2)                                                 P-N21050
      P1=-Q1                                                            P-N21060
      P2=-Q2                                                            P-N21070
      P3=-Q3                                                            P-N21080
      WP=SQRT(W1+X1*X1)                                                 P-N21090
      CALL LOREN(Q1,Q2,Q3,B1,B2,B3,WQ)                                  P-N21100
      CALL LOREN(P1,P2,P3,B1,B2,B3,WP)                                  P-N21110
      QQ1(ij)=Q1
      QQ2(ij)=Q2
      QQ3(ij)=Q3
      QQ4(ij)=WQ
      YM(ij)=XI

      RETURN                                                            P-N21120
      END SUBROUTINE DECAY2                                             P-N21130

C-------------------------------------------------------------------------------
      FUNCTION FNSCALE(E,M,I)
      implicit real*8(A-H,O-Z)
C    NN effectif introduced (if LNNEF=1) with 2 parameters S1NN,S2NN (3/2007)AB
C    Free NN for the first accepted interaction (with sqrt(S)>CUTNN)
C         I=2,0,-2  FOR PP,PN,NN                                        P-N21170

      COMMON/OPTI/CUTNN,ALPH,TFM,TFN,TFP,TFPP,
     s  PFM,PFN,PFP,PFPP,V0M,V0N,V0P,V0PP,S1NN,S2NN,V2P,V2N,LBLNN,LNNEF
!$OMP THREADPRIVATE(/OPTI/)
      COMMON/COL/R_N1,R_N2,NCOL_2C
!$OMP THREADPRIVATE(/COL/)
      COMMON/WS/R0,ADIF,RMAXWS,DRWS,BMAX,XFOISA,RLIM(500),
     &          NPAULSTR,NOSURF
!$OMP THREADPRIVATE(/WS/)

C Effective NN interaction: soft cut S1NN (0), S2NN (1)
      IF(M.EQ.0)THEN
         IF(E.LE.S1NN) THEN
            FNSCALE=0.
         ELSEIF(E.LE.S2NN) THEN
            FNSCALE=(E-S1NN)/(S2NN-S1NN)
         ELSE
            FNSCALE=1.
         ENDIF
      ELSE
C No change if not NN  (Delta involved, no change of interaction)
         FNSCALE = 1.
         RETURN
      ENDIF

c....Or Free for the first collision
      IF((LNNEF.EQ.2).AND.(NCOL_2C.EQ.0))  THEN
         FNSCALE = 1.
         RETURN
      ENDIF
c....Free in light density
      IF((LNNEF.EQ.3).AND.((R_N1.GE.(R0))
     s     .OR.(R_N2.GE.(R0))))  THEN
         FNSCALE = 1.
         RETURN
      ENDIF
c....Free for first collision OR density criteria
      IF (LNNEF.EQ.4) THEN
         IF(NCOL_2C.EQ.0)  FNSCALE = 1.
         IF((R_N1+R_N2).GE.2.*(R0-ADIF))  FNSCALE = 1.
         RETURN
      ENDIF
C....Li-Machleidt density dependence NN modification:
      IF(LNNEF.EQ.5) THEN
         D = 0.18/(1.+EXP((R_N1+R_N2-2.*R0)/(2.*ADIF)))
         T = (E*E - 3521474.4)/1876.56
         IF(T.LE.300.) THEN
            IF(I.EQ.0) THEN
               FNSCALE = (1.+0.0034*T**1.51*D**2)/(1.+21.55*D**1.34)
            ELSE
               FNSCALE = (1.+0.1667*T**1.05*D**3)/(1.+9.704*D**1.2)
            ENDIF
         ELSE
            FNSCALE = 1.
         ENDIF
      ENDIF

      RETURN

      END FUNCTION FNSCALE

C SEL                                                                   P-N21140
      FUNCTION SEL(E,M,I)                                               P-N21150
      implicit real*8(A-H,O-Z)
C         FIT BY J.VANDERMEULEN                                         P-N21160
C         LOW ENRGY FIT OF J.C., D. L'HOTE, J. VDM, NIM B111(1996)215
C         I=2,0,-2  FOR PP,PN,NN                                        P-N21170
C         M=0,1,2 FOR NUCLEON-NUCLEON,NUCLEON-DELTA,DELTA,DELTA         P-N21180
C
C    NN effectif introduced (if LNNEF=1) with 2 parameters S1NN,S2NN (3/2007)AB
      COMMON/OPTI/CUTNN,ALPH,TFM,TFN,TFP,TFPP,
     s  PFM,PFN,PFP,PFPP,V0M,V0N,V0P,V0PP,S1NN,S2NN,V2P,V2N,LBLNN,LNNEF
!$OMP THREADPRIVATE(/OPTI/)

      IF(LNNEF.EQ.0) THEN
C Here free NN (governed by CUTNN):
         SCALE=1.
      ELSE
C Here effective NN (governed by CUTNN AND criteria in FNSCALE())
         SCALE=FNSCALE(E,M,I)
      ENDIF

      PLAB=E*SQRT(E*E-4.*(938.2796)**2)/(2.*938.2796)                   P-N21210
      P1=0.001*PLAB                                                     P-N21220
      IF(PLAB.GT.2000.) GO TO 13                                        P-N21230
      IF (M-1) 1,3,3                                                    P-N21240
    1 IF (I.EQ.0) GO TO 2                                               P-N21250
    3 IF (PLAB.LT.800.) GO TO 4                                         P-N21260
      IF (PLAB.GT.2000.) GO TO 13                                       P-N21270
      SEL=(1250./(50.+P1)-4.*(P1-1.3)**2)*SCALE                         P-N21280
      GO TO 100
      RETURN

    4 IF (PLAB.LT.440.) THEN                                            P-N21290
         SEL=34.*(P1/0.4)**(-2.104)*SCALE
      ELSE
         SEL=(23.5+1000.*(P1-0.7)**4)*SCALE                               P-N21300
      ENDIF
      GO TO 100
      RETURN                                                            P-N21310

   13 SEL=77./(P1+1.5)*SCALE                                            P-N21320
      GO TO 100
      RETURN                                                            P-N21330

    2 IF (PLAB.LT.800.) GO TO 11                                        P-N21340
      IF (PLAB.GT.2000.) GO TO 13                                       P-N21350
      SEL=31./SQRT(P1)*SCALE                                            P-N21360
      GO TO 100
      RETURN                                                            P-N21370

   11 IF (PLAB.LT.450.) THEN
         ALP=LOG(P1)
         SEL=6.3555*EXP(-3.2481*ALP-0.377*ALP*ALP)*SCALE
      ELSE
         SEL=(33.+196.*SQRT(ABS(P1-0.95)**5))*SCALE                       P-N21380
      ENDIF

100   CONTINUE

      RETURN                                                            P-N21390

      END FUNCTION SEL                                                  P-N21400

C STOT                                                                  P-N21410
      FUNCTION STOT(E,M,I)                                              P-N21420
      implicit real*8(A-H,O-Z)
C        TOTAL CROSS-SECTIONS                                           P-N21430
C         I=2,0,-2  FOR PP,PN,NN                                        P-N21440
C         M=0,1,2 FOR NUCLEON-NUCLEON,NUCLEON-DELTA,DELTA,DELTA         P-N21450
C                                                                       P-N21460
      COMMON/BL6/XX10,ISA                                               P-N21470
!$OMP THREADPRIVATE(/BL6/)
      IF (M-1) 1,2,3                                                    P-N21480
    1 SINE=SPRO(E,I)                                                    P-N21490
      GO TO 4                                                           P-N21500
    2 SINE=SREC(E,XX10,I,ISA)                                           P-N21510
      GO TO 4                                                           P-N21520
    3 SINE=0.                                                           P-N21530
    4 STOT=SINE+SEL(E,M,I)                                              P-N21540
      RETURN                                                            P-N21550
      END FUNCTION STOT                                                 P-N21560
C SREC                                                                  P-N21570
      FUNCTION SREC(E,D,I,ISA)                                          P-N21580
      implicit real*8(A-H,O-Z)
      common/kind_jcd/kindf7
!$OMP THREADPRIVATE(/kind_jcd/)
      ein=e
      IF (I*I.EQ.16) GO TO 2                                            P-N21590
      IF(E.GT.938.3+D) GO TO 1                                          P-N21600
    2 SREC=0.                                                           P-N21610
      RETURN                                                            P-N21620
    1 IF(E.LT.938.3+D+2.) E=938.3+D+2.                                  P-N21630
      S=E*E                                                             P-N21640
      X=(S-4.*(938.2796)**2)/(S-(938.3+D)**2)                                    P-N21650
      Y=S/(S-(D-938.3)**2)                                              P-N21660
      SREC=0.5*X*Y*SPRO(E,I)                                            P-N21670
      SREC=SREC*(32.+I*I*(ISA*ISA-5))/64.                               P-N21680
      SREC=SREC/(1.+0.25*I*I)                                           P-N21690
c++  modification for pion-induced cascade (see JC and MC LEMAIRE,NPA489(88)781
      srec=3.*srec  !pi absorption increased also for internal pions (7/3/01)
      e=ein
      RETURN                                                            P-N21700
      END FUNCTION SREC                                                 P-N21710
C SPRO                                                                  P-N21720
      FUNCTION SPRO(E,I)                                                P-N21730
C         DELTA PRODUCTION CROSS-SECTIONS                               P-N21740
C         FIT BY J.VANDERMEULEN                                         P-N21750
C         I=2,0,-2  FOR PP,PN,NN                                        P-N21760
C                                                                       P-N21770
      implicit real*8(A-H,O-Z)
      COMMON/BL8/RATHR,RAMASS
!$OMP THREADPRIVATE(/BL8/)
      SCALI=1.                                                          P-N21780
      EE=E-RATHR                                                        P-N21790
      IF (EE*EE-3.53E6.LT.0.) GO TO 22                                  P-N21800
      PLAB=EE*SQRT(EE*EE-4.*(938.2796)**2)/(2.*938.2796)                   P-N21210
      P1=0.001*PLAB                                                     P-N21820
      IF (PLAB.GT.800.) GO TO 1                                         P-N21830
   22 SPRO=0.                                                           P-N21840
      RETURN                                                            P-N21850
    1 IF (I*I.EQ.4) GO TO 10                                            P-N21860
      IF (PLAB.LT.2000.) GO TO 2                                        P-N21870
      SPRO=(42.-77./(P1+1.5))*SCALI                                     P-N21880
      RETURN                                                            P-N21890
    2 IF (PLAB.LT.1000.) GO TO 3                                        P-N21900
      SPRO=(24.2+8.9*P1-31.1/SQRT(P1))*SCALI                            P-N21910
      RETURN                                                            P-N21920
    3 SPRO=(33.+196.*SQRT(ABS(P1-0.95)**5)-31.1/SQRT(P1))*SCALI         P-N21930
      RETURN                                                            P-N21940
   10 IF (PLAB.LT.2000.) GO TO 11                                       P-N21950
      SPRO=(41.+(60.*P1-54.)*EXP(-1.2*P1)-77./(P1+1.5))*SCALI           P-N21960
      RETURN                                                            P-N21970
   11 IF (PLAB.LT.1500.) GO TO 12                                       P-N21980
      SPRO=41.+60.*(P1-0.9)*EXP(-1.2*P1)-1250./(P1+50.)+4.*(P1-1.3)**2  P-N21990
      SPRO=SPRO*SCALI                                                   P-N22000
      RETURN                                                            P-N22010
   12 SPRO=23.5+24.6/(1.+EXP(-10.*P1+12.))-1250./(P1+50.)+4.*(P1-1.3)**2P-N22020
      SPRO=SPRO*SCALI                                                   P-N22030
      RETURN                                                            P-N22040
      END FUNCTION SPRO                                                 P-N22050
C SPN                                                                   P-N22060
      FUNCTION SPN(X,IND2T3,IPIT3,f17)   ! ***** ThA                    P-N22070
C                                                                       P-N22080
C      SIGMA(PI+ + P) IN THE (3,3) REGION                               P-N22090
C       NEW FIT BY J.VANDERMEULEN  + FIT BY Th AOUST ABOVE (3,3) RES    P-N22100
C                                     CONST AT LOW AND VERY HIGH ENERGY P-N22110
C                                                                       P-N22120
      implicit real*8(A-H,O-Z)
      COMMON/BL8/RATHR,RAMASS                                           REL21800
!$OMP THREADPRIVATE(/BL8/)
      integer f17
      Y=X*X                                                             P-N22130
      Q2=(Y-1076.**2)*(Y-800.**2)/Y/4.                                  P-N22140
      IF (Q2.GT.0.) GO TO 1                                             P-N22150
      SPN=0.                                                            P-N22160
      RETURN                                                            P-N22170
    1 Q3=(SQRT(Q2))**3                                                  P-N22180
      F3=Q3/(Q3+180.0**3)                                               P-N22190
      SPN=326.5/(((X-1215.-RAMASS)*2./(110.-RAMASS))**2+1.)   ! ***** ThA
      SPN=SPN*(1.-5.*RAMASS/1215.)
      CG=4.0+REAL(IND2T3,8)*REAL(IPIT3,8)      ! ***** ThA
      if(f17.ne.1)SPN=SPN*F3*CG/6.0                    ! ***** ThA
      if(f17.eq.1)SPN=SPN*F3

      if(f17.ne.1)then
      IF(X.LT.1200.AND.SPN.LT.5.0) THEN ! ***** ThA
        SPN=5.0                            ! ***** ThA
      ENDIF                                ! ***** ThA
      endif
c     HE pi+ p and pi- n
c
      if(f17.ne.1)then
      IF(X.GT.1290) THEN
         IF(IND2T3.EQ.1.AND.IPIT3.EQ.2.OR.IND2T3.EQ.-1.AND.IPIT3.EQ.-2)
     c        SPN=SPNPIPPHE(X)
         IF(IND2T3.EQ.1.AND.IPIT3.EQ.-2.OR.IND2T3.EQ.-1.AND.IPIT3.EQ.2)
     c        SPN=SPNPIMPHE(X)
         IF(IPIT3.EQ.0) SPN=(SPNPIPPHE(X)+SPNPIMPHE(X))/2.0
      ENDIF
      endif

      RETURN
      END FUNCTION SPN
c
c     HE and LE pi- p and pi+ n
c
      FUNCTION SPNPIPPHE(X)
      implicit real*8(A-H,O-Z)
      IF(X.LE.1750) THEN
         SPNPIPPHE=-2.33730E-06*X**3+1.13819E-02*X**2-1.83993E+01*X+
     c 9893.4
         RETURN
        ENDIF
        IF(X.GT.1750.AND.X.LE.2175) THEN
         SPNPIPPHE=1.13531E-06*X**3-6.91694E-03*X**2+1.39907E+01*X-
     c 9360.76
         RETURN
        ENDIF
        IF(X.GT.2175) THEN
         SPNPIPPHE=-3.18087*LOG(X)+52.9784
         RETURN
        ENDIF
      END FUNCTION SPNPIPPHE
c
c     HE pi- p and pi+ n
c
      FUNCTION SPNPIMPHE(X)
      implicit real*8(A-H,O-Z)
        IF(X.LE.1475) THEN
         SPNPIMPHE=0.00120683*(X-1372.52)*(X-1372.52)+26.2058
         RETURN
        ENDIF
        IF(X.GT.1475.AND.X.LE.1565) THEN
         SPNPIMPHE=1.15873E-05*X*X+49965.6/((X-1519.59)*(X-1519.59)+
     c 2372.55)
         RETURN
        ENDIF
        IF(X.GT.1565.AND.X.LE.2400) THEN
         SPNPIMPHE=34.0248+43262.2/((X-1681.65)*(X-1681.65)+1689.35)
         RETURN
        ENDIF
        IF(X.GT.2400.AND.X.LE.7500) THEN
         SPNPIMPHE=3.3E-7*(X-7500.0)*(X-7500.0)+24.5
         RETURN
        ENDIF
        IF(X.GT.7500) THEN
         SPNPIMPHE=24.5
         RETURN
        ENDIF
       END FUNCTION SPNPIMPHE

C TIME
      SUBROUTINE TIME_b (I,J)                                           P-N22240
      implicit real*8(A-H,O-Z)
      DIMENSION T(10)                                                   P-N22250
      COMMON/BL1/P1(350),P2(350),P3(350),EPS(350),IND1(350),IND2(350),TA
     -,V(350)                                                           P-N22260
!$OMP THREADPRIVATE(/BL1/)
      COMMON/BL3/R1,R2,X1(350),X2(350),X3(350),IA1,IA2,RAB2             P-N22270
!$OMP THREADPRIVATE(/BL3/)
      COMMON/GLOB_PROJ/EPROJ,P1PROJ,P2PROJ,P3PROJ,
     s IFL_BOUND_PROJ,IBOUND_NUC(4)
!$OMP THREADPRIVATE(/GLOB_PROJ/)

      IF(IFL_BOUND_PROJ.EQ.0) THEN
         T(1)=P1(I)/EPS(I)-P1(J)/EPS(J)
         T(2)=P2(I)/EPS(I)-P2(J)/EPS(J)
         T(3)=P3(I)/EPS(I)-P3(J)/EPS(J)
      ELSE
         IF(I.GT.IA1) THEN
            P1I=P1(I)
            P2I=P2(I)
            P3I=P3(I)
            EPSI=EPS(I)
         ELSE
            IF(IBOUND_NUC(I).EQ.0) THEN
               P1I=P1(I)
               P2I=P2(I)
               P3I=P3(I)
               EPSI=EPS(I)
            ELSE
               P1I=P1PROJ
               P2I=P2PROJ
               P3I=P3PROJ
               EPSI=EPROJ
            ENDIF
         ENDIF
         IF(J.GT.IA1) THEN
            P1J=P1(J)
            P2J=P2(J)
            P3J=P3(J)
            EPSJ=EPS(J)
         ELSE
            IF(IBOUND_NUC(J).EQ.0) THEN
               P1J=P1(J)
               P2J=P2(J)
               P3J=P3(J)
               EPSJ=EPS(J)
            ELSE
               P1J=P1PROJ
               P2J=P2PROJ
               P3J=P3PROJ
               EPSJ=EPROJ
            ENDIF
         ENDIF
         T(1)=P1I/EPSI-P1J/EPSJ
         T(2)=P2I/EPSI-P2J/EPSJ
         T(3)=P3I/EPSI-P3J/EPSJ
      ENDIF
      T(4)=X1(I)-X1(J)                                                  P-N22310
      T(5)=X2(I)-X2(J)                                                  P-N22320
      T(6)=X3(I)-X3(J)                                                  P-N22330
      T(7)=T(1)*T(4)+T(2)*T(5)+T(3)*T(6)                                P-N22340
      T(10)=T(1)*T(1)+T(2)*T(2)+T(3)*T(3)                               P-N22350
      IF(T(10).LE.1.e-10) THEN
         TA=100000
      ELSE
         TA=-T(7)/T(10)                                                 P-N22360
      ENDIF
      RAB2=T(4)*T(4)+T(5)*T(5)+T(6)*T(6)+TA*T(7)                        P-N22370
      RETURN                                                            P-N22380

      END SUBROUTINE TIME_b                                             P-N22390

C NEWT                                                                  P-N22400
      SUBROUTINE NEWT(L1,L2,LOCE,IBERT,ibw)                             P-N22410
      implicit real*8(A-H,O-Z)
      DIMENSION IND(20000),JND(20000)                                   P-N22420
      COMMON/BL1/P1(350),P2(350),P3(350),EPS(350),IND1(350),IND2(350),TA
     -,V(350)                                                           P-N22430
!$OMP THREADPRIVATE(/BL1/)
      COMMON/BL2/CROIS(19900),K,IND,JND                                 P-N22440
!$OMP THREADPRIVATE(/BL2/)
      COMMON/BL3/R1,R2,X1(350),X2(350),X3(350),IA1,IA2,RAB2             P-N22450
!$OMP THREADPRIVATE(/BL3/)
      COMMON/BL4/TMAX5                                                  P-N22460
!$OMP THREADPRIVATE(/BL4/)
      COMMON/BL5/TLG(350),NESC(350)                                     P-N22470
!$OMP THREADPRIVATE(/BL5/)
      COMMON/BL6/XX10,ISA                                               P-N22480
!$OMP THREADPRIVATE(/BL6/)
      COMMON/OPTI/CUTNN,ALPH,TFM,TFN,TFP,TFPP,
     s  PFM,PFN,PFP,PFPP,V0M,V0N,V0P,V0PP,S1NN,S2NN,V2P,V2N,LBLNN,LNNEF
!$OMP THREADPRIVATE(/OPTI/)
      COMMON/CTE/HC,FMP,FMPI
      COMMON/CSE/SN,SP
!$OMP THREADPRIVATE(/CSE/)
      COMMON/COL/R_N1,R_N2,NCOL_2C
!$OMP THREADPRIVATE(/COL/)

      AM(A,B,C,D)=SQRT(D*D-A*A-B*B-C*C)                                 P-N22490
      IA=IA1+IA2                                                        P-N22500
      DO 52 I=1,IA                                                      P-N22510
      IF (NESC(I).NE.0) GO TO 52                                        P-N22520
      IF (I-L2) 53,52,54                                                P-N22530
   53 IG=L2                                                             P-N22540
      ID=I                                                              P-N22550
      KG=L1                                                             P-N22560
      KD=I                                                              P-N22570
      GO TO 55                                                          P-N22580
   54 IF (I-L1) 56,52,57                                                P-N22590
   56 KG=L1                                                             P-N22600
      KD=I                                                              P-N22610
      GO TO 58                                                          P-N22620
   57 KG=I                                                              P-N22630
      KD=L1                                                             P-N22640
   58 IG=I                                                              P-N22650
      ID=L2                                                             P-N22660
   55 CALL TIME_b(IG,ID)                                                P-N22670
      IF (TA.LT.0.) GO TO 50                                            P-N22680
      IF(TA.GT.TMAX5) GO TO 50                                          P-N22690
      IF (TA.LT.TLG(L2)) GO TO 50                                       P-N22700
      IF(LBLNN.NE.0) THEN
        IF(IND2(IG).EQ.-1) THEN
            ELIM1=V(IG)-SN+FMP
      ELSE
            ELIM1=V(IG)-SP+FMP
      ENDIF
        IF(IND2(ID).EQ.-1) THEN
            ELIM2=V(ID)-SN+FMP
      ELSE
            ELIM2=V(ID)-SP+FMP
      ENDIF
        IF((EPS(IG).LT.ELIM1).AND.(EPS(ID).LT.ELIM2)) GO TO 50
      ENDIF
      IF(LOCE.NE.0) THEN
          CALL EIJLOC(IG,ID,E)
      ELSE
      E=AM(P1(IG)+P1(ID),P2(IG)+P2(ID),P3(IG)+P3(ID),EPS(IG)+EPS(ID))   P-N22720
      ENDIF
      IF (E.LT.CUTNN) GO TO 50                                          P-N22730
      IY=IND1(IG)+IND1(ID)                                              P-N22740
      R_N1=SQRT(X1(IG)**2+X2(IG)**2+X3(IG)**2)
      R_N2=SQRT(X1(ID)**2+X2(ID)**2+X3(ID)**2)
      IF (IY.NE.1) GO TO 61                                             P-N22750
      IX=IG*IND1(IG)+ID*IND1(ID)                                        P-N22760
      XX10=AM(P1(IX),P2(IX),P3(IX),EPS(IX))                             P-N22770
      ISA=IND2(IX)                                                      P-N22780
   61 IF (31.4159265358979*
     & RAB2.GT.STOT(E,IY,IND2(IG)+IND2(ID)))GO TO 50                    P-N22790
   60 CONTINUE                                                          P-N22800
      K=K+1                                                             P-N22810
      CROIS(K)=TA                                                       P-N22820
      IND(K)=IG                                                         P-N22830
      JND(K)=ID                                                         P-N22840
   50 CALL TIME_b (KG,KD)                                               P-N22850
      IF (TA.LT.0.) GO TO 52                                            P-N22860
      IF(TA.GT.TMAX5) GO TO 52                                          P-N22870
      IF (TA.LT.TLG(L1)) GO TO 52                                       P-N22880
      IF(LBLNN.NE.0) THEN
        IF(IND2(KG).EQ.-1) THEN
            ELIM1=V(KG)-SN+FMP
      ELSE
            ELIM1=V(KG)-SP+FMP
      ENDIF
        IF(IND2(KD).EQ.-1) THEN
            ELIM2=V(KD)-SN+FMP
      ELSE
            ELIM2=V(KD)-SP+FMP
      ENDIF
        IF((EPS(KG).LT.ELIM1).AND.(EPS(KD).LT.ELIM2)) GO TO 52
      ENDIF
      IF(LOCE.NE.0) THEN
          CALL EIJLOC(KG,KD,E)
      ELSE
      E=AM(P1(KG)+P1(KD),P2(KG)+P2(KD),P3(KG)+P3(KD),EPS(KG)+EPS(KD))   P-N22900
      ENDIF
      IF (E.LT.CUTNN) GO TO 52                                          P-N22910
      IY=IND1(KG)+IND1(KD)                                              P-N22920
      R_N1=SQRT(X1(KG)**2+X2(KG)**2+X3(KG)**2)
      R_N2=SQRT(X1(KD)**2+X2(KD)**2+X3(KD)**2)
      IF (IY.NE.1) GO TO 63                                             P-N22930
      IX=KG*IND1(KG)+KD*IND1(KD)                                        P-N22940
      XX10=AM(P1(IX),P2(IX),P3(IX),EPS(IX))                             P-N22950
      ISA=IND2(IX)                                                      P-N22960
   63 IF(31.4159265358979*RAB2.GT.
     & STOT(E,IY,IND2(KG)+IND2(KD))) GO TO 52                           P-N22970
   62 CONTINUE                                                          P-N22980
      K=K+1                                                             P-N22990
      CROIS(K)=TA                                                       P-N23000
      IND(K)=KG                                                         P-N23010
      JND(K)=KD                                                         P-N23020
   52 CONTINUE                                                          P-N23030
      RETURN                                                            P-N23040
      END SUBROUTINE NEWT                                               P-N23050

C   NEW1                                                                P-N23060
      SUBROUTINE NEW1(L1,LOCE)                                          P-N23070
      implicit real*8(A-H,O-Z)
      DIMENSION IND(20000),JND(20000)                                   P-N23080
      COMMON/BL1/P1(350),P2(350),P3(350),EPS(350),IND1(350),IND2(350),TA
     -,V(350)                                                           P-N23090
!$OMP THREADPRIVATE(/BL1/)
      COMMON/BL2/CROIS(19900),K,IND,JND                                 P-N23100
!$OMP THREADPRIVATE(/BL2/)
      COMMON/BL3/R1,R2,X1(350),X2(350),X3(350),IA1,IA2,RAB2             P-N23110
!$OMP THREADPRIVATE(/BL3/)
      COMMON/BL4/TMAX5                                                  P-N23120
!$OMP THREADPRIVATE(/BL4/)
      COMMON/BL5/TLG(350),NESC(350)                                     P-N23130
!$OMP THREADPRIVATE(/BL5/)
      COMMON/BL6/XX10,ISA                                               P-N23140
!$OMP THREADPRIVATE(/BL6/)
      COMMON/OPTI/CUTNN,ALPH,TFM,TFN,TFP,TFPP,
     s  PFM,PFN,PFP,PFPP,V0M,V0N,V0P,V0PP,S1NN,S2NN,V2P,V2N,LBLNN,LNNEF
!$OMP THREADPRIVATE(/OPTI/)
      COMMON/CTE/HC,FMP,FMPI
      COMMON/CSE/SN,SP
!$OMP THREADPRIVATE(/CSE/)
      COMMON/COL/R_N1,R_N2,NCOL_2C
!$OMP THREADPRIVATE(/COL/)

      AM(A,B,C,D)=SQRT(D*D-A*A-B*B-C*C)                                 P-N23150
      IA=IA1+IA2                                                        P-N23160

      DO 52 I=1,IA                                                      P-N23170
      IF (NESC(I).NE.0) GO TO 52                                        P-N23180
      IF(I-L1) 53,52,54                                                 P-N23190
   53 CALL TIME_b(I,L1)                                                 P-N23200
      IF(TA.LT.0.) GO TO 52                                             P-N23210
      IF(TA.GT.TMAX5) GO TO 52                                          P-N23220
      IF(LBLNN.NE.0) THEN
         IF(IND2(I).EQ.-1) THEN
            ELIM1=V(I)-SN+FMP
         ELSE
            ELIM1=V(I)-SP+FMP
         ENDIF
         IF(IND2(L1).EQ.-1) THEN
            ELIM2=V(L1)-SN+FMP
         ELSE
            ELIM2=V(L1)-SP+FMP
         ENDIF
         IF((EPS(I).LT.ELIM1).AND.(EPS(L1).LT.ELIM2)) GO TO 52
      ENDIF
      IF(LOCE.NE.0) THEN
         CALL EIJLOC(I,L1,E)
      ELSE
         E=AM(P1(I)+P1(L1),P2(I)+P2(L1),P3(I)+P3(L1),EPS(I)+EPS(L1))       P-N23240
      ENDIF
      IF (E.LT.CUTNN) GO TO 52                                          P-N23250
      IY=IND1(I)+IND1(L1)                                               P-N23260
      R_N1=SQRT(X1(L1)**2+X2(L1)**2+X3(L1)**2)
      R_N2=SQRT(X1(I)**2+X2(I)**2+X3(I)**2)
      IF (IY.NE.1) GO TO 61                                             P-N23270
      IX=I*IND1(I)+L1*IND1(L1)                                          P-N23280
      XX10=AM(P1(IX),P2(IX),P3(IX),EPS(IX))                             P-N23290
      ISA=IND2(IX)                                                      P-N23300
 61   IF(31.4159265358979*RAB2.GT.
     &     STOT(E,IY,IND2(I)+IND2(L1))) GO TO 52                            P-N23310
 60   CONTINUE                                                          P-N23320
      K=K+1                                                             P-N23330
      CROIS(K)=TA                                                       P-N23340
      IND(K)=L1                                                         P-N23350
      JND(K)=I                                                          P-N23360
      GO TO 52                                                          P-N23370
 54   CALL TIME_b(I,L1)                                                 P-N23380
      IF(TA.LT.0.) GO TO 52                                             P-N23390
      IF(TA.GT.TMAX5) GO TO 52                                          P-N23400
      IF(LBLNN.NE.0) THEN
         IF(IND2(I).EQ.-1) THEN
            ELIM1=V(I)-SN+FMP
         ELSE
            ELIM1=V(I)-SP+FMP
         ENDIF
         IF(IND2(L1).EQ.-1) THEN
            ELIM2=V(L1)-SN+FMP
         ELSE
            ELIM2=V(L1)-SP+FMP
         ENDIF
         IF((EPS(I).LT.ELIM1).AND.(EPS(L1).LT.ELIM2)) GO TO 52
      ENDIF
      IF(LOCE.NE.0) THEN
         CALL EIJLOC(I,L1,E)
      ELSE
         E=AM(P1(I)+P1(L1),P2(I)+P2(L1),P3(I)+P3(L1),EPS(I)+EPS(L1))       P-N23420
      ENDIF
      IF (E.LT.CUTNN) GO TO 52                                          P-N23430
      IY=IND1(I)+IND1(L1)                                               P-N23440
      R_N1=SQRT(X1(L1)**2+X2(L1)**2+X3(L1)**2)
      R_N2=SQRT(X1(I)**2+X2(I)**2+X3(I)**2)
      IF (IY.NE.1) GO TO 71                                             P-N23450
      IX=I*IND1(I)+L1*IND1(L1)                                          P-N23460
      XX10=AM(P1(IX),P2(IX),P3(IX),EPS(IX))                             P-N23470
      ISA=IND2(IX)                                                      P-N23480
 71   IF (31.4159265358979*RAB2.GT.
     &     STOT(E,IY,IND2(I)+IND2(L1))) GO TO 52                            P-N23490
 70   CONTINUE                                                          P-N23500
      K=K+1                                                             P-N23510
      CROIS(K)=TA                                                       P-N23520
      IND(K)=I                                                          P-N23530
      JND(K)=L1                                                         P-N23540
 52   CONTINUE                                                          P-N23550

      RETURN                                                            P-N23560

      END SUBROUTINE NEW1                                               P-N23570

C   NEW2                                                                P-N23580
      SUBROUTINE NEW2(NPION,L1,f17) ! ***** ThA  P-N23590
      implicit real*8(A-H,O-Z)
      DIMENSION IND(20000),JND(20000)                                   P-N23600
      COMMON/BL1/P1(350),P2(350),P3(350),EPS(350),IND1(350),IND2(350),TA
     -,V(350)                                                           P-N23610
!$OMP THREADPRIVATE(/BL1/)
      COMMON/BL2/CROIS(19900),K,IND,JND                                 P-N23620
!$OMP THREADPRIVATE(/BL2/)
      COMMON/BL3/R1,R2,X1(350),X2(350),X3(350),IA1,IA2,RAB2             P-N23630
!$OMP THREADPRIVATE(/BL3/)
      COMMON/BL4/TMAX5                                                  P-N23640
!$OMP THREADPRIVATE(/BL4/)
      COMMON/BL5/TLG(350),NESC(350)                                     P-N23650
!$OMP THREADPRIVATE(/BL5/)
      COMMON/bl12/QQ1(200),QQ2(200),QQ3(200),QQ4(200),
     s            YY1(200),YY2(200),YY3(200),YM(200),IPI(200)
!$OMP THREADPRIVATE(/bl12/)
      DIMENSION T(10)                                                   P-N23660
      integer f17

      Y1=YY1(NPION)
      Y2=YY2(NPION)
      Y3=YY3(NPION)
      Q1=QQ1(NPION)
      Q2=QQ2(NPION)
      Q3=QQ3(NPION)
      Q4=QQ4(NPION)
      IPIT3=IPI(NPION)
      IA=IA1+IA2                                                        P-N23670
      DO 52 I=1,IA                                                      P-N23680
         IF (NESC(I).NE.0) GO TO 52                                        P-N23690
         if(f17.ne.1)then
            IF (NESC(NPION+IA).NE.0) GO TO 52 ! ***** ThA test si pion out
         endif
         IF(I.EQ.L1) GO TO 52                                              P-N23700
         IF(IND1(I).EQ.1) GO TO 52                                         P-N23710
         T(1)=P1(I)/EPS(I)-Q1/Q4                                           P-N23720
         T(2)=P2(I)/EPS(I)-Q2/Q4                                           P-N23730
         T(3)=P3(I)/EPS(I)-Q3/Q4                                           P-N23740
         T(4)=X1(I)-Y1                                                     P-N23750
         T(5)=X2(I)-Y2                                                     P-N23760
         T(6)=X3(I)-Y3                                                     P-N23770
         T(7)=T(1)*T(4)+T(2)*T(5)+T(3)*T(6)                                P-N23780
         IF(T(7).GT.0.) GO TO 52                                           P-N23790
         T(10)=T(1)*T(1)+T(2)*T(2)+T(3)*T(3)                               P-N23800
         TA=-T(7)/T(10)                                                    P-N23810
         IF(TA.GT.TMAX5) GO TO 52                                          P-N23820
         XX2=T(4)*T(4)+T(5)*T(5)+T(6)*T(6)+TA*T(7)                         P-N23830
        E=SQRT((EPS(I)+Q4)**2-(P1(I)+Q1)**2-(P2(I)+Q2)**2-(P3(I)+Q3)**2)  P-N23840
c ttttttttttttttttttttttttttha
         IF (31.4159265358979*XX2.GT.
     &       SPN(E,IND2(I),IPIT3,f17)) GO TO 52 ! ***** ThA         P-N23850
         K=K+1                                                             P-N23860
         CROIS(K)=TA                                                       P-N23870
         IND(K)=IA+NPION                                                   P-N23880
         JND(K)=I                                                          P-N23890
 52   CONTINUE                                                          P-N23900

      RETURN                                                            P-N23910

      END SUBROUTINE NEW2                                               P-N23920

C LOREN                                                                 P-N23930
      SUBROUTINE LOREN(Q1,Q2,Q3,B1,B2,B3,E)                             P-N23940
      implicit real*8(A-H,O-Z)
C                                                                       P-N23950
CCC   TRANSFORMS MOMENTUM Q AND ENERGY E FROM A FRAME MOVING WITH       P-N23960
CCC   VELOCITY BETA                                                     P-N23970
C                                                                       P-N23980
      BB2=B1*B1+B2*B2+B3*B3                                             P-N23990
      BQ=B1*Q1+B2*Q2+B3*Q3                                              P-N24000
      GAM2=1./(1.-BB2)                                                  P-N24010
      GAM=SQRT(GAM2)                                                    P-N24020
      C=GAM2/(GAM+1.)                                                   P-N24030
      G=C*BQ+GAM*E                                                      P-N24040
      E=GAM*(E+BQ)                                                      P-N24050
      Q1=Q1+B1*G                                                        P-N24060
      Q2=Q2+B2*G                                                        P-N24070
      Q3=Q3+B3*G                                                        P-N24080
      RETURN                                                            P-N24090
      END SUBROUTINE LOREN                                              P-N24100

C NEW3                                                                  P-N24110
      SUBROUTINE NEW3(NPION,L1,IND2L1,f17) ! ***** ThA  P-N24120
      implicit real*8(A-H,O-Z)
      DIMENSION IND(20000),JND(20000)                                   P-N24130
      COMMON/BL1/P1(350),P2(350),P3(350),EPS(350),IND1(350),IND2(350),TA
     -,V(350)                                                           P-N24140
!$OMP THREADPRIVATE(/BL1/)
      COMMON/BL2/CROIS(19900),K,IND,JND                                 P-N24150
!$OMP THREADPRIVATE(/BL2/)
      COMMON/BL3/R1,R2,X1(350),X2(350),X3(350),IA1,IA2,RAB2             P-N24160
!$OMP THREADPRIVATE(/BL3/)
      COMMON/BL4/TMAX5                                                  P-N24170
!$OMP THREADPRIVATE(/BL4/)
      COMMON/BL5/TLG(350),NESC(350)                                     P-N24180
!$OMP THREADPRIVATE(/BL5/)
      COMMON/bl12/QQ1(200),QQ2(200),QQ3(200),QQ4(200),
     s            YY1(200),YY2(200),YY3(200),YM(200),IPI(200)
!$OMP THREADPRIVATE(/bl12/)
      DIMENSION T(10)                                                   P-N24190
      integer f17
      Y1=YY1(NPION)
      Y2=YY2(NPION)
      Y3=YY3(NPION)
      Q1=QQ1(NPION)
      Q2=QQ2(NPION)
      Q3=QQ3(NPION)
      Q4=QQ4(NPION)
      IPIT3=IPI(NPION)
      IA=IA1+IA2
c  skips collisions with escaped particle 22/3/95
      if(nesc(l1).gt.0)go to 52
      if(f17.ne.1)then
         IF (NESC(NPION+IA).NE.0) GO TO 52 ! ***** ThA test si pion out
      endif
      T(1)=P1(L1)/EPS(L1)-Q1/Q4                                         P-N24200
      T(2)=P2(L1)/EPS(L1)-Q2/Q4                                         P-N24210
      T(3)=P3(L1)/EPS(L1)-Q3/Q4                                         P-N24220
      T(4)=X1(L1)-Y1                                                    P-N24230
      T(5)=X2(L1)-Y2                                                    P-N24240
      T(6)=X3(L1)-Y3                                                    P-N24250
      T(7)=T(1)*T(4)+T(2)*T(5)+T(3)*T(6)                                P-N24260
      IF(T(7).GT.0.) GO TO 52                                           P-N24270
      T(10)=T(1)*T(1)+T(2)*T(2)+T(3)*T(3)                               P-N24280
      TA=-T(7)/T(10)                                                    P-N24290
      IF(TA.GT.TMAX5) GO TO 52                                          P-N24300
      IF (TA.LT.TLG(L1)) GO TO 52                                       P-N24310
      XX2=T(4)*T(4)+T(5)*T(5)+T(6)*T(6)+TA*T(7)                         P-N24320
      E=SQRT((EPS(L1)+Q4)**2-(P1(L1)+Q1)**2-(P2(L1)+Q2)**2-(P3(L1)+Q3)  P-N24330
     -**2)                                                              P-N24340
c ttttttttttttttttttttttttttttttha
      IF (31.4159265358979*XX2.GT.
     &     SPN(E,IND2L1,IPIT3,f17)) GO TO 52 ! ***** ThA        P-N24350
      K=K+1                                                             P-N24360
      CROIS(K)=TA                                                       P-N24370
      IND(K)=IA+NPION                                                   P-N24390
      JND(K)=L1                                                         P-N24400

   52 RETURN                                                            P-N24410

      END SUBROUTINE NEW3                                               P-N24420

C BARR                                                                  P-N24430
      FUNCTION BARR(E,IZ,IA,IZN,R,V0IA,mre,f17)                ! ThA
      implicit real*8(A-H,O-Z)
C
C
C       NOUVEAU BARR RELATIVISTE ATTENTION AUX ENTREES SORTIES!
C     (06/2005)
C
C ATTENTION ICI BARR de version AB different de version TA ...et l'appel est
C probablement version TA!
CCC   BARR=TRANSMISSION PROBABILITY FOR A PARTICLE (Nucleon, cluster or
CCC   pion) of kinetic energy E on the edge of the (attractive) well of
CCC   depth V0 felt by the particle.
CCC         IZ is the isospin of the particle,
CCC         IZN the instantaneous charge of the nucleus and R the radius of
CCC       the well.
CCC         IA is the mass number of the particle, and MRE its mass energy.
C                                                                       P-N24500
C     Modified 9/10/2002 for clusters (d,t,3He,4He) (IZ=isospin,IA=A)
C     IZ must be correct so that charge Q=(IA+IZ)/2.
C     Modified 4/2004 for relativistic expressions and pions.

      REAL*8 MRE,X
      integer f17

      if(f17.eq.1)then

         IF (E.GT.V0IA) GO TO 1
         BARR=0.                                                           P-N24520
         RETURN                                                            P-N24530

    1    X=SQRT((2.*MRE*E+E*E)*(2.*MRE*(E-V0IA)+(E-V0IA)**2))
         BARR=4.*X/(2.*MRE*(2.*E-V0IA)+E**2+(E-V0IA)**2+2.*X)
         IQ=(ABS(IA)+IZ)/2.
         IF(IA.EQ.-1.AND.IZ.EQ.0) IQ=0
         IF (IQ.GT.0.and.iq.lt.izn) GO TO 2
         RETURN                                                            P-N24570

    2   CONTINUE
C Modif AB 27/10/2010
         B=IQ*(IZN-IQ)*1.44/R
         PX=SQRT((E-V0IA)/B)
	
C Test: barriere stricte (sans transmission) pour les charges 17/2011 AB
         IF (PX.LT.1.) GO TO 3                                             P-N24600
         RETURN                                                            P-N24610

    3 G=IQ*(IZN-IQ)/137.03*SQRT(2.*MRE/(E-V0IA)/(1.+(E-V0IA)/2./MRE))
     s*(ACOS(PX)-PX*SQRT(1.-PX*PX))
          IF (G.GT.35.)THEN                                                 P-N24630
          BARR=0.                                                         P-N24640
       ELSE                                                             P-N24650
         BARR=BARR*EXP(-2.*G)                                            P-N24660
      ENDIF                                                             P-N24670
      RETURN                                                            P-N24680
      ELSE


c 12   X=SQRT(E*(E-V0IA))                                                  P-N24540
c 22   B=IZN*1.44/R                                                      P-N24580
c 32   G=IZN/137.03*SQRT(2.*938.3/(E-V0IA))*(ACOS(PX)-PX*SQRT(1.-PX*PX))   P-N24620

      IF (E.GT.V0IA) GO TO 12
      BARR=0.                                                           P-N24520
      RETURN                                                            P-N24530

 12   X=SQRT((2.*MRE*E+E*E)*(2.*MRE*(E-V0IA)+(E-V0IA)**2))
      BARR=4.*X/(2.*MRE*(2.*E-V0IA)+E**2+(E-V0IA)**2+2.*X)
      IQ=(ABS(IA)+IZ)/2.

      IF(IA.EQ.-1.AND.IZ.EQ.0) IQ=0
      IF (IQ.GT.0.and.iq.lt.izn) GO TO 22
      RETURN                                                            P-N24570

 22   CONTINUE
      B=IQ*(IZN-IQ)*1.44/R

C Test: pas de facteur de transmission; barriere stricte:
C Test 17/10/07: fact de transmission ad oc


      PX=SQRT((E-V0IA)/B)

      IF (PX.LT.1.) GO TO 32                                             P-N24600
      RETURN                                                            P-N24610

 32   G=IQ*(IZN-IQ)/137.03*SQRT(2.*MRE/(E-V0IA)/(1.+(E-V0IA)/2./MRE))
     s                             *(ACOS(PX)-PX*SQRT(1.-PX*PX))
      IF (G.GT.35.)THEN                                                 P-N24630
        BARR=0.                                                         P-N24640
       ELSE                                                             P-N24650
        BARR=BARR*EXP(-2.*G)                                            P-N24660
      ENDIF                                                             P-N24670
      RETURN                                                            P-N24680
      ENDIF

      END FUNCTION BARR                                                 P-N24690

C REF                                                                   P-N24700
      FUNCTION REF(X1,X2,X3,P1,P2,P3,E,R2,PF)                           P-N24710
      implicit real*8(A-H,O-Z)
      common/bl10/IZ1,IZ2
!$OMP THREADPRIVATE(/bl10/)
      COMMON/SAXW/ XX(30,500),YY(30,500),SS(30,500),NBPINTER(500),IMAT
!$OMP THREADPRIVATE(/SAXW/)
      COMMON/WS/R0,ADIF,RMAXWS,DRWS,BMAX,XFOISA,RLIM(500),
     &          NPAULSTR,NOSURF
!$OMP THREADPRIVATE(/WS/)

C surface : modif de REF                                                                       P-N24720
CCC   REF=TIME NECESSARY FOR A NUCLEON TO REACH THE SURFACE             P-N24730
C                                                                       P-N24740
      PF2=PF*PF
      T2=P1*P1+P2*P2+P3*P3                                              P-N24760
      p=sqrt(t2)
      r=R2
      IF (NOSURF.LE.0) THEN
C Modif pour W.S.:
         XV=p/pf
         r=FLIN(XV)
         r=r*r
         if (t2.gt.pf2) r=rmaxws**2
      END IF
 21   t4=x1*x1+x2*x2+x3*x3
      if ( abs(t4-r).lt.1d-8*abs(t4) .or. t4.le.r ) then
         go to 11
      else
         go to 2
      end if
 11   continue
      T1=X1*P1+X2*P2+X3*P3                                              P-N24750
      T3=T1/T2                                                          P-N24770
    4 T5=T3*T3+(R-T4)/T2
      if (t5.gt.0) go to 1
      ref=10000.
      return

    1 REF=(-T3+SQRT(T5))*E                                              P-N24830
      return

    2 s=sqrt(r*0.99/t4)
      x1=x1*s
      x2=x2*s
      x3=x3*s
      go to 21

      END FUNCTION REF

C REFPI
      FUNCTION REFPI(ij,R2)
      implicit real*8(A-H,O-Z)
      COMMON/bl12/Q1(200),Q2(200),Q3(200),Q4(200),
     s            Y1(200),Y2(200),Y3(200),YM(200),IPI(200)
!$OMP THREADPRIVATE(/bl12/)
C
CCC   REFPI=TIME NECESSARY FOR A PION TO REACH THE SURFACE
C
      X1=Y1(ij)
      X2=Y2(ij)
      X3=Y3(ij)
      P1=Q1(ij)
      P2=Q2(ij)
      P3=Q3(ij)
      E=Q4(ij)

      T1=X1*P1+X2*P2+X3*P3
      T2=P1*P1+P2*P2+P3*P3
      T3=T1/T2
      T4=X1*X1+X2*X2+X3*X3
      T5=T3*T3+(R2-T4)/T2
      IF (T5.GT.0.) GO TO 1
      REFPI=10000.
      RETURN
    1 REFPI=(-T3+SQRT(T5))*E
      RETURN
      END FUNCTION REFPI
      SUBROUTINE PAULIL(L,XR,PR,F,PFP,LOCE)                              P-N24870
      implicit real*8(A-H,O-Z)
C                                                                       P-N24880
C     THIS SUBROUTINE CALCULATES THE OCCUPATION IN PHASE SPACE AROUND   P-N24890
C         NUCLEON  L  , BY COUNTING THE PARTICLES IN A VOLUME AROUND L  P-N24900
C     THE VOLUME IS THE PRODUCT OF A SPHERE OF RADIUS XR IN R-SPACE BY  P-N24910
C         A SPHERE OF RADIUS PR IN MOMENTUM SPACE                       P-N24920
C     AVERAGE IS TAKEN ON THE SPIN ONLY                                 P-N24930
C                                                                       P-N24940
      COMMON/BL1/P1(350),P2(350),P3(350),EPS(350),IND1(350),IND2(350),TA P-N24950
     -,V(350)
!$OMP THREADPRIVATE(/BL1/)
      COMMON/BL3/R1,R2,X1(350),X2(350),X3(350),IA1,IA2,RAB2             P-N24960
!$OMP THREADPRIVATE(/BL3/)
      COMMON/BL5/TLG(350),NESC(350)                                     P-N24970
!$OMP THREADPRIVATE(/BL5/)
      COMMON/SAXW/ XX(30,500),YY(30,500),SS(30,500),NBPINTER(500),IMAT
!$OMP THREADPRIVATE(/SAXW/)
      COMMON/WS/R0,ADIF,RMAXWS,DRWS,BMAX,XFOISA,RLIM(500),
     &          NPAULSTR,NOSURF
!$OMP THREADPRIVATE(/WS/)
      COMMON/bl10/IZ1,IZ2
!$OMP THREADPRIVATE(/bl10/)
C Number of current p and n below the fermi level
      COMMON/YY/NPFINIT(10),NNFINIT(10),NPFSEA(10),NNFSEA(10),
     s          TFNL(10),TFPL(10),NBLF
!$OMP THREADPRIVATE(/YY/)
      COMMON/CTE/HC,FMP,FMPI

      PM2 = FMP*FMP

C Global statistical pauli
      IF(NPAULSTR.EQ.2) THEN
      IN2=IA2-IZ2

C Un seul niveau (TF), FMP**2=880368.61

C Plusieurs niveaux:
      F=0.
      T=EPS(L)-FMP

      DO i=1,NBLF
      IF(IND2(L).EQ.-1) THEN
        TL=TFNL(i)
        CL=REAL(NNFSEA(i),8)
        FNUC=NNFINIT(i)
      ELSE
        TL=TFPL(i)
        CL=REAL(NPFSEA(i),8)
        FNUC=NPFINIT(i)
      ENDIF
         IF(T.LE.TL) THEN
           F=CL/FNUC
           GO TO 10
         ENDIF
      ENDDO
10    CONTINUE


      RETURN
      ENDIF

C NO PAULI at all
      IF (NPAULSTR.EQ.3) then
      f=0.
      return
      endif
      IF (NPAULSTR.EQ.1) THEN

c Pauli strict
       f=0.
       pmod=sqrt(p1(l)**2+p2(l)**2+p3(l)**2)
       if (pmod.lt.PFP) f=1.
       return

      ELSE

      XR2=XR*XR                                                         P-N24980
      PR2=PR*PR                                                         P-N24990
      ct1=17.54596
      ct2=1239.861
      VOL=ct1*(XR*PR/ct2)**3                                            P-N25000
      RS=SQRT(X1(L)*X1(L)+X2(L)*X2(L)+X3(L)*X3(L))                      P-N25010
            IF (NOSURF.LE.0) THEN
C modifs A.B.: R2 -> RMAXWS pour la densite en W.S.
      rdeq=RMAXWS
            ELSE
      rdeq=R0
            END IF

      IF (RS-XR.LE.rdeq) GO TO 3
      F=0.                                                              P-N25030
      RETURN                                                            P-N25040
    3 IF (RS+XR.GT.rdeq) VOL=VOL*0.5*(rdeq-RS+XR)/XR
    2 IA=IA1+IA2                                                        P-N25060
      NL=0                                                              P-N25070
      IF(LOCE.EQ.1.OR.LOCE.EQ.3) THEN
C Calcul de l'impulsion locale de L:
      fmdvd=sqrt(eps(l)**2-p1(l)**2-p2(l)**2-p3(l)**2)
      EPS_loc=EPS(L)-VLOC(l,rs,fmdvd,eps(l)-fmdvd,v(l),ind1(l),ind2(l))
      coef = SQRT((EPS_loc**2 - PM2)/(EPS(L)**2-PM2))
      P1L = P1(L)*coef
      P2L = P2(L)*coef
      P3L = P3(L)*coef
      ELSE
      P1L = P1(L)
      P2L = P2(L)
      P3L = P3(L)
      ENDIF


      DO 1 I=1,IA                                                       P-N25080
      IF (NESC(I).GT.0) GO TO 1                                         P-N25090
      IF (IND1(I).GT.0) GO TO 1                                         P-N25100
      IF (IND2(I).NE.IND2(L)) GO TO 1                                   P-N25110
      DX2=(X1(L)-X1(I))**2+(X2(L)-X2(I))**2+(X3(L)-X3(I))**2            P-N25120
      IF (DX2.GT.XR2) GO TO 1                                           P-N25130
      IF(LOCE.EQ.1.OR.LOCE.EQ.3) THEN
C Calcul de l'impulsion locale de I:
      RSI = SQRT(X1(I)**2+X2(I)**2+X3(I)**2)
      fmdvd=sqrt(eps(i)**2-p1(i)**2-p2(i)**2-p3(i)**2)
      EPS_loc=EPS(i)-VLOC(i,rs,fmdvd,eps(i)-fmdvd,v(i),ind1(i),ind2(i))
      coef = SQRT((EPS_loc**2 - PM2)/(EPS(I)**2-PM2))
      P1I = P1(I)*coef
      P2I = P2(I)*coef
      P3I = P3(I)*coef
      ELSE
      P1I = P1(I)
      P2I = P2(I)
      P3I = P3(I)
      ENDIF

      DP2=(P1L-P1I)**2+(P2L-P2I)**2+(P3L-P3I)**2                        P-N25140
      IF (DP2.GT.PR2) GO TO 1                                           P-N25150
      NL=NL+1                                                           P-N25160
    1 CONTINUE                                                          P-N25170
      F=(NL-1)/VOL/2.                                                   P-N25180
      IF (F.GT.1.) F=1.                                                 P-N25190

C Coupure imposee sur l'impulsion:

      RETURN                                                            P-N25200

      ENDIF

      END SUBROUTINE PAULIL                                              P-N25210

c---------------------------------------------------------------------------
c THA ***** i
c
c     ITERATION TO fULLFILL Consvt relation with V(E)
C     Function arguments:
C
C     [snipping PK's rant about AECSVT's crystalline methodology]
C
C     The inputs (note that the kinematic variables refer to the lab
C     frame):
C     [pold11, pold12, pold13] Momentum of particle 1
C     eold1                    Energy of particle 1
C     vkfo1                    if particle 1 is a delta or a pion, its
C                              potential energy; if it is a nucleon, the
C                              energy-independent low-energy limit of
C                              its potential energy (for
C                              energy-independent potentials, it is just
C                              the nucleon potential)
C     [pold21, pold22, pold23] Momentum of particle 2
C     eold2                    Energy of particle 2
C     vkfo2                    same as vkfo1 for particle 2
C     vkf1                     same as vkfo1, for the outgoing particle 1
C     vkf2                     same as vkfo1, for the outgoing particle 2
C     [b1, b2, b3]             The boost vector (the same boost vector
C                              used before calling COLLIS)
C     vloc1                    Local energy of particle 1
C     vloc2                    Local energy of particle 2
C     loce                     flag for local energy, aka f(18)
C
C     Outputs (in the following, "outgoing" means "after AECSVT has
C     succeeded"):
C     [p11, p12, p13]          Momentum of outgoing particle 1
C     e1                       Energy of outgoing particle 1
C     [p21, p22, p23]          Momentum of outgoing particle 2
C     e2                       Energy of outgoing particle 2
C     v1                       potential energy of outgoing particle 1
C     v2                       potential energy of outgoing particle 2
C     ireject                  0 if AECSVT succeeds, 1 if it fails
C     edel                     violation of energy conservation after
C                              the call to AECSVT (should be smaller
C                              than ERREDEL if AECSVT succeeds). Its
C                              name stands for "delta E" (I think)
C     ivfcte                   type of energy-dependent potential
C                              (1=linear energy dependence,
C                              2=exponential energy dependence); INCL++
C                              only implements ivfcte=1 for the time
C                              being (25/5/11)
C     fve                      potential type, aka f(13) (see
C                              description at the beginning of this
C                              file)
C     vlocp1                   Local energy of outgoing particle 1
C                              Heh, this is actually used as an input,
C                              too; you can think of the input value as
C                              an estimation of the local energy of
C                              outgoing particle 1. Its initial value
C                              does not really matter, though, because
C                              computing the actual vlocp1 is precisely
C                              AECSVT's duty. The initial value could be
C                              zero, for all that matters. In INCL4.6
C                              most of the time it is actually
C                              VLOC(l1,r_1).
C     vlocp2                   same as vlocp1 for outgoing particle 2
C     l1                       Index of particle 1
C     r_1                      Magnitude of the position vector of particle 1
C     l2                       Index of particle 2
C     r_2                      Magnitude of the position vector of particle 2
      SUBROUTINE AECSVT(etarget,
     &B1,B2,B3,P11,P12,P13,E1,VKF1,P21,P22,P23,E2,
     &VKF2,V1,V2,IREJECT,EDEL,IVFCTE,fve,VLOCP1,VLOCP2,
     &l1,r_1,l2,r_2,loce,ind1_1,ind1_2,ind2_1,ind2_2)
      implicit real*8(A-H,O-Z)
c
c   CRIT. CONV. USED
      ERREDEL=0.0001
      ERRELAX=0.0005

c Q of the reaction for local energy:
      Q = VLOCP1+VLOCP2

c       Stock des donnees initiales pour postprocessing des erreurs
c
      IREJECT=0
      V1=0.0
      V2=0.0
      ITERA=0
c
C     Determine the total energy before the collision (so that we can
C     conserve it after the collision). Local energy has no impact on
C     this. INCL++ stores this quantity in
C     FinalState::totalEnergyBeforeInteraction.
C     In AECSVT's language, the total energy before the interaction is
C     EOLD1-VOLD1+EOLD2-VOLD2+VLOC1+VLOC2. Part of it is hidden in Q.
C     Likewise, the total energy after the interaction will be
C     E1-V1+E2-V2+VLOCP1+VLOCP2
C     Note that all we really need is the total energy before the
C     interaction; all the POLDs, for example, are only used to compute
C     this quantity. INCL++ does not need all this; it can happily use
C     the value stored in the FinalState and forget all about local
C     energy in the initial state.

C     p1 = particle1 (index l1)
C     p2 = particle2 (index l2)
c     The following IF block is equivalent to
c      IF(FM1OLD.GT.900.0.AND.FM1OLD.LT.938.3) THEN ! :WTF: an interesting way to implement isNucleon()... Argh!!!
c        VOLD1=POTENT(TOLD1,FM1OLD,VKFO1,IVFCTE,fve) !
C     End of determination of total energy before interaction

C     The code between "CAPO" and "CODA" below is equivalent to a call
C     to RootFunctor::operator() with argument x=1.0. The return value
C     is EDEL1.
C     CAPO
c
      ALPHA1=1.0
      ALPHA2=1.0
      P1=SQRT(P11**2+P12**2+P13**2) ! Particle 1 momentum
      FM1=SQRT(E1**2-P1**2) ! Particle 1 mass
      T1=E1-FM1+VLOCP1
      IF(FM1.GT.900.0.AND.FM1.LT.938.3) THEN
         V1=POTENT(T1,FM1,VKF1,IVFCTE,fve)
       ELSE
         V1=VKF1
      ENDIF
      P2=SQRT(P21**2+P22**2+P23**2)
      FM2=SQRT(E2**2-P2**2)
      T2=E2-FM2+VLOCP2
      IF(FM2.GT.900.0.AND.FM2.LT.938.3) THEN
         V2=POTENT(T2,FM2,VKF2,IVFCTE,fve)
       ELSE
         V2=VKF2
      ENDIF

C     Loop 1: Calculate the value of Q iteratively
C
C     The goal of the loop is to self-consistently determine T1, T2,
C     VLOCP1 and VLOCP2. The loop actually solves the following
C     equation iteratively for Ti (i=1,2):
C     where VLOCP(Ti,Ri) is the energy- and position-dependent
C     potential (i.e. the local energy). Convergence is assessed by
C     looking at variations of Q.
C     Note that this is part of a call to operator()! We need to loop
C     every time we evaluate the functor!
C       As an aside: since this loop is actually nothing but a
C       root-finding algorithm, it could actually be implemented using
C       RootFunctor and RootFinder. A RootFunctor inside a
C       RootFunctor... the loop usually converges quite fast, anyway.
C     Once Loop 1 converges, we can use Q to compute EDEL (but that's
C     conceptually outside the loop, really).
      deltaq=1000.
      iterq=0
      do while( ( (loce.eq.1 .or. loce.eq.3) .and. deltaq.gt.erredel )
     &     .and. iterq.lt.50 )
         iterq=iterq+1
         qold = q
         T1=E1-FM1+VLOCP1 ! T1 is recomputed every time because we are
                          ! changing VLOCP1 inside the loop.
         IF(FM1.GT.900.0.AND.FM1.LT.938.3) THEN ! if isNucleon()... Argh!
            V1=POTENT(T1,FM1,VKF1,IVFCTE,fve)
         ELSE
            V1=VKF1
         ENDIF
         T2=E2-FM2+VLOCP2
         IF(FM2.GT.900.0.AND.FM2.LT.938.3) THEN
            V2=POTENT(T2,FM2,VKF2,IVFCTE,fve)
         ELSE
            V2=VKF2
         ENDIF
         vlocp1=VLOC(l1,r_1,fm1,t1,v1,ind1_1,ind2_1)
         if(l2.le.0) then ! If l2 is a pion, it has no local energy
            Q = VLOCP1
         else
            vlocp2=VLOC(l2,r_2,fm2,t2,v2,ind1_2,ind2_2)
            Q = VLOCP1+VLOCP2
         endif
         deltaq=abs(qold-q)
      end do
      EDEL1=(E1-V1+E2-V2)-Etarget+Q ! EDEL probably
                                                      ! stands for
                                                      ! "delta E"
C     CODA

      IF(ABS(EDEL1).LT.ERREDEL) then
         edel=edel1
         return
      end if
      CALL LOREN(P11,P12,P13,-B1,-B2,-B3,E1)
      VLP11=P11
      VLP12=P12
      VLP13=P13
      VLE1=E1
      CALL LOREN(P21,P22,P23,-B1,-B2,-B3,E2)
      VLP21=P21
      VLP22=P22
      VLP23=P23
      VLE2=E2

C     We can replace the following "bracket block" with a simple call to:

C     Begin "bracket block"
c     Bracket the root of the equation in alpha
c     Choose a starting point such that EDEL1*EDEL2<0
      alpfac=1.5
      alpfacm1=1./alpfac
      iterbr=0
C     Store the values of the input particle momenta in the CM system
C     (boost is a few lines above). We will use these momenta as
C     references for the scaling (i.e. they correspond to alpha=1.0).
C     Equivalent to part of ViolationEMomentumFunctor's constructor.
      vlp110=vlp11
      vlp120=vlp12
      vlp130=vlp13
      vlp210=vlp21
      vlp220=vlp22
      vlp230=vlp23
      edel2=edel1
      oldalpha1=alpha1
      oldalpha2=alpha2
      oldedel1=edel1
      oldedel2=edel2
C     Loop 2: The logic of this loop is already implemented in
      do while(sign(real(1.,8),edel1)*sign(real(1.,8),edel2).gt.0)
         if(iterbr.gt.50) then
            ireject=1
            return
         endif
         iterbr=iterbr+1

         alpha1=alpha1*alpfacm1
         alpha2=alpha2*alpfac

c        compute edel1
         VLP11=alpha1*VLP110
         VLP12=alpha1*VLP120
         VLP13=alpha1*VLP130
         IF(E1.NE.0.) VLE1=SQRT(VLP11**2+VLP12**2+VLP13**2+FM1**2)
         P11=VLP11
         P12=VLP12
         P13=VLP13
         IF(E1.NE.0.) E1=VLE1
         CALL LOREN(P11,P12,P13,B1,B2,B3,E1)
         P1=SQRT(P11**2+P12**2+P13**2)
         T1=E1-FM1+VLOCP1
         IF(FM1.GT.900.0.AND.FM1.LT.938.3) THEN
            V1=POTENT(T1,FM1,VKF1,IVFCTE,fve)
         ELSE
            V1=VKF1
         ENDIF
         VLP21=alpha1*VLP210
         VLP22=alpha1*VLP220
         VLP23=alpha1*VLP230
         IF(E2.NE.0.) VLE2=SQRT(VLP21**2+VLP22**2+VLP23**2+FM2**2)
         P21=VLP21
         P22=VLP22
         P23=VLP23
         IF(E2.NE.0.) E2=VLE2
         CALL LOREN(P21,P22,P23,B1,B2,B3,E2)
         P2=SQRT(P21**2+P22**2+P23**2)
         T2=E2-FM2+VLOCP2
         IF(FM2.GT.900.0.AND.FM2.LT.938.3) THEN
            V2=POTENT(T2,FM2,VKF2,IVFCTE,fve)
         ELSE
            V2=VKF2
         ENDIF

C     Loop 3 (nested inside Loop 2):
C
C     This is exactly the same as Loop 1 except that we are playing the
C     game for alpha2, which is != 1.0. See CAPO2/CODA2 below.
         deltaq=1000.
         iterq=0
         do while( ( (loce.eq.1 .or. loce.eq.3) .and. deltaq.gt.erredel)
     &        .and. iterq.lt.50 )
            iterq=iterq+1
            qold = q
            T1=E1-FM1+VLOCP1
            IF(FM1.GT.900.0.AND.FM1.LT.938.3) THEN ! Argh!
               V1=POTENT(T1,FM1,VKF1,IVFCTE,fve)
            ELSE
               V1=VKF1
            ENDIF
            T2=E2-FM2+VLOCP2
            IF(FM2.GT.900.0.AND.FM2.LT.938.3) THEN ! Argh!
               V2=POTENT(T2,FM2,VKF2,IVFCTE,fve)
            ELSE
               V2=VKF2
            ENDIF
            vlocp1=VLOC(l1,r_1,fm1,t1,v1,ind1_1,ind2_1)
            if(l2.le.0) then
               Q = VLOCP1
            else
             vlocp2=VLOC(l2,r_2,fm2,t2,v2,ind1_2,ind2_2)
               Q = VLOCP1+VLOCP2
            endif
            deltaq=abs(qold-q)
         end do
         EDEL1=(E1-V1+E2-V2)-Etarget+Q

c        compute edel2
         VLP11=alpha2*VLP110
         VLP12=alpha2*VLP120
         VLP13=alpha2*VLP130
         IF(E1.NE.0.) VLE1=SQRT(VLP11**2+VLP12**2+VLP13**2+FM1**2)
         P11=VLP11
         P12=VLP12
         P13=VLP13
         IF(E1.NE.0.) E1=VLE1
         CALL LOREN(P11,P12,P13,B1,B2,B3,E1)
         P1=SQRT(P11**2+P12**2+P13**2)
         T1=E1-FM1+VLOCP1
         IF(FM1.GT.900.0.AND.FM1.LT.938.3) THEN
            V1=POTENT(T1,FM1,VKF1,IVFCTE,fve)
         ELSE
            V1=VKF1
         ENDIF
         VLP21=alpha2*VLP210
         VLP22=alpha2*VLP220
         VLP23=alpha2*VLP230
         IF(E2.NE.0.) VLE2=SQRT(VLP21**2+VLP22**2+VLP23**2+FM2**2)
         P21=VLP21
         P22=VLP22
         P23=VLP23
         IF(E2.NE.0.) E2=VLE2
         CALL LOREN(P21,P22,P23,B1,B2,B3,E2)
         P2=SQRT(P21**2+P22**2+P23**2)
         T2=E2-FM2+VLOCP2
         IF(FM2.GT.900.0.AND.FM2.LT.938.3) THEN
            V2=POTENT(T2,FM2,VKF2,IVFCTE,fve)
         ELSE
            V2=VKF2
         ENDIF

C     Loop 3 (nested inside Loop 2):
C
C     This is exactly the same as Loop 1 except that we are playing the
C     game for alpha2, which is != 1.0. See CAPO2/CODA2 below.
         deltaq=1000.
         iterq=0
         do while( ( (loce.eq.1 .or. loce.eq.3) .and. deltaq.gt.erredel)
     &        .and. iterq.lt.50 )
            iterq=iterq+1
            qold = q
            T1=E1-FM1+VLOCP1
            IF(FM1.GT.900.0.AND.FM1.LT.938.3) THEN ! Argh!
               V1=POTENT(T1,FM1,VKF1,IVFCTE,fve)
            ELSE
               V1=VKF1
            ENDIF
            T2=E2-FM2+VLOCP2
            IF(FM2.GT.900.0.AND.FM2.LT.938.3) THEN ! Argh!
               V2=POTENT(T2,FM2,VKF2,IVFCTE,fve)
            ELSE
               V2=VKF2
            ENDIF
            vlocp1=VLOC(l1,r_1,fm1,t1,v1,ind1_1,ind2_1)
            if(l2.le.0) then
               Q = VLOCP1
            else
             vlocp2=VLOC(l2,r_2,fm2,t2,v2,ind1_2,ind2_2)
               Q = VLOCP1+VLOCP2
            endif
            deltaq=abs(qold-q)
         end do
         EDEL2=(E1-V1+E2-V2)-Etarget+Q
      end do
C     End "bracket block" (Loop 2)
      if(sign(real(1.,8),edel2).eq.sign(real(1.,8),oldedel2)) then
        alpha2=oldalpha2
        edel2=oldedel2
      else
        alpha1=oldalpha1
        edel1=oldedel1
      endif

      if(alpha1.gt.alpha2) then
         tmp=alpha2
         alpha2=alpha1
         alpha1=tmp
         tmp=edel2
         edel2=edel1
         edel1=tmp
      end if
      edel = edel1
      iside = 0

C     The stuff below is the RootFinder::solve method
c     Iterate here
   10 CONTINUE ! Goto evilness: This is actually the beginning of a loop...
      IF(ABS(EDEL).LT.ERREDEL) return
c
c     increment itera + rejet si nombre eleve
      itera=itera+1
      if(itera.gt.100) then
        if(ABS(EDEL).LT.ERRELAX) return
        if(itera.lt.110) goto 30
         IREJECT=1
       RETURN
      endif
   30 continue

c
c     *** False position method
c
c     Estimate alpha:
      alpha=(edel1*alpha2-edel2*alpha1)/(edel1-edel2)

C     Code between CAPO2 and CODA2 is equivalent to a call to operator()
C     with a generic argument alpha. The return value is EDEL.
C     CAPO2

c     Update EDEL:
      VLP11=abs(ALPHA)*VLP110
      VLP12=abs(ALPHA)*VLP120
      VLP13=abs(ALPHA)*VLP130
      IF(E1.NE.0.) VLE1=SQRT(VLP11**2+VLP12**2+VLP13**2+FM1**2)
      P11=VLP11
      P12=VLP12
      P13=VLP13
      IF(E1.NE.0.) E1=VLE1
      CALL LOREN(P11,P12,P13,B1,B2,B3,E1)
      P1=SQRT(P11**2+P12**2+P13**2)
      T1=E1-FM1+VLOCP1
      IF(FM1.GT.900.0.AND.FM1.LT.938.3) THEN
         V1=POTENT(T1,FM1,VKF1,IVFCTE,fve)
       ELSE
         V1=VKF1
      ENDIF
      VLP21=abs(ALPHA)*VLP210
      VLP22=abs(ALPHA)*VLP220
      VLP23=abs(ALPHA)*VlP230
      IF(E2.NE.0.) VLE2=SQRT(VLP21**2+VLP22**2+VLP23**2+FM2**2)
      P21=VLP21
      P22=VLP22
      P23=VLP23
      IF(E2.NE.0.) E2=VLE2
      CALL LOREN(P21,P22,P23,B1,B2,B3,E2)
      P2=SQRT(P21**2+P22**2+P23**2)
      T2=E2-FM2+VLOCP2
      IF(FM2.GT.900.0.AND.FM2.LT.938.3) THEN
         V2=POTENT(T2,FM2,VKF2,IVFCTE,fve)
       ELSE
         V2=VKF2
      ENDIF

C     Loop 4: same as Loop 1 and part of the call to operator(), as
C     discussed above.
      deltaq=1000.
      iterq=0
      do while( ( (loce.eq.1 .or. loce.eq.3) .and. deltaq.gt.erredel )
     &     .and. iterq.lt.50 )
         iterq=iterq+1
         qold = q
         T1=E1-FM1+VLOCP1
         IF(FM1.GT.900.0.AND.FM1.LT.938.3) THEN
            V1=POTENT(T1,FM1,VKF1,IVFCTE,fve)
         ELSE
            V1=VKF1
         ENDIF
         T2=E2-FM2+VLOCP2
         IF(FM2.GT.900.0.AND.FM2.LT.938.3) THEN
            V2=POTENT(T2,FM2,VKF2,IVFCTE,fve)
         ELSE
            V2=VKF2
         ENDIF
         vlocp1=VLOC(l1,r_1,fm1,t1,v1,ind1_1,ind2_1)
         if(l2.le.0) then
            Q = VLOCP1
         else
            vlocp2=VLOC(l2,r_2,fm2,t2,v2,ind1_2,ind2_2)
            Q = VLOCP1+VLOCP2
         endif
         deltaq=abs(qold-q)
      end do
      EDEL=(E1-V1+E2-V2)-Etarget+Q
C     CODA2

      if(sign(real(1.,8),edel)*sign(real(1.,8),edel1).gt.0) then
         edel1=edel
         alpha1=alpha
         if(iside.eq.-1) edel2 = edel2 / 2.
         iside = -1
      else if(sign(real(1.,8),edel)*sign(real(1.,8),edel1).lt.0) then
         edel2=edel
         alpha2=alpha
         if(iside.eq.1) edel1 = edel1 / 2.
         iside = 1
      else
         return
      end if

      GOTO 10
C     End of RootFinder::solve()'s loop

   20 CONTINUE
      RETURN
      END SUBROUTINE AECSVT

c-----------------------------------------------------------------------
      FUNCTION POTENT(T,FM,V2,IVFCTE,fve)
      implicit real*8(A-H,O-Z)
c
c    From the total energy E (pc=0 MeV, Etot=938 MeV)
c     the separation energy and the Fermi energy,
c     PONTENT return the mean field V(E):
c
      double precision VI,VII,ERR
      COMMON/OPTI/CUTNN,ALPH,TFM,TFN,TFP,TFPP,
     s  PFM,PFN,PFP,PFPP,V0M,V0N,V0P,V0PP,S1NN,S2NN,V2P,V2N,LBLNN,LNNEF
!$OMP THREADPRIVATE(/OPTI/)

      IF(fve.gt.2.5) THEN
C Energy dependence above Tf only
         IF(ABS(V2-V2P).LE.ABS(V2-V2N)) THEN
            TF=TFP
            XC=V0P
         ELSE
            TF=TFN
            XC=V0N
         ENDIF

         IF(T.LE.TF) THEN
            POTENT=XC
            RETURN
         ENDIF
      ENDIF

      IF(IVFCTE.EQ.1) THEN
         ALP=0.223
         if(fve.lt.1.5) alp=0.0
         POTENT=(V2/(1.-ALP))-(ALP/(1.-ALP))*T
         IF(POTENT.LE.0.0) POTENT=0.0
         RETURN
      ENDIF
      IF(IVFCTE.EQ.2) THEN
         icomp=0
         VI=50.0
 10      CONTINUE
         VII=V2*EXP(-0.006681*(T-VI))
         ERR=ABS((VII-VI)/VII)
         IF(ERR.GT.0.0000001) THEN
            icomp=icomp+1
            if(icomp.gt.1000000) then
               write(*,*) 'compteur out, err',ERR
               POTENT=VII
               RETURN
            endif
            VI=VII
            GOTO 10
         ENDIF
         POTENT=VII
         RETURN
      ENDIF

      RETURN

      END FUNCTION POTENT

c
c-----------------------------------------------------------------------
C
CCC   GAUSSIAN RANDOM NUMBER GENERATOR
C
      subroutine rgauss(xg)
      implicit real*8(A-H,O-Z)
      logical generated
      common/crgauss/generated
!$OMP THREADPRIVATE(/crgauss/)
      real*8 u, v
      save u, v
!$OMP THREADPRIVATE(u, v)

      if(.not.generated) then
      u=rn(0)
      v=rn(0)
        v=v*6.2831853071796
        generated=.true.
        xg = sqrt(-2.*log(u))*cos(v)
        return
      else
        generated=.false.
        xg = sqrt(-2.*log(u))*sin(v)
        return
      endif

      end subroutine rgauss
c-------------------------------------------------------------------------------

C***************************************************************************
C RECHERCHE DE CLUSTERS (d,t,3He,4He) autour du nucleon K, ITCH=charge courante
C   du noyau pour la barriere coulombienne.
C   IOK=1, le cluster de type KINDCLST sort (0=pas de sortie cluster).
C   ID_NUC_CLST(4)      Numeros des nucleons constituant ce cluster.
C   EOUT,TOUT     Energie totale et cinetique de ce cluster hors du noyau.
C   POUT, LOUT    Vecteur impulsion et moment angulaire hors du noyau.
C   ROUT        Vector position of the cluster (barycenter)
C  Correction de l'appel du coulombien le 21/8/2003 (appel avec isospin et non Z)
C   Logique de retenue des clusters plus l?gers et du nucleon si un cluster
C   se forme sans sortir (POSSIBLE(4) = 0/1 non formation/OK formation,
c                         IOK=2 forcer la reflexion du nucleon (in pnu))
C
C***************************************************************************
C****************************************************************************
C***********************************************************************
      SUBROUTINE LOCEK(k,r)
      implicit real*8(A-H,O-Z)
      COMMON/BL1/P1(350),P2(350),P3(350),EPS(350),IND1(350),IND2(350),TA
     -,V(350)
!$OMP THREADPRIVATE(/BL1/)
c For calculation with local kinetic energy:
      COMMON/loc/p1l(350),p2l(350),p3l(350),epsl(350)
!$OMP THREADPRIVATE(/loc/)
      REAL*8 A,B,C,COEF
      C=880368.608D+00
      fmdvd=sqrt(eps(k)**2-p1(k)**2-p2(k)**2-p3(k)**2)
      A=eps(k)-VLOC(k,r,fmdvd,eps(k)-fmdvd,v(k),ind1(k),ind2(k))
      epsl(k)=A
      A=A**2-C
      IF(A.LE.0.) A=0.0D+00
      B=eps(k)
      B=B**2-C
      COEF=DSQRT(A/B)

      p1l(k)=p1(k)*coef
      p2l(k)=p2(k)*coef
      p3l(k)=p3(k)*coef
      RETURN
      END SUBROUTINE LOCEK
C****************************************************************************
      FUNCTION VLOC(iflag,r,fmass,tke,v,ind1,ind2)
      implicit real*8(A-H,O-Z)
      COMMON/OPTI/CUTNN,ALPH,
     s  TFL(4),PFL(4),V0L(4),S1NN,S2NN,V2P,V2N,LBLNN,LNNEF
!$OMP THREADPRIVATE(/OPTI/)
      COMMON/CSE/SN,SP
!$OMP THREADPRIVATE(/CSE/)
      COMMON/WS/R0,ADIF,RMAXWS,DRWS,BMAX,XFOISA,RLIM(500),
     &          NPAULSTR,NOSURF
!$OMP THREADPRIVATE(/WS/)
      COMMON/SAXW/ XX(30,500),YY(30,500),SS(30,500),NBPINTER(500),IMAT
!$OMP THREADPRIVATE(/SAXW/)

C Correction: FLINR() is prepared in INIT_INCL up to DRWS*29. but rmaxws
C can be larger with the NN-length of interaction:
      RLIMIT=RLIM(imat)

c For tests (prints if I<0)
      IF(iflag.LT.0) THEN
      IFL=1
      else
      ifl=0
      ENDIF

C For a possible decay of the delta OUTSIDE during avatar calculations
      IF(R.GE.RMAXWS) THEN
                  VLOC=0.
                  RETURN
      ENDIF

            IS = (ind2+5)/2
      IF(IND1.EQ.0) THEN
C This is a nucleon
      IF(TKE.LE.TFL(IS)) THEN
            PFL0 = PFL(IS)
      ELSE
            if(ind2.eq.1) then
            TF0 = V - SP
            else
            TF0 = V - SN
            endif
                  IF(TF0.LE.0.) THEN
            PFL0 = 0.
            ELSE
                  PFL0 = SQRT(TF0*(TF0+2.*fmass))
            ENDIF
      ENDIF
      IF(R.LE.RLIMIT) THEN
      PL = PFL0*FLINR(R,imat)
      ELSE
      PL = PFL0*FLINR(RLIMIT,imat)
      ENDIF

C This is the minimum kinetic energy at this place
      VLOC = SQRT(PL**2+fmass**2)-fmass
      RETURN
      ELSE
C This is a Delta. We compute the actual Pf from Tf
      IF(TKE.LE.TFL(IS)) THEN
            PFDEL = SQRT(TFL(IS)*(TFL(IS)+2.*fmass))
      ELSE
            TF0 = V - SP ! should depend on isospin!
                  IF(TF0.LE.0.) THEN
            PFDEL = 0.
            ELSE
                  PFDEL = SQRT(TF0*(TF0+2.*fmass))
            ENDIF
      ENDIF
      IF(R.LE.RLIMIT) THEN
      PL = PFDEL*FLINR(R,imat)
      ELSE
      PL = PFDEL*FLINR(RLIMIT,imat)
      ENDIF
      VLOC=SQRT(PL**2 + fmass**2) - fmass
      RETURN
      ENDIF
C This value is the local potential with T the current kinetic energy of the particle:


      RETURN
      END FUNCTION VLOC
C****************************************************************************
      SUBROUTINE EIJLOC(I,J,EIJ)
      implicit real*8(A-H,O-Z)
C calcul de EIJ a la distance minimale d'approche (temps TA calcule par
C TIME_b(I,J)) et tenant compte de l'energie potentielle locale.
C
      COMMON/BL1/P1(350),P2(350),P3(350),EPS(350),IND1(350),IND2(350),TA
     -,V(350)                                                           P-N00530
!$OMP THREADPRIVATE(/BL1/)
      COMMON/BL3/R_1,R_2,X1(350),X2(350),X3(350),IA1,IA2,RAB2
!$OMP THREADPRIVATE(/BL3/)
      COMMON/WS/R0,ADIF,RMAXWS,DRWS,BMAX,XFOISA,RLIM(500),
     &          NPAULSTR,NOSURF
!$OMP THREADPRIVATE(/WS/)
*      COMMON/Fermi/TF,PF,PF2,CUTNN,LBLNN,ELIM
      COMMON/OPTI/CUTNN,ALPH,
     s  TFL(4),PFL(4),V0L(4),S1NN,S2NN,V2P,V2N,LBLNN,LNNEF
!$OMP THREADPRIVATE(/OPTI/)
      COMMON/CTE/HC,FMP,FMPI
      COMMON/GLOB_PROJ/EPROJ,P1PROJ,P2PROJ,P3PROJ,
     s IFL_BOUND_PROJ,IBOUND_NUC(4)
!$OMP THREADPRIVATE(/GLOB_PROJ/)

c pour test:

C Position of I,J, local potentials:
      IF(IFL_BOUND_PROJ.EQ.0) THEN
      C1 = TA/EPS(I)
      X1I =X1(I)+P1(I)*C1
      X2I =X2(I)+P2(I)*C1
      X3I =X3(I)+P3(I)*C1
      C2 = TA/EPS(J)
      X1J =X1(J)+P1(J)*C2
      X2J =X2(J)+P2(J)*C2
      X3J =X3(J)+P3(J)*C2
      ELSE
        IF(I.GT.IA1) THEN
          P1I=P1(I)
          P2I=P2(I)
          P3I=P3(I)
          EPSI=EPS(I)
	ELSE	
          IF(IBOUND_NUC(I).EQ.0) THEN
            P1I=P1(I)
            P2I=P2(I)
            P3I=P3(I)
            EPSI=EPS(I)
          ELSE
            P1I=P1PROJ
            P2I=P2PROJ
            P3I=P3PROJ
            EPSI=EPROJ
          ENDIF
	ENDIF
        IF(J.GT.IA1) THEN
          P1J=P1(J)
          P2J=P2(J)
          P3J=P3(J)
          EPSJ=EPS(J)
	ELSE
          IF(IBOUND_NUC(J).EQ.0) THEN
          P1J=P1(J)
          P2J=P2(J)
          P3J=P3(J)
          EPSJ=EPS(J)
          ELSE
            P1J=P1PROJ
            P2J=P2PROJ
            P3J=P3PROJ
            EPSJ=EPROJ
          ENDIF
	ENDIF
      C1 = TA/EPSI
      X1I =X1(I)+P1I*C1
      X2I =X2(I)+P2I*C1
      X3I =X3(I)+P3I*C1
      C2 = TA/EPSJ
      X1J =X1(J)+P1J*C2
      X2J =X2(J)+P2J*C2
      X3J =X3(J)+P3J*C2
      ENDIF
	
      R1 =X1I**2 +X2I**2 +X3I**2
      R1 = SQRT(R1)
      R2 =X1J**2 +X2J**2 +X3J**2
      R2 = SQRT(R2)

      PI2 = P1(I)**2 + P2(I)**2 + P3(I)**2
      FMI2=FMP**2
      IF(IND1(I).EQ.1) THEN
      FMI2=EPS(I)**2 - PI2
      ENDIF
      fmi=sqrt(fmi2)
      vloc1 = VLOC(i,r1,fmi,eps(i)-fmi,v(i),ind1(i),ind2(i))
      PJ2 = P1(J)**2 + P2(J)**2 + P3(J)**2
      FMJ2=FMP**2
      IF(IND1(J).EQ.1) THEN
      FMJ2=EPS(J)**2 - PJ2
      ENDIF
      fmj=sqrt(fmj2)
      vloc2 = VLOC(j,r2,fmj,eps(j)-fmj,v(j),ind1(j),ind2(j))
C Mass, including a possible Delta:
C New energies and momenta:
      E1 = EPS(I) - VLOC1
      E2 = EPS(J) - VLOC2
      AA=E1**2 - FMI2
      IF (AA.LT.0) THEN
            COR1 = 0
      ELSE
      COR1=SQRT(AA/PI2)
      ENDIF
      AA=E2**2 - FMJ2
      IF (AA.LT.0) THEN
            COR2 = 0
      ELSE
      COR2=SQRT(AA/PJ2)
      ENDIF

      P1I = P1(I)*COR1
      P2I = P2(I)*COR1
      P3I = P3(I)*COR1

      P1J = P1(J)*COR2
      P2J = P2(J)*COR2
      P3J = P3(J)*COR2

      EIJ = SQRT((E1+E2)**2-(P1I+P1J)**2-(P2I+P2J)**2-(P3I+P3J)**2)


      RETURN
      END SUBROUTINE EIJLOC
*******************************************************************************
      FUNCTION SOLV_Z(denf,val,x0,xm,xacc,i_ok)
      implicit real*8(A-H,O-Z)
C  !=====================================================================
C  ! Newton-Raphson method for findind the root of the function denf-val
C  ! above xm with x0 as first guess and  with accuracy xacc,
C  ! i_ok=1/0 A solution found (1) or not (0)
C  !=====================================================================
      real*8 val,x1,x2,xacc
      real*8 f,df,fmval,dx
      external denf
      real*8 denf ! function
      integer maxit
      i_ok = 1
      maxit = 20
      iflag=0

      SOLV_Z = x0
      do j=1,maxit
            f=denf(SOLV_Z)
      df=100.*(denf(SOLV_Z+0.01)-f)
      fmval=f-val
      dx=fmval/df
      SOLV_Z=SOLV_Z-dx
      if(SOLV_Z<xm) then
            iflag=iflag+1
            IF(iflag.GT.5) THEN
      i_ok = -1
            RETURN
            ELSE
            SOLV_Z=SOLV_Z-dx/10.
            ENDIF
      endif
      if (abs(dx)<xacc) then
            return
        endif
      enddo
      i_ok = 0
      RETURN
      END FUNCTION SOLV_Z
******************************************************************************
      FUNCTION EPINUC(X)
      implicit real*8(A-H,O-Z)
      COMMON/PINDEL/PPDEL,TFDEL,RDEL
!$OMP THREADPRIVATE(/PINDEL/)
      COMMON/SAXW/ XX(30,500),YY(30,500),SS(30,500),NBPINTER(500),IMAT
!$OMP THREADPRIVATE(/SAXW/)
      COMMON/WS/R0,ADIF,RMAXWS,DRWS,BMAX,XFOISA,RLIM(500),
     &          NPAULSTR,NOSURF
!$OMP THREADPRIVATE(/WS/)

C Correction: FLINR() is prepared in INIT_INCL up to DRWS*29. but rmaxws
C can be larger with the NN-length of interaction:
      RLIMIT=RLIM(imat)

      AA = X*X - PPDEL**2
      IF(AA.LT.0) THEN
            EPINUC=0.
            RETURN
      ENDIF

      FMDEL = SQRT(AA)
      PFDEL = SQRT(TFDEL*(TFDEL+2.*FMDEL))
      IF(RDEL.LE.RLIMIT) THEN
      PL = PFDEL*FLINR(RDEL,imat)
      ELSE
      PL = PFDEL*FLINR(RLIMIT,imat)
      ENDIF
      VLOCJ = SQRT(PL**2 + FMDEL**2) - FMDEL

      EPINUC = X+VLOCJ
      RETURN
      END FUNCTION EPINUC
*******************************************************************************
      SUBROUTINE DIST_COUL_OUT(IA,IBERT,NPION,NB_CLST,F)
      implicit real*8(A-H,O-Z)
      DIMENSION F(30)
C Computes the angular deviation of escaping charged particles  due to coulomb.
      COMMON/BL1/P1(350),P2(350),P3(350),EPS(350),IND1(350),IND2(350),TA
     -,V(350)                                                           P-N00530
!$OMP THREADPRIVATE(/BL1/)
      COMMON/BL3/R1,R2,X1(350),X2(350),X3(350),IA1,IA2,RAB2             P-N00550
!$OMP THREADPRIVATE(/BL3/)
      COMMON/BL5/TLG(350),NESC(350)                                     P-N00570
!$OMP THREADPRIVATE(/BL5/)
      real*8 LOUT_CLST
      COMMON/bl11/POUT_CLST(3,20),LOUT_CLST(3,20),ROUT_CLST(3,20),
     sK_CLST(20),E_CLST(20),T_CLST(20)
!$OMP THREADPRIVATE(/bl11/)
      COMMON/bl12/Q1(200),Q2(200),Q3(200),Q4(200),
     s            Y1(200),Y2(200),Y3(200),YM(200),IPI(200)
!$OMP THREADPRIVATE(/bl12/)
C Cluster programming up to A=IAMAX, Z=IZMAX, IASTOP=maximum A searched for:
      PARAMETER(IAMAX=12,IZMAX=8,IASTOP=8)

      INTEGER ACLST,ZCLST

      COMMON/light_gaus_nuc/rms1t(9),pf1t(9),pfln(9,2),tfln(9,2),
     s vnuc(9,2)
!$OMP THREADPRIVATE(/light_gaus_nuc/)
      DIMENSION ia1t(9),iz1t(9),fmpinct(9)
      DATA ia1t,iz1t,fmpinct/1,1,0,0,0,2,3,3,4,1,0,1,0,-1,1,1,2,2,
     -938.2796,938.2796,138.0,138.0,138.0,1874.35,2806.8,2806.8,3727./

      common /cparam/ bind_clst_new(IAMAX,0:IZMAX),
     &     rmsc_new(IAMAX,0:IZMAX)

C Charge of the remnant:
      tcos=1.-0.000001
      IZREM=0
      DO i=1,IA
         IF(NESC(i).EQ.0.AND.IND2(i).EQ.1) IZREM=IZREM+1
      ENDDO
C Escaping protons:
      FMP=fmpinct(1)
      ET1=1.44*IZREM
      RC=R2+0.88
      DO i=1,IA
      IF(NESC(i).EQ.1.AND.IND2(i).EQ.1) THEN
      RJ=SQRT(X1(i)**2+X2(i)**2+X3(i)**2)
      PJ=SQRT(P1(i)**2+P2(i)**2+P3(i)**2)
      THT = ACOS((X1(i)*P1(i)+X2(i)*P2(i)+X3(i)*P3(i))/(RJ*PJ))
                  IF(THT.GT.0.00001) THEN
      ETA=ET1/(EPS(i)-FMP)
      IF(ETA.GE.(RC-0.0001)) THEN
C If below the coulomb barrier, radial emission:
      THD=-THT
      C1=SIN(THD)/TAN(THT) +COS(THD)
      C2=-PJ*SIN(THD)/(RJ*SIN(THT))
      P1(i)=C1*P1(i)+C2*X1(i)
      P2(i)=C1*P2(i)+C2*X2(i)
      P3(i)=C1*P3(i)+C2*X3(i)
      ELSE
      B0=(ETA+SQRT(ETA**2+4.*RC*RC*(SIN(THT))**2*(1.-ETA/RC)))/2.
      BINF=SQRT(B0*(B0-ETA))
      THR=ATAN(ETA/(2.*BINF))
      utemp=(1.-B0/RC)*SIN(THR)+B0/RC
      IF(utemp.GE.tcos) utemp=tcos
      THD=THT-3.141592654/2.+THR+ACOS(utemp)
      C1=SIN(THD)/TAN(THT) +COS(THD)
      C2=-PJ*SIN(THD)/(RJ*SIN(THT))
      P1(i)=C1*P1(i)+C2*X1(i)
      P2(i)=C1*P2(i)+C2*X2(i)
      P3(i)=C1*P3(i)+C2*X3(i)
      ENDIF
            ENDIF
      ENDIF
      ENDDO
C escaping charged pions:
      IF(NPION.NE.0) THEN
      FMPI=fmpinct(3)
      DO i=1,NPION
      IF(idnint(F(17)).NE.1) THEN
         IF(F(16).LT.0.5) NESC(IA+i)=1
      ENDIF

      IF(NESC(IA+i).EQ.1.AND.IPI(i).NE.0) THEN
      CHPI=IPI(i)/2.

      RJ=SQRT(Y1(i)**2+Y2(i)**2+Y3(i)**2)
      PJ=SQRT(Q1(i)**2+Q2(i)**2+Q3(i)**2)
      THT = ACOS((Y1(i)*Q1(i)+Y2(i)*Q2(i)+Y3(i)*Q3(i))/(RJ*PJ))
                  IF(THT.GT.0.00001) THEN
      ETA=ET1*CHPI/(Q4(i)-FMPI)
      IF(ETA.GE.(RC-0.0001)) THEN
C If below the coulomb barrier (for pi+ only):
      THD=-THT
      C1=SIN(THD)/TAN(THT) +COS(THD)
      C2=-PJ*SIN(THD)/(RJ*SIN(THT))
      Q1(i)=C1*Q1(i)+C2*Y1(i)
      Q2(i)=C1*Q2(i)+C2*Y2(i)
      Q3(i)=C1*Q3(i)+C2*Y3(i)
      ELSE
      B0=(ETA+SQRT(ETA**2+4.*RC*RC*(SIN(THT))**2*(1.-ETA/RC)))/2.
      BINF=SQRT(B0*(B0-ETA))
      THR=ATAN(ETA/(2.*BINF))
      utemp=(1.-B0/RC)*SIN(THR)+B0/RC
      IF(utemp.GE.tcos) utemp=tcos
      THD=THT-3.141592654/2.+THR+ACOS(utemp)
      C1=SIN(THD)/TAN(THT) +COS(THD)
      C2=-PJ*SIN(THD)/(RJ*SIN(THT))
      Q1(i)=C1*Q1(i)+C2*Y1(i)
      Q2(i)=C1*Q2(i)+C2*Y2(i)
      Q3(i)=C1*Q3(i)+C2*Y3(i)
      ENDIF
            ENDIF
      ENDIF

      ENDDO
      ENDIF
C escaping clusters:
      IF(F(11).GE.0.5.AND.NB_CLST.NE.0) THEN
      DO i=1,NB_CLST
      IF(K_CLST(i).GT.10) THEN
      ZCLST=MOD(K_CLST(i),10)
      ACLST=(K_CLST(i)-ZCLST)/10
      ELSEIF(K_CLST(i).EQ.6) THEN
            ACLST=2
            ZCLST=1
      ELSEIF(K_CLST(i).EQ.7) THEN
            ACLST=3
            ZCLST=1
      ELSEIF(K_CLST(i).EQ.8) THEN
            ACLST=3
            ZCLST=2
      ELSEIF(K_CLST(i).EQ.9) THEN
            ACLST=4
            ZCLST=2
      ELSE
            ACLST=0
            ZCLST=0
      ENDIF

      RC=R2+RMSC_NEW(ACLST,ZCLST)
      CHCLST=ZCLST
      RJ=SQRT(ROUT_CLST(1,i)**2+ROUT_CLST(2,i)**2+ROUT_CLST(3,i)**2)
      PJ=SQRT(POUT_CLST(1,i)**2+POUT_CLST(2,i)**2+POUT_CLST(3,i)**2)
      THT = ACOS((ROUT_CLST(1,i)*POUT_CLST(1,i)+ROUT_CLST(2,i)
     s  *POUT_CLST(2,i)+ROUT_CLST(3,i)*POUT_CLST(3,i))/(RJ*PJ))
                  IF(THT.GT.0.00001) THEN
      ETA=ET1*CHCLST/T_CLST(i)

      IF(ETA.GE.(RC-0.0001)) THEN
C If below the coulomb barrier, radial emission:
      THD=-THT
      C1=SIN(THD)/TAN(THT) +COS(THD)
      C2=-PJ*SIN(THD)/(RJ*SIN(THT))
      POUT_CLST(1,i)=C1*POUT_CLST(1,i)+C2*ROUT_CLST(1,i)
      POUT_CLST(2,i)=C1*POUT_CLST(2,i)+C2*ROUT_CLST(2,i)
      POUT_CLST(3,i)=C1*POUT_CLST(3,i)+C2*ROUT_CLST(3,i)
      ELSE
      B0=(ETA+SQRT(ETA**2+4.*RC*RC*(SIN(THT))**2*(1.-ETA/RC)))/2.
      BINF=SQRT(B0*(B0-ETA))
      THR=ATAN(ETA/(2.*BINF))
      utemp=(1.-B0/RC)*SIN(THR)+B0/RC
      IF(utemp.GE.tcos) utemp=tcos

      THD=THT-3.141592654/2.+THR+ACOS(utemp)
      C1=SIN(THD)/TAN(THT) +COS(THD)
      C2=-PJ*SIN(THD)/(RJ*SIN(THT))
      POUT_CLST(1,i)=C1*POUT_CLST(1,i)+C2*ROUT_CLST(1,i)
      POUT_CLST(2,i)=C1*POUT_CLST(2,i)+C2*ROUT_CLST(2,i)
      POUT_CLST(3,i)=C1*POUT_CLST(3,i)+C2*ROUT_CLST(3,i)
      ENDIF
            ENDIF

      ENDDO
      ENDIF
      RETURN
      END SUBROUTINE DIST_COUL_OUT
C***************************************************************************
C Version generale jusqu'a l'Helium-4   (1/04/2008)
C RECHERCHE DE CLUSTERS (d,t,3He,4He) autour du nucleon K, ITCH=charge courante
C   du noyau pour la barriere coulombienne.
C   IOK=1, le cluster de type KINDCLST sort (0=pas de sortie cluster).
C   Logique de retenue des clusters plus l?gers et du nucleon si un cluster
C   se forme sans sortir (POSSIBLE(4) = 0/1 non formation/OK formation,
c                         IOK=2 forcer la reflexion du nucleon (in pnu))
C   ID_NUC_CLST(IAMAX)  Numeros des nucleons constituant ce cluster.
C   EOUT,TOUT     Energie totale et cinetique de ce cluster hors du noyau.
C   POUT, LOUT    Vecteur impulsion et moment angulaire hors du noyau.
C   ROUT        Vector position of the cluster (barycenter)
C  Appel du coulombien avec l'isospin et non Z.
C   OK_CLUST(IAMAX,IZMAX)  Tableau de passage (1) ou non (0) de la barriere
C   KCLST=2 Nucleons avec locale energie dans le critere de recherche
C        =1 Recherche sans la locale energie.
C ASELECT, ZSELECT  (INTEGER) A et Z du cluster trouve
C***************************************************************************
      SUBROUTINE CLUSTER_new(K,ITCH,IACOUR,IZCOUR,NCOL,tim,IOK,KINDCLST,
     s         ID_NUC_CLST,
     s         ROUT,EOUT,TOUT,POUT,LOUT,f17,KCLST,ASELECT,ZSELECT)

      implicit real*8(A-H,O-Z)

C Cluster programming up to A=IAMAX, Z=IZMAX, IASTOP=maximum A serched for:
      PARAMETER(IAMAX=12,IZMAX=8,IASTOP=8)

      REAL*8 ROUT(3),POUT(3),LOUT(3)

      DIMENSION ID_NUC_CLST(IAMAX)


C Common de INCL:
      COMMON/BL1/P1(350),P2(350),P3(350),EPS(350),IND1(350),IND2(350),TA
     -,V(350)
!$OMP THREADPRIVATE(/BL1/)
      COMMON/BL3/R1,R2,X1(350),X2(350),X3(350),IA1,IA2,RAB2
!$OMP THREADPRIVATE(/BL3/)
      COMMON/BL5/TLG(350),NESC(350)
!$OMP THREADPRIVATE(/BL5/)
      COMMON/WS/R0,ADIF,RMAXWS,DRWS,BMAX,XFOISA,RLIM(500),
     &          NPAULSTR,NOSURF
!$OMP THREADPRIVATE(/WS/)
      COMMON/particip/JPARTICIP(350)
!$OMP THREADPRIVATE(/particip/)
      COMMON/CTE/HC,FMP,FMPI
      COMMON/CSE/SN,SP
!$OMP THREADPRIVATE(/CSE/)

C Pour recuperer les valeurs jusqu'a 4He et test A=4
      COMMON/light_gaus_nuc/rms1t(9),pf1t(9),pfln(9,2),tfln(9,2),
     s vnuc(9,2)
!$OMP THREADPRIVATE(/light_gaus_nuc/)

c For calculation with local kinetic energy:
      COMMON/loc/P1L(350),P2L(350),P3L(350),EPSL(350)
!$OMP THREADPRIVATE(/loc/)

c Flag formation du cluster et cluster sortant:
      INTEGER Possible(IAMAX,0:IZMAX),OK_CLUST(IAMAX,0:IZMAX)
      INTEGER Zmi(IAMAX),Zma(IAMAX)
c Indices des nucleons du cluster
      DIMENSION ID_NUC(IAMAX,0:IZMAX,IAMAX)
c Cluster courant:
      DIMENSION R_CLST(3,IAMAX),P_CLST(3,IAMAX)
      DIMENSION SQCLST(IAMAX,0:IZMAX),NBCLST(IAMAX,0:IZMAX)
c cluster trouve:
      DIMENSION R_CLUST(3,IAMAX,0:IZMAX),P_CLUST(3,IAMAX,0:IZMAX),
     s  Tin_clst(IAMAX,0:IZMAX),VCLST(IAMAX,0:IZMAX)
c Indice des participants possibles:
      DIMENSION IDENT_JPART(350)
c Flag des participants deja pris dans la config:
      INTEGER FLAG_JPART(350)

      COMMON /cparam/ bind_clst_new(IAMAX,0:IZMAX),
     &     rmsc_new(IAMAX,0:IZMAX)

      INTEGER A,Z,CZ,POSTCOUL,ASELECT,ZSELECT,FLAG(350)

      INTEGER NCONF,NTYP_D,NTYP_T,NTYP_HE3,NTYP_HE4
      COMMON/CPT/NCONF(2,2,2,2,3),NTYP_D(5),NTYP_T(5),
     s   NTYP_HE3(5),NTYP_HE4(5),NT1s2,NHE31s2,
     s   NBIOK0,NBIOK1,NBIOK2,NBTCUT
!$OMP THREADPRIVATE(/CPT/)

      REAL*8 taille_cc(12),CA(12),CA2(12)
      INTEGER*8 NSTEP_COUNT
      integer f17
C 150000*(A/3)**(2/3)
C     DATA taille_cc/150000.,114771.,150000.,181712.,210858.,
C 150000*(A/2)**(2/3)
C 100000*(A/2)**(2/3)
C 70000*(A/2)**(2/3)
      DATA taille_cc/70000.,180000.,90000.,90000.,128941.,
     s145607.,161365.,176389.,190798.,204681.,218109.,231135./
      DATA CA/1.,0.5,0.33333,0.25,0.2,0.16667,0.14286,0.125,
     s0.11111,0.1,0.09091,0.083333/
      DATA CA2/1.,0.25,0.11111,0.0625,0.04, 0.0277778,0.020408,
     s0.015625,0.012346,0.01,0.0082645,0.0069444/
C limits in charge for each mass of physical clusters
      DATA Zmi/0,1,1,1,1,1,1,2,2,2,3,3/
      DATA Zma/0,1,2,3,3,5,5,6,6,7,7,8/


C Special values for THIS choice of Zmi,Zma and IAMAX.
      NZMA=8
      NNMA=9
C 150000 pour le deuton:
C Parametre de translation:
C  Habituel:
C  Essai 1/09/2008:
      transp=1.00
C Parametre d'espace de phase:
      taille_c=150000.
C Choice of cluster selection mode:
C  1 : First found in the category (A,Z) has before
C  2 : All found, then random in the category (A,Z)
C  3 : All found, then most bound: (SQS-B)/A
      ICLSELECT = 3
C Coulomb barrier pre(0) or post(1) to cluster choice:
      POSTCOUL=1

C init for minimal excitation energy:
      IF(ICLSELECT.EQ.3) THEN
c    special init for choice among ALL clusters
         NBTOTCLST=0
         SQTOT=5000.
         ASELECT=0

         ener_nuc=FMP+50.
      DO i=1,IAMAX
           sqc=(i*ener_nuc)**2
      DO j=0,IZMAX
      SQCLST(i,j)=sqc
      ENDDO
      ENDDO

        ELSE IF(ICLSELECT.EQ.2) THEN
      DO i=1,IAMAX
      DO j=0,IZMAX
        NBCLST(i,j)=0
      ENDDO
      ENDDO
      ENDIF


      IA=IA1+IA2

C Reset and nucleon k is the first of all clusters:
      DO i=1,IAMAX
      DO j=0,IZMAX
        ID_NUC(i,j,1)=K
      Possible(i,j)=0
      OK_CLUST(i,j)=0
      DO l=2,IAMAX
        ID_NUC(i,j,l)=0
      ENDDO
      ENDDO
      ENDDO

        Rprime = R0 + transp
      translat = RMAXWS - Rprime

      PK=SQRT(P1(k)**2+P2(k)**2+P3(k)**2)
        cospr=(X1(k)*P1(k)+X2(k)*P2(k)+X3(k)*P3(k))/(RMAXWS*PK)
C modif pour OK avec noyau sans diffuseness ou RMAXWS petit 12/2006
      arg=RMAXWS*RMAXWS-Rprime*Rprime
      IF(arg.GT.0.) THEN
        cosmin=SQRT(arg)/RMAXWS
         if(cospr.le.cosmin)then
            translat=RMAXWS*cospr
         else
            translat=RMAXWS*(cospr-SQRT(cospr*cospr-cosmin*cosmin))
       endif
      ELSE

          translat=RMAXWS*cospr
     s               -SQRT(Rprime**2-RMAXWS**2*(1.-cospr**2))
      ENDIF
            X1K=X1(k)-P1(k)*translat/PK
            X2K=X2(k)-P2(k)*translat/PK
            X3K=X3(k)-P3(k)*translat/PK

C correction des energies et impulsions si local energies (KCLST.EQ.2)
      IF(KCLST.EQ.2) THEN
          RK= SQRT(X1K**2+X2K**2+X3K**2)
        CALL LOCEK(k,RK)
        ical = 0
      ELSE
        P1L(k)=P1(k)
        P2L(k)=P2(k)
        P3L(k)=P3(k)
          RK= SQRT(X1K**2+X2K**2+X3K**2)
      ENDIF

      NSTEP_COUNT=0
      NCONSIDERED=0
C Nb participants in the selection:
      NB_JPARTICIP=0
C Selection of a subgroup of nucleons to be considered in the search.
      DO 1000 i0=1,IA
        FLAG(i0)=0
c possible nucleon:
         IF(i0.EQ.k.OR.ind1(i0).EQ.1.OR.NESC(i0).NE.0) GO TO 1000
	
C correction des energies et impulsions si local energies (KCLST.EQ.2)
C (correction 22/08/2011, faute trouve par DM, PiL(i0) non initialise!!!)
       IF(KCLST.EQ.2) THEN
             ical=i0
             RI=SQRT(X1(i0)**2+X2(i0)**2+X3(i0)**2)
             CALL LOCEK(ical,RI)
       ELSE
          P1L(i0)=P1(i0)
          P2L(i0)=P2(i0)
          P3L(i0)=P3(i0)
       ENDIF

c possible local energy (momentum) correction for all SELECTED nucleons:
       IF(KCLST.EQ.2) THEN
             ical=i0
             RI=SQRT(X1(i0)**2+X2(i0)**2+X3(i0)**2)
             CALL LOCEK(ical,RI)
       ELSE
          P1L(i0)=P1(i0)
          P2L(i0)=P2(i0)
          P3L(i0)=P3(i0)
       ENDIF

      taille=(X1(i0)-X1k)**2
     s                 + (X2(i0)-X2k)**2 + (X3(i0)-X3k)**2
      taille = taille*((P1L(i0)-P1L(k))**2
     s       + (P2L(i0)-P2L(k))**2
     s       + (P3L(i0)-P3L(k))**2)*CA2(IASTOP)

      NSTEP_COUNT= NSTEP_COUNT+1
C Rejected if not in the phase space:
        IF(taille.GT.taille_cc(IASTOP)) GO TO 1000

      FLAG(i0)=i0

      NCONSIDERED=NCONSIDERED+1
      IF(JPARTICIP(i0).EQ.1) THEN
            NB_JPARTICIP=NB_JPARTICIP+1
            IDENT_JPART(NB_JPARTICIP)=i0
c Flag of considered participant selected in a cluster configuration (init):
            FLAG_JPART(i0)=0
      ENDIF

1000  CONTINUE

C Loop for adding the ident number of spectators to be considered
C after the participant ones in the table IDENT_JPART():
      j0=NB_JPARTICIP
      DO i0=1,IA
          IF(FLAG(i0).NE.0) THEN
           IF(JPARTICIP(i0).EQ.0) THEN
               j0=j0+1
             IDENT_JPART(j0)=i0
           ENDIF
        ENDIF
      ENDDO

      PPRINTK=SQRT(P1L(k)**2+P2L(k)**2+P3L(k)**2)

      DO 1001 i1=1,NCONSIDERED
      m1=IDENT_JPART(i1)
C premier nucleon a agreger (indice icl)
      icl = 1
C Nb nucleons in this cluster:
      A=icl+1
c possible nucleon:

      taille=(X1(m1)-X1k)**2
     s                 + (X2(m1)-X2k)**2 + (X3(m1)-X3k)**2
      taille = taille*((P1L(m1)-P1L(k))**2
     s       + (P2L(m1)-P2L(k))**2
     s       + (P3L(m1)-P3L(k))**2)*CA2(A)

      NSTEP_COUNT= NSTEP_COUNT+1
C Rejected if not in the phase space:
        IF(taille.GT.taille_cc(A)) GO TO 1001

      li1=m1      ! potential nucleon
                  R_CLST(1,icl)=(X1k+X1(m1))*CA(A)
                  R_CLST(2,icl)=(X2k+X2(m1))*CA(A)
                  R_CLST(3,icl)=(X3k+X3(m1))*CA(A)
                  P_CLST(1,icl)=(P1L(k)+P1L(m1))
                  P_CLST(2,icl)=(P2L(k)+P2L(m1))
                  P_CLST(3,icl)=(P3L(k)+P3L(m1))
C NB participants of the configuration (init):
                NBJP=0
            IF(JPARTICIP(li1).EQ.1) THEN
            NBJP=1
            FLAG_JPART(li1)=1
            ENDIF

C Isospin and charge:
            ISO = IND2(k) + IND2(li1)
            CZ = (ISO+A)*0.5

C Stop if the config is not enough energetic:
      eclst=EPS(k)+EPS(li1)
      VCL=V(k)+V(li1)
      HALF_B = 0.72*CZ*ITCH/(R2+1.7)
      Tout = eclst-A*931.3-VCL
      IF(Tout.LE.HALF_B) THEN
          IF(NBJP.GE.NB_JPARTICIP) THEN
            IF(JPARTICIP(li1).EQ.1) THEN
             NBJP=NBJP-1
             FLAG_JPART(li1)= 0
            ENDIF
            GO TO 1001
          ELSE
            DO m=1,NB_JPARTICIP
            mm=IDENT_JPART(m)
              IF(FLAG_JPART(mm).EQ.0)
     s                Tout=Tout+EPS(mm)-V(mm)-931.3
            ENDDO
            IF(Tout.LE.HALF_B) THEN
              IF(JPARTICIP(li1).EQ.1) THEN
                NBJP=NBJP-1
                FLAG_JPART(li1)= 0
              ENDIF
            GO TO 1001
            ENDIF
          ENDIF
      ENDIF

      IF(CZ.GE.ZMI(A).AND.CZ.LE.ZMA(A)) THEN
C physical cluster formed.
                  POSSIBLE(A,CZ)=1

C Pass the Coulomb barrier?
      FM = A*FMP-bind_clst_new(A,CZ)
      eclst=EPS(k)+EPS(li1)
      Tin=eclst-FM
      VCL=V(k)+V(li1)
      IF(POSTCOUL.EQ.0) THEN
            RB = R2 + rmsc_new(A,CZ)
            TCOUL=BARR(Tin,ISO,A,ITCH,RB,VCL,fm,f17)
            rndm=rn(0)
            IF(rndm.GE.TCOUL) GO TO 1101
C Here YES.
        ENDIF
C Keep the first cluster found in the category (A,Z):
          IF(ICLSELECT.EQ.1) THEN
            IF(OK_CLUST(A,CZ).EQ.0) THEN
            OK_CLUST(A,CZ)=1
            ID_NUC(A,CZ,2)=li1
                  R_CLUST(1,A,CZ)=R_CLST(1,icl)
                  R_CLUST(2,A,CZ)=R_CLST(2,icl)
                  R_CLUST(3,A,CZ)=R_CLST(3,icl)
                  P_CLUST(1,A,CZ)=P_CLST(1,icl)
                  P_CLUST(2,A,CZ)=P_CLST(2,icl)
                  P_CLUST(3,A,CZ)=P_CLST(3,icl)
            Tin_clst(A,CZ)=Tin
            VCLST(A,CZ)=VCL
            ENDIF
C Select randomely the cluster in the category (A,Z):
        ELSE IF(ICLSELECT.EQ.2) THEN
              IF(NBCLST(A,CZ).EQ.0) THEN
            NBCLST(A,CZ)=1
            OK_CLUST(A,CZ)=1
            ID_NUC(A,CZ,2)=li1
                  R_CLUST(1,A,CZ)=R_CLST(1,icl)
                  R_CLUST(2,A,CZ)=R_CLST(2,icl)
                  R_CLUST(3,A,CZ)=R_CLST(3,icl)
                  P_CLUST(1,A,CZ)=P_CLST(1,icl)
                  P_CLUST(2,A,CZ)=P_CLST(2,icl)
                  P_CLUST(3,A,CZ)=P_CLST(3,icl)
            Tin_clst(A,CZ)=Tin
            VCLST(A,CZ)=VCL
            ELSE
            NBCLST(A,CZ)=NBCLST(A,CZ)+1
            rndm=rn(0)
              IF(rndm.LE.(1./real(NBCLST(A,CZ),8))) THEN
              ID_NUC(A,CZ,2)=li1
                    R_CLUST(1,A,CZ)=R_CLST(1,icl)
                    R_CLUST(2,A,CZ)=R_CLST(2,icl)
                    R_CLUST(3,A,CZ)=R_CLST(3,icl)
                    P_CLUST(1,A,CZ)=P_CLST(1,icl)
                    P_CLUST(2,A,CZ)=P_CLST(2,icl)
                    P_CLUST(3,A,CZ)=P_CLST(3,icl)
              Tin_clst(A,CZ)=Tin
              VCLST(A,CZ)=VCL
              ENDIF
            ENDIF
        ELSE IF(ICLSELECT.EQ.3) THEN
              sqc= eclst**2 - P_CLST(1,icl)**2
     s            - P_CLST(2,icl)**2 - P_CLST(3,icl)**2
c  less bound of all:
                sqct=(SQRT(sqc)-CZ*938.27-(A-CZ)*939.57
     s              -bind_clst_new(A,CZ))*CA(A)
            OK_CLUST(A,CZ)=1
            IF(sqct.LT.SQTOT) THEN
            SQTOT=sqct
            ASELECT=A
            ZSELECT=CZ

            SQCLST(A,CZ)=sqc
            ID_NUC(A,CZ,2)=li1
                  R_CLUST(1,A,CZ)=R_CLST(1,icl)
                  R_CLUST(2,A,CZ)=R_CLST(2,icl)
                  R_CLUST(3,A,CZ)=R_CLST(3,icl)
                  P_CLUST(1,A,CZ)=P_CLST(1,icl)
                  P_CLUST(2,A,CZ)=P_CLST(2,icl)
                  P_CLUST(3,A,CZ)=P_CLST(3,icl)
            Tin_clst(A,CZ)=Tin
            VCLST(A,CZ)=VCL
            ENDIF
        ENDIF

1101    CONTINUE
        ENDIF
C limit in A search:
      IF(A.GE.IASTOP) GO TO 1201

      DO 1002 i2=1,NCONSIDERED
      m2=IDENT_JPART(i2)
      icl = 2
      A = icl+1
      icv=icl-1
c possible nucleon:
       IF(m2.EQ.li1) GO TO 1002

      taille=(X1(m2)-R_CLST(1,icv))**2
     s       + (X2(m2)-R_CLST(2,icv))**2 + (X3(m2)-R_CLST(3,icv))**2
      taille = taille*((icl*P1L(m2)-P_CLST(1,icv))**2
     s       + (icl*P2L(m2)-P_CLST(2,icv))**2
     s       + (icl*P3L(m2)-P_CLST(3,icv))**2)*CA2(A)

      NSTEP_COUNT= NSTEP_COUNT+1
C Rejected if not in the phase space:
        IF(taille.GT.taille_cc(A)) GO TO 1002

      li2=m2      ! potential nucleon
                  R_CLST(1,icl)=(icl*R_CLST(1,icv)+X1(m2))*CA(A)
                  R_CLST(2,icl)=(icl*R_CLST(2,icv)+X2(m2))*CA(A)
                  R_CLST(3,icl)=(icl*R_CLST(3,icv)+X3(m2))*CA(A)
                  P_CLST(1,icl)=(P_CLST(1,icv)+P1L(m2))
                  P_CLST(2,icl)=(P_CLST(2,icv)+P2L(m2))
                  P_CLST(3,icl)=(P_CLST(3,icv)+P3L(m2))
C NB participants of the configuration:
            IF(JPARTICIP(li2).EQ.1) THEN
            NBJP=NBJP+1
            FLAG_JPART(li2)=1
            ENDIF

            ISO = IND2(k)+IND2(li1)+IND2(li2)
            CZ=(ISO+A)/2
C Stop if the config is not enough energetic:
      eclst=EPS(k)+EPS(li1)+EPS(li2)
      VCL=V(k)+V(li1)+V(li2)
      HALF_B = 0.72*CZ*ITCH/(R2+1.7)
      Tout = eclst-A*931.3-VCL
      IF(Tout.LE.HALF_B) THEN
          IF(NBJP.GE.NB_JPARTICIP) THEN
            IF(JPARTICIP(li2).EQ.1) THEN
             NBJP=NBJP-1
             FLAG_JPART(li2)= 0
            ENDIF
            GO TO 1002
          ELSE
            DO m=1,NB_JPARTICIP
            mm=IDENT_JPART(m)
              IF(FLAG_JPART(mm).EQ.0)
     s                Tout=Tout+EPS(mm)-V(mm)-931.3
            ENDDO
            IF(Tout.LE.HALF_B) THEN
              IF(JPARTICIP(li2).EQ.1) THEN
                NBJP=NBJP-1
                FLAG_JPART(li2)= 0
              ENDIF
            GO TO 1002
            ENDIF
          ENDIF
      ENDIF

      IF(CZ.GE.ZMI(A).AND.CZ.LE.ZMA(A)) THEN
C physical cluster formed.
                  POSSIBLE(A,CZ)=1

C Pass the Coulomb barrier?
      FM = A*FMP-bind_clst_new(A,CZ)
      Tin=eclst-FM
      IF(POSTCOUL.EQ.0) THEN
            RB = R2 + rmsc_new(A,CZ)
            TCOUL=BARR(Tin,ISO,A,ITCH,RB,VCL,fm,f17)
            rndm=rn(0)
                  IF(rndm.GE.TCOUL) GO TO 1102
C Here YES.
        ENDIF
C Keep the first cluster found in the category (A,Z):
          IF(ICLSELECT.EQ.1) THEN
            IF(OK_CLUST(A,CZ).EQ.0) THEN
            OK_CLUST(A,CZ)=1
            ID_NUC(A,CZ,2)=li1
            ID_NUC(A,CZ,3)=li2
                  R_CLUST(1,A,CZ)=R_CLST(1,icl)
                  R_CLUST(2,A,CZ)=R_CLST(2,icl)
                  R_CLUST(3,A,CZ)=R_CLST(3,icl)
                  P_CLUST(1,A,CZ)=P_CLST(1,icl)
                  P_CLUST(2,A,CZ)=P_CLST(2,icl)
                  P_CLUST(3,A,CZ)=P_CLST(3,icl)
            Tin_clst(A,CZ)=Tin
            VCLST(A,CZ)=VCL
            ENDIF
C Select randomely the cluster in the category (A,Z):
        ELSE IF(ICLSELECT.EQ.2) THEN
              IF(NBCLST(A,CZ).EQ.0) THEN
            NBCLST(A,CZ)=1
            OK_CLUST(A,CZ)=1
            ID_NUC(A,CZ,2)=li1
            ID_NUC(A,CZ,3)=li2
                  R_CLUST(1,A,CZ)=R_CLST(1,icl)
                  R_CLUST(2,A,CZ)=R_CLST(2,icl)
                  R_CLUST(3,A,CZ)=R_CLST(3,icl)
                  P_CLUST(1,A,CZ)=P_CLST(1,icl)
                  P_CLUST(2,A,CZ)=P_CLST(2,icl)
                  P_CLUST(3,A,CZ)=P_CLST(3,icl)
            Tin_clst(A,CZ)=Tin
            VCLST(A,CZ)=VCL
            ELSE
            NBCLST(A,CZ)=NBCLST(A,CZ)+1
            rndm=rn(0)
              IF(rndm.LE.(1./real(NBCLST(A,CZ),8))) THEN
              ID_NUC(A,CZ,2)=li1
              ID_NUC(A,CZ,3)=li2
                    R_CLUST(1,A,CZ)=R_CLST(1,icl)
                    R_CLUST(2,A,CZ)=R_CLST(2,icl)
                    R_CLUST(3,A,CZ)=R_CLST(3,icl)
                    P_CLUST(1,A,CZ)=P_CLST(1,icl)
                    P_CLUST(2,A,CZ)=P_CLST(2,icl)
                    P_CLUST(3,A,CZ)=P_CLST(3,icl)
              Tin_clst(A,CZ)=Tin
              VCLST(A,CZ)=VCL
              ENDIF
            ENDIF
        ELSE IF(ICLSELECT.EQ.3) THEN
              sqc= eclst**2 - P_CLST(1,icl)**2
     s            - P_CLST(2,icl)**2 - P_CLST(3,icl)**2
c  less bound of all:
               sqct=(SQRT(sqc)-CZ*938.27-(A-CZ)*939.57
