C Modif logique clusters (3/2006)
      IF (TP.LE.1.E-4) GO TO 601
C ANCIENNE LOGIQUE (test barriere AVANT recherche cluster)


C Commande clusters ou non (1/0)!
      IF(Kclst.EQ.0) GO TO 1610
C-------------------------------------------------------------------
C Ici la particule L1 s'echappe du noyau:
      IF (IND1(L1).EQ.1) GO TO 1610

C Condition pour test 15/10/2007:
c       Reflexion forcee 1/2 pour les protons
      CALL CLUSTER_new45(L1,ITCH,NCOL,tim,IOK,KINDCLST,ID_NUC_CLST, ! ThA
     s             ROUT,EOUT,TOUT,POUT,LOUT,idnint(f(17)),KCLST,
     s             ASELECT,ZSELECT)

c Test for a transparent and no possible cluster:
C No print above (p 50MeV and 1 GeV on Pb): Change of the test:

C test for light targets: the remnant should be at least ONE nucleon!
      IF((IA-nbquit-ASELECT).LT.1) IOK=0

C (Test for a H.I. transparent will arrive after testing the transmission)
      IF((NCOL.EQ.0).AND.iok.ne.1.AND.IA1.EQ.1)
     s     goto 9100

      IF(IOK.EQ.0) nbiok0=nbiok0+1
      IF(IOK.EQ.1) nbiok1=nbiok1+1
      IF(IOK.EQ.2) nbiok2=nbiok2+1

C HERE we decide to force (OR NOT) a reflexion of the leading nucleon
C if a cluster is formed without escaping the coulomb barrier.


      IF (IOK.EQ.1) THEN        !cluster OK
C density of selected clusters:
         translat=1.5
         CALL CLUST_DENS_new(translat,
     s        ID_NUC_CLST,ASELECT,ZSELECT,ROUT)
         NB_CLST = NB_CLST + 1
         IF(NB_CLST.GT.20) THEN
            WRITE(6,*) 'More clusters than allowed by dimensions'
            STOP
         ENDIF

         K_CLST(NB_CLST)=KINDCLST
         E_CLST(NB_CLST)=EOUT
         T_CLST(NB_CLST)=TOUT


c Counting the probability of taking a participant in the cluster
c (there is always one participant in a cluster!).
C Histos 30-33 for comparison with NPART_CLST.
         na=0
         jpar=0
         do ii=1,IA
            if(nesc(ii).EQ.0)then
               na=na+1
               if(jparticip(ii).EQ.1)jpar=jpar+1
            endif
         enddo

         ratio_clst(NB_CLST)=real(jpar-1)/real(na-1)

         DO iloc=1,3
            POUT_CLST(iloc,NB_CLST)=POUT(iloc)
            LOUT_CLST(iloc,NB_CLST)=LOUT(iloc)
            ROUT_CLST(iloc,NB_CLST)=ROUT(iloc)
         END DO

         nb_nuc_clst = 0
         N_PARTICIP(NB_CLST)= 0
         DO iloc=1,ASELECT
            NO_NUC = ID_NUC_CLST(iloc)
            ID_CLST(iloc,NB_CLST) = NO_NUC
            IF (NO_NUC.NE.0) THEN
               NESC(NO_NUC) = 2
               TEVT(NO_NUC) = tim
               nb_nuc_clst = nb_nuc_clst + 1
               IF(jparticip(NO_NUC).EQ.1)
     s              N_PARTICIP(NB_CLST)= N_PARTICIP(NB_CLST) + 1

C Check participant content only up to Alpha
               IF (KINDCLST.LE.9) THEN
                  rat=ratio_clst(NB_CLST)
                  np_1=nb_nuc_clst-1
                  na_clst=ia1t(KINDCLST)
                  np_2=na_clst-nb_nuc_clst
                  co_ef=C_O(na_clst,nb_nuc_clst)
                  weight=co_ef*rat**np_1*(1-rat)**np_2

               ENDIF

C Critere d'arret sur energie (Ce sont des nucleons!):
               IF(F(14).EQ.1.) THEN
                  IF(IND2(NO_NUC).EQ.-1) TF=TFN
                  IF(IND2(NO_NUC).EQ.1)  TF=TFP
                  IF((EPS(NO_NUC)-FMP-V(NO_NUC)+SP).GT.EIN_MAX)
     s                 NB_SUPE = NB_SUPE - 1
               ENDIF
               IF(JPARTICIP(NO_NUC).EQ.1)nb_jpart = nb_jpart - 1

               IF (NO_NUC.NE.L1) THEN
C On retire les nucleons autre que L1 des tableaux des avatars.
C    (Le decalage en temps (TAU) se fera en traitant L1)
                  IF (K.EQ.0) GO TO 1607
                  KD=0
                  DO kloc=1,K
                     I20=kloc-KD
                     IF(JND(kloc).EQ.NO_NUC) GO TO 1604
                     IF(IND(kloc).EQ.NO_NUC.AND.JND(kloc).NE.0)
     s                    GO TO 1604
                     CROIS(I20)=CROIS(kloc)
                     IND(I20)=IND(kloc)
                     JND(I20)=JND(kloc)
                     GO TO 1603
 1604                KD=KD+1
 1603                CONTINUE
                  END DO
                  K=K-KD
 1607             CONTINUE
               ENDIF
            ENDIF
         END DO

         nbquit = nbquit + nb_nuc_clst
         IF(KINDCLST.LE.9) THEN
            ITCH = ITCH - ((KINDCLST-6)/2 + 1)
            IF(KINDCLST.EQ.6) THEN
               SEJNVT=SEJNVT+SN
               SEJPVT=SEJPVT+SP
            ENDIF
            IF(KINDCLST.EQ.7) THEN
               SEJNVT=SEJNVT+2*SN
               SEJPVT=SEJPVT+SP
            ENDIF
            IF(KINDCLST.EQ.8) THEN
               SEJNVT=SEJNVT+SN
               SEJPVT=SEJPVT+2*SP
            ENDIF
            IF(KINDCLST.EQ.9) THEN
               SEJNVT=SEJNVT+2*SN
               SEJPVT=SEJPVT+2*SP
            ENDIF
         ELSE
            ITCH=ITCH-ZSELECT
            SEJNVT=SEJNVT+(ASELECT-ZSELECT)*SN
            SEJPVT=SEJPVT+ZSELECT*SP
         ENDIF

         GO TO  610

      ENDIF                      !sortie de la particule (nucleon ou delta)

