      var_ab=p1(l1)**2+p2(l1)**2+p3(l1)**2
      GPSG=0.
      IF(var_ab.GT.0.)
     s     GPSG=SQRT(((EPS(L1)-POT)**2-FM*FM)/var_ab)                   P-N11750
      P1(L1)=GPSG*P1(L1)                                                P-N11760
      P2(L1)=GPSG*P2(L1)                                                P-N11770
      P3(L1)=GPSG*P3(L1)                                                P-N11780
      EPS(L1)=EPS(L1)-POT                                               P-N11790

