 607  IF (NESC(L1).NE.0) GO TO 613
      CALL NEW1(L1,LOCE)
      IF(IND2(L1).EQ.3) TFC=TFPP
      IF(IND2(L1).EQ.1) TFC=TFP
      IF(IND2(L1).EQ.-1) TFC=TFN
      IF(IND2(L1).EQ.-3) TFC=TFM
