 230  CONTINUE                                                          P-N12170
 255  CONTINUE                                                          P-N12200
      IF (K3.EQ.1) GO TO 256                                            P-N12210
      IF (K4.EQ.0) GO TO 256                                            P-N12220

      DO 257 I=1,IA                                                     P-N12240
         IF (IND1(I).EQ.0) GO TO 257                                       P-N12250
         NPION=NPION+1                                                     P-N12260
         var_ab=EPS(I)**2-P1(I)**2-P2(I)**2-P3(I)**2
         YM(NPION)=0.
         IF(var_ab.GT.0.) YM(NPION)=SQRT(var_ab)                                      P-N12270

c ***** ThA b    (Switch as 4.2 if f(17)=1)
         if(idnint(f(17)).ne.1)then

C TEST POSSIBLE! Delta forces en energie d'excitation!
            IF(YM(NPION).LT.(FMP+FMPI)) THEN
               NPION=NPION-1
               GOTO 262
            ENDIF

            ASSD=YM(NPION)
            xy1=p1(i)
            xy2=p2(i)
            xy3=p3(i)
            xye=eps(i)
            ICHD=IND2(I)
            TV=V(I)
            IF(IND2(I).EQ.3) VKFO1=V0PP
            IF(IND2(I).EQ.1) VKFO1=V0P
            IF(IND2(I).EQ.-1) VKFO1=V0N
            IF(IND2(I).EQ.-3) VKFO1=V0M
            Eavant=EPS(I)-V(I)

            IF(LOCED.NE.0.AND.NESC(I).EQ.0) THEN
C Where are the surviving Deltas?
               R_1 =X1(I)**2 +X2(I)**2 +X3(I)**2
               R_1 = SQRT(R_1)
               PI2 = P1(I)**2 + P2(I)**2 + P3(I)**2
               FMI2=EPS(I)**2 - PI2
               VLOC1 = VLOC45(I,R_1)
               E_1=EPS(I)-VLOC1
               AA=E_1**2 - FMI2
               IF (AA.LT.0) THEN
                  COR1 = 0
                  E_1=SQRT(FMI2)
               ELSE
                  COR1=SQRT(AA/PI2)
               ENDIF
               P1L1=P1(I)*COR1
               P2L1=P2(I)*COR1
               P3L1=P3(I)*COR1
            ENDIF

            IF(LOCED.EQ.1.AND.NESC(I).EQ.0) THEN
               EPS(I) = E_1
               P1(I) = P1L1
               P2(I) = P2L1
               P3(I) = P3L1
C Pour test conservation de E avec E-Vloc(r)
               Eavant = EPS(I)-V(I)
            ENDIF

            CALL DECAY2(P1(I),P2(I),P3(I),EPS(I),NPION,
     s           FMP,FMPI,hel(i),B1d,B2d,B3d)

C ATTENTION ICI version AB traitait decroissance forcee du Delta different de TA
            if(nesc(i).eq.0) idecf=1
