                  ID_NUC(A,CZ,8)=li7
                  ID_NUC(A,CZ,9)=li8
                  ID_NUC(A,CZ,10)=li9
                  R_CLUST(1,A,CZ)=R_CLST(1,icl)
                  R_CLUST(2,A,CZ)=R_CLST(2,icl)
                  R_CLUST(3,A,CZ)=R_CLST(3,icl)
                  P_CLUST(1,A,CZ)=P_CLST(1,icl)
                  P_CLUST(2,A,CZ)=P_CLST(2,icl)
                  P_CLUST(3,A,CZ)=P_CLST(3,icl)
                  Tin_clst(A,CZ)=Tin
                  VCLST(A,CZ)=VCL
                 ENDIF
                ENDIF

 1109           CONTINUE
               ENDIF
C limit in A search:
               IF(A.GE.IASTOP) GO TO 1009

               DO 1010 i10=1,NCONSIDERED
                m10=IDENT_JPART(i10)
                icl = 10
