C NB participants of the configuration:
                IF(JPARTICIP(li10).EQ.1) THEN
                 NBJP=NBJP+1
                 FLAG_JPART(li10)=1
                ENDIF

                ISO = IND2(k)+IND2(li1)+IND2(li2)+IND2(li3)
     s               +IND2(li4)+IND2(li5)+IND2(li6)+IND2(li7)+IND2(li8)
     s               +IND2(li9)+IND2(li10)
                CZ=(ISO+A)/2
C Stop if too much protons and neutrons:
                IF(CZ.GT.NZMA) GO TO 1010
                IF((A-CZ).GT.NNMA) GO TO 1010
C Stop if the config is not enough energetic:
               eclst=EPS(k)+EPS(li1)+EPS(li2)+EPS(li3)+EPS(li4)+EPS(li5)
     s               +EPS(li6)+EPS(li7)+EPS(li8)+EPS(li9)+EPS(li10)
                VCL=V(k)+V(li1)+V(li2)+V(li3)+V(li4)+V(li5)+V(li6)
     s              +V(li7)+V(li8)+V(li9)+V(li10)
                HALF_B = 0.72*CZ*ITCH/(R2+1.7)
                Tout = eclst-A*931.3-VCL
                IF(Tout.LE.HALF_B) THEN
                 IF(NBJP.GE.NB_JPARTICIP) THEN
                  IF(JPARTICIP(li10).EQ.1) THEN
                   NBJP=NBJP-1
                   FLAG_JPART(li10)= 0
                  ENDIF
                  GO TO 1010
                 ELSE
                  DO m=1,NB_JPARTICIP
                   mm=IDENT_JPART(m)
                   IF(FLAG_JPART(mm).EQ.0)
     s                  Tout=Tout+EPS(mm)-V(mm)-931.3
                  ENDDO
                  IF(Tout.LE.HALF_B) THEN
                   IF(JPARTICIP(li10).EQ.1) THEN
                    NBJP=NBJP-1
                    FLAG_JPART(li10)= 0
                   ENDIF
                   GO TO 1010
                  ENDIF
                 ENDIF
                ENDIF

                IF(CZ.GE.ZMI(A).AND.CZ.LE.ZMA(A)) THEN
C physical cluster formed.
                 POSSIBLE(A,CZ)=1

C Pass the Coulomb barrier?
                 FM = A*FMP-bind_clst_new(A,CZ)
