      IF(ICLSELECT.EQ.3) GO TO 300


C choix 50/50 triton/3He si les deux peuvent sortir:

C Compteur config trouvee:
      ld=1
      lt=1
      lhe3=1
      lhe4=1
      if(POSSIBLE(2,1).EQ.1) then
         ld=2
         NTYP_D(1)=NTYP_D(1)+1
         if(OK_CLUST(2,1).EQ.0) NTYP_D(2)=NTYP_D(2)+1
      endif
      if(POSSIBLE(3,1).EQ.1) then
         lt=2
         NTYP_T(1)=NTYP_T(1)+1
         if(OK_CLUST(3,1).EQ.0) NTYP_T(2)=NTYP_T(2)+1
      endif
      if(POSSIBLE(3,2).EQ.1) then
         lhe3=2
         NTYP_HE3(1)=NTYP_HE3(1)+1
         if(OK_CLUST(3,2).EQ.0) NTYP_HE3(2)=NTYP_HE3(2)+1
      endif
      if(POSSIBLE(4,2).EQ.1) then
         lhe4=2
         NTYP_HE4(1)=NTYP_HE4(1)+1
         if(OK_CLUST(4,2).EQ.0) NTYP_HE4(2)=NTYP_HE4(2)+1
      endif

C More general: Random in Z for mass A
      DO i=1,IASTOP
       IF(Zmi(i).NE.Zma(i)) THEN
        nb=0
        DO j=Zmi(i),Zma(i)
         IF(OK_CLUST(i,j).EQ.1) THEN
          nb=nb+1
          IF(nb.NE.1) THEN
           proba=1./nb
           rndm=rn(0)
           IF(rndm.GT.proba) THEN
C cluster non retenu, on l'efface:
            if(i.EQ.3.AND.j.EQ.1)NT1s2=NT1s2+1
            if(i.EQ.3.AND.j.EQ.2)NHE31s2=NHE31s2+1

            OK_CLUST(i,j)=0
           ELSE
C cluster retenu, on efface le retenu precedent:
            if(i.EQ.3.AND.jk.EQ.1)NT1s2=NT1s2+1
            if(i.EQ.3.AND.jk.EQ.2)NHE31s2=NHE31s2+1

            OK_CLUST(i,jk)=0
            jk=j
           ENDIF
          ELSE
           jk=j
          ENDIF
         ENDIF
        ENDDO
       ENDIF
