      IOK = 0                   ! init: this cluster does not escape
C cluster formed but remaining in the nucleus (KCLST=3) AB 20/3/08

      IF(KCLST.EQ.3) THEN
C Here the deuteron is keeping or not the nucleon inside:
c ...keeping
       KSPOS=POSSIBLE(2,1)
c ...not keeping
       DO i=4,3,-1            !Here not taking A=2 (treated before)
        DO j=Zmi(i),Zma(i)
         KSPOS = KSPOS + POSSIBLE(i,j)
         IF((POSSIBLE(i,j).EQ.1).AND.(OK_CLUST(i,j).EQ.0)) THEN
C cluster formed but not escaping -> all lighter not escaping
          DO l=i-1,1,-1
           DO m=Zmi(l),Zma(l)
C         Special for counters of retained clusters:
            if(OK_CLUST(l,m).EQ.1) then
             if(l.EQ.2.AND.m.EQ.1)NTYP_D(3)=NTYP_D(3)+1
             if(l.EQ.3.AND.m.EQ.1)NTYP_T(3)=NTYP_T(3)+1
             if(l.EQ.3.AND.m.EQ.2)NTYP_HE3(3)=NTYP_HE3(3)+1
             if(l.EQ.4.AND.m.EQ.2)NTYP_HE4(3)=NTYP_HE4(3)+1
            endif
            OK_CLUST(l,m)=0
           ENDDO
          ENDDO
C ...et c'est fini
          GO TO 10
         ENDIF
        ENDDO
       ENDDO
 10    CONTINUE

       IF(KSPOS.NE.0) IOK = 2   ! un cluster au moins peut se former,
                                ! on force a priori la reflexion du nucleon

      ENDIF
C End modif KCLST=3

      DO i=IASTOP,1,-1          ! cluster maxi prioritaire
       ia=i
       DO j=Zmi(i),Zma(i)
        jz=j
        IF((OK_CLUST(i,j).EQ.1)) GO TO 732
       ENDDO
      ENDDO

C compteur de configuration retenue dans le noyau:

      IF(IOK.EQ.0) NBIOK0=NBIOK0+1
      IF(IOK.EQ.2) NBIOK2=NBIOK2+1

      RETURN                    ! No cluster will escape (IOK=0 or IOK=2)

 732  CONTINUE
C Compteurs des clusters retenus par cluster MAXI prioritaire:
      IF(ia.GT.1) THEN
       DO i=1,ia-1
        DO j=Zmi(i),Zma(i)
         if(OK_CLUST(i,j).EQ.1) then
          if(i.EQ.2.AND.j.EQ.1)NTYP_D(4)=NTYP_D(4)+1
          if(i.EQ.3.AND.j.EQ.1)NTYP_T(4)=NTYP_T(4)+1
          if(i.EQ.3.AND.j.EQ.2)NTYP_HE3(4)=NTYP_HE3(4)+1
          if(i.EQ.4.AND.j.EQ.2)NTYP_HE4(4)=NTYP_HE4(4)+1
         endif
        ENDDO
       ENDDO
      ENDIF

      GO TO 301

C Jump here for test of min excit energie for ALL clusters
 300  CONTINUE
      IF(POSTCOUL.EQ.1) THEN
c Counters of formed clusters:
       if(POSSIBLE(2,1).EQ.1)NTYP_D(1)=NTYP_D(1)+1
       if(POSSIBLE(3,1).EQ.1)NTYP_T(1)=NTYP_T(1)+1
       if(POSSIBLE(3,2).EQ.1)NTYP_HE3(1)=NTYP_HE3(1)+1
       if(POSSIBLE(4,2).EQ.1)NTYP_HE4(1)=NTYP_HE4(1)+1
       IF (ASELECT.EQ.0) THEN
c   No cluster found
        IOK=0
        NBIOK0=NBIOK0+1
        RETURN
       ENDIF
       ia=ASELECT
       jz=ZSELECT
c Test barrier now on this unique cluster:
       Tin=Tin_clst(ia,jz)
       ISO=2*jz-ia
       A=ia
       RB = R2 + rmsc_new(ia,jz)
       VCL=VCLST(ia,jz)
       TCOUL=BARR45(Tin,ISO,A,ITCH,RB,VCL,f17)
       rndm=rn(0)
       IF(rndm.GE.TCOUL) THEN
C cluster below the barrier: No cluster will escape but force leading nuc. reflection:
        if(ia.EQ.2.AND.jz.EQ.1)NTYP_D(2)=NTYP_D(2)+1
        if(ia.EQ.3.AND.jz.EQ.1)NTYP_T(2)=NTYP_T(2)+1
        if(ia.EQ.3.AND.jz.EQ.2)NTYP_HE3(2)=NTYP_HE3(2)+1
        if(ia.EQ.4.AND.jz.EQ.2)NTYP_HE4(2)=NTYP_HE4(2)+1
C Forced reflection (or not) of the leading nuc for a deuteron cluster
        iforcerefd=1            !1=YES, 0=NO
        if(ia.EQ.2.AND.jz.EQ.1.AND.iforcerefd.EQ.0) then
         IOK=0
         NBIOK0=NBIOK0+1
         RETURN
        endif

        IOK=2
        NBIOK2=NBIOK2+1
        RETURN
       ENDIF
      ELSE
C (Here for POSTCOUL=0, coulomb barrier already tested)
       KSPOS=0
       if(POSSIBLE(2,1).EQ.1) then
        KSPOS=KSPOS+1
        NTYP_D(1)=NTYP_D(1)+1
        if(OK_CLUST(2,1).EQ.0) NTYP_D(2)=NTYP_D(2)+1
       endif
       if(POSSIBLE(3,1).EQ.1) then
        KSPOS=KSPOS+1
        NTYP_T(1)=NTYP_T(1)+1
        if(OK_CLUST(3,1).EQ.0) NTYP_T(2)=NTYP_T(2)+1
       endif
       if(POSSIBLE(3,2).EQ.1) then
        KSPOS=KSPOS+1
        NTYP_HE3(1)=NTYP_HE3(1)+1
        if(OK_CLUST(3,2).EQ.0) NTYP_HE3(2)=NTYP_HE3(2)+1
       endif
       if(POSSIBLE(4,2).EQ.1) then
        KSPOS=KSPOS+1
        NTYP_HE4(1)=NTYP_HE4(1)+1
        if(OK_CLUST(4,2).EQ.0) NTYP_HE4(2)=NTYP_HE4(2)+1
       endif

       IF (ASELECT.GT.0) THEN
c   cluster found above the barrier
        ia=ASELECT
        jz=ZSELECT
        GO TO 301
       ELSE
        IF(KSPOS.GT.0) THEN
C cluster below the barrier: No cluster will escape but force leading nuc. reflection:
         IOK=2
         NBIOK2=NBIOK2+1
         RETURN
        ENDIF
c   No cluster found
        IOK=0
        NBIOK0=NBIOK0+1
        RETURN
       ENDIF

      ENDIF

 301  CONTINUE

      IOK = 1                   ! This cluster will escape

C compteur de configuration cluster emis:
      if(ia.EQ.2) NTYP_D(5)=NTYP_D(5)+1
      if(ia.EQ.3.AND.jz.EQ.1) NTYP_T(5)=NTYP_T(5)+1
      if(ia.EQ.3.AND.jz.EQ.2) NTYP_HE3(5)=NTYP_HE3(5)+1
      if(ia.EQ.4) NTYP_HE4(5)=NTYP_HE4(5)+1

      IF(ia.EQ.2.AND.jz.EQ.1) THEN
       num_clst=1
       KINDCLST = num_clst + 5
      ELSEIF(ia.EQ.3.AND.jz.EQ.1) THEN
       num_clst=2
       KINDCLST = num_clst + 5
      ELSEIF(ia.EQ.3.AND.jz.EQ.2) THEN
       num_clst=3
       KINDCLST = num_clst + 5
      ELSEIF(ia.EQ.4.AND.jz.EQ.2) THEN
       num_clst=4
       KINDCLST = num_clst + 5
      ELSE
       KINDCLST = 10*ia+jz
      ENDIF

      DO i=1,IASTOP
         ID_NUC_CLST(i) = ID_NUC(ia,jz,i)
      END DO

      TOUT = Tin_clst(ia,jz)-VCLST(ia,jz) ! ThA
      FMCLST = ia*FMP - bind_clst_new(ia,jz)

      EOUT = TOUT + FMCLST

      PX = P_CLUST(1,ia,jz)
      PY = P_CLUST(2,ia,jz)
      PZ = P_CLUST(3,ia,jz)

      COEF = SQRT(TOUT*(TOUT+2.*FMCLST)/(PX*PX+PY*PY+PZ*PZ))
      POUT(1)=PX*COEF
      POUT(2)=PY*COEF
      POUT(3)=PZ*COEF

C Changed 20/7/2007, before it was PX,PY,PZ momentum INSIDE???
      RX = R_CLUST(1,ia,jz)
      RY = R_CLUST(2,ia,jz)
      RZ = R_CLUST(3,ia,jz)
      LOUT(1)=RY*POUT(3)-RZ*POUT(2)
      LOUT(2)=RZ*POUT(1)-RX*POUT(3)
      LOUT(3)=RX*POUT(2)-RY*POUT(1)

      ROUT(1)=RX
      ROUT(2)=RY
      ROUT(3)=RZ


C Spectres de correlation Energie leading particule-energie cluster

      thet_lead = (X1K*P1(k)+X2K*P2(k)+X3K*P3(k))/(RK*PK)
      thet_clust = (rout(1)*pout(1)+rout(2)*pout(2)+rout(3)*pout(3))
     &     /sqrt(rout(1)**2+rout(2)**2+rout(3)**2)
     &     /sqrt(pout(1)**2+pout(2)**2+pout(3)**2)

      IF(KINDCLST.LE.9) THEN

       ident = KINDCLST + 48    !HBOOK2 54-55-56-57
       ident = KINDCLST + 37    !HBOOK2 43-44-45-46
       ident = (KINDCLST-6)*10 + 501 !HBOOK2 501-511-521-531
       thet_lab = pout(3)/sqrt(pout(1)**2+pout(2)**2+pout(3)**2)
       ident = (KINDCLST-6)*10 + 502 !HBOOK2 502-512-522-532

       ident = (KINDCLST-6)*10 + 503 !HBOOK2 503-513-523-533

       ident = (KINDCLST-6)*10 + 504 !HBOOK2 504-514-524-534

      ENDIF

      IF(thet_clust.LE.0.7) THEN
c     No cluster found (supposed to be dissociated by a long path
c     in the nuclear density)
       IOK=0
       NBTCUT=NBTCUT+1
       RETURN
      ENDIF

C Verifs arguments de sortie

C Verifs arguments de sortie


      NBIOK1=NBIOK1+1

      RETURN
      END SUBROUTINE CLUSTER_new45
C****************************************************************************

      FUNCTION EFLMAC(IA,IZ,FLAG,OPTSHP)
C
      implicit real*8(A-H,O-Z)

      INTEGER IA,IZ,FLAG,IN,OPTSHP,MEXPIOP(0:153,0:12)
      REAL*8 Z,N,A,AV,AS,A0,C1,C4,B1,B3,F,CA,W,DP,DN,DPN,EFL,PI,BK
      REAL*8 RMAC,BS,H,R0,KF,KS,KV,RP,AY,ADEN,X0,Y0,MH,MN,ESQ,AEL,I,
     &       PARZ,PARA,DEL,E0,EFLMAC
      REAL*8 ECGNZ(0:153,0:98),ECFNZ(0:153,0:98),VGSLD(0:153,0:98)
      REAL*8 BETA2(0:250,0:136),BETA4(0:250,0:136)
      COMMON /ECLD/ECGNZ,ECFNZ,VGSLD,BETA2,BETA4
C     *** Table of liquid-drop masses ***
      INTEGER I1,I2,ITAB
      INTEGER MASS_INDEX(4,95)  ! Must fit to the data in table MASSINDEX
      REAL*8 MASS_TAB(4105)  ! Must fit to the data in table MASSTAB
      COMMON/MASS/ MASS_INDEX, MASS_TAB
      REAL*8 BIND(0:153,0:12)
      COMMON/EXPMASS/BIND,MEXPIOP


      PI = 3.141592653589793238D0
      Z   = DFLOAT(IZ)
      A   = DFLOAT(IA)
      IN  = IA-IZ
      N   = DFLOAT(IN)


C Correction 2/2010 AB-DM:
C Correction 11/2010 AB-JCD:
      IF(IN.EQ.0.OR.IZ.EQ.0) THEN
      EFLMAC=0.D+0
      RETURN
      ENDIF

      IF(FLAG.EQ.1) GOTO 311

cjcdlanl
cjcdlanl

cjcdlanl
      IF(IZ.LT.12.AND.IN.LT.3)
     &       THEN
         IF (MEXPIOP(IN,IZ).EQ.1.AND.OPTSHP.GT.0) THEN
          EFLMAC = BIND(IN,IZ)
          RETURN
	 END IF
      ENDIF
cjcdlanl

C     *** Read liquid-drop masses from table MASSTAB ***
      IF (FLAG.EQ.0) THEN
        IF (IZ.GT.95) GOTO 311 ! out of range of table
        IF (IN.LT.MASS_INDEX(2,IZ) .OR.
     &      IN.GT.MASS_INDEX(3,IZ)) GOTO 311 ! out of range
        I1 = MASS_INDEX(4,IZ) + 1
        I2 = MASS_INDEX(2,IZ)
        ITAB = I1 + (IN-I2)
        EFL = DBLE(MASS_TAB(ITAB))
        GOTO 312
      ENDIF

311   CONTINUE
C /* fundamental constants */
C /* hydrogen-atom mass excess */
      MH  = 7.289034D0
C /* neutron mass excess       */
      MN  = 8.071431D0
C /* electronic charge squared */
      ESQ = 1.4399764D0
C
C /* constants from considerations other than nucl. masses */
C /* electronic binding        */
      AEL = 1.433D-5
C /* proton rms radius         */
      RP  = 0.8D0
C /* nuclear radius constant   */
      R0  = 1.16D0
C /* range of Yukawa-plus-expon. potential */
      AY  = 0.68D0
C /* range of Yukawa function used to generate
C     nuclear charge distribution */
      ADEN= 0.70D0
C /* Wigner constant           */
      W   = 30.D0
C
C /* adjusted parameters */
C /* Volume energy              */
      AV  = 16.00126D0
C /* volume asymmetry           */
      KV  =  1.92240D0
C /* Surface energy             */
      AS  = 21.18466D0
C /* surface asymmetry          */
      KS  =  2.345D0
C /* A^0 constant               */
      A0  =  2.615D0
C /* charge asymmetry           */
      CA  =  0.10289D0
C
C
      C1  = 3.D0/5.D0*ESQ/R0
      C4  = 5.D0/4.D0*(3.D0/(2.D0*PI))**(2.D0/3.D0) * C1
C
C
      KF  = (9.D0*PI*Z/(4.D0*A))**(1.D0/3.D0)/R0
      F   = -1.D0/8.D0*RP*RP*ESQ/R0**3 *
     &      (145.D0/48.D0 - 327.D0/2880.D0*KF**2 * RP**2 +
     &      1527.D0/1209600.D0*KF**4 * RP**4)
C

      I   = (N-Z)/A
C
      X0  = R0 * A**(1.D0/3.D0) / AY
      Y0  = R0 * A**(1.D0/3.D0) / ADEN
C
      B1  = 1.D0 - 3.D0/(X0**2) +
     &      (1.D0 + X0) * (2.D0 + 3.D0/X0 + 3.D0/X0**2)
     &       * DEXP(-2.D0*X0)
C
      B3  = 1.D0 - 5.D0/Y0**2 * (1.D0 - 15.D0/(8.D0*Y0) +
     &      21.D0/(8.D0 * y0**3) -
     &      3.D0/4.D0 * (1.D0 + 9.D0/(2.D0*Y0) + 7.D0/Y0**2 +
     &      7.D0/(2.D0 * Y0**3)) * DEXP(-2.D0*Y0))
C
C NOW CALULATION OF TOTAL BINDING ENERGY A.J. 16.7.96
C
      EFL = - AV*(1.D0-KV*I*I)*A
     &	    + AS*(1.D0-KS*I*I)*B1 * A**(2.D0/3.D0) + A0
     &	    + C1*Z*Z*B3/A**(1.D0/3.D0)
     &	    - C4*Z**(4.D0/3.D0)/A**(1.D0/3.D0)
     &	    + F*Z**2/A -CA*(N-Z) - AEL * Z**(2.39D0)
C
      IF ((IN.EQ.IZ).AND.MOD(IN,2).ne.0.AND.MOD(IZ,2).ne.0
     &     .AND.IN.GT.0) THEN

C       /* N and Z odd and equal */
        EFL = EFL + W*(DABS(I)+1.D0/A)
      ELSE
        EFL= EFL + W* DABS(I)
      END IF
C
C PAIRING IS MADE OPTIONAL
C

312   CONTINUE

      IF (OPTSHP.GE.2) THEN
C *** The following part has been introduced (AK 2008) in order to have correspondance
C     between pairing in masses and level densities;

       IF((IN+IZ).GT.20)THEN
c e-o, o-e
c e-e
                E0 = 11.17D0*DFLOAT(IN+IZ)**(-0.464D0)-0.520D0
     &                -0.079D0*(ECGNZ(IN,IZ)-VGSLD(IN,IZ))
        EFL = EFL - E0
C ***
       ELSE
C /* constants from considering odd-even mass differences */
C /* average pairing gap       */
      RMAC= 4.80D0
C /* neutron-proton interaction*/
      H   = 6.6D0
C /* we will account for deformation by using the microscopic
C   corrections tabulated from p. 68ff */
      BS=1.D0
      DN = 0.D0
      DP = 0.D0

      IF(IN.GT.0) DN  = RMAC*BS/N**(1.D0/3.D0)
      IF(IZ.GT.0) DP  = RMAC*BS/Z**(1.D0/3.D0)

      DPN = H/BS/A**(2.D0/3.D0)

C AK (2008) - Even-odd effect in FRLDM masses seems to be too strong.
      DN = DN/3.D0
      DP = DP/3.D0
      DPN = DPN/3.D0

C /* average pairing - Mšller & Nix*/
        IF (MOD(IN,2).EQ.1.AND.MOD(IZ,2).EQ.1.AND.
     &       IN.GT.0.AND.IZ.GT.0) THEN
c o-o
          EFL = EFL - DPN + DN + DP
        END IF

        IF (MOD(IN,2).EQ.1.AND.MOD(IZ,2).EQ.0.AND.IN.GT.0) THEN
          EFL = EFL + DN
        END IF

        IF (MOD(IZ,2).EQ.1.AND.MOD(IN,2).EQ.0.AND.IZ.GT.0) THEN
           EFL = EFL + DP
        END IF
      ENDIF
C
C END IF FOR PAIRING TERM
C
      END IF
C
         EFLMAC = EFL

      RETURN
      END FUNCTION EFLMAC



C for INCL45
